import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import LoginForm from '../app/(auth)/login/page';
import ForgotPasswordPage from '../app/(auth)/forgot-password/page';
import { apiFetch } from '@/lib/api-client';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: false } },
});

// Mock Next.js navigation
const mockPush = vi.fn();
vi.mock('next/navigation', () => ({
  useRouter: () => ({
    push: mockPush,
  }),
  useSearchParams: () => ({
    get: vi.fn(),
  }),
}));

// Mock Next.js Image
vi.mock('next/image', () => ({
  default: ({ priority, ...props }: any) => <img {...props} />
}));

// Mock sonner toast
vi.mock('sonner', () => ({
  toast: {
    success: vi.fn(),
    error: vi.fn(),
  }
}));

// Mock api-client
vi.mock('@/lib/api-client', () => ({
  apiFetch: vi.fn(),
}));

// Mock auth store
const mockSetAuth = vi.fn();
vi.mock('@/lib/auth-store', () => ({
  useAuthStore: (selector?: any) => {
    const state = { setAuth: mockSetAuth, user: null, setSession: vi.fn(), token: null };
    return selector ? selector(state) : state;
  }
}));

describe('Authentication Components', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('LoginForm', () => {
    it('renders the login form', () => {
      render(<QueryClientProvider client={queryClient}><LoginForm /></QueryClientProvider>);
      expect(screen.getByText('Sign In')).toBeInTheDocument();
      expect(screen.getByPlaceholderText(/you@games4king\.in/i)).toBeInTheDocument();
      expect(screen.getByPlaceholderText(/••••••••/i)).toBeInTheDocument();
    });

    it('shows validation errors for empty submission', async () => {
      render(<QueryClientProvider client={queryClient}><LoginForm /></QueryClientProvider>);
      
      const submitButton = screen.getByRole('button', { name: /Sign In/i });
      fireEvent.click(submitButton);

      await waitFor(() => {
        expect(screen.getAllByText('Email or Employee ID is required')[0]).toBeInTheDocument();
        expect(screen.getAllByText('Password must be at least 6 characters')[0]).toBeInTheDocument();
      });
    });

    it('validates and submits form successfully', async () => {
      (apiFetch as any).mockImplementation(async (url: string) => {
        if (url === '/auth/login') {
          return {
            token: 'fake-token',
            user: { id: 1, name: 'Test User', current_tenant_id: 1 },
            onboarded: true
          };
        }
        return {};
      });

      render(<QueryClientProvider client={queryClient}><LoginForm /></QueryClientProvider>);
      
      fireEvent.change(screen.getByPlaceholderText(/you@games4king\.in/i), { target: { value: 'test@example.com' } });
      fireEvent.change(screen.getByPlaceholderText(/••••••••/i), { target: { value: 'password123' } });
      
      fireEvent.click(screen.getByRole('button', { name: /Sign In/i }));

      await waitFor(() => {
        expect(apiFetch).toHaveBeenCalledWith('/auth/login', expect.objectContaining({
          method: 'POST',
          body: expect.stringContaining('test@example.com')
        }));
      });
    });

    it('displays lockout message when receiving a 423 status', async () => {
      // Mock 423 response
      const lockoutError = new Error('Too many login attempts.');
      (lockoutError as any).status = 423;
      (lockoutError as any).retry_after = 600;
      
      (apiFetch as any).mockImplementation(async (url: string) => {
        if (url === '/auth/login') {
          throw lockoutError;
        }
        return {};
      });

      render(<QueryClientProvider client={queryClient}><LoginForm /></QueryClientProvider>);
      
      fireEvent.change(screen.getByPlaceholderText(/you@games4king\.in/i), { target: { value: 'test@example.com' } });
      fireEvent.change(screen.getByPlaceholderText(/••••••••/i), { target: { value: 'password123' } });
      
      fireEvent.click(screen.getByRole('button', { name: /Sign In/i }));

      await waitFor(() => {
        expect(screen.getByText(/Too many login attempts/i)).toBeInTheDocument();
      });
    });
  });

  describe('ForgotPasswordPage', () => {
    it('renders channel selection and submits correctly', async () => {
      (apiFetch as any).mockResolvedValueOnce({});

      render(<ForgotPasswordPage />);
      
      fireEvent.change(screen.getByPlaceholderText(/Enter your identifier/i), { target: { value: 'test@example.com' } });
      
      fireEvent.click(screen.getByRole('button', { name: /Recover Password/i }));

      await waitFor(() => {
        expect(apiFetch).toHaveBeenCalledWith('/auth/forgot-password', expect.objectContaining({
          body: expect.stringContaining('"identifier":"test@example.com"')
        }));
      });
    });
  });
});

import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { AttendanceHistoryCalendar } from '../../components/attendance/attendance-history-calendar';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { format } from 'date-fns';

vi.mock('@/lib/offline-engine', () => ({
  offlineEngine: {
    queueRequest: vi.fn()
  }
}));

// Mock useIsMobile — default to desktop
vi.mock('@g4k/ui/hooks', () => ({
  useIsMobile: () => false,
}));

const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: false } },
});

function renderWithProviders(ui: React.ReactElement) {
  return render(<QueryClientProvider client={queryClient}>{ui}</QueryClientProvider>);
}

const TODAY = format(new Date(), 'yyyy-MM-dd');
const YESTERDAY = format(new Date(Date.now() - 86400000), 'yyyy-MM-dd');

const mockHistory = [
  {
    id: 1, user_id: 1,
    date: TODAY,
    clock_in: '09:00:00', clock_out: '17:30:00',
    first_event: '09:00:00', last_event: '17:30:00',
    total_seconds: 30600, break_seconds: 3600, overtime_seconds: 0,
    late_minutes: 0, status: 'present', has_open_shift: false,
  },
  {
    id: 2, user_id: 1,
    date: YESTERDAY,
    clock_in: '09:30:00', clock_out: '18:00:00',
    first_event: '09:30:00', last_event: '18:00:00',
    total_seconds: 30600, break_seconds: 0, overtime_seconds: 0,
    late_minutes: 30, status: 'late', has_open_shift: false,
  },
] as any;

describe('AttendanceHistoryCalendar', () => {
  it('renders the month calendar grid on desktop', () => {
    renderWithProviders(<AttendanceHistoryCalendar days={mockHistory} />);
    expect(screen.getByTestId('month-calendar-grid')).toBeInTheDocument();
  });

  it('shows the current month title', () => {
    renderWithProviders(<AttendanceHistoryCalendar days={mockHistory} />);
    const monthTitle = format(new Date(), 'MMMM yyyy');
    expect(screen.getByText(monthTitle)).toBeInTheDocument();
  });

  it('renders day cells with data-testid for current month', () => {
    renderWithProviders(<AttendanceHistoryCalendar days={mockHistory} />);
    expect(screen.getByLabelText(`View details for ${TODAY}`)).toBeInTheDocument();
  });

  it('renders the status legend', () => {
    renderWithProviders(<AttendanceHistoryCalendar days={mockHistory} />);
    expect(screen.getByText('Present')).toBeInTheDocument();
    expect(screen.getByText('Late')).toBeInTheDocument();
    expect(screen.getByText('Leave')).toBeInTheDocument();
    expect(screen.getByText('Overtime')).toBeInTheDocument();
  });

  it('handles empty days array gracefully', () => {
    renderWithProviders(<AttendanceHistoryCalendar days={[]} />);
    expect(screen.getByTestId('attendance-history-calendar')).toBeInTheDocument();
    expect(screen.getByText('0 records this month')).toBeInTheDocument();
  });

  it('opens a detail dialog when a day cell with a record is clicked', () => {
    renderWithProviders(<AttendanceHistoryCalendar days={mockHistory} />);
    const cell = screen.getByLabelText(`View details for ${TODAY}`);
    fireEvent.click(cell);
    expect(screen.getByRole('dialog')).toBeInTheDocument();
  });

  it('shows the correct record count in the header', () => {
    renderWithProviders(<AttendanceHistoryCalendar days={mockHistory} />);
    expect(screen.getByText('2 records this month')).toBeInTheDocument();
  });
});

import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import { TimeClockWidget } from '../../components/widgets/time-clock-widget';
import { useTimerStore } from '../../stores/timer-store';
import { apiFetch } from '@/lib/api-client';
import { offlineEngine } from '@/lib/offline-engine';

// Mock the query client provider
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { toast } from 'sonner';

// Mock dependencies
vi.mock('@/lib/api-client', () => ({
  apiFetch: vi.fn(),
}));

vi.mock('@/lib/offline-engine', () => ({
  offlineEngine: {
    recordPunch: vi.fn(),
  },
}));

vi.mock('sonner', () => ({
  toast: {
    success: vi.fn(),
    error: vi.fn(),
  },
}));

const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false },
  },
});

function renderWithProviders(ui: React.ReactElement) {
  return render(<QueryClientProvider client={queryClient}>{ui}</QueryClientProvider>);
}

describe('TimeClockWidget', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    queryClient.clear();
    useTimerStore.setState({
      isActive: false,
      isOnBreak: false,
      clockInTimestamp: null,
      currentBreakStart: null,
      baseSeconds: 0,
      lastActiveTimestamp: null,
    });

    (apiFetch as any).mockResolvedValue({
      attendance_today: {
        day: { total_seconds: 0 },
        events: [],
        standard_seconds: 28800
      }
    });
  });



  it('renders initial state and fetches data', async () => {
    renderWithProviders(<TimeClockWidget />);
    
    await waitFor(() => {
      expect(screen.getByText('Start Shift')).toBeInTheDocument();
    });
    
    expect(apiFetch).toHaveBeenCalledWith('/dashboard/init');
  });

  it('handles clock in punch optimistically', async () => {
    (offlineEngine.recordPunch as any).mockResolvedValueOnce(undefined);
    // Mock the subsequent refetch triggered by invalidateQueries
    (apiFetch as any).mockResolvedValue({
      attendance_today: {
        day: { total_seconds: 0 },
        events: [{ type: 'clock_in', timestamp: new Date().toISOString() }],
        standard_seconds: 28800
      }
    });

    renderWithProviders(<TimeClockWidget />);
    
    await waitFor(() => {
      expect(screen.getByText('Start Shift')).toBeInTheDocument();
    });

    await act(async () => {
      fireEvent.click(screen.getByText('Start Shift'));
    });
    
    await waitFor(() => {
      expect(useTimerStore.getState().isActive).toBe(true);
      expect(offlineEngine.recordPunch).toHaveBeenCalledWith('clock_in', expect.any(String));
      expect(screen.getByText('End Shift')).toBeInTheDocument();
    });
  });

  it('handles clock out and break states correctly', async () => {
    // Set initial active state to avoid race conditions with queries
    useTimerStore.setState({
      isActive: true,
      isOnBreak: false,
      baseSeconds: 3600,
      clockInTimestamp: new Date().toISOString(),
    });
    
    (offlineEngine.recordPunch as any).mockResolvedValueOnce(undefined);
    (apiFetch as any).mockResolvedValue({
      attendance_today: {
        day: { total_seconds: 3600 },
        events: [
          { type: 'clock_in', timestamp: new Date().toISOString() },
          { type: 'break_start', timestamp: new Date().toISOString() }
        ],
        standard_seconds: 28800
      }
    });

    renderWithProviders(<TimeClockWidget />);
    
    await waitFor(() => {
      expect(screen.getByText('Pause for Break')).toBeInTheDocument();
    });

    await act(async () => {
      fireEvent.click(screen.getByText('Pause for Break'));
    });
    
    await waitFor(() => {
      expect(useTimerStore.getState().isOnBreak).toBe(true);
      expect(offlineEngine.recordPunch).toHaveBeenCalledWith('break_start', expect.any(String));
    });
  });

  it('rolls back state on punch failure', async () => {
    const error = new Error('Network failure');
    (offlineEngine.recordPunch as any).mockRejectedValueOnce(error);

    renderWithProviders(<TimeClockWidget />);
    
    await waitFor(() => {
      expect(screen.getByText('Start Shift')).toBeInTheDocument();
    });

    await act(async () => {
      fireEvent.click(screen.getByText('Start Shift'));
    });
    
    await waitFor(() => {
      // It should revert back to original state if api fetch fails/invalidates
      expect(toast.error).toHaveBeenCalled();
    });
  });
});

