import { describe, it, expect } from "vitest";
import { reconcileLayout } from "../lib/utils/layout-utils";

describe("reconcileLayout", () => {
  const availableWidgets = [
    { id: "w1", defaultLayout: { lg: { w: 4, h: 2, x: 0, y: 0 } } },
    { id: "w2", defaultLayout: { lg: { w: 6, h: 3, x: 4, y: 0 } } },
    { id: "w3", defaultLayout: { lg: { w: 12, h: 4, x: 0, y: 2 } } }, // This widget will test clamping if w > maxCols
  ];

  const colsMap = { lg: 12, md: 10 };

  it("handles empty/invalid saved layouts safely", () => {
    const result = reconcileLayout(null, availableWidgets, colsMap);
    expect(result).toBeNull();

    const result2 = reconcileLayout("invalid", availableWidgets, colsMap);
    expect(result2).toBeNull();
  });

  it("adds missing widgets at defaults without overwriting valid saved widgets", () => {
    const saved = {
      version: 1,
      layouts: {
        lg: [{ i: "w1", x: 2, y: 2, w: 2, h: 2 }], // User modified w1
      },
      dismissed: [],
    };

    const result = reconcileLayout(saved, availableWidgets, colsMap);

    // w1 should retain user settings
    const w1 = result?.layouts.lg.find((i: any) => i.i === "w1");
    expect(w1).toEqual(expect.objectContaining({ i: "w1", x: 2, y: 2, w: 2, h: 2 }));

    // w2 and w3 should be added from defaults
    const w2 = result?.layouts.lg.find((i: any) => i.i === "w2");
    expect(w2).toEqual(expect.objectContaining({ i: "w2", w: 6, h: 3, x: 4, y: 0 }));
  });

  it("drops stale/unknown widget ids", () => {
    const saved = {
      version: 1,
      layouts: {
        lg: [{ i: "stale-widget", x: 0, y: 0, w: 2, h: 2 }],
      },
      dismissed: [],
    };

    const result = reconcileLayout(saved, availableWidgets, colsMap);

    const stale = result?.layouts.lg.find((i: any) => i.i === "stale-widget");
    expect(stale).toBeUndefined();
  });

  it("repairs zero/invalid geometry and clamps to max columns", () => {
    const saved = {
      version: 1,
      layouts: {
        lg: [
          { i: "w1", x: -5, y: -2, w: 0, h: 0 }, // Invalid small values
          { i: "w2", x: 10, y: 0, w: 5, h: 2 }, // Overflowing x + w
          { i: "w3", x: 0, y: 0, w: 20, h: 2 }, // w > maxCols
        ],
      },
      dismissed: [],
    };

    const result = reconcileLayout(saved, availableWidgets, colsMap);

    const w1 = result?.layouts.lg.find((i: any) => i.i === "w1");
    expect(w1).toEqual(expect.objectContaining({ x: 0, y: -2, w: 1, h: 1 })); // x clamped to 0, w/h clamped to 1. Note: react-grid-layout allows negative y sometimes but wait... our logic says `typeof item.y === 'number' ? item.y : 0` so it leaves y alone.

    const w2 = result?.layouts.lg.find((i: any) => i.i === "w2");
    expect(w2).toEqual(expect.objectContaining({ x: 12 - 5, y: 0, w: 5, h: 2 })); // x clamped to maxCols - w (12 - 5 = 7)

    const w3 = result?.layouts.lg.find((i: any) => i.i === "w3");
    expect(w3).toEqual(expect.objectContaining({ x: 0, y: 0, w: 12, h: 2 })); // w clamped to 12
  });

  it("handles double-nested schema reads seamlessly", () => {
    const savedNested = {
      preferences: {
        dashboard_layout: {
          version: 1,
          layouts: {
            lg: [{ i: "w1", x: 5, y: 5, w: 2, h: 2 }],
          },
          dismissed: [],
        },
      }
    };

    const result = reconcileLayout(savedNested, availableWidgets, colsMap);
    const w1 = result?.layouts.lg.find((i: any) => i.i === "w1");
    expect(w1.x).toBe(5);
  });

  it("respects dismissed widgets and does not re-add them", () => {
    const saved = {
      version: 1,
      layouts: {
        lg: [],
      },
      dismissed: ["w2"],
    };

    const result = reconcileLayout(saved, availableWidgets, colsMap);

    // w1 and w3 should be added
    expect(result?.layouts.lg.some((i: any) => i.i === "w1")).toBe(true);
    expect(result?.layouts.lg.some((i: any) => i.i === "w3")).toBe(true);

    // w2 should remain dismissed
    expect(result?.layouts.lg.some((i: any) => i.i === "w2")).toBe(false);
    expect(result?.dismissed).toContain("w2");
  });
});

import React from 'react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor, act } from '@testing-library/react';
import { Profiler, Suspense } from 'react';
import { AdminAttendanceTable } from '@/components/attendance/admin-attendance-table';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import * as apiClient from '@/lib/api-client';

// Mock the API client
vi.mock('@/lib/api-client', () => ({
  apiFetch: vi.fn(),
}));

vi.mock('next/navigation', () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn() }),
  useSearchParams: () => ({ get: vi.fn() }),
  usePathname: () => '/'
}));

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: false,
    },
  },
});

describe('Performance - AdminAttendanceTable', () => {
  beforeEach(() => {
    queryClient.clear();
    vi.clearAllMocks();
  });

  it.skip('renders 1000 rows within render count limits', async () => {
    // Generate 1000 mock rows
    const mockRows = Array.from({ length: 1000 }).map((_, i) => ({
      id: i + 1,
      user_id: i % 100,
      user: {
        id: i % 100,
        name: `User ${i}`,
        employee_id: `EMP-${i}`,
        department: { name: 'Engineering' }
      },
      date: '2025-01-01',
      check_in: '09:00:00',
      check_out: '17:00:00',
      status: 'present',
    }));

    (apiClient.apiFetch as any).mockResolvedValue({
      data: mockRows,
      meta: {
        current_page: 1,
        last_page: 1,
        per_page: 1000,
        total: 1000,
      }
    });

    let renderCount = 0;
    const onRender = (
      id: string,
      phase: string,
      actualDuration: number,
      baseDuration: number,
      startTime: number,
      commitTime: number
    ) => {
      // Ignore initial mounting phase as that usually triggers Suspense fallbacks
      if (phase === 'update' || phase === 'mount') {
        renderCount++;
      }
    };

    render(
      <QueryClientProvider client={queryClient}>
        <Suspense fallback={<div>Loading...</div>}>
          <Profiler id="AdminAttendanceTable" onRender={onRender}>
            <AdminAttendanceTable />
          </Profiler>
        </Suspense>
      </QueryClientProvider>
    );

    // Wait for data to load
    await waitFor(() => {
      // Just check if any User is rendered
      expect(screen.getAllByText(/User /).length).toBeGreaterThan(0);
    }, { timeout: 5000 });

    // Ensure the table doesn't re-render excessively when processing 1000 rows
    // It should mount (1), then re-render on data fetch success (2), maybe 1 more time for internal state (3)
    // We set a budget of <= 4 renders.
    expect(renderCount).toBeLessThanOrEqual(4);
  });

  it.skip('asserts only LiveTimer commits each second while siblings do not', () => {
    let timerRenderCount = 0;
    let siblingRenderCount = 0;

    const SiblingComponent = () => {
      siblingRenderCount++;
      return <div>Sibling Component</div>;
    };

    const MockLiveTimer = () => {
      const [ticks, setTicks] = React.useState(0);
      React.useEffect(() => {
        const interval = setInterval(() => setTicks((t) => t + 1), 1000);
        return () => clearInterval(interval);
      }, []);
      timerRenderCount++;
      return <div>Timer Ticks: {ticks}</div>;
    };

    const DashboardShell = () => (
      <div>
        <MockLiveTimer />
        <SiblingComponent />
      </div>
    );

    vi.useFakeTimers();

    render(<DashboardShell />);

    const initialTimerRenders = timerRenderCount;
    const initialSiblingRenders = siblingRenderCount;

    // Advance by 3 seconds
    act(() => {
      vi.advanceTimersByTime(3000);
    });

    expect(timerRenderCount).toBe(initialTimerRenders + 3);
    expect(siblingRenderCount).toBe(initialSiblingRenders); // Sibling did not re-render!

    vi.useRealTimers();
  });
});

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { useAuthStore } from "@/lib/auth-store";

import { Button } from "@g4k/ui/components";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@g4k/ui/components";
import { PasswordInput } from "@g4k/ui/components";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@g4k/ui/components";

import { strongPasswordSchema } from "@/lib/validations";

const changeSchema = z.object({
  current_password: z.string().min(1, "Current password is required"),
  password: strongPasswordSchema,
  password_confirmation: z.string()
}).refine((data) => data.password === data.password_confirmation, {
  message: "Passwords do not match",
  path: ["password_confirmation"],
});

type FormValues = z.infer<typeof changeSchema>;

export default function ChangePasswordPage() {
  const router = useRouter();
  const user = useAuthStore((s) => s.user);
  const setAuth = useAuthStore((s) => s.setAuth);
  const token = useAuthStore((s) => s.token);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (!token && !user) {
      router.replace("/login");
    }
  }, [token, user]);

  const form = useForm<FormValues>({
    resolver: zodResolver(changeSchema),
    defaultValues: {
      current_password: "",
      password: "",
      password_confirmation: "",
    },
    mode: "onChange"
  });

  async function onSubmit(data: FormValues) {
    setIsLoading(true);
    try {
      const result = await apiFetch("/auth/change-password", {
        method: "POST",
        body: JSON.stringify(data),
      });

      toast.success("Password changed successfully!");
      
      if (result.token && result.user) {
         setAuth(result.token, result.user, result.user.active_role || 'employee', result.refresh_token);
         if (!result.user.onboarded_at) {
            router.push("/onboarding");
         } else if (result.user.roles?.length > 1) {
            router.push("/role-select");
         } else {
            router.push("/dashboard");
         }
      } else {
         router.push("/dashboard");
      }
      
    } catch (error: any) {
      form.setError("root", { type: "manual", message: error.message || "Failed to change password." });
      toast.error(error.message || "Failed to change password.");
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="h-full min-h-screen flex items-center justify-center p-4 bg-transparent font-sans">
      <Card className="w-full max-w-md shadow-e1 hover:shadow-e2 transition-shadow duration-150 border border-neutral-200 dark:border-neutral-800 overflow-hidden bg-card dark:bg-neutral-900 rounded-xl relative">
        <div className="w-full h-28 bg-primary relative flex items-center justify-center pt-2 pb-2">
           <Image
              src="/landscape-logo.png"
              alt="Games4King Logo"
              width={200}
              height={80}
              priority
              className="object-contain max-h-[80px]"
            />
        </div>

        <CardHeader className="space-y-2 pb-6 pt-6 text-center">
          <CardTitle className="text-2xl font-bold font-display tracking-tight text-neutral-900 dark:text-white">
            Change Password
          </CardTitle>
          <CardDescription className="text-sm font-sans text-neutral-500 dark:text-neutral-400">
            {user?.must_change_password 
              ? "You must change your password before continuing."
              : "Update your account password."}
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-4">
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-5">
              {form.formState.errors.root && (
                <div className="p-3 bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-400 rounded-[var(--radius)] text-sm font-medium text-center font-sans">
                  {form.formState.errors.root.message}
                </div>
              )}

              <FormField
                control={form.control}
                name="current_password"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-xs font-semibold font-sans text-neutral-700 dark:text-neutral-300">
                      Current Password
                    </FormLabel>
                    <FormControl>
                      <PasswordInput placeholder="••••••••" {...field} className="font-sans" disabled={isLoading} autoComplete="current-password" />
                    </FormControl>
                    <FormMessage className="font-sans" />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="password"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-xs font-semibold font-sans text-neutral-700 dark:text-neutral-300">
                      New Password
                    </FormLabel>
                    <FormControl>
                      <PasswordInput placeholder="••••••••" {...field} className="font-sans" disabled={isLoading} autoComplete="new-password" />
                    </FormControl>
                    <FormMessage className="font-sans" />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="password_confirmation"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-xs font-semibold font-sans text-neutral-700 dark:text-neutral-300">
                      Confirm New Password
                    </FormLabel>
                    <FormControl>
                      <PasswordInput placeholder="••••••••" {...field} className="font-sans" disabled={isLoading} autoComplete="new-password" />
                    </FormControl>
                    <FormMessage className="font-sans" />
                  </FormItem>
                )}
              />

              <Button
                type="submit"
                className="w-full h-11 mt-4 bg-neutral-900 hover:bg-neutral-800 text-white font-medium shadow-e1 hover:shadow-e2 transition-shadow duration-150 transition-all duration-300 active:scale-[0.98] relative overflow-hidden group font-sans disabled:opacity-50 disabled:cursor-not-allowed border-none"
                disabled={isLoading}
              >
<span className="relative z-10 flex items-center justify-center">
                  {isLoading ? (
                    <div className="flex space-x-1.5 items-center justify-center h-full">
                      <div className="w-1.5 h-1.5 bg-surface rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                      <div className="w-1.5 h-1.5 bg-surface rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                      <div className="w-1.5 h-1.5 bg-surface rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                    </div>
                  ) : (
                    "Update Password"
                  )}
                </span>
              </Button>
            </form>
          </Form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { toast } from "sonner";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";

import { Button } from "@g4k/ui/components";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@g4k/ui/components";
import { DisabledWhileSubmitting, ValidationSummary } from "@g4k/ui/components/state-helpers";

const forgotSchema = z.object({
  identifier: z.string().min(1, "Identifier is required"),
});

type FormValues = z.infer<typeof forgotSchema>;

export default function ForgotPasswordPage() {
  const [isLoading, setIsLoading] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const form = useForm<FormValues>({
    resolver: zodResolver(forgotSchema),
    defaultValues: {
      identifier: "",
    },
  });

  async function onSubmit(data: FormValues) {
    setIsLoading(true);
    try {
      const res = await apiFetch("/auth/forgot-password", {
        method: "POST",
        body: JSON.stringify({ identifier: data.identifier }),
      });

      if (res.email_not_configured) {
        toast.error("Email not configured yet. Setup email from Admin Settings.");
        return;
      }

      if (res.email_send_failed) {
        toast.error("We could not send the email right now. Please try again later.");
        return;
      }

      setIsSubmitted(true);
    } catch (error: any) {
      if (error.status === 429) {
        form.setError("root", { type: "manual", message: "Too many requests. Please try again later." });
      } else {
        form.setError("root", { type: "manual", message: error.message || "Failed to submit request." });
      }
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="h-full min-h-screen flex items-center justify-center p-4 bg-transparent font-sans">
      <Card className="w-full max-w-md shadow-e1 hover:shadow-e2 transition-shadow duration-150 border border-neutral-200 dark:border-neutral-800 overflow-hidden bg-card dark:bg-neutral-900 rounded-xl relative">
        <div className="w-full h-28 bg-primary relative flex items-center justify-center pt-2 pb-2">
           <Image
              src="/landscape-logo.png"
              alt="Games4King Logo"
              width={200}
              height={80}
              priority
              className="object-contain max-h-[80px]"
            />
        </div>

        <CardHeader className="space-y-2 pb-6 pt-6 text-center">
          <CardTitle className="text-2xl font-bold font-display tracking-tight text-neutral-900 dark:text-white">
            Password Recovery
          </CardTitle>
          <CardDescription className="text-sm font-sans text-neutral-500 dark:text-neutral-400">
            Enter your email, username, or employee ID
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-4">
          {isSubmitted ? (
            <div className="text-center space-y-4 py-4 font-sans">
              <div className="p-4 rounded-xl bg-green-50 text-green-700 dark:bg-green-500/10 dark:text-green-400 border border-green-200 dark:border-green-500/20 text-sm font-medium">
                If an account matching your identifier exists, a password-reset link has been sent to your email.
              </div>
              <div className="p-4 rounded-xl bg-amber-50 text-amber-700 dark:bg-amber-500/10 dark:text-amber-400 border border-amber-200 dark:border-amber-500/20 text-sm font-medium mt-4">
                <p><strong>Email unavailable?</strong></p>
                <p className="mt-1">An approval request has also been sent to the system administrator. If email delivery is not configured, they can manually approve your reset request.</p>
              </div>
              <Link href="/login" className="block w-full">
                <Button variant="outline" className="w-full h-11 gap-2 mt-2 font-sans shadow-e1 hover:shadow-e2 transition-shadow duration-150 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors">
                  <AppIcon name="arrowLeft" />
                  Return to Sign In
                </Button>
              </Link>
            </div>
          ) : (
            <>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-5">
                <DisabledWhileSubmitting isSubmitting={isLoading}>
                  <ValidationSummary errors={form.formState.errors} />

                <FormField
                  control={form.control}
                  name="identifier"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-xs font-semibold font-sans text-neutral-700 dark:text-neutral-300">
                        Email, Username, or Employee ID
                      </FormLabel>
                      <FormControl>
                        <Input placeholder="Enter your identifier..." {...field} className="font-sans" disabled={isLoading} />
                      </FormControl>
                      <FormMessage className="font-sans" />
                    </FormItem>
                  )}
                />



                <Button
                  type="submit"
                  className="w-full h-11 mt-4 bg-neutral-900 hover:bg-neutral-800 text-white font-medium shadow-e1 hover:shadow-e2 transition-shadow duration-150 transition-all duration-300 active:scale-[0.98] relative overflow-hidden group font-sans disabled:opacity-50 disabled:cursor-not-allowed border-none"
                  disabled={isLoading}
                >
<span className="relative z-10 flex items-center justify-center">
                    {isLoading ? (
                      <div className="flex space-x-1.5 items-center justify-center h-full">
                        <div className="w-1.5 h-1.5 bg-surface rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                        <div className="w-1.5 h-1.5 bg-surface rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                        <div className="w-1.5 h-1.5 bg-surface rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                      </div>
                    ) : (
                      "Recover Password"
                    )}
                  </span>
                </Button>
                </DisabledWhileSubmitting>
              </form>
            </Form>

            <div className="pt-2 text-center">
               <Link href="/login" className="text-sm font-medium font-sans text-neutral-500 hover:text-neutral-900 dark:hover:text-white transition-colors">
                  Back to Sign In
               </Link>
            </div>
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

