"use client";

import { useAuthStore } from "@/lib/auth-store";
import { WidgetEngine } from "@/components/widgets/widget-engine";
import { useRouter } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import { useCapabilities, hasCapability } from "@/lib/capabilities";
import { useQueryClient, useQuery } from "@tanstack/react-query";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { GRID_COLS } from "@/lib/reconcile-layout";
import { queryKeys } from "@/lib/query-keys";
import { apiFetch } from "@/lib/api-client";
import { format } from "date-fns";
import { QuickNotes } from "@/components/widgets/quick-notes";
import { getGreeting } from "@/lib/greeting";
import { toast } from "sonner";
import { AppIcon, IconName } from "@g4k/ui/components";
import { TimeClockWidget } from "@/components/widgets/time-clock-widget";
import { MetricWidget } from "@/components/widgets/metric-widget";
import { AnnouncementBoard } from "@/components/widgets/announcement-board";
import { HrTeamAttendanceWidget } from "@/components/dashboard/hr-team-attendance-widget";
import { HrActivityFeedWidget } from "@/components/attendance/hr-activity-feed-widget";

import Link from "next/link";
import { RecentActivityWidget } from "@/components/widgets/recent-activity-widget";
import { Skeleton } from "@g4k/ui/components";
import { Card } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";

import { AdminTodayAttendanceWidget } from "@/components/dashboard/admin-today-attendance-widget";
import { QuickTaskWidget } from "@/components/dashboard/quick-task-widget";
import { UpcomingHolidaysWidget } from "@/components/widgets/upcoming-holidays-widget";
import { EmployeeTaskProgressWidget } from "@/components/dashboard/employee-task-progress-widget";
import { PendingApprovalsWidget } from "@/components/widgets/pending-approvals-widget";
import { EmployeeApprovalStatusWidget } from "@/components/dashboard/employee-approval-status-widget";

const EMPTY_CAPABILITIES: any[] = [];
const cols = GRID_COLS;

function responsiveLayout(base: { x: number, y: number, w: number, h: number }) {
  return {
    lg: base,
    md: { ...base, w: Math.min(base.w, cols.md) },
    sm: { ...base, w: Math.min(base.w, cols.sm), x: 0 },
    xs: { ...base, w: Math.min(base.w, cols.xs), x: 0 },
    xxs: { ...base, w: Math.min(base.w, cols.xxs), x: 0 },
  };
}

export default function DashboardPage() {
  const user = useAuthStore((s) => s.user);
  const router = useRouter();
  const queryClient = useQueryClient();

  const token = useAuthStore((s) => s.token);

  const { data: initData, isLoading, isError, refetch } = useDashboardInit();

  // Role determined by initData?.role or user?.active_role, falling back to employee
  const activeRole = initData?.role || user?.active_role || "employee";

  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (typeof window !== "undefined") {
      const params = new URLSearchParams(window.location.search);
      if (params.get("error") === "unauthorized") {
        toast.error("You don't have access to that section.");
        router.replace("/dashboard");
      }
    }
  }, [router]);

  const { data: userCapabilities = EMPTY_CAPABILITIES } = useCapabilities();

  // Memoized widget catalog based on active role
  const availableWidgets = useMemo(() => {
    if (activeRole === "super_admin") {
      return [
        {
          id: "total-employees",
          component: (
            <MetricWidget title="Total Employees" metricKey="total_employees" icon={"directory"} color="indigo" breakdown={true} href="/dashboard/org/users" />
          ),
          defaultLayout: responsiveLayout({ x: 0, y: 0, w: 3, h: 2 }),
        },
        {
          id: "active-projects",
          component: (
            <MetricWidget title="Active Projects" metricKey="active_projects" icon={"projects"} color="emerald" subtitle="In progress" href="/dashboard/projects" />
          ),
          defaultLayout: responsiveLayout({ x: 3, y: 0, w: 3, h: 2 }),
        },
        {
          id: "admin-today-attendance",
          component: <AdminTodayAttendanceWidget />,
          defaultLayout: responsiveLayout({ x: 6, y: 0, w: 3, h: 2 }),
        },
        {
          id: "pending-approvals",
          component: <PendingApprovalsWidget />,
          defaultLayout: responsiveLayout({ x: 0, y: 2, w: 6, h: 3 }),
        },
        {
          id: "recent-activity",
          component: <RecentActivityWidget />,
          defaultLayout: responsiveLayout({ x: 6, y: 2, w: 6, h: 3 }),
        },
        {
          id: "quick-task",
          component: <QuickTaskWidget />,
          defaultLayout: responsiveLayout({ x: 0, y: 5, w: 6, h: 3 }),
        }
      ];
    }

    if (activeRole === "hr") {
      const hrWidgets = [
        {
          id: "team-attendance",
          component: <HrTeamAttendanceWidget />,
          defaultLayout: responsiveLayout({ x: 0, y: 0, w: 4, h: 2 }),
        },
        {
          id: "pending-leave",
          component: <PendingApprovalsWidget />, // Handles leave & submissions
          defaultLayout: responsiveLayout({ x: 4, y: 0, w: 4, h: 3 }),
        },
        {
          id: "team-activity",
          component: <HrActivityFeedWidget />,
          defaultLayout: responsiveLayout({ x: 0, y: 3, w: 6, h: 3 }),
        },
        {
          id: "quick-task",
          component: <QuickTaskWidget />,
          defaultLayout: responsiveLayout({ x: 6, y: 3, w: 6, h: 3 }),
        },
        {
          id: "announcements",
          component: <AnnouncementBoard />,
          defaultLayout: responsiveLayout({ x: 0, y: 6, w: 8, h: 3 }),
        },
        {
          id: "upcoming-holidays",
          component: <UpcomingHolidaysWidget />,
          defaultLayout: responsiveLayout({ x: 8, y: 6, w: 4, h: 3 }),
        },
      ];
      
      if (hasCapability(userCapabilities, "attendance.clock-self")) {
        hrWidgets.push({
          id: "time-clock",
          component: <TimeClockWidget />,
          defaultLayout: responsiveLayout({ x: 0, y: 6, w: 6, h: 3 }),
        });
      }
      return hrWidgets;
    }

    // Default Employee view
    const widgets = [
      {
        id: "announcements",
        component: <AnnouncementBoard />,
        defaultLayout: responsiveLayout({ x: 0, y: 0, w: 12, h: 3 }),
      },
      {
        id: "active-projects",
        component: <MetricWidget title="Active Projects" metricKey="active_projects" icon={"clipboard"} color="blue" subtitle="Projects you're in" href="/dashboard/projects" />,
        defaultLayout: responsiveLayout({ x: 0, y: 3, w: 2, h: 2 }),
      },
      {
        id: "pending-tasks",
        component: <MetricWidget title="Pending Tasks" metricKey="pending_tasks" icon={"clipboard"} color="amber" subtitle="Tasks assigned to you" href="/dashboard/tasks" />,
        defaultLayout: responsiveLayout({ x: 2, y: 3, w: 2, h: 2 }),
      },
      {
        id: "approval-status",
        component: <EmployeeApprovalStatusWidget />,
        defaultLayout: responsiveLayout({ x: 8, y: 3, w: 4, h: 3 }),
      },
      {
        id: "recent-task-progress",
        component: <EmployeeTaskProgressWidget />,
        defaultLayout: responsiveLayout({ x: 0, y: 5, w: 4, h: 3 }),
      },
      {
        id: "upcoming-holidays",
        component: <UpcomingHolidaysWidget />,
        defaultLayout: responsiveLayout({ x: 4, y: 5, w: 4, h: 3 }),
      },
      {
        id: "quick-notes",
        component: <QuickNotes />,
        defaultLayout: responsiveLayout({ x: 8, y: 5, w: 4, h: 3 }),
      },
    ];

    if (hasCapability(userCapabilities, "attendance.clock-self")) {
      widgets.push({
        id: "time-clock",
        component: <TimeClockWidget />,
        defaultLayout: responsiveLayout({ x: 4, y: 3, w: 4, h: 3 }),
      });
    }

    return widgets;
  }, [activeRole, userCapabilities]);

  const greetingData = useMemo(() => getGreeting(new Date(), user?.id || 0), [user?.id]);
  const firstName = user?.name?.split(" ")[0] || "Team Member";

  if (!mounted || isLoading || (!activeRole && !isError)) {
    return (
      <div className="space-y-6">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 bg-card dark:bg-neutral-900 p-6 rounded-2xl shadow-e1 border border-border">
          <div className="space-y-2">
            <Skeleton className="h-3 w-20" />
            <Skeleton className="h-8 w-48" />
            <Skeleton className="h-3 w-32" />
          </div>
          <div className="flex gap-2">
            <Skeleton className="h-10 w-24 rounded-full" />
            <Skeleton className="h-10 w-24 rounded-full" />
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <Skeleton className="h-32 rounded-xl" />
          <Skeleton className="h-32 rounded-xl" />
          <Skeleton className="h-32 rounded-xl hidden lg:block" />
          <Skeleton className="h-64 rounded-xl md:col-span-2 lg:col-span-1" />
          <Skeleton className="h-64 rounded-xl md:col-span-2" />
        </div>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="flex flex-col items-center justify-center h-[50dvh] space-y-4 bg-neutral-50 dark:bg-neutral-900/50 rounded-2xl border border-neutral-200 dark:border-neutral-800 p-8">
        <div className="w-12 h-12 rounded-full bg-rose-100 flex items-center justify-center mb-2">
          <AppIcon name="warning" className="text-rose-600 text-xl" />
        </div>
        <h3 className="font-semibold text-lg">Dashboard Unavailable</h3>
        <p className="text-sm text-neutral-500 font-medium text-center max-w-md">
          We couldn't load your dashboard data. This might be due to a network issue or an expired session.
        </p>
        <div className="flex items-center gap-3 mt-4">
          <Button onClick={() => refetch()} variant="primary" className="shadow-e1">
            <AppIcon name="refresh" className="mr-2" /> Retry Connection
          </Button>
          <Button onClick={() => useAuthStore.getState().clearAuth()} variant="outline">
            Sign Out
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 bg-card dark:bg-neutral-900 p-6 rounded-2xl text-neutral-900 dark:text-white shadow-e1 hover:shadow-e2 transition-shadow duration-150 border border-border">
        <div>
          <p className="text-[11px] font-bold uppercase tracking-wider text-neutral-500 mb-1">
            {greetingData.salutation}
          </p>
          <h1 className="text-2xl font-bold font-display text-neutral-900 dark:text-white">
            {greetingData.title}, {firstName}
          </h1>
          <p className="text-xs text-neutral-500 mt-1">
            {greetingData.subtitle}
          </p>
        </div>
      </div>


      <WidgetEngine availableWidgets={availableWidgets} />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon } from "@g4k/ui/components";
import Link from "next/link";
import { apiFetch } from "@/lib/api-client";
import { useAuthStore } from "@/lib/auth-store";
import { queryKeys } from "@/lib/query-keys";

import {
  Button,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Input,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Skeleton
} from "@g4k/ui/components";
import { DisabledWhileSubmitting } from "@g4k/ui/components/state-helpers";

export function ProfileGeneralTab() {
  const queryClient = useQueryClient();
  const authUser = useAuthStore((s) => s.user);
  const setAuth = useAuthStore((s) => s.setAuth);

  const [name, setName] = useState(authUser?.name || "");
  const [phone, setPhone] = useState("");
  const [designationId, setDesignationId] = useState("");

  const { data: profile, isLoading } = useQuery({
    queryKey: queryKeys.profile,
    queryFn: async () => {
      const data = await apiFetch("/profile");
      setName(data.name || "");
      setPhone(data.phone || "");
      setDesignationId(data.designation_id?.toString() || "");
      return data;
    },
  });

  const { data: designations } = useQuery({
    queryKey: ["designations"],
    queryFn: () => apiFetch("/designations").then((res: any) => Array.isArray(res?.data) ? res.data : (Array.isArray(res) ? res : [])),
  });

  const { data: companyProfile, isLoading: isCompanyLoading } = useQuery({
    queryKey: queryKeys.companyProfile,
    queryFn: () => apiFetch("/company-profile"),
  });

  const updateProfileMutation = useMutation({
    mutationFn: async (payload: any) => {
      return apiFetch("/profile", {
        method: "PUT",
        body: JSON.stringify(payload),
      });
    },
    onSuccess: (res: any) => {
      toast.success("Profile updated successfully!");
      if (authUser) {
        setAuth(useAuthStore.getState().token!, res, authUser.active_role);
      }
      queryClient.invalidateQueries({ queryKey: queryKeys.profile });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to update profile.");
    },
  });

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {/* Personal Details Form */}
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardHeader>
          <CardTitle className="text-base font-bold flex items-center gap-2 font-display text-foreground">
            <AppIcon name="profile" className=" text-brand-violet" />
            Personal & Contact Information
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground font-sans">
            Update your display name and phone number.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4 text-xs font-sans">
          <DisabledWhileSubmitting isSubmitting={updateProfileMutation.isPending}>
            <div className="space-y-4">
              <div>
                <label className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Full Name</label>
                <Input value={name} onChange={(e) => setName(e.target.value)} className="font-sans" />
              </div>
              <div>
                <label className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Phone Number</label>
                <Input
                  placeholder="+91 98765 43210"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  className="font-sans"
                />
              </div>
              <div>
                <label className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Designation</label>
                <Select value={designationId || "unset"} onValueChange={(v) => { setDesignationId(v === "unset" ? "" : v); }}>
                  <SelectTrigger className="w-full h-9">
                    <SelectValue placeholder="Select Designation" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="unset">Select Designation</SelectItem>
                    {designations?.map((d: any) => (
                      <SelectItem key={d.id} value={String(d.id)}>
                        {d.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="font-semibold block mb-1 text-muted-foreground">Email Address (Read-only)</label>
                <Input value={profile?.email || ""} disabled className="bg-muted/50 font-sans" />
              </div>
              <Button
                onClick={() => updateProfileMutation.mutate({ name, phone, designation_id: designationId || null })}
                disabled={updateProfileMutation.isPending}
                className="w-full mt-4 bg-neutral-900 hover:bg-neutral-800 text-white font-medium shadow-e1 font-sans"
              >
                {updateProfileMutation.isPending ? (
                  <AppIcon name="loading" className=" animate-spin animate-spin" />
                ) : (
                  "Save Personal Info"
                )}
              </Button>
            </div>
          </DisabledWhileSubmitting>
        </CardContent>
      </Card>

      {/* Company Profile (Read-Only) */}
      <Card className="border border-border shadow-e1 bg-card rounded-xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-secondary" />
        <CardHeader className="flex flex-row justify-between items-start pt-6">
          <div>
            <CardTitle className="text-base font-bold flex items-center gap-2 font-display text-foreground">
              <AppIcon name="building" className=" text-brand-violet" />
              Company Information
            </CardTitle>
            <CardDescription className="text-xs text-muted-foreground font-sans mt-1">
              General details about the organization.
            </CardDescription>
          </div>
          {authUser?.active_role === 'super_admin' && (
            <Link href="/dashboard/settings" className="text-xs font-semibold text-brand-violet flex items-center gap-1 hover:underline">
              Edit in Settings <AppIcon name="externalLink" />
            </Link>
          )}
        </CardHeader>
        <CardContent className="space-y-4 font-sans text-sm">
          {isCompanyLoading ? (
            <div className="space-y-2">
              <Skeleton className="h-4 w-1/3" />
              <Skeleton className="h-4 w-1/4" />
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <div className="text-xs font-medium text-muted-foreground mb-1">Company Name</div>
                <div className="font-semibold text-foreground">
                  {companyProfile?.name || "Games4King"}
                </div>
              </div>
              <div>
                <div className="text-xs font-medium text-muted-foreground mb-1">Short Name</div>
                <div className="font-semibold text-foreground">
                  {companyProfile?.short_name || "-"}
                </div>
              </div>
              <div className="md:col-span-2">
                <div className="text-xs font-medium text-muted-foreground mb-1">Description</div>
                <div className="text-neutral-700 dark:text-neutral-300 text-sm">
                  {companyProfile?.description || "-"}
                </div>
              </div>
              <div className="md:col-span-2">
                <div className="text-xs font-medium text-muted-foreground mb-1">Address</div>
                <div className="text-neutral-700 dark:text-neutral-300 text-sm">
                  {companyProfile?.address || "-"}
                </div>
              </div>
              <div>
                <div className="text-xs font-medium text-muted-foreground mb-1">Primary Phone</div>
                <div className="text-neutral-700 dark:text-neutral-300">
                  {companyProfile?.primary_phone || "-"}
                </div>
              </div>
              <div>
                <div className="text-xs font-medium text-muted-foreground mb-1">Email</div>
                <div className="text-neutral-700 dark:text-neutral-300">
                  {companyProfile?.email || "-"}
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useRef, useCallback } from "react";
import Image from "next/image";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { getAuthToken } from "@/lib/auth-store";
import { queryKeys } from "@/lib/query-keys";

import { Card, CardContent, Avatar, AvatarFallback, Button, Input } from "@g4k/ui/components";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";

export function ProfileHeader() {
  const queryClient = useQueryClient();
  const [isAvatarOpen, setIsAvatarOpen] = useState(false);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const { data: profile, isLoading } = useQuery({
    queryKey: queryKeys.profile,
    queryFn: async () => apiFetch("/profile"),
  });

  const handleOpenChange = (open: boolean) => {
    setIsAvatarOpen(open);
    if (!open) {
      setAvatarFile(null);
      setPreviewUrl(null);
      setIsDragging(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const uploadAvatarMutation = useMutation({
    mutationFn: async (file: File) => {
      const formData = new FormData();
      formData.append("avatar", file);

      const token = getAuthToken();
      let API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "/api";
      if (API_BASE_URL.startsWith("http") && !API_BASE_URL.endsWith("/api")) {
        API_BASE_URL = `${API_BASE_URL.replace(/\/$/, "")}/api`;
      }
      const baseUrl = API_BASE_URL.startsWith("http")
        ? API_BASE_URL.replace(/\/$/, "")
        : `${window.location.origin}${API_BASE_URL}`;

      const res = await fetch(`${baseUrl}/profile/avatar`, {
        method: "POST",
        headers: {
          ...(token ? { "Authorization": `Bearer ${token}` } : {}),
          "Accept": "application/json",
        },
        body: formData,
      });

      if (!res.ok) {
        let errMessage = "Failed to upload avatar.";
        try {
          const errorData = await res.json();
          errMessage = errorData.message || errMessage;
        } catch (e) {}
        throw new Error(errMessage);
      }
      return res.json();
    },
    onSuccess: () => {
      toast.success("Avatar updated!");
      handleOpenChange(false);
      queryClient.invalidateQueries({ queryKey: queryKeys.profile });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to upload avatar.");
    },
  });

  const handleFile = (file: File | undefined) => {
    if (!file) return;
    if (!["image/jpeg", "image/png", "image/webp", "image/jpg", "image/gif", "image/svg+xml"].includes(file.type)) {
      toast.error("Please select a valid image file (JPEG, PNG, WEBP, GIF, SVG).");
      return;
    }
    if (file.size > 2 * 1024 * 1024) {
      toast.error("File size must be 2MB or less.");
      return;
    }
    setAvatarFile(file);
    setPreviewUrl(URL.createObjectURL(file));
  };

  const onDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const onDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    handleFile(e.dataTransfer.files?.[0]);
  }, []);

  return (
    <>
      {/* Header Profile Card */}
      <Card className="border border-border shadow-e1 overflow-hidden bg-card rounded-xl relative">
        <div className="absolute top-0 left-0 w-full h-1.5 bg-primary-600" />
        <CardContent className="p-6 sm:p-8 flex flex-col sm:flex-row items-center sm:items-start gap-6 bg-brand-violet/5 dark:bg-brand-violet/10">
          <div className="relative group shrink-0">
            <div className="w-24 h-24 rounded-full bg-card border-2 border-brand-violet flex items-center justify-center font-bold text-3xl shadow-e1 overflow-hidden text-brand-violet">
              {profile?.avatar_url ? (
                <Image
                  src={profile.avatar_url}
                  alt={profile.name || "User"}
                  width={96}
                  height={96}
                  className="w-full h-full object-cover"
                />
              ) : (
                <Avatar className="w-full h-full">
                  <AvatarFallback name={profile?.name || ""} className="text-4xl" />
                </Avatar>
              )}
            </div>
            <button
              onClick={() => setIsAvatarOpen(true)}
              className="absolute inset-0 bg-black/60 rounded-full opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity text-white text-xs font-semibold gap-1 backdrop-blur-sm"
            >
              <AppIcon name="upload" />
              <span>Upload</span>
            </button>
          </div>

          <div className="space-y-2 text-center sm:text-left flex-1">
            <div className="flex flex-col sm:flex-row items-center sm:items-start justify-between gap-2">
              <div>
                <h1 className="text-2xl font-bold font-display text-foreground">
                  {isLoading && !profile ? <Skeleton className="h-8 w-48 mb-2" /> : (profile?.name || "Your Profile")}
                </h1>
                <div className="flex flex-wrap items-center gap-4 text-sm font-sans mt-2">
                  <div className="flex items-center text-muted-foreground bg-surface/50 dark:bg-neutral-900/50 px-3 py-1 rounded-full border border-border">
                    <AppIcon name="hash" className=" mr-2 text-brand-violet/70" />
                    {isLoading && !profile ? <Skeleton className="h-4 w-24" /> : (profile?.employee_id || "Employee ID: N/A")}
                  </div>
                  <div className="flex items-center text-muted-foreground bg-surface/50 dark:bg-neutral-900/50 px-3 py-1 rounded-full border border-border">
                    <AppIcon name="building" className=" mr-2 text-brand-violet/70" />
                    {isLoading && !profile ? <Skeleton className="h-4 w-32" /> : (profile?.department?.name || "No Department")}
                  </div>
                  <div className="flex items-center text-muted-foreground bg-surface/50 dark:bg-neutral-900/50 px-3 py-1 rounded-full border border-border">
                    <AppIcon name="briefcase" className=" mr-2 text-brand-violet/70" />
                    {isLoading && !profile ? <Skeleton className="h-4 w-32" /> : (profile?.designation?.name || "No Designation")}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex flex-wrap justify-center sm:justify-start gap-4 pt-3 text-xs text-muted-foreground font-medium">
              <span className="flex items-center gap-1.5 bg-card px-2 py-1 rounded-[var(--radius)] border border-border shadow-e1">
                <AppIcon name="mail" className=" .5 .5 text-brand-violet" />
                {profile?.email}
              </span>
              {profile?.phone && (
                <span className="flex items-center gap-1.5 bg-card px-2 py-1 rounded-[var(--radius)] border border-border shadow-e1">
                  <AppIcon name="phone" className=" .5 .5 text-brand-violet" />
                  {profile.phone}
                </span>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Avatar Upload Dialog */}
      <Dialog open={isAvatarOpen} onOpenChange={handleOpenChange}>
        <DialogContent className="sm:max-w-md font-sans">
          <DialogHeader>
            <DialogTitle className="font-display">Upload Profile Photo</DialogTitle>
            <DialogDescription className="text-xs font-sans">
              Choose a clear photo so your team can easily recognize you.
            </DialogDescription>
          </DialogHeader>

          <div className="py-2">
            {!previewUrl ? (
              <div
                onDragOver={onDragOver}
                onDragLeave={onDragLeave}
                onDrop={onDrop}
                onClick={() => fileInputRef.current?.click()}
                className={`w-full h-48 border-2 border-dashed rounded-xl flex flex-col items-center justify-center cursor-pointer transition-colors ${
                  isDragging ? "border-brand-violet bg-brand-violet/5" : "border-neutral-200 dark:border-neutral-800 hover:bg-neutral-50 dark:hover:bg-neutral-900"
                }`}
              >
                <div className="bg-neutral-100 dark:bg-neutral-800 p-3 rounded-full mb-3">
                  <AppIcon name="upload" className="text-neutral-500 w-6 h-6" />
                </div>
                <p className="text-sm font-medium text-neutral-700 dark:text-neutral-300">Click or drag and drop</p>
                <p className="text-xs text-neutral-500 mt-1">SVG, PNG, JPG or GIF (max. 2MB)</p>
              </div>
            ) : (
              <div className="w-full flex flex-col items-center py-4 relative">
                <div className="w-32 h-32 rounded-full overflow-hidden border-4 border-white dark:border-neutral-950 shadow-lg relative group">
                  <Image src={previewUrl} alt="Preview" fill className="object-cover" />
                  <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-white hover:text-white hover:bg-white/20"
                      onClick={(e) => {
                        e.stopPropagation();
                        fileInputRef.current?.click();
                      }}
                    >
                      <AppIcon name="edit" size="sm" className="mr-1" /> Change
                    </Button>
                  </div>
                </div>
                <Button 
                  variant="ghost" 
                  size="sm" 
                  className="mt-4 text-red-500 hover:text-red-600 hover:bg-red-50"
                  onClick={() => {
                    setAvatarFile(null);
                    setPreviewUrl(null);
                    if (fileInputRef.current) fileInputRef.current.value = "";
                  }}
                >
                  <AppIcon name="trash" size="sm" className="mr-1" /> Remove Photo
                </Button>
              </div>
            )}
            
            <input
              type="file"
              ref={fileInputRef}
              accept="image/jpeg,image/png,image/webp,image/jpg,image/gif,image/svg+xml"
              className="hidden"
              onChange={(e) => handleFile(e.target.files?.[0])}
            />
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => handleOpenChange(false)} className="font-sans">
              Cancel
            </Button>
            <Button
              onClick={() => avatarFile && uploadAvatarMutation.mutate(avatarFile)}
              disabled={uploadAvatarMutation.isPending || !avatarFile}
              className="bg-neutral-900 hover:bg-neutral-800 text-white font-sans shadow-e1"
            >
              {uploadAvatarMutation.isPending ? (
                <>
                  <AppIcon name="loading" className="mr-2 animate-spin" /> Uploading...
                </>
              ) : (
                "Save Photo"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

