"use client";

import { useState, useEffect } from "react";
import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { AppIcon } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { useAuthStore } from "@/lib/auth-store";
import { useUIStore } from "@/lib/ui-store";

import {
  Button,
  Input,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@g4k/ui/components";

export function ProfilePreferencesTab() {
  const router = useRouter();
  const authUser = useAuthStore((s) => s.user);
  const setAuth = useAuthStore((s) => s.setAuth);
  
  const restoreWidgets = useUIStore((s) => s.restoreWidgets);
  const dismissedWidgetsCount = useUIStore((s) => s.dismissedWidgets?.length ?? 0);

  const [visibility, setVisibility] = useState(authUser?.preferences?.directory_visibility || "internal");

  useEffect(() => {
    if (authUser?.preferences?.directory_visibility) {
      setVisibility(authUser.preferences.directory_visibility);
    }
  }, [authUser?.preferences?.directory_visibility]);

  const updateVisibilityMutation = useMutation({
    mutationFn: async (val: string) => {
      return apiFetch("/auth/preferences", {
        method: "PUT",
        body: JSON.stringify({ directory_visibility: val }),
      });
    },
    onSuccess: (res: any) => {
      toast.success("Visibility preference updated!");
      if (authUser) {
        setAuth(useAuthStore.getState().token!, { ...authUser, preferences: res.preferences }, authUser.active_role);
      }
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to update preference.");
    },
  });

  const handleVisibilityChange = (val: string) => {
    setVisibility(val);
    updateVisibilityMutation.mutate(val);
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
      {/* Privacy & Visibility Preferences */}
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardHeader>
          <CardTitle className="text-base font-bold flex items-center gap-2 font-display text-foreground">
            <AppIcon name="eye" className=" text-brand-violet" />
            Privacy & Visibility
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground font-sans">
            Control who can see your contact information in the company directory.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4 text-xs font-sans">
          <div className="grid grid-cols-1 gap-2">
            <button
              onClick={() => handleVisibilityChange("public")}
              disabled={updateVisibilityMutation.isPending}
              className={`p-3 text-left border rounded-[var(--radius)] transition-colors ${visibility === "public" ? "border-brand-violet bg-brand-violet/5" : "border-border hover:bg-neutral-50 dark:hover:bg-neutral-800/50"}`}
            >
              <div className="font-semibold text-foreground mb-0.5">Public</div>
              <div className="text-muted-foreground text-[11px]">Phone and email visible to all users.</div>
            </button>
            <button
              onClick={() => handleVisibilityChange("internal")}
              disabled={updateVisibilityMutation.isPending}
              className={`p-3 text-left border rounded-[var(--radius)] transition-colors ${visibility === "internal" ? "border-brand-violet bg-brand-violet/5" : "border-border hover:bg-neutral-50 dark:hover:bg-neutral-800/50"}`}
            >
              <div className="font-semibold text-foreground mb-0.5">Internal Only</div>
              <div className="text-muted-foreground text-[11px]">Contact info visible only to your department & HR.</div>
            </button>
            <button
              onClick={() => handleVisibilityChange("private")}
              disabled={updateVisibilityMutation.isPending}
              className={`p-3 text-left border rounded-[var(--radius)] transition-colors ${visibility === "private" ? "border-brand-violet bg-brand-violet/5" : "border-border hover:bg-neutral-50 dark:hover:bg-neutral-800/50"}`}
            >
              <div className="font-semibold text-foreground mb-0.5">Private</div>
              <div className="text-muted-foreground text-[11px]">Contact info completely hidden from directory.</div>
            </button>
          </div>
        </CardContent>
      </Card>

      {/* Dashboard Preferences */}
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardHeader>
          <CardTitle className="text-base font-bold flex items-center gap-2 font-display text-foreground">
            <AppIcon name="dashboard" className=" text-brand-violet" />
            Dashboard Preferences
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground font-sans">
            Manage your dashboard widgets and layout.
          </CardDescription>
        </CardHeader>
        <CardContent className="text-xs font-sans space-y-4">
          <div className="flex items-center justify-between p-3 border border-border rounded-[var(--radius)] bg-neutral-50 dark:bg-neutral-800/50">
            <div>
              <div className="font-semibold text-foreground mb-0.5">Hidden Widgets</div>
              <div className="text-muted-foreground text-[11px]">You have {dismissedWidgetsCount} hidden widget(s) on your dashboard.</div>
            </div>
            <Button 
              variant="outline" 
              size="sm" 
              onClick={() => {
                restoreWidgets();
                toast.success("Dashboard widgets restored to default.");
              }}
              disabled={dismissedWidgetsCount === 0}
            >
              Restore Defaults
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Feedback & Complaints Form */}
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardHeader>
          <CardTitle className="text-base font-bold flex items-center gap-2 font-display text-foreground">
            <AppIcon name="mail" className=" text-brand-violet" />
            Submit Feedback or Complaint
          </CardTitle>
          <CardDescription className="text-xs text-muted-foreground font-sans">
            Send direct feedback or file a complaint to HR.
          </CardDescription>
        </CardHeader>
        <CardContent className="text-xs font-sans">
          <form
            onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              const subject = formData.get('subject') as string;
              const category = formData.get('category') as string;
              const body = formData.get('body') as string;
              if (!subject || !category || !body) {
                toast.error("Please fill all fields");
                return;
              }
              apiFetch('/feedback', {
                method: 'POST',
                body: JSON.stringify({ subject, category, body })
              }).then((res) => {
                toast.success("Feedback submitted successfully. HR will contact you via direct message.");
                (e.target as HTMLFormElement).reset();
                if (res.conversation_id) {
                  router.push(`/dashboard/chat?conversation=${res.conversation_id}`);
                }
              }).catch((err) => {
                toast.error(err.message || "Failed to submit feedback");
              });
            }}
            className="space-y-4"
          >
            <div>
              <label htmlFor="fb-category" className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Category</label>
              <select id="fb-category" name="category" className="w-full h-9 rounded-[var(--radius)] border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring">
                <option value="suggestion">Suggestion</option>
                <option value="complaint">Complaint</option>
              </select>
            </div>
            <div>
              <label htmlFor="fb-subject" className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Subject</label>
              <Input id="fb-subject" name="subject" placeholder="What is this about?" required />
            </div>
            <div>
              <label htmlFor="fb-body" className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Details</label>
              <textarea id="fb-body" name="body" required rows={4} className="w-full rounded-[var(--radius)] border border-input bg-transparent px-3 py-2 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring resize-none" placeholder="Please provide details..."></textarea>
            </div>
            <Button type="submit" className="w-full bg-neutral-900 hover:bg-neutral-800 text-white shadow-e1">
              Submit to HR
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { useAuthStore } from "@/lib/auth-store";
import { strongPasswordSchema } from "@/lib/validations";
import { parseUserAgent } from "@/lib/utils";
import { ColumnDef } from "@tanstack/react-table";
import { queryKeys } from "@/lib/query-keys";

import {
  Button,
  PasswordInput,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  ConfirmDialog,
  DataTable
} from "@g4k/ui/components";
import { DisabledWhileSubmitting } from "@g4k/ui/components/state-helpers";

export function ProfileSecurityTab() {
  const queryClient = useQueryClient();
  const authUser = useAuthStore((s) => s.user);

  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const [isRevokeOpen, setIsRevokeOpen] = useState(false);
  const [revokeId, setRevokeId] = useState<string | null>(null);

  const { data: sessions } = useQuery({
    queryKey: queryKeys.sessions,
    queryFn: async () => apiFetch("/auth/sessions"),
  });

  const changePasswordMutation = useMutation({
    mutationFn: async () => {
      if (newPassword !== confirmPassword) {
        throw new Error("New passwords do not match.");
      }
      const valResult = strongPasswordSchema.safeParse(newPassword);
      if (!valResult.success) {
        throw new Error(valResult.error.issues[0]?.message || "Invalid password.");
      }
      return apiFetch("/auth/change-password", {
        method: "POST",
        body: JSON.stringify({
          current_password: currentPassword,
          password: newPassword,
          password_confirmation: confirmPassword,
        }),
      });
    },
    onSuccess: () => {
      toast.success("Password updated!");
      setCurrentPassword("");
      setNewPassword("");
      setConfirmPassword("");
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to change password.");
    },
  });

  const revokeSessionMutation = useMutation({
    mutationFn: async (sessionId: string) => {
      return apiFetch(`/auth/sessions/${sessionId}`, { method: "DELETE" });
    },
    onSuccess: () => {
      toast.success("Session revoked!");
      queryClient.invalidateQueries({ queryKey: queryKeys.sessions });
      setIsRevokeOpen(false);
      setRevokeId(null);
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to revoke session.");
    },
  });

  const columns: ColumnDef<any>[] = [
    {
      accessorKey: "device_name",
      header: "Device / Browser",
      cell: ({ row }) => (
        <div className="flex flex-col min-w-[120px]">
          <div className="flex items-center gap-2 font-semibold text-foreground">
            <AppIcon name="laptop" className=" text-brand-violet shrink-0" />
            <span className="truncate">{row.original.device_name || "Unknown Device"}</span>
          </div>
          {row.original.user_agent && (
            <span className="text-[10px] text-muted-foreground mt-0.5 ml-6">
              {parseUserAgent(row.original.user_agent)}
            </span>
          )}
        </div>
      ),
    },
    {
      accessorKey: "ip_address",
      header: "IP Address",
      cell: ({ row }) => (
        <span className="text-muted-foreground font-mono text-xs">{row.original.ip_address || "Unknown"}</span>
      ),
    },
    {
      accessorKey: "last_used_at",
      header: "Last Used",
      cell: ({ row }) => (
        <span className="text-muted-foreground text-xs">
          {row.original.last_used_at ? new Date(row.original.last_used_at).toLocaleString() : "Recently"}
        </span>
      ),
    },
    {
      accessorKey: "status",
      header: "Status",
      cell: ({ row }) => {
        if (row.original.is_current) {
          return (
            <span className="px-2.5 py-1 rounded-[var(--radius)] text-[10px] font-bold bg-green-100 text-green-700 dark:bg-green-500/10 dark:text-green-400 border border-green-200 dark:border-green-500/20 whitespace-nowrap">
              Current Device
            </span>
          );
        }
        return <span className="text-muted-foreground text-[11px] font-medium">Active</span>;
      },
    },
    {
      id: "actions",
      header: () => <div className="text-right">Action</div>,
      cell: ({ row }) => {
        if (row.original.is_current) return null;
        return (
          <div className="text-right">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                setRevokeId(row.original.id);
                setIsRevokeOpen(true);
              }}
              className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-500/10 font-medium"
            >
              <AppIcon name="trash" className=" mr-1" />
              <span>Revoke</span>
            </Button>
          </div>
        );
      },
    },
  ];

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {/* Password Security Form */}
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardHeader>
          <div className="flex justify-between items-start gap-4">
            <div>
              <CardTitle className="text-base font-bold flex items-center gap-2 font-display text-foreground">
                <AppIcon name="key" className=" text-brand-violet" />
                Security & Password
              </CardTitle>
              <CardDescription className="text-xs text-muted-foreground font-sans mt-1">
                Change your password and manage two-factor authentication.
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="text-xs font-sans">
          <form
            className="space-y-4"
            onSubmit={(e) => {
              e.preventDefault();
              if (!changePasswordMutation.isPending && currentPassword && newPassword && confirmPassword) {
                changePasswordMutation.mutate();
              }
            }}
          >
            <DisabledWhileSubmitting isSubmitting={changePasswordMutation.isPending}>
              <div className="space-y-4">
                <input type="text" name="username" value={authUser?.email || ""} autoComplete="username" className="hidden" readOnly />
                <div>
                  <label className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Current Password</label>
                  <PasswordInput
                    placeholder="Current password"
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    className="font-sans"
                    autoComplete="current-password"
                  />
                </div>
                <div>
                  <label className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">New Password</label>
                  <PasswordInput
                    placeholder="New password (min 8 chars, mixed case, numbers, symbols)"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="font-sans"
                    autoComplete="new-password"
                  />
                </div>
                <div>
                  <label className="font-semibold block mb-1 text-neutral-700 dark:text-neutral-300">Confirm New Password</label>
                  <PasswordInput
                    placeholder="Confirm new password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="font-sans"
                    autoComplete="new-password"
                  />
                </div>
                <Button
                  type="submit"
                  disabled={
                    changePasswordMutation.isPending ||
                    !currentPassword ||
                    !newPassword ||
                    !confirmPassword
                  }
                  className="w-full mt-4 bg-neutral-900 hover:bg-neutral-800 text-white font-medium shadow-e1 font-sans"
                >
                  {changePasswordMutation.isPending ? (
                    <AppIcon name="loading" className=" animate-spin animate-spin" />
                  ) : (
                    "Update Password"
                  )}
                </Button>
              </div>
            </DisabledWhileSubmitting>
          </form>
        </CardContent>
      </Card>

      {/* Active Device Sessions */}
      <Card className="border border-border shadow-e1 bg-card rounded-xl lg:col-span-2">
        <CardHeader className="flex flex-row justify-between items-start">
          <div>
            <CardTitle className="text-base font-bold flex items-center gap-2 font-display text-foreground">
              <AppIcon name="laptop" className=" text-brand-violet" />
              Active Device Sessions
            </CardTitle>
            <CardDescription className="text-xs text-muted-foreground font-sans mt-1">
              Devices currently logged into your Games4King Workplace OS account. Revoking a session will immediately log out that device.
            </CardDescription>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={async () => {
              try {
                await apiFetch("/auth/logout", { method: "POST" });
                toast.success("Logged out successfully");
                window.location.href = "/login";
              } catch (e: any) {
                toast.error(e.message || "Logout failed");
              }
            }}
            className="text-xs text-rose-600 hover:text-rose-700 hover:bg-rose-50 border-rose-200 shrink-0"
          >
            Log Out Current Device
          </Button>
        </CardHeader>
        <CardContent className="p-0 overflow-x-auto border-t border-border dark:border-neutral-800">
          <DataTable
            columns={columns}
            data={sessions || []}
          />
        </CardContent>
      </Card>

      <ConfirmDialog
        open={isRevokeOpen}
        onOpenChange={(open) => {
          if (!open) {
            setIsRevokeOpen(false);
            setRevokeId(null);
          }
        }}
        onConfirm={() => {
          if (revokeId) {
            revokeSessionMutation.mutate(revokeId);
          }
        }}
        title="Revoke Session"
        description="Are you sure you want to log out this device? Any unsaved work on that device may be lost."
        confirmText="Revoke Device"
        isLoading={revokeSessionMutation.isPending}
      />
    </div>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { AppIcon } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { Card, CardContent } from "@g4k/ui/components";

export function ProfileStats() {
  const { data: attendanceHistory } = useQuery({
    queryKey: ["attendance-history-me"],
    queryFn: () => apiFetch("/attendance/me/history?limit=31"),
  });

  const { data: leaveHistory } = useQuery({
    queryKey: ["leave-history-me"],
    queryFn: () => apiFetch("/leave-requests/history?per_page=100"),
  });

  const { data: activeTasks } = useQuery({
    queryKey: ["tasks-me"],
    queryFn: () => apiFetch("/tasks"),
  });

  // Calculate summaries
  const attendanceData = attendanceHistory?.data || [];
  const presentCount = attendanceData.filter((r: any) => ["present", "late", "half_day"].includes(r.status)).length;
  const absentCount = attendanceData.filter((r: any) => r.status === "absent").length;
  const lateCount = attendanceData.filter((r: any) => r.status === "late").length;

  const leaveData = leaveHistory?.data || [];
  const approvedLeaves = leaveData.filter((l: any) => l.approval?.status === "approved").length;
  const pendingLeaves = leaveData.filter((l: any) => !l.approval || l.approval.status === "pending").length;

  const taskData = activeTasks?.data || [];
  const pendingTasks = taskData.filter((t: any) => t.status === "pending" || t.status === "in_progress").length;
  const completedTasks = taskData.filter((t: any) => t.status === "completed").length;

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardContent className="p-4 flex items-center gap-4">
          <div className="p-3 bg-blue-50 dark:bg-blue-500/10 text-blue-600 dark:text-blue-400 rounded-[var(--radius)] shrink-0">
            <AppIcon name="calendar" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-foreground">My Attendance (Recent)</h3>
            <p className="text-xs text-muted-foreground mt-0.5">
              <span className="font-medium text-emerald-600 dark:text-emerald-400">{presentCount} Present</span> •{" "}
              <span className="font-medium text-amber-600 dark:text-amber-400">{lateCount} Late</span> •{" "}
              <span className="font-medium text-rose-600 dark:text-rose-400">{absentCount} Absent</span>
            </p>
          </div>
        </CardContent>
      </Card>
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardContent className="p-4 flex items-center gap-4">
          <div className="p-3 bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-400 rounded-[var(--radius)] shrink-0">
            <AppIcon name="fileText" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-foreground">My Leave Summary</h3>
            <p className="text-xs text-muted-foreground mt-0.5">
              <span className="font-medium text-emerald-600 dark:text-emerald-400">{approvedLeaves} Approved</span> •{" "}
              <span className="font-medium text-amber-600 dark:text-amber-400">{pendingLeaves} Pending</span>
            </p>
          </div>
        </CardContent>
      </Card>
      <Card className="border border-border shadow-e1 bg-card rounded-xl">
        <CardContent className="p-4 flex items-center gap-4">
          <div className="p-3 bg-primary-50 dark:bg-primary-500/10 text-primary-600 dark:text-primary-400 rounded-[var(--radius)] shrink-0">
            <AppIcon name="tasks" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-foreground">My Active Tasks</h3>
            <p className="text-xs text-muted-foreground mt-0.5">
              <span className="font-medium text-primary-600 dark:text-primary-400">{pendingTasks} Active</span> •{" "}
              <span className="font-medium text-emerald-600 dark:text-emerald-400">{completedTasks} Completed</span>
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useParams, useRouter } from "next/navigation";
import { useState, useRef } from "react";
import { format } from "date-fns";
import { useVirtualizer } from "@tanstack/react-virtual";
import { safeFormat } from "@/lib/format";
import { AppIcon, IconName } from "@g4k/ui/components";
import { QAFieldRenderer } from "@/components/projects/qa-field-renderer";
import { toast } from "sonner";
import { apiFetch, unwrapOne, unwrapList } from "@/lib/api-client";
import { useCapabilities, hasCapability } from "@/lib/capabilities";
import { Button, Input, Textarea, Skeleton, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, DatePicker, Checkbox, Avatar, AvatarFallback, FileUploadPopup, DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem, ConfirmDialog } from "@g4k/ui/components";
import { Card, CardContent, CardHeader, CardTitle, Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@g4k/ui/components";
import { TasksTab } from "@/components/projects/tasks-tab";
import { queryKeys } from "@/lib/query-keys";

export default function ProjectDetailPage() {
  const params = useParams();
  const router = useRouter();
  const queryClient = useQueryClient();
  const { data: caps } = useCapabilities();
  const projectId = params.id as string;
  const [submissionNote, setSubmissionNote] = useState("");
  const [activeTab, setActiveTab] = useState<"overview" | "tasks">("overview");
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [isDeleteConfirmOpen, setIsDeleteConfirmOpen] = useState(false);
  const [editForm, setEditForm] = useState<any>({ name: "", description: "", priority: "", department_id: "none", qa_form_id: "none", deadline: "", member_ids: [], allow_employee_tasks: false, cover_image: null });
  const [showUploadPopup, setShowUploadPopup] = useState(false);
  const [qaValues, setQaValues] = useState<any>({});
  const [showQaErrors, setShowQaErrors] = useState(false);

  const { data: deptsData } = useQuery({ queryKey: ["departments"], queryFn: () => apiFetch("/departments") });
  const { data: qaFormsData } = useQuery({ queryKey: queryKeys.qaForms, queryFn: () => apiFetch("/qa-forms") });
  const { data: usersData } = useQuery({ queryKey: queryKeys.usersList, queryFn: () => apiFetch("/users") });
  // /departments, /users and /qa-forms may return Laravel paginators ({ data: [...] }) — unwrap to plain arrays
  const departments = unwrapList(deptsData);
  const qaForms = unwrapList(qaFormsData);
  const users = unwrapList(usersData);
  const { data: projectResponse, isLoading } = useQuery({
    queryKey: queryKeys.project(projectId),
    queryFn: () => apiFetch(`/projects/${projectId}`),
  });
  const { data: historyResponse } = useQuery({
    queryKey: [...queryKeys.project(projectId), "history"],
    queryFn: () => apiFetch(`/projects/${projectId}/history`),
  });
  const projectHistory = unwrapList(historyResponse);

  const historyParentRef = useRef<HTMLDivElement>(null);
  const rowVirtualizer = useVirtualizer({
    count: projectHistory.length,
    getScrollElement: () => historyParentRef.current,
    estimateSize: () => 50,
    overscan: 5,
  });

  const project: any = unwrapOne(projectResponse);
  const submitProjectMutation = useMutation({
    mutationFn: async () => {
      // QA enforcement: every field marked required in the qa_form must have a non-empty value
      const missingQaLabels = (project?.qa_form?.fields || [])
        .filter((field: any) => field.required && !String(qaValues[field.id] ?? "").trim())
        .map((field: any) => field.label);
        
      if (project?.qa_form_id && missingQaLabels.length > 0) {
        throw new Error(`Please fill in the required QA fields: ${missingQaLabels.join(", ")}.`);
      }
      return apiFetch(`/projects/${projectId}/submit`, {
        method: "POST",
        body: JSON.stringify({ 
          notes: submissionNote,
          qa_values: Object.keys(qaValues).length > 0 ? qaValues : null,
        }),
      });
    },
    onSuccess: () => {
      toast.success("Project submitted for review.");
      queryClient.invalidateQueries({ queryKey: queryKeys.project(projectId) });
      setSubmissionNote("");
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to submit project.");
    },
  });

  const updateProjectMutation = useMutation({
    mutationFn: async () => {
      return apiFetch(`/projects/${projectId}`, {
        method: "PUT",
        body: JSON.stringify({
          ...editForm,
          department_id: editForm.department_id === "none" ? null : editForm.department_id,
          qa_form_id: editForm.qa_form_id === "none" ? null : editForm.qa_form_id,
        }),
      });
    },
    onSuccess: () => {
      toast.success("Project updated successfully.");
      setIsEditOpen(false);
      queryClient.invalidateQueries({ queryKey: queryKeys.project(projectId) });
      queryClient.invalidateQueries({ queryKey: queryKeys.projects() });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to update project.");
    },
  });

  const deleteProjectMutation = useMutation({
    mutationFn: async () => {
      return apiFetch(`/projects/${projectId}`, { method: "DELETE" });
    },
    onSuccess: () => {
      toast.success("Project deleted.");
      queryClient.invalidateQueries({ queryKey: queryKeys.projects() });
      router.push("/dashboard/projects");
    },
    onError: (err: any) => toast.error(err.message || "Failed to delete project."),
  });

  const archiveProjectMutation = useMutation({
    mutationFn: async () => {
      return apiFetch(`/projects/${projectId}`, {
        method: "PUT",
        body: JSON.stringify({ status: "archived" }),
      });
    },
    onSuccess: () => {
      toast.success("Project archived.");
      queryClient.invalidateQueries({ queryKey: queryKeys.project(projectId) });
      queryClient.invalidateQueries({ queryKey: queryKeys.projects() });
    },
    onError: (err: any) => toast.error(err.message || "Failed to archive project."),
  });

  const reviewProjectMutation = useMutation({
    // T-46.4: BE ProjectController validates `decision` field, not `status`
    mutationFn: async (decision: "approved" | "redo") => {
      return apiFetch(`/projects/${projectId}/review`, {
        method: "POST",
        body: JSON.stringify({ decision }),
      });
    },
    onSuccess: (_, decision) => {
      toast.success(`Project ${decision === 'approved' ? 'approved' : 'sent back for rework'}.`);
      queryClient.invalidateQueries({ queryKey: queryKeys.project(projectId) });
      queryClient.invalidateQueries({ queryKey: queryKeys.projects() });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
    onError: (err: any) => {
      toast.error(err.message || "Review failed.");
    },
  });



  if (!isLoading && !project) return <div>Project not found</div>;

  return (
    <div className="space-y-6 relative">
      {project?.cover_image && (
        <div className="w-full h-48 rounded-xl overflow-hidden mb-6 border border-neutral-200 dark:border-neutral-800 shadow-sm relative">
          <div className="absolute inset-0 bg-gradient-to-t from-background/90 to-transparent dark:from-background/90 z-10" />
          <img src={project.cover_image} alt="Project Cover" className="w-full h-full object-cover" />
        </div>
      )}
      <div className={`flex items-center gap-3 justify-between ${project?.cover_image ? '-mt-16 relative z-20 px-4' : ''}`}>
        <div className="flex items-center gap-3">
          <Button variant="outline" size="sm" onClick={() => router.push("/dashboard/projects")} className="h-8 bg-background/50 backdrop-blur-sm">
            <AppIcon name="arrowLeft" className=" mr-1" /> Back
          </Button>
          <div>
            <h1 className="text-xl font-bold flex items-center gap-2">
              <AppIcon name="archive" className=" w-5 h-5 text-primary-600" />
              {project ? project.name : <Skeleton className="h-6 w-48" />}
            </h1>
            <p className="text-sm text-neutral-500">
              {project ? (project.description || "No description.") : <Skeleton className="h-4 w-64" />}
            </p>
          </div>
        </div>
        
        {hasCapability(caps, "projects.manage") && (
          <div className="flex items-center gap-2">
            <Button 
              variant="outline" 
              size="sm" 
              className="h-8"
              onClick={() => {
                setEditForm({ 
                  name: project.name, 
                  description: project.description || "", 
                  priority: project.priority,
                  department_id: project.department_id?.toString() || "none",
                  qa_form_id: project.qa_form_id?.toString() || "none",
                  deadline: project.deadline || "",
                  member_ids: project.members?.map((m: any) => m.id) || [],
                  allow_employee_tasks: project.allow_employee_tasks || false,
                  cover_image: project.cover_image || null,
                });
                setIsEditOpen(true);
              }}
            >
              <AppIcon name="edit" className=" mr-2" /> Edit Project
            </Button>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm" className="h-8 w-8 p-0">
                  <AppIcon name="moreH" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onClick={() => archiveProjectMutation.mutate()} disabled={archiveProjectMutation.isPending || project.status === "archived"}>
                  <AppIcon name="archive" className="mr-2 h-4 w-4" />
                  Archive Project
                </DropdownMenuItem>
                <DropdownMenuItem className="text-red-600 focus:text-red-600" onClick={() => setIsDeleteConfirmOpen(true)} disabled={deleteProjectMutation.isPending}>
                  <AppIcon name="trash" className="mr-2 h-4 w-4" />
                  Delete Project
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        )}
      </div>

      <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Project</DialogTitle>
            <DialogDescription className="sr-only">Edit project details and settings.</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4 max-h-[70dvh] overflow-y-auto px-1">
            <div className="space-y-1">
              <label className="text-xs font-medium">Name</label>
              <Input 
                value={editForm.name} 
                onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} 
                placeholder="Project name" 
                className="text-xs"
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-medium">Description</label>
              <Textarea 
                value={editForm.description} 
                onChange={(e: any) => setEditForm({ ...editForm, description: e.target.value })} 
                placeholder="Project description"
                className="text-xs resize-none"
                rows={3} 
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-medium">Priority</label>
                <Select
                  value={editForm.priority}
                  onValueChange={(val) => setEditForm({ ...editForm, priority: val })}
                >
                  <SelectTrigger className="w-full bg-surface text-xs h-9">
                    <SelectValue placeholder="Select priority" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                    <SelectItem value="urgent">Urgent</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium">Department</label>
                <Select value={editForm.department_id} onValueChange={(val) => setEditForm({ ...editForm, department_id: val })}>
                  <SelectTrigger className="w-full text-xs h-9">
                    <SelectValue placeholder="No Department" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">-- Global / No Dept --</SelectItem>
                    {departments?.map((dept: any) => (
                      <SelectItem key={dept.id} value={dept.id.toString()}>{dept.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1 flex flex-col">
                <label className="text-xs font-semibold text-neutral-500">Deadline</label>
                <DatePicker
                  value={editForm.deadline ? new Date(editForm.deadline) : undefined}
                  onChange={(d) => setEditForm({ ...editForm, deadline: d ? format(d, "yyyy-MM-dd") : "" })}
                  placeholder="Select deadline"
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium">QA Form</label>
                <Select value={editForm.qa_form_id} onValueChange={(val) => setEditForm({ ...editForm, qa_form_id: val })}>
                  <SelectTrigger className="w-full text-xs h-9">
                    <SelectValue placeholder="None" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">-- None --</SelectItem>
                    {qaForms?.map((qa: any) => (
                      <SelectItem key={qa.id} value={qa.id.toString()}>{qa.title}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2 pt-2 border-t border-border">
              <label className="text-xs font-medium flex justify-between items-center">
                <span>Manage Team Members</span>
              </label>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 border border-input rounded-[var(--radius)] p-2 max-h-[150px] overflow-y-auto">
                {users?.map((u: any) => (
                  <label key={u.id} className="flex items-center gap-2 p-1.5 hover:bg-neutral-50 dark:hover:bg-neutral-900 rounded cursor-pointer text-xs">
                    <Checkbox
                      checked={editForm.member_ids.includes(u.id)}
                      onCheckedChange={(checked) => {
                        if (checked) {
                          setEditForm({ ...editForm, member_ids: [...editForm.member_ids, u.id] });
                        } else {
                          setEditForm({ ...editForm, member_ids: editForm.member_ids.filter((id: number) => id !== u.id) });
                        }
                      }}
                    />
                    <Avatar className="w-5 h-5">
                      {u.avatar_url && <img src={u.avatar_url} alt={u.name} />}
                      <AvatarFallback name={u.name} className="text-[9px]" />
                    </Avatar>
                    <span className="truncate">{u.name}</span>
                  </label>
                ))}
              </div>
            </div>

            <div className="flex items-center space-x-2 pt-2">
              <Checkbox 
                id="edit-allow-employee-tasks" 
                checked={editForm.allow_employee_tasks}
                onCheckedChange={(c) => setEditForm({ ...editForm, allow_employee_tasks: !!c })}
              />
              <label htmlFor="edit-allow-employee-tasks" className="text-xs font-medium leading-none cursor-pointer">
                Allow employees to create tasks
              </label>
            </div>

            <div className="pt-2 border-t border-border">
              <label className="text-xs font-semibold text-neutral-500 mb-2 block">Project Cover Image</label>
              {editForm.cover_image ? (
                <div className="relative w-full h-24 rounded-lg overflow-hidden border border-neutral-200 dark:border-neutral-800">
                  <img src={editForm.cover_image} alt="Cover" className="w-full h-full object-cover" />
                  <Button
                    size="sm"
                    variant="destructive"
                    className="absolute top-1 right-1 h-6 w-6 p-0 rounded-full"
                    onClick={() => setEditForm({ ...editForm, cover_image: null })}
                  >
                    <AppIcon name="close" size="xs" />
                  </Button>
                </div>
              ) : (
                <Button variant="outline" className="w-full h-20 border-dashed" onClick={() => setShowUploadPopup(true)}>
                  <AppIcon name="file" className=" mr-2" /> Upload Cover Image
                </Button>
              )}
            </div>
            <Button
              onClick={() => updateProjectMutation.mutate()}
              disabled={updateProjectMutation.isPending || !editForm.name}
              className="w-full bg-primary-600 hover:bg-primary-700 text-white font-semibold"
            >
              {updateProjectMutation.isPending ? <AppIcon name="loading" className=" animate-spin" /> : "Update Project"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
      <FileUploadPopup
        open={showUploadPopup}
        onOpenChange={setShowUploadPopup}
        onUpload={async (file: File) => {
          const formData = new FormData();
          formData.append("cover_image", file);
          try {
            const res = await apiFetch("/projects/cover", {
              method: "POST",
              body: formData, // let browser set multipart/form-data boundary
              headers: { "Content-Type": undefined } as any
            });
            if (res.url) {
              setEditForm({ ...editForm, cover_image: res.url });
              setShowUploadPopup(false);
              toast.success("Cover image uploaded");
            }
          } catch (e: any) {
            toast.error(e.message || "Failed to upload cover");
          }
        }}
        acceptedTypes={["image/png", "image/jpeg", "image/webp"]}
        maxSizeMB={5}
      />

      <div className="flex bg-neutral-100/80 dark:bg-neutral-900/50 p-1 rounded-[var(--radius)] w-fit mb-2">
        <Button variant={activeTab === "overview" ? "primary" : "ghost"} size="sm" onClick={() => setActiveTab("overview")} className="h-8 text-xs px-4">Overview</Button>
        <Button variant={activeTab === "tasks" ? "primary" : "ghost"} size="sm" onClick={() => setActiveTab("tasks")} className="h-8 text-xs px-4">Tasks</Button>
      </div>

      {activeTab === "tasks" ? (
        <TasksTab defaultProjectId={projectId} />
      ) : (
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-2 space-y-6">
          <Card className="border-none shadow-e1">
            <CardHeader>
              <CardTitle className="text-base font-bold">Project History & Activity</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 rounded-xl bg-neutral-50 dark:bg-neutral-900">
                  <div>
                    <span className="text-[10px] uppercase font-bold text-neutral-400 block mb-1">Time Spent</span>
                    <span className="font-semibold">{project?.total_time_hours || 0} hrs</span>
                  </div>
                  <div>
                    <span className="text-[10px] uppercase font-bold text-neutral-400 block mb-1">Tasks Done</span>
                    <span className="font-semibold">{project ? `${project.completed_tasks_count || 0} / ${project.total_tasks_count || 0}` : <Skeleton className="h-4 w-12" />}</span>
                  </div>
                  <div>
                    <span className="text-[10px] uppercase font-bold text-neutral-400 block mb-1">Team</span>
                    <span className="font-semibold">{project?.members?.length || 0} members</span>
                  </div>
                  <div>
                    <span className="text-xs uppercase font-semibold text-neutral-500">Status</span>
                    {project ? (
                      <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                        project.status === 'completed' ? 'bg-green-100 text-green-700' :
                        project.status === 'active' ? 'bg-blue-100 text-blue-700' :
                        project.status === 'on_hold' ? 'bg-amber-100 text-amber-700' :
                        'bg-neutral-100 text-neutral-700'
                      }`}>
                        {project.status || "In Progress"}
                      </span>
                    ) : <Skeleton className="h-6 w-16 rounded-full" />}
                  </div>
                </div>

                <div className="space-y-2 mt-4 flex flex-col h-[300px]">
                  <h3 className="font-semibold text-sm shrink-0">Activity Log</h3>
                  <div ref={historyParentRef} className="flex-1 overflow-auto thin-scrollbar relative pr-2">
                    {projectHistory?.length > 0 ? (
                      <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, width: '100%', position: 'relative' }}>
                        {rowVirtualizer.getVirtualItems().map((virtualItem) => {
                          const h: any = projectHistory[virtualItem.index];
                          return (
                            <div 
                              key={virtualItem.key}
                              data-index={virtualItem.index}
                              ref={rowVirtualizer.measureElement}
                              style={{
                                position: 'absolute',
                                top: 0,
                                left: 0,
                                width: '100%',
                                transform: `translateY(${virtualItem.start}px)`
                              }}
                              className="flex gap-3 text-xs p-2 hover:bg-neutral-50 dark:hover:bg-neutral-800 rounded-[var(--radius)]"
                            >
                              <AppIcon name="teamAttendance" className=" text-neutral-400 shrink-0 mt-0.5" />
                              <div>
                                <p><span className="font-semibold">{h.user?.name}</span> {h.event}</p>
                                <span className="text-neutral-400 text-[10px]">{format(new Date(h.created_at), "MMM d, yyyy h:mm a")}</span>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    ) : (
                      <p className="text-xs text-neutral-400 mt-2">No history yet.</p>
                    )}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        <div className="space-y-6">
          <Card className="border-none shadow-e1">
            <CardHeader className="pb-3">
              <CardTitle className="text-base font-bold flex items-center justify-between">
                <span>Team</span>
                <span className="text-xs font-normal text-neutral-500 bg-neutral-100 dark:bg-neutral-800 px-2 py-0.5 rounded-full">
                  {project?.members?.length || 0} members
                </span>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex flex-col gap-3">
                {project?.members?.length > 0 ? (
                  project.members.map((member: any) => (
                    <div key={member.id} className="flex items-center gap-3">
                      <Avatar className="w-8 h-8 border border-neutral-200 dark:border-neutral-800">
                        {member.avatar_url && <img src={member.avatar_url} alt={member.name} />}
                        <AvatarFallback name={member.name} className="text-xs" />
                      </Avatar>
                      <div className="flex flex-col">
                        <span className="text-sm font-semibold text-neutral-900 dark:text-neutral-100">{member.name}</span>
                        <span className="text-[10px] text-neutral-500">{member.active_role?.replace("_", " ") || "Employee"}</span>
                      </div>
                    </div>
                  ))
                ) : (
                  <p className="text-xs text-neutral-400">No members assigned.</p>
                )}
              </div>
            </CardContent>
          </Card>

          <Card className="border-none shadow-e1 bg-primary-50/50 dark:bg-primary-950/30 border-primary-100 dark:border-primary-900">
            <CardHeader>
              <CardTitle className="text-base font-bold text-primary-800 dark:text-primary-300">Project Workflow</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {project?.status !== "completed" && project?.status !== "review" && (
                <div className="space-y-3">
                  <label className="text-xs font-semibold">Submit for Completion</label>
                  
                  {project?.qa_form && (
                    <div className="p-3 bg-primary-50/50 dark:bg-primary-950/30 rounded-[var(--radius)] border border-primary-100 dark:border-primary-900 space-y-2 mb-3">
                      <h4 className="font-bold text-primary-700 dark:text-primary-300 flex items-center gap-1.5">
                        <AppIcon name="success" size="sm" />
                        QA Form Required: {project.qa_form.title}
                      </h4>
                      {project.qa_form.fields?.map((field: any) => (
                        <div key={field.id} className="space-y-1">
                          <label className="text-[11px] font-medium text-neutral-600 dark:text-neutral-300">
                            {field.label} {field.required && "*"}
                          </label>
                          <QAFieldRenderer
                            field={field}
                            value={qaValues[field.id]}
                            onChange={(val) => setQaValues({ ...qaValues, [field.id]: val })}
                          />
                        </div>
                      ))}
                    </div>
                  )}

                  <textarea
                    value={submissionNote}
                    onChange={(e) => setSubmissionNote(e.target.value)}
                    placeholder="Completion notes..."
                    className="w-full p-2 text-xs rounded border border-input bg-background resize-none"
                    rows={3}
                  />
                  <Button 
                    className="w-full bg-primary-600 text-white" 
                    onClick={() => submitProjectMutation.mutate()}
                    disabled={submitProjectMutation.isPending || !submissionNote}
                  >
                    {submitProjectMutation.isPending ? <AppIcon name="loading" className=" animate-spin" /> : "Submit Report"}
                  </Button>
                </div>
              )}

              {project?.status === "review" && hasCapability(caps, "projects.manage") && (
                <div className="space-y-3 p-4 bg-surface dark:bg-neutral-900 rounded-[var(--radius)] border border-amber-200 dark:border-amber-900">
                  <div className="flex items-center gap-2 text-amber-600 font-bold text-sm">
                    <AppIcon name="error" /> Pending HR Review
                  </div>
                  <p className="text-xs text-neutral-600 dark:text-neutral-400">"{project.submission_note}"</p>
                  
                  {project.qa_submission && project.qa_form && (
                    <div className="mt-4 p-3 bg-neutral-50 dark:bg-neutral-950 rounded border border-neutral-200 dark:border-neutral-800">
                      <h4 className="text-xs font-bold text-neutral-700 dark:text-neutral-300 mb-2 border-b border-neutral-200 dark:border-neutral-800 pb-1">
                        QA Form Answers: {project.qa_form.title}
                      </h4>
                      <dl className="space-y-2">
                        {project.qa_form.fields?.map((field: any) => (
                          <div key={field.id}>
                            <dt className="text-[10px] font-semibold text-neutral-500">{field.label}</dt>
                            <dd className="text-xs text-neutral-800 dark:text-neutral-200">
                              {project.qa_submission.values?.[field.id] || "—"}
                            </dd>
                          </div>
                        ))}
                      </dl>
                    </div>
                  )}

                  <div className="flex gap-2 pt-2">
                    <Button 
                      className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white text-xs h-8"
                      onClick={() => reviewProjectMutation.mutate("approved")}
                      disabled={reviewProjectMutation.isPending}
                    >
                      Approve
                    </Button>
                    <Button 
                      variant="outline"
                      className="flex-1 text-xs h-8 text-rose-600 hover:bg-rose-50"
                      onClick={() => reviewProjectMutation.mutate("redo")}
                      disabled={reviewProjectMutation.isPending}
                    >
                      Redo
                    </Button>
                  </div>
                </div>
              )}

              {project?.status === "completed" && (
                <div className="flex flex-col items-center justify-center p-6 text-emerald-600 bg-emerald-50 dark:bg-emerald-950/50 rounded-xl">
                  <AppIcon name="success" size="2xl" className=" mb-2" />
                  <span className="font-bold">Project Completed</span>
                  <span className="text-[10px] text-emerald-700/70 mt-1">
                    Approved on {safeFormat(project?.completed_at || new Date(), "MMM d, yyyy")}
                  </span>
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
      )}

      <ConfirmDialog
        open={isDeleteConfirmOpen}
        onOpenChange={setIsDeleteConfirmOpen}
        title="Delete Project"
        description="Are you sure you want to delete this project? This action cannot be undone."
        confirmText="Delete"
        onConfirm={() => deleteProjectMutation.mutate()}
      />
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { apiFetch, unwrapOne } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { TaskDetailSheet } from "@/components/tasks/task-detail-sheet";

export default function TaskPage() {
  const params = useParams();
  const router = useRouter();
  const taskId = params.id as string;

  const { data: taskResponse, isLoading } = useQuery({
    queryKey: ["tasks", taskId],
    queryFn: () => apiFetch(`/tasks/${taskId}`),
    enabled: !!taskId,
  });

  const task = unwrapOne(taskResponse);

  if (isLoading) {
    return <div className="p-8 text-center text-sm text-neutral-500">Loading task...</div>;
  }

  if (!task) {
    return (
      <div className="p-8 flex flex-col items-center justify-center text-center space-y-4 h-[50vh]">
        <div className="p-4 bg-neutral-100 dark:bg-neutral-800 rounded-full">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-neutral-400"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>
        </div>
        <div>
          <h2 className="text-lg font-semibold text-neutral-900 dark:text-neutral-100">Task Not Found</h2>
          <p className="text-sm text-neutral-500 mt-1">This task may have been deleted or you don't have permission to view it.</p>
        </div>
        <button
          onClick={() => router.push("/dashboard/projects?tab=tasks")}
          className="mt-4 px-4 py-2 bg-primary-600 hover:bg-primary-700 text-white text-sm font-medium rounded-md transition-colors"
        >
          Back to Tasks
        </button>
      </div>
    );
  }

  return (
    <TaskDetailSheet
      task={task}
      open={true}
      onOpenChange={(open) => {
        if (!open) {
          router.push("/dashboard/projects?tab=tasks");
        }
      }}
    />
  );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { AppIcon, IconName } from "@g4k/ui/components";
import { cn } from "@/lib/utils";

import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api-client";
import { queryKeys, STALE_TIME_USERS, STALE_TIME_PROJECTS } from "@/lib/query-keys";

const SEGMENT_LABELS: Record<string, string> = {
  admin: "Administration",
  org: "Organization",
  users: "Employee Directory",
  leave: "Leave Management",
  attendance: "Attendance Records",
  settings: "Settings",
  projects: "Projects",
  tasks: "Task Management",
  reports: "Reports & Analytics",
  chat: "Team Chat",
  profile: "My Profile",
};

function BreadcrumbSegment({
  segment,
  parentSegment,
  url,
  isLast,
}: {
  segment: string;
  parentSegment: string;
  url: string;
  isLast: boolean;
}) {
  let formatted = SEGMENT_LABELS[segment] || segment.replace(/-/g, " ");

  const isNumericId = !isNaN(Number(segment));
  const isUserSegment = isNumericId && parentSegment === "users";
  const isProjectSegment = isNumericId && parentSegment === "projects";

  const { data: userData } = useQuery({
    queryKey: queryKeys.user(Number(segment)),
    queryFn: () => apiFetch(`/users/${segment}`),
    enabled: isUserSegment,
    staleTime: STALE_TIME_USERS,
  });

  const { data: projectData } = useQuery({
    queryKey: queryKeys.project(Number(segment)),
    queryFn: () => apiFetch(`/projects/${segment}`),
    enabled: isProjectSegment,
    staleTime: STALE_TIME_PROJECTS,
  });

  if (isUserSegment) {
    if (userData?.data?.name) {
      formatted = userData.data.name;
    } else if (userData?.name) {
      formatted = userData.name;
    } else {
      formatted = "Profile"; // Fallback while loading or error
    }
  } else if (isProjectSegment) {
    if (projectData?.data?.name) {
      formatted = projectData.data.name;
    } else if (projectData?.name) {
      formatted = projectData.name;
    } else {
      formatted = "Project"; // Fallback while loading or error
    }
  }

  return (
    <div className="flex items-center gap-1 capitalize min-w-0">
      <AppIcon name="chevronRight" size="xs" className=" text-neutral-400 shrink-0" />
      <Link
        href={url}
        className={cn(
          "transition-colors truncate max-w-[120px] sm:max-w-[200px] inline-block align-bottom",
          isLast
            ? "font-semibold text-neutral-900 dark:text-white"
            : "hover:text-neutral-900 dark:hover:text-white"
        )}
      >
        {formatted}
      </Link>
    </div>
  );
}

export function Breadcrumb() {
  const pathname = usePathname();
  const segments = pathname.split("/").filter(Boolean);

  if (segments.length <= 1) return null;

  return (
    <nav className="flex items-center gap-1 text-xs text-neutral-500 mb-4 overflow-x-auto py-1 thin-scrollbar">
      <Link
        href="/dashboard"
        className="hover:text-neutral-900 dark:hover:text-white flex items-center gap-1 font-medium shrink-0"
      >
        <AppIcon name="home" size="sm" className=" shrink-0" />
        <span>Dashboard</span>
      </Link>

      {segments.slice(1).map((segment, index) => {
        let url = `/${segments.slice(0, index + 2).join("/")}`;
        if (url === "/dashboard/org") url = "/dashboard/org/users";
        if (segment === "org") return null; // Skip 'org' in breadcrumb display
        const isLast = index === segments.length - 2;
        const parentSegment = segments[index]; // Because we slice(1), segments[index] refers to the parent
        
        return (
          <BreadcrumbSegment
            key={url}
            segment={segment}
            parentSegment={parentSegment}
            url={url}
            isLast={isLast}
          />
        );
      })}
    </nav>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useTheme } from "next-themes";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { useTimerStore } from "@/stores/timer-store";
import { offlineEngine } from "@/lib/offline-engine";
import { useCapabilities, hasCapability } from "@/lib/capabilities";
import { apiFetch } from "@/lib/api-client";
import { useRecentStore } from "@/stores/recent-store";
import { safeFromNow } from "@/lib/format";

import {
  CommandDialog,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandShortcut,
} from "@g4k/ui/components";

export function CommandPalette() {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const router = useRouter();
  const { setTheme } = useTheme();
  const isActive = useTimerStore((s) => s.isActive);
  const isOnBreak = useTimerStore((s) => s.isOnBreak);
  const { data: capabilities = [] } = useCapabilities();
  const { recentItems } = useRecentStore();

  const isHrOrAdmin = hasCapability(capabilities, "hr.view-team-attendance") || hasCapability(capabilities, "admin.view-all-attendance");
  const canCorrect = hasCapability(capabilities, "admin.correct-attendance") || hasCapability(capabilities, "attendance.correct-team") || isHrOrAdmin;
  const canClockSelf = hasCapability(capabilities, "attendance.clock-self");

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen((open) => !open);
      }
    };
    document.addEventListener("keydown", down);
    return () => document.removeEventListener("keydown", down);
  }, []);

  const runCommand = (command: () => void) => {
    setOpen(false);
    command();
  };

  const handleExport = async () => {
    try {
      const res = await apiFetch("/attendance/export");
      if (res.download_url) {
        window.location.href = res.download_url;
      } else {
        toast.success("Export started successfully.");
      }
    } catch (err: any) {
      toast.error(err.message || "Failed to export");
    }
  };

  return (
    <CommandDialog open={open} onOpenChange={setOpen}>
      <CommandInput placeholder="Type a command or search workspace..." value={search} onValueChange={setSearch} />
      <CommandList>
        <CommandEmpty>No results found.</CommandEmpty>
        
        {!search && recentItems.length > 0 && (
          <CommandGroup heading="Recently Viewed">
            {recentItems.map((item) => (
              <CommandItem key={`${item.type}-${item.id}`} onSelect={() => runCommand(() => router.push(item.url))}>
                <div className="flex items-center justify-between w-full">
                  <div className="flex items-center">
                    <AppIcon name="profile" className=" mr-2 opacity-70" />
                    <div className="flex flex-col">
                      <span className="text-sm">{item.title}</span>
                      {item.subtitle && <span className="text-xs text-muted-foreground">{item.subtitle}</span>}
                    </div>
                  </div>
                  <span className="text-[10px] text-muted-foreground">{safeFromNow(item.timestamp)}</span>
                </div>
              </CommandItem>
            ))}
          </CommandGroup>
        )}
        
        {isHrOrAdmin && (
          <CommandGroup heading="HR Actions">
            <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/org/attendance"))}>
              <AppIcon name="directory" className=" mr-2" />
              <span>View Team Attendance</span>
            </CommandItem>
            {canCorrect && (
              <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/org/attendance?correction=true"))}>
                <AppIcon name="edit" className=" mr-2" />
                <span>Correct Attendance</span>
              </CommandItem>
            )}
            <CommandItem onSelect={() => runCommand(handleExport)}>
              <AppIcon name="download" className=" mr-2" />
              <span>Export Team Report</span>
            </CommandItem>
          </CommandGroup>
        )}
        
        <CommandGroup heading="Attendance">
          {canClockSelf && (
            <>
              {!isActive && (
                <CommandItem onSelect={() => runCommand(async () => {
                  const ts = new Date().toISOString();
                  useTimerStore.getState().startTimer(ts, 0);
                  try { 
                    await offlineEngine.recordPunch("clock_in", ts); 
                    if (!navigator.onLine) toast.warning("Offline. Clock In queued."); else toast.success("Clocked In"); 
                  } catch(err: any) { toast.error(err.message); }
                })}>
                  <AppIcon name="play" className=" mr-2 text-emerald-500" />
                  <span>Clock In</span>
                </CommandItem>
              )}
              {isActive && !isOnBreak && (
                <CommandItem onSelect={() => runCommand(async () => {
                  const ts = new Date().toISOString();
                  useTimerStore.getState().startBreak(ts);
                  try { 
                    await offlineEngine.recordPunch("break_start", ts); 
                    if (!navigator.onLine) toast.warning("Offline. Break Start queued."); else toast.success("Break Started"); 
                  } catch(err: any) { toast.error(err.message); }
                })}>
                  <AppIcon name="break" className=" mr-2 text-amber-500" />
                  <span>Start Break</span>
                </CommandItem>
              )}
              {isOnBreak && (
                <CommandItem onSelect={() => runCommand(async () => {
                  const ts = new Date().toISOString();
                  const { endBreak } = useTimerStore.getState();
                  endBreak(ts);
                  try { 
                    await offlineEngine.recordPunch("break_end", ts); 
                    if (!navigator.onLine) toast.warning("Offline. Break End queued."); else toast.success("Break Ended"); 
                  } catch(err: any) { toast.error(err.message); }
                })}>
                  <AppIcon name="play" className=" mr-2 text-emerald-500" />
                  <span>End Break & Resume Work</span>
                </CommandItem>
              )}
              {isActive && (
                <CommandItem onSelect={() => runCommand(async () => {
                  const ts = new Date().toISOString();
                  const state = useTimerStore.getState();
                  if (state.isOnBreak) {
                    await offlineEngine.recordPunch("break_end", ts);
                    state.endBreak(ts);
                  }
                  state.stopTimer();
                  try { 
                    await offlineEngine.recordPunch("clock_out", ts); 
                    if (!navigator.onLine) toast.warning("Offline. Clock Out queued."); else toast.success("Clocked Out"); 
                  } catch(err: any) { toast.error(err.message); }
                })}>
                  <AppIcon name="stop" className=" mr-2 text-rose-600" />
                  <span>Clock Out</span>
                </CommandItem>
              )}
            </>
          )}
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/attendance"))}>
            <AppIcon name="teamAttendance" className=" mr-2" />
            <span>View Attendance History</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/attendance?tab=leave"))}>
            <AppIcon name="break" className=" mr-2 text-primary-500" />
            <span>Request Leave</span>
          </CommandItem>
        </CommandGroup>

        {isHrOrAdmin && (
          <CommandGroup heading="Admin Actions">
            <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/org/attendance?tab=all"))}>
              <AppIcon name="directory" className=" mr-2 text-emerald-500" />
              <span>View Company Attendance</span>
            </CommandItem>
            {hasCapability(capabilities, "admin.view-all-attendance") && (
              <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/admin/attendance"))}>
                <AppIcon name="teamAttendance" className=" mr-2 text-blue-500" />
                <span>Admin Attendance Overview</span>
              </CommandItem>
            )}
            {hasCapability(capabilities, "reports.view") && (
              <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/reports"))}>
                <AppIcon name="spreadsheet" className=" mr-2 text-primary-500" />
                <span>Reports & Analytics</span>
              </CommandItem>
            )}
          </CommandGroup>
        )}

        <CommandGroup heading="Navigation">
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard"))}>
            <AppIcon name="dashboard" className=" mr-2" />
            <span>Dashboard</span>
            <CommandShortcut>⌘D</CommandShortcut>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/directory"))}>
            <AppIcon name="directory" className=" mr-2" />
            <span>Employee Directory</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/org/users"))}>
            <AppIcon name="directory" className=" mr-2" />
            <span>User Accounts Management</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/org/users?tab=departments"))}>
            <AppIcon name="building" className=" mr-2" />
            <span>Departments & Teams</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/org/users?tab=designations"))}>
            <AppIcon name="briefcase" className=" mr-2" />
            <span>Designations Master</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/profile"))}>
            <AppIcon name="profile" className=" mr-2" />
            <span>My Profile</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => router.push("/dashboard/profile?tab=settings"))}>
            <AppIcon name="settings" className=" mr-2" />
            <span>Admin Settings</span>
          </CommandItem>
        </CommandGroup>

        <CommandGroup heading="Theme Controls">
          <CommandItem onSelect={() => runCommand(() => setTheme("light"))}>
            <AppIcon name="sun" className=" mr-2" />
            <span>Switch to Light Theme</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => setTheme("dark"))}>
            <AppIcon name="moon" className=" mr-2" />
            <span>Switch to Dark Theme</span>
          </CommandItem>
          <CommandItem onSelect={() => runCommand(() => setTheme("system"))}>
            <AppIcon name="laptop" className=" mr-2" />
            <span>Use System Theme</span>
          </CommandItem>
        </CommandGroup>
      </CommandList>
    </CommandDialog>
  );
}

import { useState, useEffect, memo } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import { AppIcon, IconName } from "@g4k/ui/components";
import { hasCapability } from "@/lib/capabilities";
import { useAuthStore } from "@/lib/auth-store";
import { useQueryClient } from "@tanstack/react-query";
import { queryKeys } from "@/lib/query-keys";
import { apiFetch } from "@/lib/api-client";

export const NavItem = memo(function NavItem({ 
  item, 
  isCollapsed, 
  isSheet, 
  getAccent 
}: any) {
  const pathname = usePathname();
  const density = useAuthStore((s) => s.density);
  const isActive = pathname === item.href || (item.href !== "/dashboard" && pathname.startsWith(item.href));
  const accent = getAccent(item.href);
  const currentlyCollapsed = !isSheet && isCollapsed;
  const isDisabled = !!item.disabled;
  
  // Phased Label fade
  const [showLabels, setShowLabels] = useState(!currentlyCollapsed);
  
  useEffect(() => {
    if (currentlyCollapsed) {
      const t = setTimeout(() => setShowLabels(false), 120);
      return () => clearTimeout(t);
    }
    setShowLabels(true);
  }, [currentlyCollapsed]);

  const queryClient = useQueryClient();

  const handleMouseEnter = () => {
    if (isDisabled) return;
    if (item.href === "/dashboard/leave") {
      queryClient.prefetchQuery({ queryKey: queryKeys.myLeaveHistory(), queryFn: () => apiFetch("/leave-requests/history") });
    } else if (item.href === "/dashboard/directory") {
      queryClient.prefetchQuery({ queryKey: queryKeys.directory(), queryFn: () => apiFetch("/directory") });
    } else if (item.href === "/dashboard/projects") {
      queryClient.prefetchQuery({ queryKey: queryKeys.projects(), queryFn: () => apiFetch("/projects") });
    } else if (item.href === "/dashboard/tasks") {
      queryClient.prefetchQuery({ queryKey: queryKeys.tasks, queryFn: () => apiFetch("/tasks") });
    } else if (item.href === "/dashboard/announcements") {
      queryClient.prefetchQuery({ queryKey: queryKeys.dashboardInit, queryFn: () => apiFetch("/dashboard/init") });
    } else if (item.href === "/dashboard/org/leave") {
      queryClient.prefetchQuery({ queryKey: queryKeys.orgLeaveRequestsPaginated(), queryFn: () => apiFetch("/leave-requests/pending") });
    }
  };

  const itemPy = density === "compact" ? "py-1.5" : "py-2";
  
  const content = (
    <div className="relative group/nav flex items-center">
      <Link
        href={isDisabled ? "#" : item.href}
        prefetch={false}
        onMouseEnter={handleMouseEnter}
        onClick={(e) => {
          if (isDisabled) e.preventDefault();
        }}
        aria-disabled={isDisabled}
        aria-label={item.name}
        className={cn(
          "flex-1 flex items-center gap-3 px-3 transition-all relative overflow-hidden focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 rounded-[var(--radius)]",
          itemPy,
          currentlyCollapsed ? "justify-center px-0 text-[13px]" : "text-sm",
          isDisabled
            ? "opacity-50 cursor-not-allowed text-neutral-400 dark:text-neutral-600"
            : isActive
            ? cn("font-semibold shadow-e1 ring-1 ring-inset", accent.bg, accent.bgDark, accent.ring, accent.text, accent.textDark)
            : cn("text-neutral-700 dark:text-neutral-300 font-medium group-hover/nav:bg-opacity-50 hover:shadow-e1", accent.hoverBg, accent.hoverText)
        )}
      >
        <div className={cn(
          "w-8 h-8 rounded-[var(--radius)] flex items-center justify-center shrink-0 transition-colors bg-transparent"
        )}>
          <AppIcon
            name={item.icon}
            size="md"
            className={cn(
              "shrink-0 transition-colors",
              isDisabled
                ? "text-neutral-400 dark:text-neutral-600"
                : isActive
                ? "text-inherit"
                : cn(accent.text, "group-hover/nav:text-inherit")
            )}
          />
        </div>
        {showLabels && (
          <span className={cn(
            "whitespace-nowrap transition-opacity duration-[120ms]",
            currentlyCollapsed && showLabels ? "opacity-0" : "opacity-100"
          )}>
            {item.name}
            {isActive && <span className="sr-only"> (Current)</span>}
          </span>
        )}
      </Link>
    </div>
  );

  return content;
});

export const NavGroup = memo(function NavGroup({ 
  group, 
  userCapabilities, 
  isCollapsed, 
  isSheet, 
  getAccent 
}: any) {
  // Filter items by capability
  const visibleItems = group.items.filter(
    (item: any) => !item.capability || hasCapability(userCapabilities, item.capability)
  );

  if (visibleItems.length === 0) return null;

  return (
    <div className="mb-2">
      {(!isCollapsed || isSheet) ? (
        <div className="text-[10px] font-bold tracking-wider text-neutral-400 dark:text-neutral-500 uppercase px-3 mb-1 mt-4 transition-opacity duration-[120ms]">
          {group.label}
        </div>
      ) : (
        <div className="h-px bg-border mx-2 my-3 transition-opacity duration-[120ms]" />
      )}
      <div className="flex flex-col gap-1">
        {visibleItems.map((item: any) => (
          <NavItem 
            key={item.name} 
            item={item} 
            isCollapsed={isCollapsed} 
            isSheet={isSheet} 
            getAccent={getAccent} 
          />
        ))}
      </div>
    </div>
  );
});

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import Link from "next/link";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { useAuthStore } from "@/lib/auth-store";
import { useUIStore } from "@/lib/ui-store";
import { useReverb } from "@/hooks/use-reverb";
import { safeFromNow } from "@/lib/format";
import { Button, ErrorBoundary, Tooltip, TooltipContent, TooltipProvider, TooltipTrigger, Dialog, DialogContent, DialogTitle } from "@g4k/ui/components";
import { useShallow } from "zustand/react/shallow";
import { queryKeys } from "@/lib/query-keys";

export function NotificationsBell() {
  const user = useAuthStore((s) => s.user);
  const { subscribe, leaveChannel, isConnected } = useReverb();
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const [filter, setFilter] = useState<"recent" | "unread" | "important">("recent");

  const dismissedNotificationIds = useUIStore(useShallow((s) => s.dismissedNotificationIds));
  const clearPopupNotifications = useUIStore((s) => s.clearPopupNotifications);

  const { data: countData } = useQuery({
    queryKey: queryKeys.unreadCount,
    queryFn: () => apiFetch("/notifications/unread-count"),
    enabled: !!user,
    refetchInterval: isConnected ? false : 30_000,
  });

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.notifications(filter),
    queryFn: () => {
      let qs = "";
      if (filter === "unread") qs = "?unreadOnly=true";
      else if (filter === "important") qs = "?importantOnly=true";
      return apiFetch(`/notifications${qs}`);
    },
    enabled: !!user,
    refetchInterval: isConnected ? false : 30_000,
  });

  const markReadMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiFetch(`/notifications/${id}/mark-read`, { method: "POST" });
    },
    onMutate: async (id) => {
      await queryClient.cancelQueries({ queryKey: ["notifications"] });
      const previous = queryClient.getQueryData(queryKeys.notifications(filter));
      
      queryClient.setQueryData(queryKeys.notifications(filter), (old: any) => {
        return old ? {
          ...old,
          data: (old.data ?? []).map((n: any) => 
            n.id === id ? { ...n, read_at: new Date().toISOString() } : n
          )
        } : old;
      });

      return { previous };
    },
    onSuccess: (data, id) => {
      toast("Notification marked as read", {
        duration: 3000,
      });
    },
    onError: (err, id, context: any) => {
      queryClient.setQueryData(queryKeys.notifications(filter), context.previous);
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.unreadCount });
    },
  });

  const markAllReadMutation = useMutation({
    mutationFn: async () => {
      return apiFetch("/notifications/mark-all-read", { method: "POST" });
    },
    onMutate: async () => {
      await queryClient.cancelQueries({ queryKey: ["notifications"] });
      const previous = queryClient.getQueryData(queryKeys.notifications(filter));

      queryClient.setQueryData(queryKeys.notifications(filter), (old: any) => {
        return old ? {
          ...old,
          data: (old.data ?? []).map((n: any) => ({ ...n, read_at: new Date().toISOString() }))
        } : old;
      });

      return { previous };
    },
    onSuccess: () => {
      toast.success("All notifications marked as read");
    },
    onError: (err, variables, context: any) => {
      queryClient.setQueryData(queryKeys.notifications(filter), context.previous);
      toast.error("Failed to mark notifications as read");
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.unreadCount });
    },
  });

  // Real-time listener
  useEffect(() => {
    if (!user) return;
    
    const channelName = `private-user.${user.id}`;
    const channel = subscribe(channelName);
    
    const handleNotification = (e: any) => {
      queryClient.invalidateQueries({ queryKey: ["notifications"] });
      queryClient.invalidateQueries({ queryKey: queryKeys.unreadCount });
      if (e.title) {
        toast.info(e.title, { description: e.body || "You have a new notification." });
      } else {
        toast.info("New Notification", { description: "You have a new notification." });
      }
    };

    const handleApproval = () => {
      queryClient.invalidateQueries({ queryKey: [queryKeys.myLeaveHistory()[0]] });
      queryClient.invalidateQueries({ queryKey: [queryKeys.orgLeaveRequestsPaginated()[0]] });
    };

    if (channel) {
      channel.listen(".notification-created", handleNotification);
      channel.listen(".approval-status-change", handleApproval);
    }

    return () => {
      if (channel) {
        channel.stopListening(".notification-created");
        channel.stopListening(".approval-status-change");
      }
      leaveChannel(channelName);
    };
  }, [user, subscribe, leaveChannel, queryClient]);

  const rawNotifications = data?.data || [];
  // Filter out client-side dismissed notification IDs (cleared from popup only)
  const visibleNotifications = rawNotifications.filter(
    (n: any) => !dismissedNotificationIds.includes(n.id)
  );
  const unreadCount = countData?.count || 0;
  const highPriorityCount = countData?.high_priority_count || 0;

  const getIcon = (type: string) => {
    switch (type) {
      case "leave_decision":
        return <AppIcon name="success" className=" text-emerald-500 shrink-0" />;
      case "task_assigned":
        return <AppIcon name="briefcase" className=" text-primary-500 shrink-0" />;
      case "message":
        return <AppIcon name="chat" className=" text-blue-500 shrink-0" />;
      case "missed_clock_in":
        return <AppIcon name="error" className=" text-rose-600 shrink-0" />;
      case "shift_reminder":
        return <AppIcon name="teamAttendance" className=" text-amber-500 shrink-0" />;
      case "attendance_correction":
        return <AppIcon name="edit" className=" text-blue-500 shrink-0" />;
      default:
        return <AppIcon name="error" className=" text-amber-500 shrink-0" />;
    }
  };

  const handleClearPopup = () => {
    if (visibleNotifications.length === 0) return;
    clearPopupNotifications(visibleNotifications.map((n: any) => n.id));
    toast("Notifications cleared from popup", {
      description: "Original notifications are preserved in Notification Center.",
    });
  };

  return (
    <>
      <TooltipProvider delayDuration={150}>
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              onClick={() => setOpen(true)}
              className={`relative h-9 w-9 flex items-center justify-center rounded-[var(--radius)] hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 shrink-0 ${highPriorityCount > 0 ? "text-rose-500 animate-pulse" : "text-neutral-600 dark:text-neutral-400"}`}
              aria-label="Notifications"
            >
              <AppIcon name="bell" size="lg" />
              {/* T-47.6: bell badge shows high-priority unread only; the full
                  unread count remains visible in the panel header and tooltip. */}
              {highPriorityCount > 0 ? (
                <span className="absolute -top-1 -right-1 min-w-[16px] h-4 px-1 text-white text-[10px] font-bold rounded-full flex items-center justify-center ring-2 ring-surface bg-rose-500">
                  {highPriorityCount > 99 ? "99+" : highPriorityCount}
                </span>
              ) : null}
            </button>
          </TooltipTrigger>
          <TooltipContent className="text-xs">
            Notifications ({unreadCount} unread)
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="sm:max-w-md p-0 gap-0 overflow-hidden outline-none bg-surface border-border">
          {/* Modal Header */}
          <div className="flex items-center justify-between p-4 border-b border-border bg-surface-2/50">
            <div className="flex items-center gap-2">
              <DialogTitle className="font-bold text-sm text-primary">Notifications</DialogTitle>
              {unreadCount > 0 && (
                <span className="text-[10px] font-bold bg-rose-500/10 text-rose-600 dark:text-rose-400 px-2 py-0.5 rounded-full border border-rose-500/20">
                  {unreadCount} new
                </span>
              )}
            </div>
            
            <div className="flex items-center gap-1 pr-8">
              {visibleNotifications.length > 0 && (
                <>
                  <button
                    onClick={() => markAllReadMutation.mutate()}
                    title="Mark as Read"
                    className="flex items-center gap-1.5 px-2 py-1.5 rounded-[var(--radius)] text-xs font-semibold text-neutral-500 hover:text-emerald-600 hover:bg-emerald-500/10 transition-colors"
                  >
                    <AppIcon name="read" size="sm" />
                    <span className="hidden sm:inline">Mark read</span>
                  </button>
                  <button
                    onClick={() => handleClearPopup()}
                    title="Clear All"
                    className="flex items-center gap-1.5 px-2 py-1.5 rounded-[var(--radius)] text-xs font-semibold text-neutral-500 hover:text-rose-600 hover:bg-rose-500/10 transition-colors"
                  >
                    <AppIcon name="trash" size="sm" />
                    <span className="hidden sm:inline">Clear</span>
                  </button>
                </>
              )}
            </div>
          </div>

          {/* Filter Tabs */}
          <div className="flex items-center px-4 py-2 border-b border-border bg-surface text-xs gap-2">
            <button 
              onClick={() => setFilter("recent")} 
              className={`px-3 py-1 text-xs font-semibold rounded-[var(--radius)] transition-colors ${
                filter === "recent" 
                  ? "bg-orange-500/10 text-orange-600 dark:text-orange-400" 
                  : "text-neutral-500 hover:bg-surface-2"
              }`}
            >
              Recent
            </button>
            <button 
              onClick={() => setFilter("unread")} 
              className={`px-3 py-1 text-xs font-semibold rounded-[var(--radius)] transition-colors ${
                filter === "unread" 
                  ? "bg-orange-500/10 text-orange-600 dark:text-orange-400" 
                  : "text-neutral-500 hover:bg-surface-2"
              }`}
            >
              Unread
            </button>
            <button 
              onClick={() => setFilter("important")} 
              className={`px-3 py-1 text-xs font-semibold rounded-[var(--radius)] transition-colors ${
                filter === "important" 
                  ? "bg-rose-500/10 text-rose-600 dark:text-rose-400" 
                  : "text-neutral-500 hover:bg-surface-2"
              }`}
            >
              Important
            </button>
          </div>
          
          {/* Scrollable Notifications List */}
          <div className="max-h-[360px] overflow-y-auto divide-y divide-border thin-scrollbar">
            <ErrorBoundary name="NotificationsList" fallbackTitle="Could not load notifications">
            {isLoading ? (
              <div className="p-4 space-y-3">
                {[1, 2, 3].map((i) => (
                  <div key={i} className="flex gap-3 items-center">
                    <div className="w-8 h-8 rounded-full bg-neutral-200 dark:bg-neutral-800 animate-pulse shrink-0" />
                    <div className="flex-1 space-y-1.5">
                      <div className="h-3 w-3/4 bg-neutral-200 dark:bg-neutral-800 rounded animate-pulse" />
                      <div className="h-2.5 w-1/2 bg-neutral-200 dark:bg-neutral-800 rounded animate-pulse" />
                    </div>
                  </div>
                ))}
              </div>
            ) : visibleNotifications.length === 0 ? (
              <div className="p-10 text-center text-xs text-neutral-500">
                <AppIcon name="bell" size="2xl" className=" mx-auto mb-2 text-neutral-300 dark:text-neutral-700" />
                No {filter === "unread" ? "unread " : ""}notifications.
              </div>
            ) : (
              visibleNotifications.map((n: any) => (
                <div
                  key={n.id}
                  className={`flex gap-3 p-4 min-h-[44px] transition-colors ${
                    !n.read_at ? "bg-orange-500/5 dark:bg-orange-500/10" : "hover:bg-surface-2/60"
                  }`}
                >
                  <div className="mt-0.5 shrink-0">{getIcon(n.type)}</div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-semibold text-primary truncate flex items-center gap-1.5">
                      {n.link ? (
                        <Link 
                          href={n.link} 
                          prefetch={false} 
                          className="hover:underline hover:text-orange-600 dark:hover:text-orange-400" 
                          onClick={() => {
                            if (!n.read_at) markReadMutation.mutate(n.id);
                            setOpen(false);
                          }}
                        >
                          {n.title || "Notification"}
                        </Link>
                      ) : (
                        <span>{n.title || "Notification"}</span>
                      )}
                      {n.priority === 'urgent' && (
                        <span className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-pulse shrink-0" title="Urgent" />
                      )}
                    </p>
                    <p className="text-[11px] text-neutral-500 line-clamp-2 mt-0.5">
                      {n.body || ""}
                    </p>
                    <p className="text-[10px] text-neutral-400 mt-1">
                      {safeFromNow(n.created_at)}
                    </p>
                  </div>
                  {!n.read_at && (
                    <button
                      onClick={() => markReadMutation.mutate(n.id)}
                      className="shrink-0 p-1 rounded hover:bg-surface-2 text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-200 transition-colors self-start"
                      title="Mark as read"
                      aria-label="Mark as read"
                    >
                      <AppIcon name="check" size="sm" />
                    </button>
                  )}
                </div>
              ))
            )}
            </ErrorBoundary>
          </div>
          
          {/* Modal Footer */}
          <div className="p-3 border-t border-border bg-surface-2/50 flex justify-end">
            <Button 
              variant="ghost" 
              asChild 
              className="w-full h-8 text-xs text-neutral-600 dark:text-neutral-400 hover:text-primary font-medium"
            >
              <Link href="/dashboard/notifications" prefetch={false} onClick={() => setOpen(false)}>
                View all in Notification Center
              </Link>
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { Popover, PopoverContent, PopoverTrigger } from "@g4k/ui/components";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { toast } from "sonner";
import { hasCapability, useCapabilities } from "@/lib/capabilities";
import { useTimerStore } from "@/stores/timer-store";

export function ProjectTimerWidget() {
  const [isOpen, setIsOpen] = useState(false);
  const [projectId, setProjectId] = useState<string>("");
  const [logDescription, setLogDescription] = useState("");
  const { 
    isProjectTimerRunning, 
    projectTimerAccumulatedSeconds, 
    projectTimerStartedAt,
    activeTaskId,
    startProjectTimer,
    pauseProjectTimer,
    resumeProjectTimer,
    stopProjectTimer
  } = useTimerStore();

  const [taskId, setTaskId] = useState<string>("none");
  const queryClient = useQueryClient();
  const { data: caps = [] } = useCapabilities();
  const canTrack = hasCapability(caps, "timer.track");

  const { data: projectsData } = useQuery({ 
    queryKey: queryKeys.projects(), 
    queryFn: () => apiFetch("/projects"),
    enabled: canTrack
  });

  const { data: tasksData } = useQuery({ 
    queryKey: [...queryKeys.tasks, projectId], 
    queryFn: () => apiFetch(`/tasks?project_id=${projectId}&per_page=100`),
    enabled: !!projectId && canTrack
  });

  const [elapsedSeconds, setElapsedSeconds] = useState(0);

  // Sync elapsed seconds
  useEffect(() => {
    let interval: NodeJS.Timeout;
    
    const updateElapsed = () => {
      let total = projectTimerAccumulatedSeconds;
      if (isProjectTimerRunning && projectTimerStartedAt) {
        total += Math.floor((Date.now() - projectTimerStartedAt) / 1000);
      }
      setElapsedSeconds(total);
    };

    updateElapsed(); // Initial update

    if (isProjectTimerRunning) {
      interval = setInterval(updateElapsed, 1000);
    }
    return () => clearInterval(interval);
  }, [isProjectTimerRunning, projectTimerAccumulatedSeconds, projectTimerStartedAt]);

  const timerMutation = useMutation({
    mutationFn: async (minutes: number) => {
      return apiFetch("/timer/log", {
        method: "POST",
        body: JSON.stringify({
          project_id: projectId,
          task_id: taskId === "none" ? null : taskId,
          minutes_logged: minutes,
          description: logDescription || undefined,
        }),
      });
    },
    onSuccess: () => {
      toast.success("Time logged successfully.");
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
      queryClient.invalidateQueries({ queryKey: queryKeys.projects() });
      if (projectId) {
        queryClient.invalidateQueries({ queryKey: queryKeys.project(projectId) });
      }
    },
    onError: (err: any) => toast.error(err.message || "Failed to log time"),
  });

  const handleStop = () => {
    const { elapsedSeconds: total, taskId: stoppedTaskId, projectId: stoppedProjectId } = stopProjectTimer();
    const mins = Math.ceil(total / 60);
    if (mins > 0 && stoppedProjectId) {
      timerMutation.mutate(mins);
    }
    setElapsedSeconds(0);
    setProjectId("");
    setTaskId("none");
    setLogDescription("");
    setIsOpen(false);
  };

  const handlePauseResume = () => {
    if (isProjectTimerRunning) {
      pauseProjectTimer();
    } else {
      resumeProjectTimer();
    }
  };

  const handleStart = () => {
    startProjectTimer(projectId, taskId, "Project Tracking");
  };

  const formatTime = (totalSeconds: number) => {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  if (!canTrack) return null;

  const isActive = isProjectTimerRunning || elapsedSeconds > 0;

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger asChild>
        <Button variant={isActive ? "primary" : "ghost"} size="sm" className="gap-2 h-9 px-3 rounded-full">
          <AppIcon name="timer" size="sm" className={isActive && isProjectTimerRunning ? "animate-pulse" : ""} />
          {isActive ? formatTime(elapsedSeconds) : "Track Time"}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-80 p-4" align="end">
        <div className="space-y-4">
          <h4 className="font-semibold text-sm">Time Tracker</h4>
          
          <div className="text-3xl font-mono text-center font-bold tracking-tight">
            {formatTime(elapsedSeconds)}
          </div>

          <div className="space-y-3">
            <div className="space-y-1">
              <label className="text-xs font-medium text-neutral-500">Project</label>
              <Select value={projectId} onValueChange={setProjectId} disabled={isActive}>
                <SelectTrigger className="h-8 text-xs">
                  <SelectValue placeholder="Select Project" />
                </SelectTrigger>
                <SelectContent>
                  {projectsData?.data?.map((p: any) => (
                    <SelectItem key={p.id} value={String(p.id)}>{p.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {projectId && (
              <div className="space-y-1">
                <label className="text-xs font-medium text-neutral-500">Task (Optional)</label>
                <Select value={taskId} onValueChange={setTaskId} disabled={isActive}>
                  <SelectTrigger className="h-8 text-xs">
                    <SelectValue placeholder="No specific task" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">No specific task</SelectItem>
                    {tasksData?.data?.map((t: any) => (
                      <SelectItem key={t.id} value={String(t.id)}>{t.title}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {isActive && (
              <div className="space-y-1">
                <label className="text-xs font-medium text-neutral-500">Log Description (Optional)</label>
                <Input
                  value={logDescription}
                  onChange={(e) => setLogDescription(e.target.value)}
                  placeholder="What did you work on?"
                  className="h-8 text-xs"
                />
              </div>
            )}
          </div>

          <div className="flex gap-2">
            {!isActive ? (
              <Button 
                className="w-full bg-green-600 hover:bg-green-700 text-white" 
                onClick={handleStart}
                disabled={!projectId}
              >
                <AppIcon name="play" className="mr-2" size="sm" /> Start Timer
              </Button>
            ) : (
              <>
                <Button 
                  variant={isProjectTimerRunning ? "outline" : "primary"} 
                  className="flex-1"
                  onClick={handlePauseResume}
                >
                  <AppIcon name={isProjectTimerRunning ? "pause" : "play"} className="mr-2" size="sm" />
                  {isProjectTimerRunning ? "Pause" : "Resume"}
                </Button>
                <Button 
                  variant="destructive"
                  className="flex-1"
                  onClick={handleStop}
                  disabled={timerMutation.isPending}
                >
                  <AppIcon name="stop" className="mr-2" size="sm" /> 
                  {timerMutation.isPending ? "Saving..." : "Stop & Log"}
                </Button>
              </>
            )}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { STALE_TIME_ATTENDANCE, queryKeys } from "@/lib/query-keys";
import { useUrlState } from "@/hooks/use-url-state";
import { useMemo } from "react";

export function AdminAttendanceAnalytics() {
  const [selectedDate] = useUrlState("date", format(new Date(), "yyyy-MM-dd"));
  const [deptFilter] = useUrlState("dept", "all");

  const { data, isLoading } = useQuery({
    queryKey: ['attendance-analytics', selectedDate, deptFilter],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (selectedDate) params.append("date", selectedDate);
      if (deptFilter && deptFilter !== "all") params.append("department_id", deptFilter);
      
      try {
        // Try the new analytics endpoint first
        return await apiFetch(`/attendance/admin/analytics?${params.toString()}`);
      } catch (e) {
        // Fallback to overview if analytics endpoint doesn't exist yet
        params.append("per_page", "1000"); // Try to get all records for stats
        return await apiFetch(`/attendance/admin/overview?${params.toString()}`);
      }
    },
    staleTime: STALE_TIME_ATTENDANCE,
  });

  const stats = useMemo(() => {
    // If backend returns the new dedicated analytics object shape
    if (data && !Array.isArray(data) && !data.data && data.present !== undefined) {
      return {
        present: data.present || 0,
        absent: data.absent || 0,
        late: data.late || 0,
        leave: data.leave || 0,
        total: data.total || 0,
        avgClockIn: data.avg_clock_in || "—",
        totalOvertime: data.total_overtime_formatted || "—",
      };
    }

    // Fallback: calculate from records
    const records = data?.data || [];
    let present = 0;
    let absent = 0;
    let late = 0;
    let leave = 0;
    let totalOvertimeSecs = 0;
    let totalClockInTime = 0;
    let clockInCount = 0;

    records.forEach((record: any) => {
      const status = record.status;
      if (status === "present") present++;
      else if (status === "absent") absent++;
      else if (status === "late") late++;
      else if (status === "leave") leave++;

      if (record.overtime_seconds > 0) {
        totalOvertimeSecs += record.overtime_seconds;
      }

      if (record.clock_in) {
        const d = new Date(record.clock_in);
        // Get hours and minutes since midnight
        const mins = d.getHours() * 60 + d.getMinutes();
        totalClockInTime += mins;
        clockInCount++;
      }
    });

    const total = present + absent + late + leave;
    const avgClockInMins = clockInCount > 0 ? Math.floor(totalClockInTime / clockInCount) : 0;
    const avgClockInFmt = avgClockInMins > 0 
      ? `${String(Math.floor(avgClockInMins / 60)).padStart(2, "0")}:${String(avgClockInMins % 60).padStart(2, "0")}`
      : "—";

    const otHours = Math.floor(totalOvertimeSecs / 3600);
    const otMins = Math.floor((totalOvertimeSecs % 3600) / 60);
    const otFmt = totalOvertimeSecs > 0 ? `${otHours}h ${otMins}m` : "—";

    return {
      present,
      absent,
      late,
      leave,
      total,
      avgClockIn: avgClockInFmt,
      totalOvertime: otFmt,
    };
  }, [data]);

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        {[...Array(6)].map((_, i) => (
          <div key={i} className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-xl p-4 flex flex-col justify-center animate-pulse">
            <div className="h-4 bg-neutral-200 dark:bg-neutral-800 rounded w-1/2 mb-2"></div>
            <div className="h-8 bg-neutral-200 dark:bg-neutral-800 rounded w-3/4"></div>
          </div>
        ))}
      </div>
    );
  }

  const cards = [
    { title: "Present", value: stats.present, icon: "directory", color: "text-success", bg: "bg-success/10", total: stats.total },
    { title: "Late", value: stats.late, icon: "teamAttendance", color: "text-warning", bg: "bg-warning/10", total: stats.total },
    { title: "Absent", value: stats.absent, icon: "calendarX", color: "text-danger", bg: "bg-danger/10", total: stats.total },
    { title: "On Leave", value: stats.leave, icon: "calendar", color: "text-info", bg: "bg-info/10", total: stats.total },
    { title: "Avg Clock-In", value: stats.avgClockIn, icon: "login", color: "text-info", bg: "bg-info/10" },
    { title: "Total Overtime", value: stats.totalOvertime, icon: "teamAttendance", color: "text-warning", bg: "bg-warning/10" },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
      {cards.map((card, i) => (
        <div key={i} className="bg-card border border-border rounded-xl p-4 relative overflow-hidden group hover:border-primary/50 transition-colors">
          <div className="flex items-center justify-between mb-3">
            <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400">{card.title}</h4>
            <div className={`p-1.5 rounded-[var(--radius)] ${card.bg}`}>
              <AppIcon name={card.icon as IconName} className={`w-4 h-4 ${card.color}`} />
            </div>
          </div>
          <div className="flex items-end gap-2">
            <span className="text-2xl font-bold text-neutral-900 dark:text-white">
              {card.value}
            </span>
            {card.total !== undefined && card.total > 0 && (
              <span className="text-xs text-neutral-400 dark:text-neutral-500 mb-1 font-medium">
                / {card.total}
              </span>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { format, startOfMonth, endOfMonth, startOfWeek, endOfWeek, eachDayOfInterval, isSameMonth, isToday, addMonths, subMonths, isFuture } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { Button } from "@g4k/ui/components";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@g4k/ui/components";
import { useUrlState } from "@/hooks/use-url-state";

export function AdminAttendanceCalendar() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [tab, setTab] = useUrlState('tab', 'today');
  const [selectedDate, setSelectedDate] = useUrlState('date', format(new Date(), 'yyyy-MM-dd'));

  const monthParam = format(currentDate, "yyyy-MM-dd");
  
  const { data, isLoading } = useQuery({
    queryKey: queryKeys.adminAttendanceGraph("date", "monthly", monthParam),
    queryFn: () => apiFetch(`/attendance/admin/graph?groupBy=date&mode=monthly&date=${monthParam}`),
  });

  const statsByDate = useMemo(() => {
    if (!data?.stats) return {};
    return data.stats.reduce((acc: any, stat: any) => {
      acc[stat.date] = stat;
      return acc;
    }, {});
  }, [data]);

  const calendarDays = useMemo(() => {
    const start = startOfWeek(startOfMonth(currentDate), { weekStartsOn: 1 });
    const end = endOfWeek(endOfMonth(currentDate), { weekStartsOn: 1 });
    return eachDayOfInterval({ start, end });
  }, [currentDate]);

  const prevMonth = () => setCurrentDate((prev) => subMonths(prev, 1));
  const nextMonth = () => setCurrentDate((prev) => addMonths(prev, 1));

  const handleDayClick = (date: Date) => {
    setSelectedDate(format(date, "yyyy-MM-dd"));
    setTab("today");
  };

  const WEEKDAY_LABELS = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];

  return (
    <div className="bg-card dark:bg-neutral-900 rounded-xl border border-neutral-200 dark:border-neutral-800 p-6 shadow-e1 hover:shadow-e2 transition-shadow duration-150">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-lg font-bold text-neutral-900 dark:text-white">
            {format(currentDate, "MMMM yyyy")}
          </h2>
          <p className="text-sm text-neutral-500 dark:text-neutral-400">
            Company-wide attendance heatmap
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="icon" onClick={prevMonth} className="h-8 w-8">
            <AppIcon name="chevronLeft" />
          </Button>
          <Button variant="outline" size="icon" onClick={nextMonth} className="h-8 w-8">
            <AppIcon name="chevronRight" />
          </Button>
        </div>
      </div>

      {isLoading ? (
        <div className="h-64 flex items-center justify-center">
          <AppIcon name="loading" size="xl" className=" animate-spin text-primary-500" />
        </div>
      ) : (
        <TooltipProvider delayDuration={100}>
          <div className="w-full max-w-lg mx-auto">
            <div className="grid grid-cols-7 mb-2">
              {WEEKDAY_LABELS.map((d) => (
                <div key={d} className="text-center text-xs font-semibold text-neutral-400 py-2">
                  {d}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-7 gap-2 sm:gap-2.5">
              {calendarDays.map((date, idx) => {
                const dateStr = format(date, "yyyy-MM-dd");
                const stat = statsByDate[dateStr];
                const inCurrentMonth = isSameMonth(date, currentDate);
                const isTodayFlag = isToday(date);
                const isFutureFlag = isFuture(date);
                
                let bgColor = "bg-neutral-50 dark:bg-neutral-800/50";
                let textColor = "text-neutral-600 dark:text-neutral-400";
                
                if (stat && stat.total > 0 && inCurrentMonth) {
                  const presentRate = stat.present / stat.total;
                  if (presentRate >= 0.9) {
                    bgColor = "bg-emerald-500 dark:bg-emerald-600";
                    textColor = "text-white";
                  } else if (presentRate >= 0.7) {
                    bgColor = "bg-emerald-300 dark:bg-emerald-400/80";
                    textColor = "text-emerald-900 dark:text-emerald-100";
                  } else if (presentRate >= 0.5) {
                    bgColor = "bg-amber-300 dark:bg-amber-500/80";
                    textColor = "text-amber-900 dark:text-amber-100";
                  } else {
                    bgColor = "bg-rose-400 dark:bg-rose-500/80";
                    textColor = "text-white";
                  }
                }

                return (
                  <Tooltip key={idx}>
                    <TooltipTrigger asChild>
                      <button
                        onClick={() => handleDayClick(date)}
                        disabled={isFutureFlag && !stat}
                        className={[
                          "relative flex flex-col items-center justify-center rounded-md sm:rounded-lg aspect-square w-full transition-all duration-200",
                          inCurrentMonth ? "opacity-100" : "opacity-30",
                          isFutureFlag && !stat ? "cursor-default" : "cursor-pointer hover:scale-105 hover:shadow-e2",
                          bgColor,
                          isTodayFlag ? "ring-2 ring-primary-500 ring-offset-2 dark:ring-offset-neutral-900" : ""
                        ].join(" ")}
                      >
                        <span className={`text-xs sm:text-sm font-semibold ${textColor}`}>
                          {format(date, "d")}
                        </span>
                        {stat && stat.total > 0 && inCurrentMonth && (
                          <span className={`text-[9px] sm:text-[10px] mt-0.5 font-medium ${textColor} opacity-90`}>
                            {Math.round((stat.present / stat.total) * 100)}%
                          </span>
                        )}
                      </button>
                    </TooltipTrigger>
                    {stat && stat.total > 0 && inCurrentMonth && (
                      <TooltipContent side="top" className="flex flex-col gap-1 p-3">
                        <p className="font-semibold text-sm">{format(date, "EEEE, MMMM d")}</p>
                        <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-xs mt-1">
                          <span className="text-neutral-500">Total:</span>
                          <span className="font-medium">{stat.total}</span>
                          <span className="text-emerald-500">Present:</span>
                          <span className="font-medium text-emerald-500">{stat.present}</span>
                          <span className="text-amber-500">Late:</span>
                          <span className="font-medium text-amber-500">{stat.late}</span>
                          <span className="text-rose-500">Absent:</span>
                          <span className="font-medium text-rose-500">{stat.absent}</span>
                        </div>
                        <p className="text-[10px] text-neutral-400 mt-2 text-center">Click to view day summary</p>
                      </TooltipContent>
                    )}
                  </Tooltip>
                );
              })}
            </div>
            
            <div className="flex items-center justify-center gap-6 mt-8">
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded bg-emerald-500" />
                <span className="text-xs text-neutral-500">&ge; 90% Present</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded bg-emerald-300" />
                <span className="text-xs text-neutral-500">70% - 89%</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded bg-amber-300" />
                <span className="text-xs text-neutral-500">50% - 69%</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded bg-rose-400" />
                <span className="text-xs text-neutral-500">&lt; 50%</span>
              </div>
            </div>
          </div>
        </TooltipProvider>
      )}
    </div>
  );
}

