"use client";

import { useState, useEffect } from "react";
import { useQuery, useQueryClient, useMutation } from "@tanstack/react-query";
import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";

import { useUrlState } from "@/hooks/use-url-state";
import { apiFetch } from "@/lib/api-client";
import { queryKeys, STALE_TIME_DIRECTORY, STALE_TIME_DEPARTMENTS, STALE_TIME_ATTENDANCE } from "@/lib/query-keys";
import { usePaginatedList } from "@/lib/pagination";
import {  Input, Button, Checkbox, DataTable , Select, SelectContent, SelectItem, SelectTrigger, SelectValue, DatePicker, FilterBar } from "@g4k/ui/components";
import { StatusBadge } from "@g4k/ui/components/badge";
import { ColumnDef } from "@tanstack/react-table";
import { HrCorrectionDialog } from "./hr-correction-dialog";

export function AdminOpenShiftsTable() {
  const queryClient = useQueryClient();
  const [selectedDate, setSelectedDate] = useUrlState("date", format(new Date(), "yyyy-MM-dd"));
  const [deptFilter, setDeptFilter] = useUrlState("dept", "all");
  const [search, setSearch] = useUrlState("search", "");
  
  const [debouncedSearch, setDebouncedSearch] = useState(search);
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(20);
  
  // Dialog & selection state
  const [correctionData, setCorrectionData] = useState<{ dayId: number, userId: number, date: string, action: string, type: string } | null>(null);
  const [rowSelection, setRowSelection] = useState({});

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(search);
      setPage(1);
    }, 250);
    return () => clearTimeout(handler);
  }, [search]);

  useEffect(() => {
    setPage(1);
  }, [selectedDate, deptFilter]);

  const { data: departments = [] } = useQuery({
    queryKey: queryKeys.departments,
    queryFn: () => apiFetch("/departments").then(res => res.data || []),
    staleTime: STALE_TIME_DEPARTMENTS,
  });

  const { data: queryData, isLoading, error, refetch } = useQuery({
    queryKey: [...queryKeys.adminAttendance(selectedDate, deptFilter), "open", debouncedSearch, page, perPage],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (selectedDate) params.append("date", selectedDate);
      if (deptFilter && deptFilter !== "all") params.append("department_id", deptFilter);
      if (debouncedSearch) params.append("search", debouncedSearch);
      params.append("status", "open");
      params.append("page", page.toString());
      params.append("per_page", perPage.toString());
      return apiFetch(`/attendance/admin/overview?${params.toString()}`);
    },
    staleTime: STALE_TIME_ATTENDANCE,
  });

  const paginatedData = usePaginatedList<any>(queryData);
  const openShifts = paginatedData.data;
  const totalPages = paginatedData.last_page || 1;

  const notifyMutation = useMutation({
    mutationFn: (ids: string[]) => apiFetch('/attendance/admin/notify-open-shifts', { method: 'POST', body: JSON.stringify({ ids }) }),
    onSuccess: () => {
      toast.success("Notified HR about open shifts.");
      setRowSelection({});
    },
    onError: (err: any) => toast.error(err.message || "Failed to notify HR."),
  });

  const handleBulkNotify = async () => {
    const selectedIds = Object.keys(rowSelection);
    if (selectedIds.length === 0) return;
    notifyMutation.mutate(selectedIds);
  };

  const columns: any[] = [
    {
      id: "select",
      header: ({ table }: any) => (
        <Checkbox
          checked={table.getIsAllPageRowsSelected()}
          onCheckedChange={(value: any) => table.toggleAllPageRowsSelected(!!value)}
          aria-label="Select all"
          className="ml-2"
        />
      ),
      cell: ({ row }: any) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(value: any) => row.toggleSelected(!!value)}
          aria-label="Select row"
          className="ml-2"
        />
      ),
      enableSorting: false,
      enableHiding: false,
    },
    {
      accessorKey: "user_name",
      header: "Employee",
      cell: ({ row }: any) => {
        return (
          <div className="flex flex-col text-left">
            <span className="font-semibold text-foreground">{row.original.user_name || "Employee"}</span>
            <span className="text-[11px] text-muted-foreground font-normal">{row.original.user_email}</span>
          </div>
        );
      },
    },
    {
      accessorKey: "department",
      header: "Department",
      cell: ({ row }: any) => {
        return <span className="text-xs font-medium text-muted-foreground">{row.original.department_name || "—"}</span>;
      },
    },
    {
      accessorKey: "clock_in",
      header: "Clock In",
      cell: ({ row }: any) => {
        const val = row.getValue("clock_in") as string;
        return (
          <div className="flex items-center gap-2">
            <span className="font-mono text-muted-foreground">{val ? format(new Date(val), "hh:mm a") : "—"}</span>
            <StatusBadge status="warning" className="gap-1 px-1.5 py-0.5 tracking-wide">
              <AppIcon name="error" size="xs" />
              OPEN
            </StatusBadge>
          </div>
        );
      },
    },
    {
      id: "actions",
      header: "Actions",
      cell: ({ row }: any) => {
        return (
          <Button 
            variant="outline" 
            size="sm"
            onClick={() => setCorrectionData({
              dayId: row.original.id,
              userId: row.original.user_id,
              date: row.original.date,
              action: "add_event",
              type: "clock_out"
            })}
            className="h-8 text-xs font-medium"
          >
            Assign Correction
          </Button>
        );
      },
    }
  ];

  return (
    <div className="space-y-4">
      <div className="flex flex-col xl:flex-row items-center gap-4 bg-card p-4 rounded-xl border border-warning/30 relative overflow-hidden shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        <div className="absolute top-0 left-0 w-1 h-full bg-warning" />
        
        {/* Search & Dept */}
        <FilterBar
          searchQuery={search || ""}
          onSearchChange={setSearch}
          searchPlaceholder="Search company..."
          filters={[
            {
              key: "department",
              label: "Department",
              type: "select",
              value: deptFilter,
              onChange: setDeptFilter,
              options: departments.map((d: any) => ({ label: d.name, value: d.id.toString() }))
            }
          ]}
          onClearAll={() => {
            setSearch("");
            setDeptFilter("all");
          }}
        />

        <div className="flex-1 flex justify-start xl:justify-end items-center gap-2 w-full xl:w-auto overflow-x-auto">
          {Object.keys(rowSelection).length > 0 && (
            <Button variant="outline" size="sm" onClick={handleBulkNotify} className="h-10 text-amber-600 border-amber-200 hover:bg-amber-50 dark:hover:bg-amber-900/20 whitespace-nowrap shrink-0">
              <AppIcon name="bell" className=" mr-2" />
              Notify HR ({Object.keys(rowSelection).length})
            </Button>
          )}
          <DatePicker 
            value={selectedDate ? new Date(selectedDate) : undefined} 
            onChange={(date) => setSelectedDate(date ? format(date, "yyyy-MM-dd") : "")}
            className="w-auto min-w-[140px] h-10 shrink-0 border-amber-100 dark:border-amber-900/30 focus-visible:ring-amber-500"
          />
        </div>
      </div>

      <div className="bg-card rounded-xl border border-border overflow-x-auto overflow-y-hidden w-full shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        {openShifts.length === 0 && !isLoading ? (
          <div className="p-12 text-center flex flex-col items-center">
            <div className="w-12 h-12 bg-emerald-100 dark:bg-emerald-900/30 rounded-full flex items-center justify-center mb-4">
              <AppIcon name="error" size="xl" className=" text-emerald-600 dark:text-emerald-400" />
            </div>
            <h3 className="text-lg font-medium text-foreground mb-1">No Open Shifts</h3>
            <p className="text-sm text-muted-foreground">
              All employees have successfully clocked out for this date.
            </p>
          </div>
        ) : (
          <DataTable 
            columns={columns} 
            data={openShifts}
            isLoading={isLoading}
            isError={!!error}
            stickyHeader={true}
            stickyFirstCol={true}
            onRowSelectionChange={setRowSelection}
            rowSelection={rowSelection}
            getRowId={(row: any) => String(row.id)}
            page={page}
            perPage={perPage}
            totalPages={totalPages}
            onPageChange={setPage}
            onPerPageChange={setPerPage}
          />
        )}
      </div>

      <HrCorrectionDialog
        isOpen={!!correctionData}
        onOpenChange={(open) => !open && setCorrectionData(null)}
        dayId={correctionData?.dayId || 0}
        userId={correctionData?.userId || 0}
        date={correctionData?.date || ""}
        defaultAction={correctionData?.action as any}
        defaultType={correctionData?.type as any}
      />
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { format } from "date-fns";
import { useState } from "react";
import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { getAuthToken } from "@/lib/auth-store";
import { Card, Button, DataTable, Tabs, TabsList, TabsTrigger, TabsContent } from "@g4k/ui/components";
import { StatusBadge } from "@g4k/ui/components/badge";
import { FilterBar } from "@g4k/ui/components";
import { LeaveApprovalActionsCell } from "@/components/leave/leave-approval-actions-cell";
import { LeaveHistoryTable } from "@/components/leave/leave-history-table";
import { useUrlState } from "@/hooks/use-url-state";
import { queryKeys } from "@/lib/query-keys";
import { toast } from "sonner";
import { usePaginatedList } from "@/lib/pagination";
import { useExport } from "@/hooks/use-export";
import { LEAVE_TYPES } from "@/lib/constants";

export function ApprovalsTab() {
  const [subTab, setSubTab] = useUrlState("sub", "approvals");
  const [statusFilter, setStatusFilter] = useUrlState("status", "pending");
  const [historyStatusFilter, setHistoryStatusFilter] = useUrlState("h_status", "all");
  const [historyTypeFilter, setHistoryTypeFilter] = useUrlState("h_type", "all");
  const [search, setSearch] = useUrlState("search", "");
  const { triggerExport, isExporting } = useExport();

  const [userIdFilter, setUserIdFilter] = useUrlState("user_id", "");

  // Approvals pagination
  const [approvalsPage, setApprovalsPage] = useState(1);
  const [approvalsPerPage, setApprovalsPerPage] = useState(20);

  // History pagination
  const [historyPage, setHistoryPage] = useState(1);
  const [historyPerPage, setHistoryPerPage] = useState(20);

  const { data, isLoading } = useQuery({
    queryKey: [...queryKeys.orgLeaveRequestsPaginated(statusFilter, search), userIdFilter, approvalsPage, approvalsPerPage],
    queryFn: () => {
      const params = new URLSearchParams();
      if (statusFilter !== "all") params.append("status", statusFilter);
      if (search) params.append("search", search);
      if (userIdFilter) params.append("user_id", userIdFilter);
      params.append("page", approvalsPage.toString());
      params.append("per_page", approvalsPerPage.toString());
      return apiFetch(`/leave-requests?${params.toString()}`);
    },
    placeholderData: keepPreviousData,
  });

  const { data: historyData, isLoading: isLoadingHistory } = useQuery({
    queryKey: ['admin_leave_history', historyStatusFilter, historyTypeFilter, search, userIdFilter, historyPage, historyPerPage],
    queryFn: () => {
      const params = new URLSearchParams();
      if (historyStatusFilter !== "all") params.append("status", historyStatusFilter);
      if (historyTypeFilter !== "all") params.append("type", historyTypeFilter);
      if (search) params.append("search", search);
      if (userIdFilter) params.append("user_id", userIdFilter);
      params.append("page", historyPage.toString());
      params.append("per_page", historyPerPage.toString());
      return apiFetch(`/leave-requests/admin/history?${params.toString()}`);
    },
    enabled: subTab === "history",
    placeholderData: keepPreviousData,
  });

  const paginatedData = usePaginatedList<any>(data);
  const records = paginatedData.data;
  const approvalsTotalPages = paginatedData.last_page || 1;

  const pendingCount = records.filter((r: any) => r.approval?.status === "pending").length;

  const columns = useMemo<any[]>(
    () => [
      {
        accessorKey: "employee",
        header: "Employee",
        cell: ({ row }: any) => {
          const startDate = new Date(row.original.start_date);
          const endDate = new Date(row.original.end_date);
          return (
            <div>
              <div className="font-semibold text-neutral-900 dark:text-white">
                {row.original.user?.name || "Employee"}
              </div>
              <div className="text-[11px] text-neutral-400 font-normal">
                {format(startDate, "MMM d")} - {format(endDate, "MMM d, yyyy")}
              </div>
            </div>
          );
        },
      },
      {
        accessorKey: "type",
        header: "Type",
        cell: ({ row }: any) => (
          <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-neutral-100 text-neutral-800 dark:bg-neutral-800 dark:text-neutral-200">
            {row.original.type}
          </span>
        ),
      },
      {
        accessorKey: "reason",
        header: "Reason",
        cell: ({ row }: any) => (
          <div className="text-sm text-neutral-600 dark:text-neutral-400 max-w-[200px] truncate" title={row.original.reason}>
            {row.original.reason}
          </div>
        ),
      },
      {
        accessorKey: "status",
        header: "Status",
        cell: ({ row }: any) => {
          const status = row.original.approval?.status || "pending";
          return (
            <StatusBadge 
              status={status === "approved" ? "success" : status === "rejected" ? "danger" : "warning"}
              className="uppercase tracking-wide"
            >
              {status}
            </StatusBadge>
          );
        },
      },
      {
        id: "actions",
        header: () => <div className="text-right">Actions</div>,
        cell: ({ row }: any) => (
          <div className="flex justify-end">
            <LeaveApprovalActionsCell record={row.original} />
          </div>
        ),
      },
    ],
    []
  );

  const handleExport = async () => {
    try {
      await triggerExport(
        `/leave-requests/export?status=${statusFilter}`,
        `leave_export_${statusFilter}.xlsx`
      );
    } catch (e: any) {
      console.error(e);
      toast.error(e.message || "Failed to export");
    }
  };

  const paginatedHistory = usePaginatedList<any>(historyData);
  const historyRecords = paginatedHistory.data;
  const historyTotalPages = paginatedHistory.last_page || 1;

  return (
    <div className="space-y-6 mt-4">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-3 mt-1">
            <p className="text-sm text-neutral-500">Review and manage team time off requests.</p>
            {userIdFilter && (
              <Button 
                variant="ghost" 
                size="sm" 
                className="h-6 text-xs text-rose-600 hover:text-rose-700 bg-rose-50"
                onClick={() => setUserIdFilter("")}
              >
                Clear User Filter
              </Button>
            )}
          </div>
        </div>
      </div>

      <Tabs value={subTab} onValueChange={setSubTab} className="w-full space-y-6">
        <TabsList>
          <TabsTrigger value="approvals">Pending Approvals</TabsTrigger>
          <TabsTrigger value="history">All Leave History</TabsTrigger>
        </TabsList>

        <TabsContent value="approvals" className="mt-0">
          <Card className="border-none shadow-e1 hover:shadow-e2 transition-shadow duration-150 flex flex-col h-[calc(100dvh-250px)]">
            <div className="px-4 py-3 border-b border-neutral-100 dark:border-neutral-800 flex justify-between items-center">
              <FilterBar
                searchQuery={search || ""}
                onSearchChange={setSearch}
                filters={[
                  {
                    key: "status",
                    label: "Status",
                    type: "select",
                    value: statusFilter,
                    onChange: setStatusFilter,
                    options: [
                      { label: "Pending", value: "pending" },
                      { label: "Approved", value: "approved" },
                      { label: "Rejected", value: "rejected" },
                    ],
                  },
                ]}
              />
              <Button variant="outline" size="sm" onClick={handleExport} disabled={isExporting} className="h-8 text-xs font-semibold">
                <AppIcon name="download" size="sm" className=" mr-1.5" />
                {isExporting ? "Exporting..." : "Export"}
              </Button>
            </div>
            <div className="flex-1 min-h-[300px] flex flex-col">
              <DataTable
                columns={columns}
                data={records}
                isLoading={isLoading}
                page={approvalsPage}
                perPage={approvalsPerPage}
                totalPages={approvalsTotalPages}
                onPageChange={setApprovalsPage}
                onPerPageChange={setApprovalsPerPage}
              />
            </div>
          </Card>
        </TabsContent>
        
        <TabsContent value="history" className="mt-0">
          <Card className="border-none shadow-e1 hover:shadow-e2 transition-shadow duration-150 flex flex-col h-[calc(100dvh-250px)]">
            <div className="px-4 py-3 border-b border-neutral-100 dark:border-neutral-800 flex justify-between items-center">
              <FilterBar
                searchQuery={search || ""}
                onSearchChange={setSearch}
                filters={[
                  {
                    key: "status",
                    label: "Status",
                    type: "select",
                    value: historyStatusFilter,
                    onChange: setHistoryStatusFilter,
                    options: [
                      { label: "Pending", value: "pending" },
                      { label: "Approved", value: "approved" },
                      { label: "Rejected", value: "rejected" },
                    ],
                  },
                  {
                    key: "type",
                    label: "Type",
                    type: "select",
                    value: historyTypeFilter,
                    onChange: setHistoryTypeFilter,
                    options: LEAVE_TYPES,
                  },
                ]}
              />
            </div>
            <div className="flex-1 min-h-[300px] flex flex-col p-4 overflow-y-auto">
              <LeaveHistoryTable
                records={historyRecords}
                isLoading={isLoadingHistory}
                typeFilter={historyTypeFilter}
                setTypeFilter={setHistoryTypeFilter}
                statusFilter={historyStatusFilter}
                setStatusFilter={setHistoryStatusFilter}
                showEmployee={true}
                hideFilters={true}
                page={historyPage}
                perPage={historyPerPage}
                totalPages={historyTotalPages}
                onPageChange={setHistoryPage}
                onPerPageChange={setHistoryPerPage}
              />
            </div>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  format,
  addMonths,
  subMonths,
  startOfMonth,
  endOfMonth,
  startOfWeek,
  endOfWeek,
  eachDayOfInterval,
  isSameMonth,
  isToday,
  subWeeks,
  eachWeekOfInterval,
  isSameDay,
  parseISO,
} from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import {
  Button,
  Skeleton,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@g4k/ui/components";
import { useQuery } from "@tanstack/react-query";
import { StatusBadge } from "@g4k/ui/components/badge";
import { safeFormat } from "@/lib/format";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { useIsMobile } from "@g4k/ui/hooks";
import { useTimerStore } from "@/stores/timer-store";

// ─── Types ───────────────────────────────────────────────────────────────────

interface AttendanceEvent {
  id: number;
  user_id: number;
  type: string;
  timestamp: string;
  device_meta: any;
  source: string;
}

interface AttendanceDay {
  id: number;
  user_id: number;
  date: string;
  clock_in: string | null;
  clock_out: string | null;
  first_event: string | null;
  last_event: string | null;
  total_seconds: number;
  break_seconds: number;
  overtime_seconds: number;
  late_minutes: number;
  status: string;
  has_open_shift: boolean;
  projects?: string[];
  tasks?: string[];
}

type DayStatus = "present" | "overtime" | "late" | "leave" | "absent" | "holiday" | "nodata";

// ─── Helpers ─────────────────────────────────────────────────────────────────

function formatSecs(secs: number): string {
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  return `${h}h ${m}m`;
}

function getStatus(days: AttendanceDay[], holidays: any[], dateStr: string): DayStatus {
  const day = days.find((d) => d.date === dateStr);
  const isHoliday = holidays.find((h) => h.date === dateStr);
  
  if (day && day.status === "leave") return "leave";
  if (day && day.status === "late") return "late";
  if (day && day.status === "present" && day.overtime_seconds > 0) return "overtime";
  if (day && day.status === "present") return "present";
  
  if (isHoliday) return "holiday";
  
  if (!day) return "nodata";
  return "absent";
}

function getDayRecord(days: AttendanceDay[], dateStr: string): AttendanceDay | undefined {
  return days.find((d) => d.date === dateStr);
}

const STATUS_STYLES: Record<DayStatus, string> = {
  nodata: "bg-neutral-100 dark:bg-neutral-800",
  absent: "bg-neutral-200 dark:bg-neutral-700",
  late: "bg-amber-300 dark:bg-amber-500",
  present: "bg-emerald-300 dark:bg-emerald-500",
  overtime: "bg-indigo-400 dark:bg-indigo-500",
  leave: "bg-primary-300 dark:bg-primary-500",
  holiday: "bg-blue-300 dark:bg-blue-500",
};

const STATUS_LABEL: Record<DayStatus, string> = {
  nodata: "No data",
  absent: "Absent",
  late: "Late",
  present: "Present",
  overtime: "Overtime",
  leave: "On Leave",
  holiday: "Holiday",
};

// ─── Legend ──────────────────────────────────────────────────────────────────

function CalendarLegend({ compact = false }: { compact?: boolean }) {
  const items: [DayStatus, string][] = [
    ["nodata", "No Data"],
    ["late", "Late"],
    ["present", "Present"],
    ["overtime", "Overtime"],
    ["leave", "Leave"],
    ["holiday", "Holiday"],
  ];
  return (
    <div
      className={`flex flex-wrap items-center gap-x-3 gap-y-1 ${compact ? "gap-x-2" : ""}`}
      aria-label="Calendar legend"
    >
      {items.map(([status, label]) => (
        <span key={status} className="flex items-center gap-1">
          <span
            className={`${compact ? "w-2.5 h-2.5" : "w-3 h-3"} rounded-sm flex-shrink-0 ${STATUS_STYLES[status]}`}
            aria-hidden
          />
          <span className={`${compact ? "text-[9px]" : "text-[10px]"} text-neutral-500 dark:text-neutral-400`}>
            {compact ? label.split(" ")[0] : label}
          </span>
        </span>
      ))}
    </div>
  );
}

// ─── Day Tooltip Content ──────────────────────────────────────────────────────

function DayTooltipContent({ date, record, holiday }: { date: Date; record?: AttendanceDay; holiday?: any }) {
  const dateStr = format(date, "yyyy-MM-dd");
  const status = getStatus(record ? [record] : [], holiday ? [holiday] : [], dateStr);
  return (
    <div className="space-y-1 text-left min-w-[120px]">
      <p className="font-semibold text-xs">{format(date, "EEEE, MMM d")}</p>
      {holiday && (
        <p className="text-[11px] font-bold text-blue-600 dark:text-blue-400">
          {holiday.name} {holiday.type === 'event' ? '(Event)' : ''}
        </p>
      )}
      <p className="text-[11px] capitalize">
        <span
          className={`inline-block w-2 h-2 rounded-sm mr-1 ${STATUS_STYLES[status]}`}
          aria-hidden
        />
        {STATUS_LABEL[status]}
      </p>
      {record && record.total_seconds > 0 && (
        <p className="text-[11px] text-neutral-400">
          Worked: <span className="font-mono font-medium text-neutral-200">{formatSecs(record.total_seconds)}</span>
        </p>
      )}
      {record && record.overtime_seconds > 0 && (
        <p className="text-[11px] text-amber-400 font-mono">
          +{formatSecs(record.overtime_seconds)} OT
        </p>
      )}
      {record && record.status === "late" && record.late_minutes > 0 && (
        <p className="text-[11px] text-amber-400">{record.late_minutes}m late</p>
      )}
      <p className="text-[10px] text-neutral-500 mt-0.5">Click to view timeline</p>
    </div>
  );
}

// ─── Month Calendar Grid (Desktop) ───────────────────────────────────────────

function MonthCalendarGrid({
  days,
  holidays,
  currentDate,
  onDayClick,
}: {
  days: AttendanceDay[];
  holidays: any[];
  currentDate: Date;
  onDayClick: (day: AttendanceDay | null, date: Date) => void;
}) {
  const calendarDays = useMemo(() => {
    const start = startOfWeek(startOfMonth(currentDate), { weekStartsOn: 1 });
    const end = endOfWeek(endOfMonth(currentDate), { weekStartsOn: 1 });
    return eachDayOfInterval({ start, end });
  }, [currentDate]);

  const WEEKDAY_LABELS = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];

  return (
    <TooltipProvider delayDuration={200}>
      <div className="w-full" data-testid="month-calendar-grid">
        {/* Weekday headers */}
        <div className="grid grid-cols-7 mb-1">
          {WEEKDAY_LABELS.map((d) => (
            <div
              key={d}
              className="text-center text-[10px] font-semibold text-neutral-400 dark:text-neutral-500 py-1"
            >
              {d}
            </div>
          ))}
        </div>

        {/* Day cells */}
        <div className="grid grid-cols-7 border-t border-l border-border/50" data-testid="month-calendar-grid-cells">
        {calendarDays.map((date, i) => {
          const dateStr = format(date, "yyyy-MM-dd");
          const isCurrMonth = isSameMonth(date, currentDate);
          const isCurrDay = isToday(date);
          const record = getDayRecord(days, dateStr);
          const holiday = holidays.find(h => h.date === dateStr);
          const status = getStatus(days, holidays, dateStr);
          const isFuture = date > new Date();

          return (
            <Tooltip key={dateStr}>
              <TooltipTrigger asChild>
                <button
                  onClick={() => onDayClick(record || null, date)}
                  disabled={isFuture}
                  className={`
                    relative p-1 md:p-2 min-h-[4rem] md:min-h-[5.5rem] border-r border-b border-border/50
                    hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors
                    flex flex-col items-start focus:outline-none focus-visible:ring-2 focus-visible:ring-primary-500
                    ${!isCurrMonth ? "opacity-30 bg-neutral-50/50 dark:bg-neutral-900/50" : ""}
                    ${isFuture ? "cursor-not-allowed opacity-50" : "cursor-pointer"}
                  `}
                  aria-label={`View details for ${dateStr}`}
                >
                  <div className="flex items-center justify-between w-full">
                    <span
                      className={`text-xs md:text-sm font-semibold flex items-center justify-center
                      ${isCurrDay ? "bg-primary-600 text-white w-6 h-6 rounded-full" : "text-neutral-700 dark:text-neutral-300 w-6 h-6"}
                    `}
                    >
                      {format(date, "d")}
                    </span>
                    {status !== "nodata" && (
                      <div
                        className={`w-2 h-2 rounded-full ${STATUS_STYLES[status]}`}
                        title={STATUS_LABEL[status]}
                      />
                    )}
                  </div>
                  {/* Compact timeline bar for desktop */}
                  {record && record.first_event && record.last_event && (
                    <div className="hidden md:block w-full mt-auto">
                      <div className="h-1.5 w-full bg-neutral-200 dark:bg-neutral-700 rounded-sm overflow-hidden flex">
                        {record.break_seconds > 0 ? (
                          <div className="flex w-full h-full">
                            <div className="h-full bg-primary-400" style={{ width: "45%" }} />
                            <div className="h-full bg-amber-400" style={{ width: "10%" }} />
                            <div className="h-full bg-primary-400" style={{ width: "45%" }} />
                          </div>
                        ) : (
                          <div className="h-full bg-primary-400 w-full" />
                        )}
                      </div>
                    </div>
                  )}
                  {holiday && (
                    <div className="w-full mt-auto truncate text-[9px] text-blue-600 dark:text-blue-400 font-semibold hidden md:block">
                      {holiday.name}
                    </div>
                  )}
                </button>
              </TooltipTrigger>
              <TooltipContent side="top" className="p-3 shadow-xl">
                <DayTooltipContent date={date} record={record} holiday={holiday} />
              </TooltipContent>
            </Tooltip>
          );
        })}
      </div>
      </div>
    </TooltipProvider>
  );
}

// ─── Activity Strip (Mobile — GitHub-style) ──────────────────────────────────

function ContributionHeatmap({ days, holidays }: { days: AttendanceDay[]; holidays: any[] }) {
  const isMobile = useIsMobile();
  const weeksToShow = isMobile ? 26 : 52; 
  
  const calendarWeeks = useMemo(() => {
    const end = endOfWeek(new Date(), { weekStartsOn: 1 });
    const start = startOfWeek(subWeeks(end, weeksToShow - 1), { weekStartsOn: 1 });
    return eachWeekOfInterval({ start, end }, { weekStartsOn: 1 });
  }, [weeksToShow]);

  return (
    <TooltipProvider delayDuration={0}>
      <div className="flex items-start gap-2 overflow-x-auto pb-2 scrollbar-hide" data-testid="contribution-heatmap">
        {/* Days of week labels */}
        <div className="flex flex-col gap-[3px] text-[10px] text-neutral-400 font-medium pr-1 pt-[14px]">
          <span className="h-[10px] flex items-center leading-none">M</span>
          <span className="h-[10px] flex items-center leading-none"></span>
          <span className="h-[10px] flex items-center leading-none">W</span>
          <span className="h-[10px] flex items-center leading-none"></span>
          <span className="h-[10px] flex items-center leading-none">F</span>
          <span className="h-[10px] flex items-center leading-none"></span>
          <span className="h-[10px] flex items-center leading-none">S</span>
        </div>

        {/* Grid cells */}
        <div className="flex gap-[3px]">
          {calendarWeeks.map((weekStart, wIdx) => {
            const weekDays = eachDayOfInterval({
              start: weekStart,
              end: endOfWeek(weekStart, { weekStartsOn: 1 }),
            });
            return (
              <div key={wIdx} className="flex flex-col gap-[3px]">
                {weekDays.map((date) => {
                  const dateStr = format(date, "yyyy-MM-dd");
                  const record = getDayRecord(days, dateStr);
                  const holiday = holidays.find(h => h.date === dateStr);
                  const status = getStatus(days, holidays, dateStr);
                  const isFuture = date > new Date();

                  // Hide future days
                  if (isFuture && !holiday) {
                    return <div key={dateStr} className="w-[10px] h-[10px] rounded-[2px]" />;
                  }
                  if (isFuture && holiday) {
                      return (
                      <Tooltip key={dateStr}>
                        <TooltipTrigger asChild>
                          <div
                            className={`w-[10px] h-[10px] rounded-[2px] transition-colors ${STATUS_STYLES[status]}`}
                            aria-label={`Holiday on ${dateStr}`}
                          />
                        </TooltipTrigger>
                        <TooltipContent side="top">
                          <DayTooltipContent date={date} holiday={holiday} />
                        </TooltipContent>
                      </Tooltip>
                    );
                  }

                  return (
                    <Tooltip key={dateStr}>
                      <TooltipTrigger asChild>
                        <div
                          className={`w-[10px] h-[10px] rounded-[2px] transition-all hover:ring-1 hover:ring-offset-1 hover:ring-neutral-400 ${STATUS_STYLES[status]}`}
                          aria-label={`${STATUS_LABEL[status]} on ${dateStr}`}
                        />
                      </TooltipTrigger>
                      <TooltipContent side="top">
                        <DayTooltipContent date={date} record={record} holiday={holiday} />
                      </TooltipContent>
                    </Tooltip>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
    </TooltipProvider>
  );
}

// ─── Main Export ─────────────────────────────────────────────────────────────

export function AttendanceHistoryCalendar({
  days,
  userId,
}: {
  days: AttendanceDay[];
  userId?: number;
}) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<AttendanceDay | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const isMobile = useIsMobile();

  const prevMonth = () => setCurrentDate((prev) => subMonths(prev, 1));
  const nextMonth = () => setCurrentDate((prev) => addMonths(prev, 1));

  // FE-ATT-02: Month-scoped fetching
  const { data: monthData } = useQuery({
    queryKey: ['attendanceMonth', userId || 'me', format(currentDate, "yyyy-MM")],
    queryFn: async () => {
      const monthStr = format(currentDate, "yyyy-MM");
      if (userId) {
        return apiFetch(`/attendance/hr/history/${userId}?month=${monthStr}&per_page=100`).then(res => res.data || []);
      }
      return apiFetch(`/attendance/me/history?month=${monthStr}&per_page=100`).then(res => res.data || []);
    },
  });

  // Merge parent days (initial load) with our fetched monthData
  const allDays = useMemo(() => {
    const combined = [...days];
    if (monthData && Array.isArray(monthData)) {
      monthData.forEach((d: AttendanceDay) => {
        if (!combined.find(c => c.date === d.date)) {
          combined.push(d);
        }
      });
    }
    return combined;
  }, [days, monthData]);

  // Count records for this specific month
  const recordsThisMonth = useMemo(() => {
    return allDays.filter(d => d.date.startsWith(format(currentDate, "yyyy-MM"))).length;
  }, [allDays, currentDate]);

  const { data: holidaysData } = useQuery({
    queryKey: queryKeys.holidays(currentDate.getFullYear()),
    queryFn: () => apiFetch(`/holidays?year=${currentDate.getFullYear()}`),
  });
  const holidays = Array.isArray(holidaysData) 
    ? holidaysData 
    : (Array.isArray(holidaysData?.data) ? holidaysData.data : []);

  const handleDayClick = (record: AttendanceDay | null, date: Date) => {
    if (record) {
      setSelectedDay(record);
      setSelectedDate(date);
    } else {
      const synthetic: AttendanceDay = {
        id: 0,
        user_id: 0,
        date: format(date, "yyyy-MM-dd"),
        clock_in: null,
        clock_out: null,
        first_event: null,
        last_event: null,
        total_seconds: 0,
        break_seconds: 0,
        overtime_seconds: 0,
        late_minutes: 0,
        status: "nodata",
        has_open_shift: false,
      };
      setSelectedDay(synthetic);
      setSelectedDate(date);
    }
  };

  return (
    <div className="w-full space-y-4" data-testid="attendance-history-calendar">
      {/* ── Header ─────────────────────────────────────── */}
      <div className="flex items-center justify-between gap-2">
        <div>
          <h3 className="font-semibold text-base text-neutral-900 dark:text-white leading-tight">
            {format(currentDate, "MMMM yyyy")}
          </h3>
          <p className="text-[10px] text-neutral-400 mt-0.5">
            {recordsThisMonth} record{recordsThisMonth !== 1 ? "s" : ""} this month
          </p>
        </div>
        
        {/* Navigation available on both desktop and mobile now */}
        <div className="flex items-center gap-1.5">
          <Button
            variant="outline"
            size="icon"
            className="h-7 w-7"
            onClick={prevMonth}
            aria-label="Previous month"
          >
            <AppIcon name="chevronLeft" size="sm" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="h-7 w-7"
            onClick={nextMonth}
            aria-label="Next month"
          >
            <AppIcon name="chevronRight" size="sm" />
          </Button>
        </div>
      </div>

      {/* ── Calendar / Strip ───────────────────────────── */}
      <MonthCalendarGrid
        days={allDays}
        holidays={holidays}
        currentDate={currentDate}
        onDayClick={handleDayClick}
      />

      {/* ── Legend ─────────────────────────────────────── */}
      <CalendarLegend compact={isMobile} />

      {/* ── Day Detail Dialog ──────────────────────────── */}
      <Dialog
        open={!!selectedDay}
        onOpenChange={(open) => {
          if (!open) {
            setSelectedDay(null);
            setSelectedDate(null);
          }
        }}
      >
        <DialogContent className="sm:max-w-[500px] max-h-[90dvh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 flex-wrap">
              <span>
                {selectedDate ? format(selectedDate, "EEEE, MMMM d, yyyy") : "Day Details"}
              </span>
              {selectedDay?.has_open_shift && (
                <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-[10px] font-bold rounded-full uppercase">
                  Open Shift
                </span>
              )}
            </DialogTitle>
            <DialogDescription className="sr-only">
              View detailed attendance records and punch timeline for the selected date.
            </DialogDescription>
          </DialogHeader>
          {selectedDay && (
            <DayDetailContent
              date={selectedDay.date}
              summaryDay={selectedDay}
              userId={userId}
            />
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ─── Day Detail Content ───────────────────────────────────────────────────────

function DayDetailContent({
  date,
  summaryDay,
  userId,
}: {
  date: string;
  summaryDay: AttendanceDay;
  userId?: number;
}) {
  const { data, isLoading } = useQuery({
    queryKey: queryKeys.attendanceDayDetail(date, userId),
    queryFn: () =>
      apiFetch(
        userId ? `/attendance/hr/day/${date}/${userId}` : `/attendance/me/day/${date}`
      ),
    enabled: summaryDay.id > 0, // skip synthetic empty day
  });

  const events: AttendanceEvent[] = data?.events || [];
  const day: AttendanceDay = data?.day || summaryDay;
  const timerStandard = useTimerStore((s) => s.standardSeconds);
  const standardSeconds: number = data?.standard_seconds || (userId ? 31500 : timerStandard);

  if (summaryDay.id === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-10 space-y-2 text-center">
        <AppIcon name="calendar" size="2xl" />
        <p className="text-sm font-medium text-neutral-500">No attendance record for this day.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4 pt-1">
      {/* Summary bar */}
      <div className="flex justify-between items-start bg-neutral-50 dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-100 dark:border-neutral-800">
        <div className="space-y-1">
          <p className="text-[10px] text-neutral-500 font-bold uppercase tracking-wider">Status</p>
          <p className="capitalize font-medium flex items-center gap-2">
            {day.status}
            {day.status === "late" && (
              <StatusBadge status="warning">{day.late_minutes}m Late</StatusBadge>
            )}
          </p>
        </div>
        <div className="space-y-1 text-right">
          <p className="text-[10px] text-neutral-500 font-bold uppercase tracking-wider">
            Total Worked
          </p>
          <p className="font-mono font-bold text-primary-600">{formatSecs(day.total_seconds)}</p>
          {day.overtime_seconds > 0 && (
            <p className="text-[10px] font-bold text-indigo-600 font-mono">
              +{formatSecs(day.overtime_seconds)} OT
            </p>
          )}
        </div>
      </div>

      {/* Punch timeline */}
      <div>
        <h4 className="text-sm font-bold mb-3">Punch Timeline</h4>
        {isLoading ? (
          <div className="space-y-2">
            <Skeleton className="h-12 w-full rounded-[var(--radius)]" />
            <Skeleton className="h-12 w-full rounded-[var(--radius)]" />
          </div>
        ) : events.length === 0 ? (
          <p className="text-xs text-neutral-500 italic">No punches recorded for this day.</p>
        ) : (
          <div className="space-y-2">
            {events.map((evt: AttendanceEvent) => (
              <div
                key={evt.id}
                className="flex items-center gap-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-[var(--radius)] p-3 border border-neutral-100 dark:border-neutral-800"
              >
                <div className="w-2 h-2 rounded-full bg-primary-400 shrink-0" />
                <div className="flex-1 min-w-0">
                  <span className="text-[10px] font-bold uppercase text-neutral-500 tracking-wider">
                    {evt.type.replace(/_/g, " ")}
                  </span>
                  <div className="font-mono text-sm font-semibold mt-0.5">
                    {safeFormat(evt.timestamp, "hh:mm a")}
                  </div>
                </div>
                {evt.device_meta?.platform && (
                  <span className="text-[9px] text-neutral-400 shrink-0 hidden sm:block">
                    {evt.device_meta.platform}
                  </span>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Projects */}
      {Array.isArray(data?.projects) && data.projects.length > 0 && (
        <div>
          <h4 className="text-sm font-bold mb-2">Projects Worked</h4>
          <div className="flex flex-wrap gap-2">
            {data.projects.map((p: string, i: number) => (
              <span
                key={i}
                className="text-[10px] bg-neutral-100 dark:bg-neutral-800 px-2 py-1 rounded-full"
              >
                {p}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Tasks */}
      {Array.isArray(data?.tasks) && data.tasks.length > 0 && (
        <div>
          <h4 className="text-sm font-bold mb-2">Tasks Completed</h4>
          <div className="flex flex-wrap gap-2">
            {data.tasks.map((t: string, i: number) => (
              <span
                key={i}
                className="text-[10px] bg-primary-50 dark:bg-primary-950/40 text-primary-700 dark:text-primary-300 border border-primary-200 dark:border-primary-800 px-2 py-1 rounded-full"
              >
                {t}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useMemo } from "react";
import Link from "next/link";
import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { format, parseISO } from "date-fns";
import { Card, CardHeader, CardTitle, CardContent, AppIcon, Avatar, AvatarFallback, AvatarImage, Badge, Skeleton, EmptyState } from "@g4k/ui/components";

import { apiFetch } from "@/lib/api-client";
import { STALE_TIME_ATTENDANCE, queryKeys } from "@/lib/query-keys";
import { safeFromNow } from "@/lib/format";

interface MemberDay {
  id: number;
  user_id: number;
  user_name: string;
  user_email: string;
  status: string;
  clock_in?: string;
  clock_out?: string;
  has_open_shift?: boolean;
}

export function HrActivityFeedWidget() {
  const todayDate = format(new Date(), "yyyy-MM-dd");
  const { data, isLoading, error } = useQuery({
    queryKey: queryKeys.hrAttendance(todayDate),
    queryFn: () => apiFetch(`/attendance/hr/today?date=${todayDate}`),
    staleTime: STALE_TIME_ATTENDANCE,
    placeholderData: keepPreviousData,
  });

  const activities = useMemo(() => {
    const items = (Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : [])) as MemberDay[];
    const acts: any[] = [];
    
    items.forEach((member: MemberDay) => {
      const userObj = {
        id: member.user_id,
        name: member.user_name || "Unknown",
      };

      // Check for late arrivals
      if (member.status === "late" && member.clock_in) {
        acts.push({
          id: `late-${member.user_id}`,
          user: userObj,
          type: "late",
          message: "Clocked in late",
          timestamp: member.clock_in,
          icon: "teamAttendance",
          color: "text-amber-500",
          bg: "bg-amber-100 dark:bg-amber-950/30",
        });
      }

      // Check for open shifts
      if (member.has_open_shift && member.clock_in) {
        acts.push({
          id: `open-${member.user_id}`,
          user: userObj,
          type: "open_shift",
          message: "Shift currently open",
          timestamp: member.clock_in,
          icon: "activity",
          color: "text-emerald-500",
          bg: "bg-emerald-100 dark:bg-emerald-950/30",
        });
      }
    });

    // Sort descending by timestamp
    return acts.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 10);
  }, [data]);

  return (
    <div className="h-[400px] bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 overflow-hidden flex flex-col transition-shadow duration-150">
      <div className="flex items-center justify-between pb-3">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-[var(--radius)] bg-primary-100 dark:bg-primary-950 flex items-center justify-center">
            <AppIcon name="activity" className=" text-primary-600 dark:text-primary-400" />
          </div>
          <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider">
            Team Activity Feed
          </span>
        </div>
        <span className="text-[10px] font-bold text-primary-600 dark:text-primary-400 uppercase tracking-wider bg-primary-100 dark:bg-primary-900/30 px-2 py-0.5 rounded-full">
          Live
        </span>
      </div>
      
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {isLoading && (
          <div className="space-y-4">
            {[1, 2, 3].map(i => (
              <div key={i} className="flex gap-3">
                <Skeleton className="w-8 h-8 rounded-full shrink-0" />
                <div className="space-y-2 flex-1">
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-3 w-1/4" />
                </div>
              </div>
            ))}
          </div>
        )}

        {error && (
          <div className="text-sm text-rose-600 p-2 text-center bg-rose-50 dark:bg-rose-950/30 rounded-[var(--radius)]">
            Failed to load activity
