"use client";

import { useQuery } from "@tanstack/react-query";
import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { STALE_TIME_ATTENDANCE, queryKeys } from "@/lib/query-keys";
import { useUrlState } from "@/hooks/use-url-state";
import { useMemo } from "react";


export function HrAttendanceAnalytics() {
  const [selectedDate] = useUrlState("date", format(new Date(), "yyyy-MM-dd"));
  const [deptFilter] = useUrlState("dept", "all");

  const { data, isLoading } = useQuery({
    queryKey: ['attendance-analytics-hr', selectedDate, deptFilter],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (selectedDate) params.append("date", selectedDate);
      if (deptFilter && deptFilter !== "all") params.append("department_id", deptFilter);
      
      try {
        // Try the new analytics endpoint first
        return await apiFetch(`/attendance/hr/analytics?${params.toString()}`);
      } catch (e) {
        // Fallback to overview if analytics endpoint doesn't exist yet
        params.append("per_page", "1000"); // Try to get all records for stats
        return await apiFetch(`/attendance/hr/today?${params.toString()}`);
      }
    },
    staleTime: STALE_TIME_ATTENDANCE,
  });

  const stats = useMemo(() => {
    // If backend returns the new dedicated analytics object shape
    if (data && !Array.isArray(data) && !data.data && data.present !== undefined) {
      return {
        present: data.present || 0,
        absent: data.absent || 0,
        late: data.late || 0,
        leave: data.leave || 0,
        total: data.total || 0,
        avgClockIn: data.avg_clock_in || "—",
        totalOvertime: data.total_overtime_formatted || "—",
      };
    }

    // Fallback: calculate from records
    const records = (Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []));
    let present = 0;
    let absent = 0;
    let late = 0;
    let leave = 0;
    let totalOvertimeSecs = 0;
    let totalClockInTime = 0;
    let clockInCount = 0;

    records.forEach((record: any) => {
      const status = record.status;
      if (status === "present") present++;
      else if (status === "absent") absent++;
      else if (status === "late") late++;
      else if (status === "leave") leave++;

      if (record.overtime_seconds > 0) {
        totalOvertimeSecs += record.overtime_seconds;
      }

      if (record.clock_in) {
        const d = new Date(record.clock_in);
        // Get hours and minutes since midnight
        const mins = d.getHours() * 60 + d.getMinutes();
        totalClockInTime += mins;
        clockInCount++;
      }
    });

    const total = present + absent + late + leave;
    const avgClockInMins = clockInCount > 0 ? Math.floor(totalClockInTime / clockInCount) : 0;
    const avgClockInFmt = avgClockInMins > 0 
      ? `${String(Math.floor(avgClockInMins / 60)).padStart(2, "0")}:${String(avgClockInMins % 60).padStart(2, "0")}`
      : "—";

    const otHours = Math.floor(totalOvertimeSecs / 3600);
    const otMins = Math.floor((totalOvertimeSecs % 3600) / 60);
    const otFmt = totalOvertimeSecs > 0 ? `${otHours}h ${otMins}m` : "—";

    return {
      present,
      absent,
      late,
      leave,
      total,
      avgClockIn: avgClockInFmt,
      totalOvertime: otFmt,
    };
  }, [data]);

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
        {[...Array(4)].map((_, i) => (
          <div key={i} className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-xl p-4 flex flex-col justify-center animate-pulse">
            <div className="h-4 bg-neutral-200 dark:bg-neutral-800 rounded w-1/2 mb-2"></div>
            <div className="h-8 bg-neutral-200 dark:bg-neutral-800 rounded w-3/4"></div>
          </div>
        ))}
      </div>
    );
  }

  const cards = [
    { title: "Present", value: stats.present, icon: "directory", color: "text-success", bg: "bg-success/10", total: stats.total },
    { title: "Late", value: stats.late, icon: "teamAttendance", color: "text-warning", bg: "bg-warning/10", total: stats.total },
    { title: "Absent", value: stats.absent, icon: "calendarX", color: "text-danger", bg: "bg-danger/10", total: stats.total },
    { title: "On Leave", value: stats.leave, icon: "calendar", color: "text-info", bg: "bg-info/10", total: stats.total },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
      {cards.map((card, i) => (
        <div key={i} className="bg-card border border-border rounded-xl p-4 relative overflow-hidden group hover:border-primary/50 transition-colors">
          <div className="flex items-center justify-between mb-3">
            <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400">{card.title}</h4>
            <div className={`p-1.5 rounded-[var(--radius)] ${card.bg}`}>
              <AppIcon name={card.icon as IconName} className={`w-4 h-4 ${card.color}`} />
            </div>
          </div>
          <div className="flex items-end gap-2">
            <span className="text-2xl font-bold text-neutral-900 dark:text-white">
              {card.value}
            </span>
            {card.total !== undefined && card.total > 0 && (
              <span className="text-xs text-neutral-400 dark:text-neutral-500 mb-1 font-medium">
                / {card.total}
              </span>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import dynamic from "next/dynamic";
import { Skeleton } from "@g4k/ui/components";
import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { AppIcon, IconName } from "@g4k/ui/components";
import { format } from "date-fns";
import { safeFormat } from "@/lib/format";

import * as echarts from 'echarts/core';
import { BarChart, LineChart } from 'echarts/charts';
import { TooltipComponent, LegendComponent, GridComponent } from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';

echarts.use([BarChart, LineChart, TooltipComponent, LegendComponent, GridComponent, CanvasRenderer]);

const ReactECharts = dynamic(() => import("echarts-for-react/lib/core").then((mod) => {
  const Core = mod.default || (mod as any);
  return function EChartsWrapper(props: any) {
    return <Core echarts={echarts} {...props} />;
  };
}), { 
  ssr: false,
  loading: () => <Skeleton className="w-full h-[400px]" />
}) as any;

export function HrAttendanceGraph() {
  const [groupBy, setGroupBy] = useState<"date" | "employee">("date");
  const [mode, setMode] = useState<"weekly" | "monthly">("weekly");
  const [date, setDate] = useState(format(new Date(), "yyyy-MM-dd"));

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.hrAttendanceGraph(groupBy, mode, date),
    queryFn: () => apiFetch(`/attendance/hr/graph?groupBy=${groupBy}&mode=${mode}&date=${date}`),
  });

  const chartData = useMemo(() => {
    if (!data?.stats) return { labels: [], present: [], absent: [], late: [], hours: [], overtime: [] };
    
    const stats = data.stats;
    const labels = stats.map((d: any) => groupBy === "date" ? safeFormat(d.date, "MMM d") : d.name);
    const present = stats.map((d: any) => d.present || 0);
    const absent = stats.map((d: any) => d.absent || 0);
    const late = stats.map((d: any) => d.late || 0);
    const hours = stats.map((d: any) => Number(((d.total_seconds || 0) / 3600).toFixed(1)));
    const overtime = stats.map((d: any) => Number(((d.overtime_seconds || 0) / 3600).toFixed(1)));

    return { labels, present, absent, late, hours, overtime };
  }, [data, groupBy]);

  const option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' }
    },
    legend: {
      data: ['Present', 'Late', 'Absent', 'Total Hours', 'Overtime (hrs)'],
      bottom: 0,
      textStyle: {
        color: '#6b7280'
      }
    },
    grid: {
      left: '3%',
      right: '4%',
      bottom: '10%',
      top: '5%',
      containLabel: true
    },
    xAxis: [
      {
        type: 'category',
        data: chartData.labels,
        axisLabel: {
          interval: 0,
          rotate: groupBy === "employee" ? 45 : 0,
          color: '#6b7280'
        }
      }
    ],
    yAxis: [
      {
        type: 'value',
        name: 'Days/Count',
        minInterval: 1,
        axisLabel: {
          color: '#6b7280'
        }
      },
      {
        type: 'value',
        name: 'Hours',
        position: 'right',
        axisLabel: { color: '#6b7280' },
        splitLine: { show: false }
      }
    ],
    series: [
      {
        name: 'Present',
        type: 'bar',
        stack: 'Total',
        itemStyle: { color: '#34d399', borderRadius: [0, 0, 0, 0] }, // emerald-400
        data: chartData.present
      },
      {
        name: 'Late',
        type: 'bar',
        stack: 'Total',
        itemStyle: { color: '#fbbf24', borderRadius: [0, 0, 0, 0] }, // amber-400
        data: chartData.late
      },
      {
        name: 'Absent',
        type: 'bar',
        stack: 'Total',
        itemStyle: { color: '#f87171', borderRadius: [4, 4, 0, 0] }, // red-400
        data: chartData.absent
      },
      {
        name: 'Total Hours',
        type: 'line',
        yAxisIndex: 1,
        itemStyle: { color: '#6366f1' }, // indigo-500
        lineStyle: { width: 3 },
        smooth: true,
        data: chartData.hours
      },
      {
        name: 'Overtime (hrs)',
        type: 'line',
        yAxisIndex: 1,
        itemStyle: { color: '#f59e0b' }, // amber-500
        lineStyle: { width: 2, type: 'dashed' },
        smooth: true,
        data: chartData.overtime
      }
    ]
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-card p-4 rounded-xl border border-border shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        <div className="flex items-center gap-2 bg-secondary p-1 rounded-[var(--radius)]">
          <button
            onClick={() => setGroupBy("date")}
            className={`px-4 py-1.5 rounded-[var(--radius)] text-sm font-medium transition-colors ${
              groupBy === "date" 
                ? "bg-card text-foreground shadow-e1" 
                : "text-muted-foreground hover:text-neutral-700 dark:hover:text-neutral-300"
            }`}
          >
            Team Overview
          </button>
          <button
            onClick={() => setGroupBy("employee")}
            className={`px-4 py-1.5 rounded-[var(--radius)] text-sm font-medium transition-colors ${
              groupBy === "employee" 
                ? "bg-card text-foreground shadow-e1" 
                : "text-muted-foreground hover:text-neutral-700 dark:hover:text-neutral-300"
            }`}
          >
            Per Employee
          </button>
        </div>

        <div className="flex items-center gap-2 bg-secondary p-1 rounded-[var(--radius)]">
          <button
            onClick={() => setMode("weekly")}
            className={`px-4 py-1.5 rounded-[var(--radius)] text-sm font-medium transition-colors ${
              mode === "weekly" 
                ? "bg-card text-foreground shadow-e1" 
                : "text-muted-foreground hover:text-neutral-700 dark:hover:text-neutral-300"
            }`}
          >
            This Week
          </button>
          <button
            onClick={() => setMode("monthly")}
            className={`px-4 py-1.5 rounded-[var(--radius)] text-sm font-medium transition-colors ${
              mode === "monthly" 
                ? "bg-card text-foreground shadow-e1" 
                : "text-muted-foreground hover:text-neutral-700 dark:hover:text-neutral-300"
            }`}
          >
            This Month
          </button>
        </div>
      </div>

      <div className="w-full bg-card rounded-xl p-6 border border-border relative min-h-[450px] shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        {isLoading ? (
          <div className="absolute inset-0 flex items-center justify-center bg-surface/50 dark:bg-neutral-900/50 backdrop-blur-sm z-10 rounded-xl">
            <AppIcon name="loading" size="2xl" className=" animate-spin text-emerald-500" />
          </div>
        ) : !data?.stats || data.stats.length === 0 ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-muted-foreground z-10">
            <div className="w-16 h-16 rounded-full bg-secondary flex items-center justify-center mb-4">
              <AppIcon name="chart" size="2xl" className="text-muted-foreground" />
            </div>
            <p className="font-medium">No data available for this period</p>
          </div>
        ) : null}
        
        <ReactECharts
          option={option}
          style={{ height: '400px', width: '100%' }}
          notMerge={true}
        />
      </div>
    </div>
  );
}

