"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { format } from "date-fns";
import { safeFormat } from "@/lib/format";
import { AppIcon, IconName } from "@g4k/ui/components";
import Link from "next/link";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@g4k/ui/components";
import { Skeleton, Tabs, TabsList, TabsTrigger, TabsContent } from "@g4k/ui/components";
import { EmptyState } from "@g4k/ui/components";
import { StatusBadge } from "@g4k/ui/components/badge";
import { apiFetch } from "@/lib/api-client";
import { AttendanceHistoryCalendar } from "./attendance-history-calendar";
import { TeamMemberTrendsGraph } from "./team-member-trends-graph";

interface TeamMemberAttendanceSheetProps {
  userId: number | null;
  date: string;
  initialTab?: "day" | "history" | "trends";
  onClose: () => void;
}
import { queryKeys } from "@/lib/query-keys";

import { useEffect } from "react";

export function TeamMemberAttendanceSheet({ userId, date, initialTab = "day", onClose }: TeamMemberAttendanceSheetProps) {
  const [tab, setTab] = useState(initialTab);

  useEffect(() => {
    if (userId) {
      setTab(initialTab);
    }
  }, [userId, initialTab]);

  const { data: dayData, isLoading: isLoadingDay } = useQuery({
    queryKey: userId !== null ? queryKeys.memberAttendanceDay(userId, date) : [],
    queryFn: () => apiFetch(`/attendance/hr/day/${date}/${userId}`),
    enabled: !!userId && !!date && tab === "day",
  });

  const { data: historyData, isLoading: isLoadingHistory } = useQuery({
    queryKey: userId !== null ? queryKeys.memberHistory(userId) : [],
    queryFn: () => apiFetch(`/attendance/hr/history/${userId}`),
    enabled: !!userId && tab === "history",
  });

  const day = dayData?.day;
  const events = dayData?.events || [];
  const user = dayData?.user;

  // Process breaks from events
  const breaks = [];
  if (events) {
    let currentBreakStart = null;
    for (const event of events) {
      if (event.type === "break_start") {
        currentBreakStart = event;
      } else if (event.type === "break_end" && currentBreakStart) {
        const start = new Date(currentBreakStart.timestamp);
        const end = new Date(event.timestamp);
        const durationSecs = Math.floor((end.getTime() - start.getTime()) / 1000);
        breaks.push({ start, end, duration: durationSecs, isApproved: currentBreakStart.is_approved });
        currentBreakStart = null;
      }
    }
    if (currentBreakStart) {
      const start = new Date(currentBreakStart.timestamp);
      const end = new Date();
      const durationSecs = Math.floor((end.getTime() - start.getTime()) / 1000);
      breaks.push({ start, end: null, duration: durationSecs, isOngoing: true, isApproved: currentBreakStart.is_approved });
    }
  }

  return (
    <Sheet open={!!userId} onOpenChange={(open) => !open && onClose()}>
      <SheetContent className="w-full sm:max-w-xl md:max-w-2xl lg:max-w-3xl overflow-y-auto">
        <SheetHeader className="mb-6">
          <SheetTitle>Attendance Details</SheetTitle>
          <SheetDescription>
            {user ? `${user.name} - ${safeFormat(date, "EEEE, MMMM do, yyyy")}` : "Loading..."}
          </SheetDescription>
        </SheetHeader>

        <Tabs value={tab} onValueChange={(value) => setTab(value as "day" | "history" | "trends")} className="w-full">
          <TabsList className="w-full mb-6">
            <TabsTrigger value="day" className="flex-1">Day Timeline</TabsTrigger>
            <TabsTrigger value="history" className="flex-1">Full History</TabsTrigger>
            <TabsTrigger value="trends" className="flex-1">Trends</TabsTrigger>
          </TabsList>

          <TabsContent value="day" className="mt-0">
            {isLoadingDay ? (
              <div className="space-y-6">
                <Skeleton className="h-24 w-full" />
                <Skeleton className="h-[300px] w-full" />
              </div>
            ) : !day && events.length === 0 ? (
              <EmptyState
                title="No Attendance Data"
                description="There are no punch records for this employee on this date."
                icon={<AppIcon name="teamAttendance" size="2xl" className=" text-neutral-300" />}
              />
            ) : (
              <div className="space-y-8">
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-neutral-50 dark:bg-neutral-900 p-4 rounded-xl border border-neutral-100 dark:border-neutral-800">
                    <div className="text-xs text-neutral-500 mb-1 font-semibold uppercase tracking-wider">Productive Hours</div>
                    <div className="text-2xl font-mono font-bold text-neutral-900 dark:text-white">
                      {day?.total_seconds ? `${Math.floor(day.total_seconds / 3600)}h ${Math.floor((day.total_seconds % 3600) / 60)}m` : "0h 0m"}
                    </div>
                  </div>
                  <div className="bg-amber-50 dark:bg-amber-950/30 p-4 rounded-xl border border-amber-100 dark:border-amber-900/50">
                    <div className="text-xs text-amber-600/80 dark:text-amber-500/80 mb-1 font-semibold uppercase tracking-wider">Overtime</div>
                    <div className="text-2xl font-mono font-bold text-amber-700 dark:text-amber-400">
                      {day?.overtime_seconds ? `${Math.floor(day.overtime_seconds / 3600)}h ${Math.floor((day.overtime_seconds % 3600) / 60)}m` : "0h 0m"}
                    </div>
                  </div>
                </div>

                {/* Breaks Summary */}
                <div className="bg-neutral-50 dark:bg-neutral-900 p-4 rounded-xl border border-neutral-100 dark:border-neutral-800 flex flex-col gap-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2 text-neutral-500">
                      <AppIcon name="break" />
                      <span className="text-sm font-medium">Unapproved Break Duration</span>
                    </div>
                    <span className="text-sm font-bold text-neutral-900 dark:text-white">
                      {day?.unapproved_break_seconds ? `${Math.floor(day.unapproved_break_seconds / 3600)}h ${Math.floor((day.unapproved_break_seconds % 3600) / 60)}m` : "0h 0m"}
                      {breaks.length > 0 && <span className="text-xs text-neutral-400 font-normal ml-1">({breaks.filter((b: any) => !b.isApproved).length})</span>}
                    </span>
                  </div>
                  {breaks.length > 0 && (
                    <div className="pl-6 space-y-2 mt-1 border-l-2 border-neutral-100 dark:border-neutral-800 ml-1.5 py-1">
                      {breaks.map((b: any, i: number) => (
                        <div key={i} className="flex justify-between items-center text-xs text-neutral-500">
                          <div className="flex items-center gap-2">
                            <span>
                              {b.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {b.isOngoing ? "Now" : b.end?.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </span>
                            <StatusBadge status={b.isApproved ? "success" : "warning"} dot className="text-[10px] py-0 px-1.5 h-4">
                              {b.isApproved ? "Approved" : "Unapproved"}
                            </StatusBadge>
                          </div>
                          <span className="font-mono">{Math.floor(b.duration / 60)}m</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
                {day?.late_minutes > 0 && (
                  <div className="bg-amber-100/50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-400 p-3 rounded-[var(--radius)] border border-amber-200 dark:border-amber-800/50 text-sm font-medium flex items-center gap-2">
                    <AppIcon name="error" />
                    Late by {day.late_minutes}m
                  </div>
                )}

                <div>
                  <h3 className="text-sm font-bold text-neutral-900 dark:text-white mb-4 uppercase tracking-wider">Timeline</h3>
                  <div className="relative pl-4 space-y-6 before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-border">
                    {events.map((event: any, i: number) => {
                      const isClockIn = event.type === 'clock_in';
                      const isClockOut = event.type === 'clock_out';
                      const isBreakStart = event.type === 'break_start';
                      const isBreakEnd = event.type === 'break_end';
                      
                      return (
                        <div key={event.id} className="relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group is-active">
                          <div className={`flex items-center justify-center w-6 h-6 rounded-full border-2 bg-card dark:bg-neutral-950 shrink-0 md:order-1 shadow-e1 hover:shadow-e2 transition-shadow duration-150 z-10 ${
                            isClockIn ? 'border-emerald-500' : isClockOut ? 'border-rose-500' : 'border-amber-400'
                          }`}>
                            {isClockIn && <AppIcon name="success" size="xs" className=" text-emerald-500" />}
                            {isClockOut && <div className="w-2 h-2 bg-rose-500 rounded-sm" />}
                            {(isBreakStart || isBreakEnd) && <AppIcon name="teamAttendance" size="xs" className=" text-amber-500" />}
                          </div>
                          
                          <div className="w-[calc(100%-2rem)] md:w-[calc(50%-1.5rem)] px-4">
                            <div className="flex flex-col bg-card dark:bg-neutral-900 p-3 rounded-xl border border-neutral-100 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150">
                              <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                  <span className="font-bold text-sm text-neutral-900 dark:text-white capitalize">
                                    {event.type.replace('_', ' ')}
                                  </span>
                                  {event.is_manual && (
                                    <Link 
                                      href={`/dashboard/audit?action=attendance_correction&user_id=${userId}`}
                                      title="View in audit log"
                                    >
                                      <StatusBadge status="info" className="uppercase hover:opacity-80 transition-opacity">
                                        Manual
                                      </StatusBadge>
                                    </Link>
                                  )}
                                </div>
                                <time className="text-xs font-mono text-neutral-500">
                                  {safeFormat(event.timestamp, "hh:mm a")}
                                </time>
                              </div>
                              
                              {event.device_meta && (
                                <div className="flex items-center gap-1.5 mt-2 text-[10px] text-neutral-400 font-medium bg-neutral-50 dark:bg-neutral-950 px-2 py-1 rounded-[var(--radius)] w-fit">
                                  <AppIcon name="devices" size="xs" />
                                  {event.device_meta.platform} • {event.device_meta.ip}
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            )}
          </TabsContent>

          <TabsContent value="history" className="mt-0 h-[400px]">
            {isLoadingHistory ? (
              <div className="flex items-center justify-center h-full">
                <AppIcon name="loading" size="2xl" className=" animate-spin text-neutral-400" />
              </div>
            ) : (
              <AttendanceHistoryCalendar 
                days={historyData?.data || []} 
                userId={userId || undefined}
              />
            )}
          </TabsContent>

          <TabsContent value="trends" className="mt-0">
            {userId && <TeamMemberTrendsGraph userId={userId} />}
          </TabsContent>
        </Tabs>
      </SheetContent>
    </Sheet>
  );
}

"use client";

import { useMemo, useState } from "react";
import dynamic from "next/dynamic";
import { Skeleton } from "@g4k/ui/components";
import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api-client";
import { AppIcon, IconName } from "@g4k/ui/components";
import { format } from "date-fns";
import { safeFormat } from "@/lib/format";

import * as echarts from 'echarts/core';
import { BarChart, LineChart } from 'echarts/charts';
import { TooltipComponent, LegendComponent, GridComponent } from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';

echarts.use([BarChart, LineChart, TooltipComponent, LegendComponent, GridComponent, CanvasRenderer]);

const ReactECharts = dynamic(() => import("echarts-for-react/lib/core").then((mod) => {
  const Core = mod.default || (mod as any);
  return function EChartsWrapper(props: any) {
    return <Core echarts={echarts} {...props} />;
  };
}), { 
  ssr: false,
  loading: () => <Skeleton className="w-full h-[400px]" />
}) as any;

export function TeamMemberTrendsGraph({ userId }: { userId: number }) {
  const [mode, setMode] = useState<"weekly" | "monthly">("weekly");
  const date = format(new Date(), "yyyy-MM-dd");

  const { data, isLoading } = useQuery({
    queryKey: ['attendance_graph', userId, mode, date],
    queryFn: () => apiFetch(`/attendance/hr/graph?user_id=${userId}&mode=${mode}&date=${date}`),
    enabled: !!userId,
  });

  const chartData = useMemo(() => {
    if (!data?.stats) return { labels: [], hours: [], overtime: [] };
    
    const stats = data.stats;
    const labels = stats.map((d: any) => safeFormat(d.date, "MMM d"));
    // Convert seconds to hours
    const hours = stats.map((d: any) => parseFloat(((d.total_seconds || 0) / 3600).toFixed(2)));
    const overtime = stats.map((d: any) => parseFloat(((d.overtime_seconds || 0) / 3600).toFixed(2)));
    
    return { labels, hours, overtime };
  }, [data]);

  const option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' }
    },
    legend: {
      data: ['Hours Worked', 'Overtime'],
      bottom: 0,
      textStyle: { color: '#6b7280' }
    },
    grid: {
      left: '3%',
      right: '4%',
      bottom: '10%',
      top: '5%',
      containLabel: true
    },
    xAxis: [
      {
        type: 'category',
        data: chartData.labels,
        axisLabel: { color: '#6b7280' }
      }
    ],
    yAxis: [
      {
        type: 'value',
        name: 'Hours',
        axisLabel: { color: '#6b7280' }
      }
    ],
    series: [
      {
        name: 'Hours Worked',
        type: 'bar',
        itemStyle: { color: '#8b5cf6', borderRadius: [4, 4, 0, 0] }, // violet-500
        data: chartData.hours
      },
      {
        name: 'Overtime',
        type: 'line',
        itemStyle: { color: '#fbbf24' }, // amber-400
        data: chartData.overtime
      }
    ]
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-end bg-card dark:bg-neutral-900 p-4 rounded-xl border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        <div className="flex items-center gap-2 bg-neutral-100 dark:bg-neutral-800 p-1 rounded-[var(--radius)]">
          <button
            onClick={() => setMode("weekly")}
            className={`px-4 py-1.5 rounded-[var(--radius)] text-sm font-medium transition-colors ${
              mode === "weekly" 
                ? "bg-card dark:bg-neutral-900 text-neutral-900 dark:text-white shadow-e1 hover:shadow-e2 transition-shadow duration-150" 
                : "text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300"
            }`}
          >
            This Week
          </button>
          <button
            onClick={() => setMode("monthly")}
            className={`px-4 py-1.5 rounded-[var(--radius)] text-sm font-medium transition-colors ${
              mode === "monthly" 
                ? "bg-card dark:bg-neutral-900 text-neutral-900 dark:text-white shadow-e1 hover:shadow-e2 transition-shadow duration-150" 
                : "text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300"
            }`}
          >
            This Month
          </button>
        </div>
      </div>

      <div className="bg-card dark:bg-neutral-900 rounded-xl border border-neutral-200 dark:border-neutral-800 p-4 relative min-h-[400px] shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        {isLoading && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-surface/50 dark:bg-neutral-900/50 backdrop-blur-sm rounded-xl">
            <AppIcon name="loading" size="xl" className=" animate-spin text-primary-500" />
          </div>
        )}
        
        {(!data?.stats || data.stats.length === 0) && !isLoading ? (
          <div className="absolute inset-0 flex items-center justify-center text-neutral-500">
            No trend data available for this period.
          </div>
        ) : null}
        
        <ReactECharts option={option} style={{ height: '400px', width: '100%' }} />
      </div>
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api-client";
import { Card, CardContent, CardHeader, CardTitle, StatusBadge } from "@g4k/ui/components";
import { AppIcon, IconName } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { useTimerStore } from "@/stores/timer-store";
import { LiveTimer } from "@/components/attendance/live-timer";
import { Badge } from "@g4k/ui/components";
import { queryKeys, STALE_TIME_ATTENDANCE } from "@/lib/query-keys";

export function TodaySummaryCard() {
  const isActive = useTimerStore((s) => s.isActive);
  const isOnBreak = useTimerStore((s) => s.isOnBreak);

  const { data, isPending } = useQuery({
    queryKey: queryKeys.attendanceToday,
    queryFn: () => apiFetch("/attendance/me/today"),
    staleTime: STALE_TIME_ATTENDANCE,
    placeholderData: keepPreviousData,
  });

  const setStandardSeconds = useTimerStore((s) => s.setStandardSeconds);
  
  useEffect(() => {
    if (data?.standard_seconds) {
      setStandardSeconds(data.standard_seconds);
    }
  }, [data?.standard_seconds, setStandardSeconds]);

  if (isPending) {
    return (
      <Card className="h-full border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
        <CardHeader>
          <Skeleton className="h-6 w-32" />
        </CardHeader>
        <CardContent className="space-y-4">
          <Skeleton className="h-4 w-full" />
          <Skeleton className="h-4 w-3/4" />
          <Skeleton className="h-4 w-1/2" />
        </CardContent>
      </Card>
    );
  }

  const day = data?.day;
  const standardSeconds = data?.standard_seconds || 31500;

  const formatTime = (secs: number) => {
    const h = Math.floor(secs / 3600);
    const m = Math.floor((secs % 3600) / 60);
    return `${h}h ${m}m`;
  };

  const getStatusBadge = () => {
    if (day?.status === "absent" && !isActive) return <StatusBadge status="danger" dot className="uppercase">ABSENT</StatusBadge>;
    if (isOnBreak) return <StatusBadge status="warning" dot className="uppercase">ON BREAK</StatusBadge>;
    if (isActive) return <StatusBadge status="success" dot className="uppercase">ACTIVE SHIFT</StatusBadge>;
    if (day?.status === "present") return <StatusBadge status="info" dot className="uppercase">COMPLETED</StatusBadge>;
    if (day?.status === "late") return <StatusBadge status="warning" dot className="uppercase">LATE</StatusBadge>;
    return <StatusBadge status="neutral" dot className="uppercase">OFF</StatusBadge>;
  };

  const isLate = day?.status === "late";
  const lateMinutes = day?.late_minutes || 0;

  // Process breaks from events
  const breaks = [];
  if (data?.events) {
    let currentBreakStart = null;
    for (const event of data.events) {
      if (event.type === "break_start") {
        currentBreakStart = event;
      } else if (event.type === "break_end" && currentBreakStart) {
        const start = new Date(currentBreakStart.timestamp);
        const end = new Date(event.timestamp);
        const durationSecs = Math.floor((end.getTime() - start.getTime()) / 1000);
        breaks.push({ start, end, duration: durationSecs });
        currentBreakStart = null;
      }
    }
    // Handle ongoing break
    if (currentBreakStart) {
      const start = new Date(currentBreakStart.timestamp);
      const end = new Date();
      const durationSecs = Math.floor((end.getTime() - start.getTime()) / 1000);
      breaks.push({ start, end: null, duration: durationSecs, isOngoing: true });
    }
  }

  return (
    <Card className="h-full flex flex-col border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader className="pb-3 border-b border-neutral-100 dark:border-neutral-800 flex flex-row items-center justify-between">
        <CardTitle className="text-base font-bold flex items-center gap-2">
          <AppIcon name="info" className=" text-emerald-600" />
          Today's Summary
        </CardTitle>
        {getStatusBadge()}
      </CardHeader>
      <CardContent className="pt-4 flex-1 flex flex-col justify-between">
        {!day && !isActive && !isOnBreak ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-6 bg-neutral-50 dark:bg-neutral-900/50 rounded-xl border border-dashed border-neutral-200 dark:border-neutral-800">
            <AppIcon name="teamAttendance" size="xl" className="text-neutral-300 dark:text-neutral-700 mb-3" />
            <p className="text-sm font-semibold text-neutral-600 dark:text-neutral-400">
              You haven't clocked in yet
            </p>
            <p className="text-xs text-neutral-500 mt-1">
              Start your shift using the Time Clock widget.
            </p>
          </div>
        ) : (
          <>
            <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-neutral-500">
              <AppIcon name="teamAttendance" />
              <span className="text-sm font-medium">Clock In</span>
            </div>
            <span className="text-sm font-bold text-neutral-900 dark:text-white">
              {day?.clock_in ? new Date(day.clock_in).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "--:--"}
            </span>
          </div>

          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-neutral-500">
                <AppIcon name="break" />
                <span className="text-sm font-medium">Break Duration</span>
              </div>
              <span className="text-sm font-bold text-neutral-900 dark:text-white">
                {day?.break_seconds ? formatTime(day.break_seconds) : "0h 0m"}
                {breaks.length > 0 && <span className="text-xs text-neutral-400 font-normal ml-1">({breaks.length})</span>}
              </span>
            </div>

            {breaks.length > 0 && (
              <div className="pl-6 space-y-1 mt-1 border-l-2 border-neutral-100 dark:border-neutral-800 ml-1.5">
                {breaks.map((b, i) => (
                  <div key={i} className="flex justify-between items-center text-xs text-neutral-500">
                    <span>
                      {b.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {b.isOngoing ? "Now" : b.end?.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                    <span className="font-mono">{Math.floor(b.duration / 60)}m</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-neutral-500">
              <AppIcon name="logout" />
              <span className="text-sm font-medium">Clock Out</span>
            </div>
            <span className="text-sm font-bold text-neutral-900 dark:text-white">
              {day?.clock_out ? new Date(day.clock_out).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : (isActive ? "In Progress" : "--:--")}
            </span>
          </div>

          {isLate && (
            <div className="bg-amber-50 dark:bg-amber-950/30 p-3 rounded-[var(--radius)] border border-amber-100 dark:border-amber-900/50 flex items-start gap-2">
              <AppIcon name="warning" className=" text-amber-600 mt-0.5" />
              <div>
                <p className="text-xs font-bold text-amber-700 dark:text-amber-500">Late Arrival</p>
                <p className="text-[11px] text-amber-600 dark:text-amber-400 mt-0.5">
                  You clocked in {lateMinutes} minutes after your shift start.
                </p>
              </div>
            </div>
          )}

          {day?.clock_in && !isLate && (
            <div className="bg-emerald-50 dark:bg-emerald-950/30 p-2 rounded-[var(--radius)] border border-emerald-100 dark:border-emerald-900/50 flex items-center justify-center">
              <span className="text-xs font-bold text-emerald-700 dark:text-emerald-500 flex items-center gap-1">On Time Arrival <AppIcon name="check" size="xs" /></span>
            </div>
          )}

        </div>

        <div className="mt-6 pt-4 border-t border-neutral-100 dark:border-neutral-800">
          <LiveTimer
            render={(formattedTime, displaySeconds) => {
              const isOvertime = displaySeconds > standardSeconds;
              return (
                <>
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium text-neutral-500">Total Worked</span>
                    <span className="text-lg font-bold text-neutral-900 dark:text-white font-mono tabular-nums">
                      {formattedTime}
                    </span>
                  </div>
                  {isOvertime && (
                    <div className="flex items-center justify-between mt-1">
                      <span className="text-xs font-medium text-amber-600">Overtime</span>
                      <span className="text-xs font-bold text-amber-600 font-mono tabular-nums">
                        +{formatTime(displaySeconds - standardSeconds)}
                      </span>
                    </div>
                  )}
                </>
              );
            }}
            />
          </div>
        </>
        )}
      </CardContent>
    </Card>
  );
}

