import { useState, useRef, useEffect } from "react";
import { AppIcon, IconName } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { FileUploadPopup } from "@g4k/ui/components";

export function MessageComposer({
  onSend,
  disabled,
  conversation,
}: {
  onSend: (body: string, mentions?: number[], attachment?: File | null) => void;
  disabled?: boolean;
  conversation?: any;
}) {
  const [text, setText] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  
  // Mentions state
  const [showMentions, setShowMentions] = useState(false);
  const [mentionQuery, setMentionQuery] = useState("");
  const [mentionIndex, setMentionIndex] = useState(-1);
  const [selectedMentions, setSelectedMentions] = useState<number[]>([]);
  const [mentionNavIndex, setMentionNavIndex] = useState(0);

  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const [showUploadPopup, setShowUploadPopup] = useState(false);


  useEffect(() => {
    // Detect @ typing
    const match = text.match(/@(\w*)$/);
    if (match) {
      setMentionQuery(match[1]);
      setMentionIndex(text.lastIndexOf("@"));
      setShowMentions(true);
      setMentionNavIndex(0);
    } else {
      setShowMentions(false);
    }
  }, [text]);

  const filteredUsers = conversation?.users?.filter((u: any) => 
    u.name.toLowerCase().includes(mentionQuery.toLowerCase())
  ) || [];

  const handleMentionSelect = (user: any) => {
    if (mentionIndex !== -1) {
      const before = text.substring(0, mentionIndex);
      setText(before + `@${user.name} `);
      setSelectedMentions([...selectedMentions, user.id]);
    }
    setShowMentions(false);
    textareaRef.current?.focus();
  };

  const handleSend = () => {
    if (text.trim()) {
      onSend(text.trim(), selectedMentions);
      setText("");
      setSelectedMentions([]);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (showMentions && filteredUsers.length > 0) {
      if (e.key === "Enter") {
        e.preventDefault();
        handleMentionSelect(filteredUsers[mentionNavIndex]);
        return;
      }
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setMentionNavIndex((prev) => Math.min(prev + 1, filteredUsers.length - 1));
        return;
      }
      if (e.key === "ArrowUp") {
        e.preventDefault();
        setMentionNavIndex((prev) => Math.max(prev - 1, 0));
        return;
      }
      if (e.key === "Escape") {
        setShowMentions(false);
        return;
      }
    }
    
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  return (
    <div className="relative p-3 border-t border-neutral-100 dark:border-neutral-800 bg-card dark:bg-neutral-900 flex items-center gap-2">
      {/* Mentions Dropdown */}
      {showMentions && filteredUsers.length > 0 && (
        <div className="absolute bottom-full left-12 mb-2 w-48 bg-card dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-[var(--radius)] shadow-e3 z-50 overflow-hidden">
          {filteredUsers.map((u: any, idx: number) => (
            <button
              key={u.id}
              onClick={() => handleMentionSelect(u)}
              onMouseEnter={() => setMentionNavIndex(idx)}
              className={`w-full text-left px-3 py-2 text-xs flex items-center gap-2 ${mentionNavIndex === idx ? "bg-neutral-100 dark:bg-neutral-700" : "hover:bg-neutral-100 dark:hover:bg-neutral-700"}`}
            >
              <AppIcon name="profile" size="xs" className=" text-neutral-400" />
              {u.name}
            </button>
          ))}
        </div>
      )}


      <FileUploadPopup 
        open={showUploadPopup} 
        onOpenChange={setShowUploadPopup} 
        title="Share File" 
        description="Select a file to share in this conversation. Maximum size is 10MB."
        maxSizeMB={10}
        acceptedTypes={[]} 
        onUpload={async (file) => {
          onSend(text.trim() || '', selectedMentions, file);
          setText("");
          setSelectedMentions([]);
          setShowUploadPopup(false);
        }} 
      />

      <Button 
        size="icon" 
        variant="ghost" 
        className="h-9 w-9 text-neutral-400 shrink-0" 
        aria-label="Add attachment"
        onClick={() => setShowUploadPopup(true)}
      >
        <AppIcon name="paperclip" />
      </Button>

      <textarea
        ref={textareaRef}
        value={text}
        onChange={(e) => {
          setText(e.target.value);
          e.target.style.height = 'auto';
          e.target.style.height = e.target.scrollHeight + 'px';
        }}
        onKeyDown={handleKeyDown}
        placeholder="Type a message... (use @ to mention)"
        className="flex-1 text-xs bg-neutral-50 dark:bg-neutral-800 p-2.5 resize-none focus:outline-none focus:ring-1 focus:ring-primary-500 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl max-h-[120px] thin-scrollbar"
        rows={1}
      />

      <Button
        size="icon"
        disabled={disabled || !text.trim()}
        onClick={handleSend}
        className="h-9 w-9 bg-primary-600 hover:bg-primary-700 text-white rounded-xl shrink-0"
        aria-label="Send message"
      >
        <AppIcon name="send" />
      </Button>
    </div>
  );
}

"use client";

import { useEffect, useRef, memo, useCallback } from "react";
import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { useVirtualizer } from "@tanstack/react-virtual";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger, Button, Dialog, DialogContent, DialogTrigger } from "@g4k/ui/components";

const MessageItem = memo(function MessageItem({
  msg,
  isMe,
  isConsecutive = false,
  onPinMessage,
  onUnpinMessage,
  canManage,
  onMarkRead,
}: {
  msg: any;
  isMe: boolean;
  isConsecutive?: boolean;
  onPinMessage?: (msgId: number) => void;
  onUnpinMessage?: (msgId: number) => void;
  canManage?: boolean;
  onMarkRead?: () => void;
}) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isMe || !onMarkRead) return;
    
    // Only trigger if this is an unread direct message
    const hasRead = msg.reads && msg.reads.length > 0;
    if (hasRead) return;

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        onMarkRead();
        observer.disconnect();
      }
    }, { threshold: 0.5 });

    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [isMe, onMarkRead, msg.reads]);

  return (
    <div ref={ref} className={`flex flex-col ${isMe ? "items-end" : "items-start"} ${isConsecutive ? "mt-1" : "mt-4"}`}>
      {!isConsecutive && (
        <div className="flex items-center gap-1.5 mb-1 text-[10px] text-neutral-400">
          <span className="font-semibold text-neutral-700 dark:text-neutral-300">
            {isMe ? "You" : msg.sender?.name}
          </span>
          <span>•</span>
          <span>{format(new Date(msg.created_at), "h:mm a")}</span>
        </div>
      )}

      <div
        className={`max-w-[75%] p-3 rounded-xl text-xs space-y-1 ${
          isMe
            ? "bg-primary-600 text-white rounded-tr-none"
            : "bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-tl-none"
        }`}
      >
        {msg.replyTo && (
          <div className={`p-1.5 rounded text-[10px] mb-1 opacity-80 ${isMe ? "bg-primary-700" : "bg-neutral-200 dark:bg-neutral-700"}`}>
            <span className="font-bold block">{msg.replyTo.sender?.name}</span>
            <span className="truncate block">{msg.replyTo.body}</span>
          </div>
        )}

        <p className="leading-relaxed whitespace-pre-wrap">
          {msg.body?.split(/(@[a-zA-Z0-9_-]+)/g).map((part: string, i: number) => 
            part.startsWith('@') ? (
              <span key={i} className="text-amber-500 font-semibold">{part}</span>
            ) : (
              <span key={i}>{part}</span>
            )
          )}
        </p>

        {msg.attachment_url && (
          <div className="mt-2">
            {/\.(jpe?g|png|gif|webp|pdf)$/i.test(msg.attachment_url) ? (
              <Dialog>
                <DialogTrigger asChild>
                  <button className="text-left w-full max-w-full">
                    {/\.(pdf)$/i.test(msg.attachment_url) ? (
                      <div className="flex items-center gap-2 p-3 bg-neutral-50 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg hover:opacity-80 transition-opacity">
                        <AppIcon name="fileText" className="w-8 h-8 text-rose-500" />
                        <div className="flex flex-col truncate">
