            ) : (
              <a
                href={msg.attachment_url}
                target="_blank"
                rel="noreferrer"
                download
                className={`flex items-center gap-1.5 underline text-[10px] ${isMe ? "text-primary-200" : "text-primary-600"}`}
              >
                <AppIcon name="paperclip" size="xs" /> Download File
