              {msg.pinned ? (
                <DropdownMenuItem onClick={() => onUnpinMessage?.(msg.id)}>
                  <AppIcon name="pin" className=" mr-2 text-neutral-400" /> Unpin Message
                </DropdownMenuItem>
              ) : (
                <DropdownMenuItem onClick={() => onPinMessage?.(msg.id)}>
                  <AppIcon name="pin" className=" mr-2 text-amber-500" /> Pin Message
                </DropdownMenuItem>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      )}
    </div>
  );
});

export function MessageList({
  messages,
  currentUserId,
  onFetchNextPage,
  hasNextPage,
  isFetchingNextPage,
  onPinMessage,
  onUnpinMessage,
  canManage,
  onMarkRead,
}: {
  messages: any[];
  currentUserId: number;
  onFetchNextPage?: () => void;
  hasNextPage?: boolean;
  isFetchingNextPage?: boolean;
  onPinMessage?: (msgId: number) => void;
  onUnpinMessage?: (msgId: number) => void;
  canManage?: boolean;
  onMarkRead?: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const previousScrollHeight = useRef<number>(0);
  const isScrolledToBottom = useRef<boolean>(true);

  const rowVirtualizer = useVirtualizer({
    count: messages.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: useCallback(() => 72, []),
    overscan: 5,
  });

  useEffect(() => {
    if (scrollRef.current) {
      if (isFetchingNextPage) {
        // We're loading older messages; save scroll height
        previousScrollHeight.current = scrollRef.current.scrollHeight;
      } else {
        const currentScrollHeight = scrollRef.current.scrollHeight;
        if (previousScrollHeight.current > 0 && currentScrollHeight > previousScrollHeight.current) {
          // Older messages just loaded, restore scroll position to avoid jump
          scrollRef.current.scrollTop += (currentScrollHeight - previousScrollHeight.current);
          previousScrollHeight.current = 0;
        } else if (isScrolledToBottom.current) {
          // New message came in and we were already at bottom, scroll to bottom
          scrollRef.current.scrollTop = currentScrollHeight;
        }
      }
    }
  }, [messages.length, isFetchingNextPage]);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const target = e.currentTarget;
    isScrolledToBottom.current = Math.abs(target.scrollHeight - target.clientHeight - target.scrollTop) < 10;
    
    if (target.scrollTop === 0 && hasNextPage && !isFetchingNextPage && onFetchNextPage) {
      onFetchNextPage();
    }
  };

  const pinnedMessages = messages.filter(m => m.pinned);

  return (
    <div className="flex flex-col h-full w-full relative">
      {pinnedMessages.length > 0 && (
        <div className="absolute top-0 left-0 right-0 z-10 bg-amber-50/95 dark:bg-amber-950/95 border-b border-amber-200 dark:border-amber-900 p-2 text-xs flex flex-col gap-2 shadow-sm backdrop-blur">
          <div className="flex items-center gap-1.5 text-amber-700 dark:text-amber-400 font-bold mb-1">
            <AppIcon name="pin" size="sm" /> Pinned Messages ({pinnedMessages.length})
          </div>
          <div className="flex gap-2 overflow-x-auto thin-scrollbar pb-1">
            {pinnedMessages.map(pm => (
              <div key={pm.id} className="min-w-[200px] max-w-[250px] shrink-0 bg-white dark:bg-neutral-900 border border-amber-200 dark:border-amber-800 rounded p-2">
                <span className="font-semibold block text-[10px] text-amber-600 dark:text-amber-500 mb-0.5">{pm.sender?.name}</span>
                <span className="truncate block">{pm.body}</span>
              </div>
            ))}
          </div>
        </div>
      )}
      
      <div 
        ref={scrollRef} 
        onScroll={handleScroll}
        className={`flex-1 overflow-y-auto p-4 space-y-3 relative ${pinnedMessages.length > 0 ? "pt-[110px]" : ""}`}
      >
        {isFetchingNextPage && (
          <div className="text-center text-xs text-neutral-400 py-1">Loading older messages...</div>
        )}
      <div
        className="w-full relative"
        style={{ height: `${rowVirtualizer.getTotalSize()}px` }}
      >
        {rowVirtualizer.getVirtualItems().map((virtualRow) => {
          const msg = messages[virtualRow.index];
          if (!msg) return null;
          
          const prevMsg = virtualRow.index > 0 ? messages[virtualRow.index - 1] : null;
          
          const msgDate = new Date(msg.created_at);
          const prevDate = prevMsg ? new Date(prevMsg.created_at) : null;
          
          const isNewDay = !prevDate || msgDate.toDateString() !== prevDate.toDateString();
          const isConsecutive = !isNewDay && prevMsg && prevMsg.sender_id === msg.sender_id && (msgDate.getTime() - prevDate.getTime() < 5 * 60 * 1000);

          const isMe = msg.sender_id === currentUserId;

          return (
            <div
              key={msg.id || virtualRow.index}
              data-index={virtualRow.index}
              ref={rowVirtualizer.measureElement}
              className="absolute top-0 left-0 w-full group flex flex-col"
              style={{
                transform: `translateY(${virtualRow.start}px)`,
              }}
            >
              {isNewDay && (
                <div className="flex justify-center my-4">
                  <span className="bg-neutral-100 dark:bg-neutral-800 text-neutral-500 text-[10px] font-bold px-2 py-1 rounded-full">
                    {format(msgDate, "MMMM d, yyyy")}
                  </span>
                </div>
              )}
              <MessageItem 
                msg={msg} 
                isMe={isMe} 
                isConsecutive={isConsecutive}
                onPinMessage={onPinMessage} 
                onUnpinMessage={onUnpinMessage}
                canManage={canManage}
                onMarkRead={onMarkRead}
              />
            </div>
          );
        })}
      </div>
    </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import { format } from "date-fns";
import { safeFromNow } from "@/lib/format";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import Link from "next/link";
import { apiFetch } from "@/lib/api-client";
import { ContentSkeleton, IsolatedError, MeaningfulEmpty } from "@g4k/ui/components/state-helpers";

import { DataTable, Skeleton, ErrorBoundary } from "@g4k/ui/components";
import { FilterBar } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { useUrlState } from "@/hooks/use-url-state";
import { queryKeys, STALE_TIME_NOTIFICATIONS } from "@/lib/query-keys";
import { useReverb } from "@/hooks/use-reverb";

/**
 * Canonical notification type taxonomy emitted by the backend.
 * Used for both the Type filter options and the human-readable row label
 * (unknown types fall back to a prettified string instead of being hidden).
 */
const NOTIFICATION_TYPE_LABELS: Record<string, string> = {
  leave_request: "Leave Requests",
  leave_decision: "Leave Decisions",
  task_assigned: "Task Assigned",
  task_submitted: "Task Submissions",
  task_decision: "Task Decisions",
  task_reminder: "Task Reminders",
  project_submitted: "Project Submissions",
  project_decision: "Project Decisions",
  announcement: "Announcements",
  holiday_reminder: "Holiday Reminders",
  shift_reminder: "Shift Reminders",
  missed_clock: "Missed Clock-ins",
  session: "Sessions",
  suspicious_login: "Suspicious Logins",
  feedback: "Feedback",
  mention: "Mentions",
  export: "Exports",
  system: "System",
  // Legacy types still emitted by older notification rows
  message: "Messages",
  security: "Security",
};

function notificationTypeLabel(type?: string): string {
  if (!type) return "General";
  return NOTIFICATION_TYPE_LABELS[type] ?? type.replace(/_/g, " ");
}

export function NotificationsTab() {
  const queryClient = useQueryClient();
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(50);
  const [search, setSearch] = useUrlState("search", "");
  const [filter, setFilter] = useState<{ readStatus: string; type: string }>({
    readStatus: "all",
    type: "all"
  });

  const { isConnected } = useReverb();

  const { data, isLoading, isError, refetch } = useQuery({
    queryKey: [...queryKeys.notifications(filter, search), page, perPage],
    queryFn: () => {
      const params = new URLSearchParams();
      if (filter.readStatus === "unread") params.set("unreadOnly", "true");
      if (filter.type !== "all") params.set("type", filter.type);
      if (search) params.set("search", search);
      params.set("page", page.toString());
      params.set("per_page", perPage.toString());
      return apiFetch(`/notifications?${params.toString()}`);
    },
    placeholderData: keepPreviousData,
    staleTime: STALE_TIME_NOTIFICATIONS,
    refetchInterval: isConnected ? false : 30_000,
  });

  const notificationsData = (Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []));
  const totalPages = data?.last_page || data?.data?.last_page || 1;

  const markReadMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiFetch(`/notifications/${id}/mark-read`, { method: "POST" });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notifications"] });
      queryClient.invalidateQueries({ queryKey: queryKeys.unreadCount });
    }
  });

  const markAllReadMutation = useMutation({
    mutationFn: async () => {
      return apiFetch(`/notifications/mark-all-read`, { method: "POST" });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notifications"] });
      queryClient.invalidateQueries({ queryKey: queryKeys.unreadCount });
      toast.success("All notifications marked as read");
    }
  });

  const getIcon = (type: string) => {
    switch (type) {
      case "leave_decision":
        return <AppIcon name="success" className=" text-emerald-500" />;
      case "task_assigned":
      case "project_submission":
        return <AppIcon name="briefcase" className=" text-primary-500" />;
      case "message":
        return <AppIcon name="chat" className=" text-blue-500" />;
      case "security":
        return <AppIcon name="error" className=" text-rose-600" />;
      case "announcement":
        return <AppIcon name="mailOpen" className=" text-amber-500" />;
      case "holiday_reminder":
        return <AppIcon name="clock" className=" text-green-500" />;
      case "feedback":
        return <AppIcon name="info" className=" text-cyan-500" />;
      default:
        return <AppIcon name="error" className=" text-neutral-400" />;
    }
  };

  const columns = [
    {
      header: "Type",
      cell: ({ row }: any) => {
        const item = row.original;
        return (
          <div className="flex items-center gap-2">
            {getIcon(item.type)}
            <span className="capitalize text-xs font-medium">{notificationTypeLabel(item.type)}</span>
          </div>
        );
      }
    },
    {
      header: "Notification",
      cell: ({ row }: any) => {
        const item = row.original;
        return (
          <div className="flex flex-col">
            <div className="flex items-center gap-2">
              {item.link ? (
                <Link 
                  href={item.link} 
                  onClick={() => { if (!item.read_at) markReadMutation.mutate(item.id); }}
                  className={`text-sm hover:underline hover:text-primary-600 dark:hover:text-primary-400 ${!item.read_at ? 'font-semibold text-neutral-900 dark:text-white' : 'text-neutral-700 dark:text-neutral-300'}`}
                >
                  {item.title || "Notification"}
                </Link>
              ) : (
                <span className={`text-sm ${!item.read_at ? 'font-semibold text-neutral-900 dark:text-white' : 'text-neutral-700 dark:text-neutral-300'}`}>
                  {item.title || "Notification"}
                </span>
              )}
              {item.priority === 'urgent' && (
                <div className="flex items-center gap-1.5 px-1.5 py-0.5 rounded text-[10px] font-bold bg-rose-50 dark:bg-rose-950/50 text-rose-600 dark:text-rose-400 uppercase">
                  <span className="relative flex h-2 w-2">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-rose-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-2 w-2 bg-rose-500"></span>
                  </span>
                  Urgent
                </div>
              )}
            </div>
            <span className="text-xs text-neutral-500 mt-1">{item.body || ""}</span>
          </div>
        );
      }
    },
    {
      header: "Received",
      cell: ({ row }: any) => {
        const item = row.original;
        return (
          <div className="flex flex-col text-xs text-neutral-500">
            <span>{safeFromNow(item.created_at)}</span>
            <span className="text-[10px] text-neutral-400">{item.created_at ? format(new Date(item.created_at), 'MMM d, yyyy h:mm a') : ""}</span>
          </div>
        );
      }
    },
    {
      header: "Actions",
      cell: ({ row }: any) => {
        const item = row.original;
        return (
          <div className="flex justify-end">
            {!item.read_at ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => markReadMutation.mutate(item.id)}
                disabled={markReadMutation.isPending}
                className="text-xs flex items-center gap-2"
              >
                <AppIcon name="check" />
                Mark Read
              </Button>
            ) : (
              <span className="text-xs text-neutral-400 flex items-center gap-2">
                <AppIcon name="mailOpen" /> Read
              </span>
            )}
          </div>
        );
      }
    }
  ];

  return (
    <div className="space-y-6 mt-4">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-lg font-bold text-neutral-900 dark:text-white">All Notifications</h2>
        <Button 
          variant="outline" 
          size="sm" 
          onClick={() => markAllReadMutation.mutate()}
          disabled={markAllReadMutation.isPending}
          className="flex items-center gap-2"
        >
          <AppIcon name="success" />
          Mark all as read
        </Button>
      </div>
        <FilterBar
          searchQuery={search || ""}
          onSearchChange={setSearch}
          filters={[
            {
              key: "readStatus",
              label: "Status",
              type: "select",
              options: [
                { label: "Unread", value: "unread" }
              ],
              value: filter.readStatus,
              onChange: (v) => setFilter(f => ({ ...f, readStatus: v }))
            },
            {
              key: "type",
              label: "Type",
              type: "select",
              options: Object.entries(NOTIFICATION_TYPE_LABELS).map(([value, label]) => ({ label, value })),
              value: filter.type,
              onChange: (v) => setFilter(f => ({ ...f, type: v }))
            }
          ]}
        />
      
      {isLoading ? (
        <div className="space-y-3 p-4">
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
        </div>
      ) : isError ? (
        <div className="flex flex-col items-center justify-center p-12 text-neutral-400 bg-card dark:bg-neutral-900 rounded-xl border border-neutral-100 dark:border-neutral-800">
          <AppIcon name="error" size="2xl" className=" mb-3 text-rose-500" />
          <p className="text-sm font-medium text-neutral-900 dark:text-white mb-1">Failed to load notifications</p>
          <p className="text-xs mb-4">Please check your connection and try again.</p>
          <Button variant="outline" size="sm" onClick={() => refetch()}>
            Try Again
          </Button>
        </div>
      ) : (
        <ErrorBoundary name="NotificationsDataTable" fallbackTitle="Could not load notifications table">
          <DataTable
            columns={columns}
            data={notificationsData}
            page={page}
            perPage={perPage}
            totalPages={totalPages}
            onPageChange={setPage}
            onPerPageChange={setPerPage}
          />
        </ErrorBoundary>
      )}
    </div>
  );
}

"use client";

