                    status={
                      task.approval_state === "approved" ? "success" :
                      task.approval_state === "pending_approval" ? "warning" : "danger"
                    }
                    className="uppercase text-[10px] shrink-0"
                  >
                    {task.approval_state.replace('_', ' ')}
                  </StatusBadge>
                </div>
                {task.approval_state === 'redo_required' && task.feedback && (
                  <div className="text-[10px] text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/20 p-1.5 rounded border border-rose-100 dark:border-rose-900/50">
                    <span className="font-semibold">Feedback:</span> {task.feedback}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </Card>
  );
}

"use client";

import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { apiFetch } from "@/lib/api-client";
import { Card, Skeleton, Button } from "@g4k/ui/components";
import { queryKeys } from "@/lib/query-keys";
import { AppIcon, IconName } from "@g4k/ui/components";
import Link from "next/link";
import { safeFromNow } from "@/lib/format";

export function EmployeeTaskProgressWidget() {
  const { data, isLoading, isError, refetch } = useDashboardInit({
    select: (data: any) => Array.isArray(data.metrics?.recent_task_progress) ? data.metrics.recent_task_progress : [],
    placeholderData: keepPreviousData,
  });

  if (isLoading) {
    return (
      <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 transition-shadow duration-150">
        <div className="flex items-center gap-2 pb-3">
          <Skeleton className="w-7 h-7 rounded-[var(--radius)]" />
          <Skeleton className="h-4 w-32" />
        </div>
        <Skeleton className="h-14 w-full" />
      </Card>
    );
  }

  if (isError) {
    return (
      <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col transition-shadow duration-150">
        <div className="flex items-center justify-between pb-3 border-b border-neutral-100 dark:border-neutral-800">
          <div className="flex items-center gap-2">
            <span className="text-sm font-bold">Task Progress</span>
          </div>
        </div>
        <div className="flex-1 flex flex-col items-center justify-center bg-rose-50/50 dark:bg-rose-950/10 rounded-[var(--radius)] p-4 mt-4">
          <AppIcon name="warning" size="xl" className=" text-rose-400 mb-2" />
          <span className="text-[11px] text-rose-600 font-medium mb-2">Failed to load tasks</span>
          <Button variant="outline" size="sm" onClick={() => refetch()} className="h-6 text-[10px] px-2">
            Retry
          </Button>
        </div>
      </Card>
    );
  }

  const tasks = Array.isArray(data) ? data : [];

  return (
    <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col justify-between transition-shadow duration-150">
      <div className="flex flex-col h-full">
        <div className="flex items-center justify-between pb-3">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-[var(--radius)] bg-purple-100 dark:bg-purple-950 flex items-center justify-center">
              <AppIcon name="success" className=" text-purple-600 dark:text-purple-400" />
            </div>
            <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider">
              Recent Task Progress
            </span>
          </div>
        </div>

        {tasks.length === 0 ? (
          <div className="flex-1 flex items-center justify-center text-xs text-neutral-400">
            No recent tasks
