        ) : (
          <div className="space-y-3 overflow-y-auto thin-scrollbar">
            {tasks.map((task: any) => (
              <Link 
                key={task.id} 
                href={`/dashboard/tasks/${task.id}`}
                className="block group p-3 rounded-xl bg-neutral-50 hover:bg-neutral-100 dark:bg-neutral-800/50 dark:hover:bg-neutral-800 transition-colors border border-neutral-100 dark:border-neutral-800"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2 max-w-[70%]">
                    <AppIcon name="tasks" className=" text-neutral-400 shrink-0" />
                    <p className="text-xs font-semibold text-neutral-900 dark:text-neutral-100 truncate">
                      {task.title}
                    </p>
                  </div>
                  <span className="text-[10px] font-medium text-neutral-500 shrink-0">
                    {task.progress}%
                  </span>
                </div>
                
                <div className="w-full bg-neutral-200 dark:bg-neutral-700 rounded-full h-1.5 mb-2 overflow-hidden">
                  <div 
                    className="bg-purple-500 h-1.5 rounded-full transition-all duration-500" 
                    style={{ width: `${task.progress}%` }} 
                  />
                </div>
                
                <p className="text-[10px] text-neutral-400 flex items-center gap-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-neutral-300 dark:bg-neutral-600 inline-block"></span>
                  Updated {safeFromNow(task.updated_at) || 'recently'}
                </p>
              </Link>
            ))}
          </div>
        )}
      </div>
    </Card>
  );
}

"use client";

import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import Link from "next/link";

import { Card, Skeleton, Button, StatusBadge, Avatar, AvatarFallback } from "@g4k/ui/components";

import { apiFetch } from "@/lib/api-client";
import { STALE_TIME_ATTENDANCE, queryKeys } from "@/lib/query-keys";

export function HrTeamAttendanceWidget() {
  const { data, isPending, isFetching, isError, refetch } = useQuery({
    queryKey: queryKeys.hrAttendance(format(new Date(), "yyyy-MM-dd")),
    queryFn: () => apiFetch(`/attendance/hr/today?date=${format(new Date(), "yyyy-MM-dd")}`),
    staleTime: STALE_TIME_ATTENDANCE,
    placeholderData: keepPreviousData,
  });

  const records = (Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []));
  const presentCount = records.filter((r: any) => r.status === "present" || r.status === "late").length;
  const totalCount = records.length;
  const topRecords = records.slice(0, 3);

  return (
    <Card className="h-full flex flex-col bg-card border shadow-e1 hover:shadow-e2 rounded-xl p-5 overflow-hidden transition-shadow duration-150">
      <div className="flex items-center justify-between pb-3">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-[var(--radius)] bg-emerald-100 dark:bg-emerald-950 flex items-center justify-center">
            <AppIcon name="directory" className=" text-emerald-600 dark:text-emerald-400" />
          </div>
          <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider">
            Team Attendance
          </span>
          {isFetching && !isPending && <AppIcon name="loading" size="xs" className=" animate-spin text-muted-foreground" />}
        </div>
        
        {totalCount > 0 && (
          <div className="flex items-baseline gap-1 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-[var(--radius)]">
            <span className="text-lg font-bold text-emerald-700 dark:text-emerald-400">{presentCount}</span>
            <span className="text-xs font-medium text-emerald-600/70 dark:text-emerald-400/70">/ {totalCount}</span>
          </div>
        )}
      </div>

      <div className="flex-1 flex flex-col">
        {isPending ? (
          <div className="space-y-4 w-full pt-2">
            {[1, 2, 3].map((i) => (
              <div key={i} className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Skeleton className="w-6 h-6 rounded-full" />
                  <Skeleton className="h-4 w-20" />
                </div>
                <Skeleton className="h-4 w-12 rounded-full" />
              </div>
            ))}
          </div>
        ) : isError ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center space-y-2">
            <AppIcon name="error" size="lg" className=" text-rose-400" />
            <p className="text-xs font-medium text-rose-600">Failed to load team</p>
            <Button variant="outline" size="sm" onClick={() => refetch()} className="h-6 text-[10px] px-2">
              Retry
            </Button>
          </div>
        ) : records.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center">
            <p className="text-sm font-medium text-muted-foreground">No team members scheduled</p>
          </div>
        ) : (
          <div className="space-y-3 flex-1">
            {topRecords.map((r: any) => (
              <div key={r.user_id} className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Avatar className="w-6 h-6">
                    <AvatarFallback name={r.user_name} className="text-[10px]" />
                  </Avatar>
                  <span className="text-xs font-semibold text-neutral-700 dark:text-neutral-300">{r.user_name}</span>
                </div>
                <StatusBadge 
                  status={
                    r.status === "present" ? "success" :
                    r.status === "late" ? "warning" :
                    r.status === "leave" ? "info" : "danger"
                  } 
                  className="uppercase text-[10px]"
                >
                  {r.status}
                </StatusBadge>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="pt-3 mt-auto">
        <Link 
          href="/dashboard/org/attendance"
          className="flex items-center justify-between w-full text-xs font-semibold text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 dark:hover:text-emerald-300 group transition-colors"
        >
          View Full Report
          <AppIcon name="arrowRight" size="xs" className=" group-hover:translate-x-1 transition-transform" />
        </Link>
      </div>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { Card, CardTitle, Button, Input, Select, SelectTrigger, SelectValue, SelectContent, SelectItem, Avatar, AvatarFallback, AvatarImage } from "@g4k/ui/components";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";

import { WidgetInfo } from "../widgets/widget-info";
import { FormError } from "@/components/forms/form-error";

export function QuickTaskWidget() {
  const queryClient = useQueryClient();
  const [title, setTitle] = useState("");
  const [assigneeId, setAssigneeId] = useState("");
  const [fieldErrors, setFieldErrors] = useState<Record<string, string[]>>({});

  const { data: usersData, isLoading: usersLoading } = useQuery({
    queryKey: queryKeys.usersSelectList,
    queryFn: () => apiFetch("/users?limit=50"),
  });

  const users = Array.isArray(usersData?.data) ? usersData.data : (Array.isArray(usersData) ? usersData : []);

  const createTaskMutation = useMutation({
    mutationFn: (payload: { title: string; assignee_id: string; notify_global_chat: boolean }) =>
      apiFetch("/tasks", {
        method: "POST",
        body: JSON.stringify(payload),
      }),
    onSuccess: () => {
      toast.success("Task assigned successfully!");
      setTitle("");
      setAssigneeId("");
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to create task");
      if (err.errors) {
        setFieldErrors(err.errors);
      }
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFieldErrors({});
    if (!title.trim()) return toast.error("Please enter a task title");
    if (!assigneeId) return toast.error("Please select an assignee");
    createTaskMutation.mutate({ title, assignee_id: assigneeId, notify_global_chat: true });
  };

  return (
    <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col justify-between transition-shadow duration-150 overflow-hidden">
      <div>
        <div className="flex items-center justify-between pb-3">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-[var(--radius)] bg-emerald-100 dark:bg-emerald-950 flex items-center justify-center">
              <AppIcon name="success" className=" text-emerald-600 dark:text-emerald-400" />
            </div>
            <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider flex items-center gap-1.5">
              Quick Task
              <WidgetInfo summary="Instantly dispatch a work item to any employee" />
            </span>
            {usersLoading && <AppIcon name="loading" size="xs" className=" animate-spin text-neutral-400" />}
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-2.5">
          <div>
            <Input 
              placeholder="Task title..." 
              value={title} 
              onChange={(e) => setTitle(e.target.value)}
              className={`h-8 text-xs ${fieldErrors.title ? "border-red-500" : ""}`}
            />
            <FormError errors={fieldErrors.title} />
          </div>

          <div>
            <Select value={assigneeId} onValueChange={setAssigneeId}>
              <SelectTrigger className={`h-8 text-xs w-full ${fieldErrors.assignee_id ? "border-red-500" : ""}`}>
                <SelectValue placeholder="Select Assignee" />
              </SelectTrigger>
              <SelectContent>
                {users.map((u: any) => (
                  <SelectItem key={u.id} value={u.id.toString()} className="text-xs">
                    {u.name} ({u.email})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <FormError errors={fieldErrors.assignee_id} />
          </div>

          <Button 
            type="submit" 
            size="sm" 
            disabled={createTaskMutation.isPending}
            className="w-full h-8 text-xs font-bold gap-1 bg-emerald-600 hover:bg-emerald-700 text-white"
          >
            {createTaskMutation.isPending ? (
              <AppIcon name="loading" size="sm" className=" animate-spin" />
            ) : (
              <AppIcon name="send" size="sm" />
            )}
            Assign Task
          </Button>
        </form>
      </div>
    </Card>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { format } from "date-fns";
import { apiFetch } from "@/lib/api-client";
import { Card, CardContent, CardHeader, CardTitle, Skeleton, Avatar, AvatarFallback, AvatarImage, Button } from "@g4k/ui/components";
import { StatusBadge } from "@g4k/ui/components/badge";
import { AppIcon } from "@g4k/ui/components";

export function TeamAttendanceWidget() {
  const date = format(new Date(), "yyyy-MM-dd");
  
  const { data, isLoading, isError, refetch } = useQuery({
    queryKey: ["attendance", "team-today", date],
    queryFn: () => apiFetch(`/attendance/team-today?date=${date}`),
    staleTime: 60000,
  });

  if (isError) {
    return (
      <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col transition-shadow duration-150">
        <div className="flex items-center justify-between pb-3 border-b border-neutral-100 dark:border-neutral-800">
          <div className="flex items-center gap-2">
            <AppIcon name="directory" className=" text-primary-600" />
            <span className="text-sm font-bold">Team Attendance</span>
          </div>
        </div>
        <div className="flex-1 flex flex-col items-center justify-center bg-rose-50/50 dark:bg-rose-950/10 rounded-[var(--radius)] p-4 mt-4">
          <AppIcon name="warning" size="xl" className=" text-rose-400 mb-2" />
          <span className="text-[11px] text-rose-600 font-medium mb-2">Failed to load attendance</span>
          <Button variant="outline" size="sm" onClick={() => refetch()} className="h-6 text-[10px] px-2">
            Retry
          </Button>
        </div>
      </Card>
    );
  }

  const counts = data?.counts || { present: 0, late: 0, leave: 0, absent: 0, leave_pending: 0 };
  const employees = Array.isArray(data?.employees) ? data.employees : (Array.isArray(data) ? data : []);

  if (!isLoading && employees.length === 0) {
    return (
      <Card className="h-full flex flex-col items-center justify-center border-none shadow-e1 overflow-hidden p-6 text-center">
        <div className="text-sm font-semibold text-muted-foreground">No team members scheduled today</div>
      </Card>
    );
  }

  return (
    <Card className="h-full flex flex-col border-none shadow-e1 overflow-hidden">
      <CardHeader className="pb-3 border-b border-border dark:border-neutral-800">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <CardTitle className="text-base font-bold flex items-center gap-2">
            <AppIcon name="directory" className=" text-primary-600" />
            Today's Team Attendance
          </CardTitle>
          {isLoading ? (
            <Skeleton className="h-6 w-48" />
          ) : (
            <div className="flex flex-wrap items-center gap-1.5">
              {counts.present > 0 && <StatusBadge status="success">{counts.present} Present</StatusBadge>}
              {counts.late > 0 && <StatusBadge status="warning">{counts.late} Late</StatusBadge>}
              {counts.leave > 0 && <StatusBadge status="info">{counts.leave} Leave</StatusBadge>}
              {counts.leave_pending > 0 && <StatusBadge status="neutral">{counts.leave_pending} Pend. Leave</StatusBadge>}
              {counts.absent > 0 && <StatusBadge status="danger">{counts.absent} Absent</StatusBadge>}
            </div>
          )}
        </div>
      </CardHeader>
      <CardContent className="flex-1 p-0 overflow-y-auto thin-scrollbar max-h-[320px]">
        {isLoading ? (
          <div className="p-4 space-y-3">
            {[1, 2, 3].map(i => (
              <Skeleton key={i} className="h-12 w-full rounded-[var(--radius)]" />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-px bg-secondary">
            {employees.map((emp: any) => {
              const statusColor = 
                emp.category === 'present' ? 'bg-emerald-500' :
                emp.category === 'late' ? 'bg-amber-500' :
                emp.category === 'leave' ? 'bg-blue-500' :
                emp.category === 'leave_pending' ? 'bg-neutral-400' :
                'bg-red-500';

              return (
                <div key={emp.user_id} className="flex items-center gap-3 p-3 bg-card transition-colors hover:bg-neutral-50 dark:hover:bg-neutral-800/50">
                  <div className="relative">
                    <Avatar className="w-8 h-8">
                      <AvatarImage src={emp.avatar_url || ''} />
                      <AvatarFallback name={emp.user_name} className="text-[10px]" />
                    </Avatar>
                    <div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-white dark:border-neutral-900 ${statusColor}`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold truncate text-foreground">
                      {emp.user_name}
                    </p>
                    <p className="text-[10px] text-muted-foreground truncate">
                      {emp.department_name || 'No Department'}
                    </p>
                  </div>
                  <div className="text-right shrink-0">
                    {emp.clock_in && (
                      <p className="text-xs font-mono font-medium">
                        {format(new Date(emp.clock_in), "hh:mm a")}
                      </p>
                    )}
                    {emp.late_minutes > 0 && (
                      <p className="text-[10px] text-amber-600 font-bold">
                        {emp.late_minutes}m late
                      </p>
                    )}
                    {emp.category === 'leave' || emp.category === 'leave_pending' ? (
                      <p className="text-[10px] text-blue-600 uppercase tracking-wider">
                        {emp.leave_type ? emp.leave_type.replace('_', ' ') : 'Leave'}
                      </p>
                    ) : null}
                    {emp.category === 'absent' && (
                      <p className="text-[10px] text-red-600 uppercase tracking-wider">
                        Absent
                      </p>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

