"use client";

import { useState, useEffect, useMemo } from "react";
import { useRouter } from "next/navigation";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";

import {
  queryKeys,
  STALE_TIME_DIRECTORY,
  STALE_TIME_DEPARTMENTS,
  STALE_TIME_DESIGNATIONS
} from "@/lib/query-keys";
import { useFormDraft } from "@/hooks/use-form-draft";
import { useExport } from "@/hooks/use-export";
import { useIsMobile } from "@g4k/ui/hooks/use-mobile";

import { Button } from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";
import { Checkbox } from "@g4k/ui/components";
import {
  Card,
  CardContent,
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@g4k/ui/components";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@g4k/ui/components";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { FilterBar } from "@g4k/ui/components";
import { useDebounce } from "@/hooks/use-debounce";
import { useUrlState } from "@/hooks/use-url-state";
import Link from "next/link";
import { getAuthToken } from "@/lib/auth-store";
import { EmptyState } from "@g4k/ui/components";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@g4k/ui/components";
import { ConfirmDialog } from "@g4k/ui/components";
import { StatusBadge } from "@g4k/ui/components";
import { Avatar, AvatarFallback, AvatarImage } from "@g4k/ui/components";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@g4k/ui/components";
import { Combobox } from "@g4k/ui/components";
import { useCapabilities, hasCapability } from "@/lib/capabilities";
import { useUserActions } from "@/hooks/use-user-actions";
import { UserEditDialog } from "@/components/users/user-edit-dialog";
import { UserForm, UserFormValues } from "@/components/users/user-form";
import { PageContainer } from "@/components/layout/page-container";
import { FormError } from "@/components/forms/form-error";

import { DataTable } from "@g4k/ui/components";

export function EmployeeManagementTab() {
  const queryClient = useQueryClient();
  const router = useRouter();
  const { data: capabilities } = useCapabilities();
  const canManageUsers = hasCapability(capabilities, "users.hr.manage") || hasCapability(capabilities, "users.employee.manage");
  const isMobile = useIsMobile();

  const [search, setSearch] = useUrlState("search", "");
  const [roleFilter, setRoleFilter] = useUrlState("role", "all");
  const [statusFilter, setStatusFilter] = useUrlState("status", "all");
  const [deptFilter, setDeptFilter] = useUrlState("department_id", "all");

  // Pagination State
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(20);
  const [debouncedSearch, setDebouncedSearch] = useState(search);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(search);
      setPage(1);
    }, 300);
    return () => clearTimeout(handler);
  }, [search]);

  useEffect(() => {
    setPage(1);
  }, [roleFilter, statusFilter, deptFilter]);

  const { triggerExport, isExporting } = useExport();

  const [rowSelection, setRowSelection] = useState({});

  // Modals
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isActivityOpen, setIsActivityOpen] = useState(false);
  const [activityUser, setActivityUser] = useState<any>(null);

  const {
    confirmState, setConfirmState,
    isEditOpen, setIsEditOpen,
    editingUser, setEditingUser,
    updateMutation, statusMutation, deleteMutation, resetPasswordMutation, restoreMutation
  } = useUserActions();

  // Forms
  const { formData: draftData, setFormData: setDraftData, hasDraft, restoreDraft, clearDraft } = useFormDraft<UserFormValues>("create_user", {
    name: "",
    email: "",
    username: "",
    phone: "",
    department_id: "",
    designation_id: "",
    team_id: "",
    employee_id: "",
    work_schedule_id: "",
    roles: ["employee"],
  });

  // Context-aware Ctrl+N shortcut
  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "n" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        if (!hasDraft) clearDraft();
        setIsCreateOpen(true);
      }
    };
    document.addEventListener("keydown", down);
    return () => document.removeEventListener("keydown", down);
  }, [hasDraft, clearDraft, setIsCreateOpen]);

  // Queries
  const { data, isPending, isError, refetch } = useQuery({
    queryKey: [...queryKeys.usersPaginated(debouncedSearch, roleFilter, statusFilter, deptFilter), page, perPage],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (debouncedSearch) params.append("search", debouncedSearch);
      if (roleFilter && roleFilter !== "all") params.append("role", roleFilter);
      if (statusFilter && statusFilter !== "all") {
        if (statusFilter === "trashed") {
          params.append("only_trashed", "1");
        } else {
          params.append("status", statusFilter);
        }
      }
      if (deptFilter && deptFilter !== "all") params.append("department_id", deptFilter);
      params.append("page", page.toString());
      params.append("per_page", perPage.toString());
      return apiFetch(`/users?${params.toString()}`);
    },
    placeholderData: keepPreviousData,
  });

  const { data: departments = [] } = useQuery({
    queryKey: queryKeys.departments,
    queryFn: () => apiFetch("/departments").then((res: any) => Array.isArray(res?.data) ? res.data : []),
    staleTime: STALE_TIME_DEPARTMENTS,
    enabled: canManageUsers,
  });

  const watchDept = draftData.department_id;
  const selectedDept = (Array.isArray(departments) ? departments : []).find((d: any) => d.id === Number(watchDept));
  const availableTeams = selectedDept?.teams || [];



  const { data: designations = [] } = useQuery({
    queryKey: queryKeys.designations,
    queryFn: () => apiFetch("/designations").then((res: any) => Array.isArray(res?.data) ? res.data : []),
    staleTime: STALE_TIME_DESIGNATIONS,
    enabled: canManageUsers,
  });

  const { data: work_schedules = [] } = useQuery({
    queryKey: ["work_schedules"],
    queryFn: () => apiFetch("/work-schedules").then((res: any) => Array.isArray(res?.data) ? res.data : []),
    enabled: hasCapability(capabilities, "settings.manage") || hasCapability(capabilities, "users.hr.manage"),
  });

  const { data: activityData, isLoading: isLoadingActivity } = useQuery({
    queryKey: queryKeys.userActivity(activityUser?.id),
    queryFn: () => apiFetch(`/users/${activityUser.id}/activity`),
    enabled: !!activityUser && isActivityOpen,
  });

  // Mutations
  const onSubmitCreate = (data: UserFormValues) => {
    createMutation.mutate(data);
  };

  const onSubmitEdit = (data: UserFormValues) => {
    updateMutation.mutate({ id: editingUser.id, payload: data });
  };

  const createMutation = useMutation({
    mutationFn: (payload: any) => apiFetch("/users", { method: "POST", body: JSON.stringify(payload) }),
    onSuccess: () => {
      toast.success("User created successfully!");
      setIsCreateOpen(false);
      clearDraft();
      queryClient.invalidateQueries({ queryKey: queryKeys.usersPaginated() });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to create user.");
    },
  });

  const bulkMutation = useMutation({
    mutationFn: (payload: { ids: number[], action: string }) => apiFetch('/users/bulk', { method: 'POST', body: JSON.stringify(payload) }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.usersPaginated() });
      toast.success("Bulk action completed.");
      setRowSelection({});
    },
    onError: (err: any) => toast.error(err.message || "Bulk action failed."),
  });

  const bulkExport = async () => {
    const params = new URLSearchParams();
    if (debouncedSearch) params.append("search", debouncedSearch);
    if (roleFilter && roleFilter !== "all") params.append("role", roleFilter);
    if (statusFilter && statusFilter !== "all") params.append("status", statusFilter);
    if (deptFilter && deptFilter !== "all") params.append("department_id", deptFilter);

    await triggerExport(`/users/export?${params.toString()}`, "users_export.csv");
  };

  const usersList = (Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []));
  const totalPages = data?.last_page || data?.data?.last_page || 1;
  const selectedCount = Object.keys(rowSelection).length;

  const columns: any[] = useMemo<any[]>(() => [
    {
      id: "select",
      header: ({ table }: any) => canManageUsers ? (
        <Checkbox
          checked={table.getIsAllPageRowsSelected()}
          onCheckedChange={(value: any) => table.toggleAllPageRowsSelected(!!value)}
          aria-label="Select all"
        />
      ) : null,
      cell: ({ row }: any) => canManageUsers ? (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(value: any) => row.toggleSelected(!!value)}
          aria-label="Select row"
        />
      ) : null,
      enableSorting: false,
      enableHiding: false,
    },
    {
      accessorKey: "name",
      header: "Employee",
      cell: ({ row }: any) => {
        const user = row.original;
        return (
          <button className={`flex items-center gap-3 w-full text-left transition-opacity ${canManageUsers ? 'hover:opacity-80' : ''}`} onClick={() => {
            if (!canManageUsers) return;
            router.push(`/dashboard/org/users/${user.id}`);
          }}>
            <Avatar className="w-9 h-9">
              {user.avatar_url && <AvatarImage src={user.avatar_url} alt={user.name} />}
              <AvatarFallback name={user.name} className="font-bold" />
            </Avatar>
            <div>
              <div className="font-semibold text-neutral-900 dark:text-white">
                {user.name}
              </div>
              <div className="text-neutral-400 text-[11px] flex items-center gap-2">
                <span>{user.email}</span>
              </div>
            </div>
          </button>
        );
      },
    },
    {
      accessorKey: "employee_id",
      header: "Code",
      cell: ({ row }: any) => {
        const code = row.original.employee_code || row.original.employee_id || "N/A";
        return <span className="font-mono font-medium text-neutral-600 dark:text-neutral-300">{code}</span>;
      }
    },
    {
      accessorKey: "department.name",
      header: "Department",
      cell: ({ row }: any) => {
        const dept = row.original.department;
        const desig = row.original.designation;
        return (
          <div className="flex flex-col gap-1">
            {dept ? (
              <span className="inline-flex items-center gap-1 text-neutral-700 dark:text-neutral-300 text-xs font-medium">
                <AppIcon name="building" size="sm" className=" text-neutral-400" />
                {dept.name}
              </span>
            ) : <span className="text-neutral-400">—</span>}
            {desig && <span className="text-[10px] text-neutral-500">{desig.name}</span>}
          </div>
        );
      }
    },
    {
      accessorKey: "roles",
      header: "Role",
      cell: ({ row }: any) => {
        const rawRoles = row.original.role_assignments?.map((r: any) => r.role)
          || (Array.isArray(row.original.roles) ? row.original.roles.map((r: any) => typeof r === 'string' ? r : r.role) : [])
          || (row.original.active_role ? [row.original.active_role] : []);
        const activeRoles = Array.from(new Set(rawRoles.filter(Boolean))) as string[];
        return (
          <div className="flex flex-wrap gap-1">
            {activeRoles.length > 0 ? (
              activeRoles.map((r: string) => (
                <span key={r} className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-primary-100 dark:bg-primary-950 text-primary-700 dark:text-primary-300 capitalize">
                  {r.replace("_", " ")}
                </span>
              ))
            ) : (
              <span className="px-2 py-0.5 rounded-full text-[10px] bg-neutral-100 text-neutral-600">Employee</span>
            )}
          </div>
        );
      }
    },
    {
      accessorKey: "status",
      header: "Status",
      cell: ({ row }: any) => {
        const isInactive = row.original.status === "inactive";
        return (
          <StatusBadge status={isInactive ? "danger" : "success"} dot className="uppercase">
            {row.original.status || "active"}
          </StatusBadge>
        );
      }
    },
    {
      id: "actions",
      header: () => <div className="text-right">Actions</div>,
      cell: ({ row }: any) => {
        const user = row.original;
        const isInactive = user.status === "inactive";
        if (!canManageUsers) return null;
        return (
          <div className="text-right">
            <DropdownMenu>
              <TooltipProvider delayDuration={150}>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon" className="h-8 w-8" aria-label="User actions">
                        <AppIcon name="more" />
                      </Button>
                    </DropdownMenuTrigger>
                  </TooltipTrigger>
                  <TooltipContent className="text-xs">
                    User actions
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
              <DropdownMenuContent align="end" className="w-56 font-sans">
                {user.deleted_at ? (
                  <DropdownMenuItem onClick={() => setConfirmState({ isOpen: true, type: "restore", payload: user })} className="gap-2 text-emerald-600 font-medium">
                    <AppIcon name="history" /> Restore User
                  </DropdownMenuItem>
                ) : (
                  <>
                    <DropdownMenuItem onClick={() => router.push(`/dashboard/org/users/${user.id}`)} className="gap-2 font-medium text-primary-600">
                      <AppIcon name="userCheck" /> View Details
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => {
                      setActivityUser(user);
                      setIsActivityOpen(true);
                    }} className="gap-2 text-blue-600">
                      <AppIcon name="activity" /> View Activity
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setConfirmState({ isOpen: true, type: "reset-password", payload: user })} className="gap-2 text-amber-600">
                      <AppIcon name="key" /> Reset Password
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={() => {
                      if (isInactive) {
                        statusMutation.mutate({ id: user.id, status: 'active' });
                      } else {
                        setConfirmState({ isOpen: true, type: "deactivate", payload: user });
                      }
                    }} className={`gap-2 ${isInactive ? "text-emerald-600" : "text-amber-600"}`}>
                      {isInactive ? <AppIcon name="userCheck" /> : <AppIcon name="userX" />}
                      {isInactive ? "Activate" : "Deactivate"}
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setConfirmState({ isOpen: true, type: "delete", payload: user })} className="gap-2 text-rose-600">
                      <AppIcon name="trash" /> Delete
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => { setEditingUser(row.original); setIsEditOpen(true); }} className="gap-2">
                      <AppIcon name="edit" /> Edit
                    </DropdownMenuItem>
                  </>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        );
      }
    }
  ], [canManageUsers]);

  const deptOptions = (Array.isArray(departments) ? departments : []).map((d: any) => ({ label: d.name, value: d.id.toString() }));

  return (
    <div className="space-y-6 mt-4">
      <Card className="border-none shadow-e1 hover:shadow-e2 transition-shadow duration-150 mb-6">
        <CardContent className="p-4 flex flex-col md:flex-row items-center gap-4">
          <div className="flex-1 w-full">
            <FilterBar
              searchQuery={search}
              onSearchChange={setSearch}
              searchPlaceholder="Search by name, email, code..."
              filters={[
                {
                  type: "select",
                  key: "role",
                  label: "Role",
                  value: roleFilter,
                  onChange: setRoleFilter,
                  options: [
                    { label: "Super Admin", value: "super_admin" },
                    { label: "HR", value: "hr" },
                    { label: "Employee", value: "employee" },
                  ],
                },
                {
                  type: "select",
                  key: "status",
                  label: "Status",
                  value: statusFilter,
                  onChange: setStatusFilter,
                  options: [
                    { label: "Active", value: "active" },
                    { label: "Inactive", value: "inactive" },
                    { label: "Deleted", value: "trashed" },
                  ],
                },
                {
                  type: "select",
                  key: "dept",
                  label: "Department",
                  value: deptFilter,
                  onChange: setDeptFilter,
                  options: [...deptOptions],
                },
              ]}
            />
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <Button variant="outline" onClick={bulkExport} disabled={isExporting} className="h-9 gap-2 shadow-sm">
              {isExporting ? <AppIcon name="loading" className=" animate-spin" /> : <AppIcon name="download" />}
              Export
            </Button>
            {canManageUsers && (
              <Button onClick={() => {
                if (!hasDraft) clearDraft();
                setIsCreateOpen(true);
              }} className="h-9 gap-2 shadow-sm">
                <AppIcon name="plus" />
                Add Employee
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
      {selectedCount > 0 && (
        <div className="bg-primary-50 dark:bg-primary-900/20 border border-primary-100 dark:border-primary-900/50 rounded-[var(--radius)] p-3 flex items-center justify-between animate-in fade-in slide-in-from-top-4">
          <span className="text-sm font-medium text-primary-700 dark:text-primary-300">{selectedCount} users selected</span>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" className="h-8" onClick={() => bulkMutation.mutate({ ids: Object.keys(rowSelection).map(Number), action: 'activate' })}>Bulk Activate</Button>
            <Button variant="outline" size="sm" className="h-8 text-rose-600" onClick={() => setConfirmState({ isOpen: true, type: "bulk-deactivate", payload: { ids: Object.keys(rowSelection).map(Number) } })}>Bulk Deactivate</Button>
            <Button variant="outline" size="sm" className="h-8" onClick={() => triggerExport(`/users/export?ids=${Object.keys(rowSelection).join(",")}`, 'users_export.csv')}>Bulk Export</Button>
          </div>
        </div>
      )}

      <Card className="border-none shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        <CardContent className="p-0">
          {isPending ? (
            <div className="p-6 space-y-4">
              <Skeleton className="h-12 w-full" />
              <Skeleton className="h-12 w-full" />
              <Skeleton className="h-12 w-full" />
            </div>
          ) : isError ? (
            <div className="p-12">
              <EmptyState title="Failed to load employees" description="There was an error fetching the user list. Please try again." icon={<AppIcon name="error" size="2xl" className=" text-rose-400" />} />
              <div className="flex justify-center mt-4">
                <Button onClick={() => refetch()} variant="outline">Retry</Button>
              </div>
            </div>
          ) : usersList.length === 0 ? (
            <div className="p-12">
              <EmptyState title="No employees found" description="Try adjusting your search query or filter settings." icon={<AppIcon name="userX" className="w-8 h-8 text-neutral-400" />} />
              <div className="flex justify-center mt-4">
                <Link href="/dashboard/directory">
                  <Button variant="outline" className="gap-2"><AppIcon name="users" /> View Directory</Button>
                </Link>
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              <DataTable
                columns={columns}
                data={usersList}
                getRowId={(r: any) => String(r.id)}
                onRowSelectionChange={setRowSelection}
                page={page}
                perPage={perPage}
                totalPages={totalPages}
                onPageChange={setPage}
                onPerPageChange={setPerPage}
              />
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create New Employee</DialogTitle>
            <DialogDescription>Add a new employee to the directory.</DialogDescription>
          </DialogHeader>
          <UserForm
            defaultValues={draftData}
            onValuesChange={setDraftData}
            departments={departments}
            designations={designations}
            work_schedules={work_schedules}
            onSubmit={onSubmitCreate}
            onCancel={() => setIsCreateOpen(false)}
            isPending={createMutation.isPending}
            submitLabel="Create User"
          />
        </DialogContent>
      </Dialog>

      {isEditOpen && editingUser && (
        <UserEditDialog
          isOpen={isEditOpen}
          onOpenChange={setIsEditOpen}
          user={editingUser}
          departments={departments}
          designations={designations}
          work_schedules={work_schedules}
          onSubmit={onSubmitEdit}
          isPending={updateMutation.isPending}
        />
      )}

      <Sheet open={isActivityOpen} onOpenChange={setIsActivityOpen}>
        <SheetContent className="w-full sm:w-[540px]">
          <SheetHeader>
            <SheetTitle>Activity Log</SheetTitle>
            <SheetDescription>Recent actions performed by {activityUser?.name}</SheetDescription>
          </SheetHeader>
          <div className="mt-6 space-y-4">
            {isLoadingActivity ? (
              <div className="space-y-2"><Skeleton className="h-16 w-full" /><Skeleton className="h-16 w-full" /></div>
            ) : activityData?.data?.length === 0 ? (
              <EmptyState title="No activity" description="No recent actions recorded." icon={<AppIcon name="history" size="2xl" className=" text-neutral-400" />} />
            ) : (
              activityData?.data?.map((log: any) => (
                <div key={log.id} className="p-3 border rounded-[var(--radius)] text-sm bg-neutral-50 dark:bg-neutral-900 flex flex-col gap-1">
                  <span className="font-semibold text-neutral-800 dark:text-neutral-200">{log.action} {log.subject_type}</span>
                  <span className="text-xs text-neutral-500">{new Date(log.at).toLocaleString()} - IP: {log.ip_address || 'N/A'}</span>
                </div>
              ))
            )}
          </div>
        </SheetContent>
      </Sheet>

      <ConfirmDialog
        open={confirmState.isOpen}
        onOpenChange={(open) => !open && setConfirmState({ isOpen: false, type: "" })}
        title={
          confirmState.type === "delete" ? "Delete User" :
          confirmState.type === "restore" ? "Restore User" :
          confirmState.type === "deactivate" ? "Deactivate User" :
          confirmState.type === "bulk-deactivate" ? "Bulk Deactivate" :
          "Reset Password"
        }
        description={
          confirmState.type === "delete" ? `Are you sure you want to delete ${confirmState.payload?.name}? This will archive their record but preserve historical data.` :
          confirmState.type === "restore" ? `Are you sure you want to restore ${confirmState.payload?.name}? Their account will be reactivated.` :
          confirmState.type === "deactivate" ? `Deactivating ${confirmState.payload?.name} will prevent them from logging in.` :
          confirmState.type === "bulk-deactivate" ? `Are you sure you want to deactivate ${confirmState.payload?.ids?.length} users?` :
          `Are you sure you want to reset the password for ${confirmState.payload?.name}? It will be reset to the default "Password@123".`
        }
        confirmText={
          confirmState.type === "delete" ? "Delete" :
          confirmState.type === "restore" ? "Restore" :
          confirmState.type === "deactivate" ? "Deactivate" :
          confirmState.type === "bulk-deactivate" ? "Deactivate All" :
          "Reset Password"
        }
        isDestructive={confirmState.type !== "restore"}
        onConfirm={() => {
          if (confirmState.type === "delete") {
            deleteMutation.mutate(confirmState.payload.id);
          } else if (confirmState.type === "restore") {
            restoreMutation.mutate(confirmState.payload.id);
          } else if (confirmState.type === "deactivate") {
            statusMutation.mutate({ id: confirmState.payload.id, status: 'inactive' });
          } else if (confirmState.type === "bulk-deactivate") {
            bulkMutation.mutate({ ids: confirmState.payload.ids, action: 'deactivate' });
          } else if (confirmState.type === "reset-password") {
            resetPasswordMutation.mutate(confirmState.payload.id);
          }
        }}
        isLoading={deleteMutation.isPending || statusMutation.isPending || bulkMutation.isPending || resetPasswordMutation.isPending || restoreMutation.isPending}
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useQuery, useMutation, useInfiniteQuery, keepPreviousData } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { queryKeys, STALE_TIME_DIRECTORY, STALE_TIME_DEPARTMENTS, STALE_TIME_DESIGNATIONS } from "@/lib/query-keys";

import { Button } from "@g4k/ui/components";
import { Card, CardContent } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { ContentSkeleton, IsolatedError, MeaningfulEmpty } from "@g4k/ui/components/state-helpers";
import { Avatar, AvatarFallback, AvatarImage } from "@g4k/ui/components";
import { useDebounce } from "@/hooks/use-debounce";
import { useUrlState } from "@/hooks/use-url-state";
import { FilterBar } from "@g4k/ui/components";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@g4k/ui/components";
import { DataTable } from "@g4k/ui/components";
import { useTrackRecent } from "@/hooks/use-track-recent";
export function CorporateDirectoryTab() {
  const router = useRouter();
  const [search, setSearch] = useUrlState("search", "");
  const debouncedSearch = useDebounce(search, 250);
  const [deptFilter, setDeptFilter] = useUrlState("department", "all");
  const [desigFilter, setDesigFilter] = useUrlState("designation", "all");
  const [visFilter, setVisFilter] = useUrlState("visibility", "all");
  const [selectedUser, setSelectedUser] = useState<any | null>(null);


  useTrackRecent(
    selectedUser
      ? {
        id: String(selectedUser.id),
        type: "employee",
        title: selectedUser.name,
        subtitle: selectedUser.designation?.name || "Employee",
        url: `/dashboard/directory?search=${selectedUser.name}`, // Preserving search context roughly
      }
      : null
  );

  const { data: deptsData } = useQuery({
    queryKey: queryKeys.departments,
    queryFn: () => apiFetch("/departments?limit=100"),
    staleTime: STALE_TIME_DEPARTMENTS,
  });

  const { data: desigsData } = useQuery({
    queryKey: queryKeys.designations,
    queryFn: () => apiFetch("/designations?limit=100"),
    staleTime: STALE_TIME_DESIGNATIONS,
  });

  const { data, fetchNextPage, hasNextPage, isFetchingNextPage, isPending, isError, refetch } = useInfiniteQuery({
    queryKey: queryKeys.directory(debouncedSearch, deptFilter, desigFilter, visFilter),
    queryFn: ({ pageParam = 1 }) => {
      const params = new URLSearchParams();
      if (debouncedSearch) params.append("search", debouncedSearch);
      if (deptFilter !== "all") params.append("department_id", deptFilter);
      if (desigFilter !== "all") params.append("designation_id", desigFilter);
      if (visFilter !== "all") params.append("visibility", visFilter);
      params.append("page", String(pageParam));
      return apiFetch(`/directory?${params.toString()}`);
    },
    getNextPageParam: (lastPage: any) => {
      const currentPage = lastPage?.current_page || lastPage?.meta?.current_page;
      const lastPageNum = lastPage?.last_page || lastPage?.meta?.last_page;
      if (currentPage && lastPageNum && currentPage < lastPageNum) {
        return currentPage + 1;
      }
      return undefined;
    },
    initialPageParam: 1,
    placeholderData: keepPreviousData,
    staleTime: STALE_TIME_DIRECTORY,
  });

  const sendMessageMutation = useMutation({
    mutationFn: (recipientId: number) => apiFetch("/conversations/dm", {
      method: "POST",
      body: JSON.stringify({ recipient_id: recipientId }),
    }),
    onSuccess: (conversation: any) => {
      router.push(`/dashboard/chat?conversation=${conversation.conversation_id || conversation.id}`);
    },
    onError: (err: any) => toast.error(err.message || "Failed to start chat."),
  });

  const users = data?.pages.flatMap((page: any) => {
    if (Array.isArray(page?.data)) return page.data;
    if (Array.isArray(page?.data?.data)) return page.data.data;
    if (Array.isArray(page)) return page;
    return [];
  }) || [];

  const columns: any[] = [
    {
      accessorKey: "name",
      header: "Name",
      cell: ({ row }: any) => (
        <button className="flex items-center gap-3 hover:opacity-80 transition-opacity text-left w-full" onClick={() => setSelectedUser(row.original)}>
          <Avatar className="w-8 h-8">
            <AvatarImage src={row.original.avatar_url} />
            <AvatarFallback name={row.original.name} />
          </Avatar>
          <div className="font-semibold text-neutral-900 dark:text-white">{row.original.name}</div>
        </button>
      ),
    },
    {
      accessorKey: "designation.name",
      header: "Designation",
      cell: ({ row }: any) => (
        <span className="text-neutral-600 dark:text-neutral-300 cursor-pointer" onClick={() => setSelectedUser(row.original)}>
          {row.original.designation?.name || "—"}
        </span>
      ),
    },
    {
      accessorKey: "department.name",
      header: "Department",
      cell: ({ row }: any) => (
        <span className="text-neutral-600 dark:text-neutral-300 cursor-pointer" onClick={() => setSelectedUser(row.original)}>
          {row.original.department?.name || "—"}
        </span>
      ),
    },
    {
      accessorKey: "email",
      header: "Contact",
      cell: ({ row }: any) => (
        <span className="text-neutral-500 cursor-pointer" onClick={() => setSelectedUser(row.original)}>
          {row.original.email}
        </span>
      ),
    },
    {
      id: "actions",
      header: () => <div className="text-right">Action</div>,
      cell: ({ row }: any) => (
        <div className="text-right">
          <Button
            onClick={(e) => {
              e.stopPropagation();
              sendMessageMutation.mutate(row.original.id);
            }}
            variant="ghost"
            size="sm"
            className="text-primary-600 hover:text-primary-700"
          >
            Message
          </Button>

        </div>
      ),
    },
  ];

  return (
    <div className="space-y-6 mt-4">
      {/* Search Bar & View Toggle */}
      <Card className="border-none shadow-e1 hover:shadow-e2 transition-shadow duration-150 mb-6">
        <CardContent className="p-4 flex flex-col md:flex-row items-center gap-4">
          <div className="flex-1 w-full">
            <FilterBar
              searchQuery={search}
              onSearchChange={setSearch}
              searchPlaceholder="Search by name, email, designation, or department..."
              filters={[
                {
                  key: "department",
                  label: "Department",
                  type: "select",
                  value: deptFilter,
                  onChange: setDeptFilter,
                  options: (deptsData?.data || deptsData || []).map((d: any) => ({ label: d.name, value: d.id.toString() }))
                },
                {
                  key: "designation",
                  label: "Designation",
                  type: "select",
                  value: desigFilter,
                  onChange: setDesigFilter,
                  options: (desigsData?.data || desigsData || []).map((d: any) => ({ label: d.name, value: d.id.toString() }))
                }
              ]}
            />
          </div>
        </CardContent>
      </Card>

      {/* Grid or List View */}
      {isPending ? (
        <ContentSkeleton type="card-grid" rows={8} />
      ) : isError ? (
        <IsolatedError error={isError ? "Failed to load directory." : undefined} onRetry={() => refetch()} />
      ) : users.length === 0 ? (
        <MeaningfulEmpty 
          entityName="employees" 
          icon="users"
          description="Try broadening your search term."
        />
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {users.map((user: any) => (
            <Card
              key={user.id}
              onClick={() => setSelectedUser(user)}
              className="border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 hover:shadow-e2 transition-all cursor-pointer group relative overflow-hidden flex flex-col h-full bg-card dark:bg-neutral-900 rounded-xl"
            >
              <div className="h-16 w-full bg-primary-600 dark:bg-primary-800 relative">
                <div className="absolute inset-0 bg-surface/10 dark:bg-black/10 pattern-dots opacity-20"></div>
              </div>
              <CardContent className="p-0 flex-1 flex flex-col items-center text-center">
                <div className="-mt-10 mb-3 relative rounded-full p-1 bg-card dark:bg-neutral-900">
                  <Avatar className="w-20 h-20 border-2 border-neutral-100 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150">
                    <AvatarImage src={user.avatar_url || ""} />
                    <AvatarFallback name={user.name} className="text-xl" />
                  </Avatar>
                </div>
                <div className="px-6 flex-1 flex flex-col w-full">
                  <h3 className="font-bold text-base text-neutral-900 dark:text-white truncate">
                    {user.name}
                  </h3>
                  <p className="text-xs font-semibold text-primary-600 dark:text-primary-400 mt-1 truncate">
                    {user.designation?.name || "Team Member"}
                  </p>

                  <div className="space-y-2 mt-4 mb-4 text-xs text-neutral-500 w-full flex-1">
                    {user.department && (
                      <div className="flex justify-center items-center gap-1.5 truncate text-neutral-600 dark:text-neutral-400 font-medium">
                        <AppIcon name="building" size="sm" />
                        <span>{user.department.name}</span>
                      </div>
                    )}
                    <div className="flex justify-center items-center gap-1.5 truncate">
                      <AppIcon name="mail" size="sm" className=" text-neutral-400" />
                      {user.email ? (
                        <span>{user.email}</span>
                      ) : (
                        <span className="text-neutral-400 italic">Hidden</span>
                      )}
                    </div>
                    {user.phone && (
                      <div className="flex justify-center items-center gap-1.5 truncate">
                        <AppIcon name="phone" size="sm" className=" text-neutral-400" />
                        <span>{user.phone}</span>
                      </div>
                    )}
                  </div>

                  <div className="w-full flex items-center justify-between border-t border-neutral-100 dark:border-neutral-800 pt-3 pb-4 mt-auto">
                    <div className="text-[10px] uppercase font-bold tracking-wider text-neutral-400">
                      ID: {user.employee_code || user.employee_id || "N/A"}
                    </div>
                    <div className="flex gap-1">

                      <Button
                        onClick={(e) => {
                          e.stopPropagation();
                          sendMessageMutation.mutate(user.id);
                        }}
                        variant="ghost"
                        size="icon"
                        aria-label={`Message ${user.name}`}
                        className="h-11 w-11 sm:h-8 sm:w-8 text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-500/10 hover:bg-primary-100 dark:hover:bg-primary-500/20 rounded-full"
                      >
                        <AppIcon name="chat" size="sm" />
                      </Button>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
          {hasNextPage && (
            <div className="col-span-1 sm:col-span-2 lg:col-span-3 xl:col-span-4 flex justify-center pb-6">
              <Button variant="outline" onClick={() => fetchNextPage()} disabled={isFetchingNextPage}>
                {isFetchingNextPage ? <AppIcon name="loading" className=" mr-2 animate-spin" /> : null}
                Load More
              </Button>
            </div>
          )}
        </div>
      )}

      {/* User Detail Sheet */}
      <Sheet open={!!selectedUser} onOpenChange={() => setSelectedUser(null)}>
        <SheetContent className="sm:max-w-md">
          {selectedUser && (
            <div className="space-y-6 pt-4">
              <SheetHeader className="text-left space-y-2">
                <Avatar size="lg" className="w-16 h-16 text-2xl">
                  <AvatarImage src={selectedUser.avatar_url || ""} />
                  <AvatarFallback name={selectedUser.name} />
                </Avatar>
                <SheetTitle className="text-xl font-bold font-display">
                  {selectedUser.name}
                </SheetTitle>
                <SheetDescription className="text-xs">
                  {selectedUser.designation?.name || "Employee"} •{" "}
                  {selectedUser.department?.name || "Games4King"}
                </SheetDescription>
              </SheetHeader>

              <div className="space-y-4 text-xs border-t border-b border-neutral-100 dark:border-neutral-800 py-4">
                <div className="flex items-center gap-3">
                  <AppIcon name="mail" className=" text-neutral-400" />
                  <div>
                    <div className="text-neutral-400 font-medium">Email</div>
                    <div className="font-semibold">{selectedUser.email}</div>
                  </div>
                </div>

                {selectedUser.phone && (
                  <div className="flex items-center gap-3">
                    <AppIcon name="phone" className=" text-neutral-400" />
                    <div>
                      <div className="text-neutral-400 font-medium">Phone</div>
                      <div className="font-semibold">{selectedUser.phone}</div>
                    </div>
                  </div>
                )}

                <div className="flex items-center gap-3">
                  <AppIcon name="userCheck" className=" text-neutral-400" />
                  <div>
                    <div className="text-neutral-400 font-medium">Employee Code</div>
                    <div className="font-mono font-semibold">
                      {selectedUser.employee_code || selectedUser.employee_id || "N/A"}
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex gap-2 w-full">
                <Button
                  onClick={() => sendMessageMutation.mutate(selectedUser.id)}
                  className="flex-1 bg-primary-600 hover:bg-primary-700 text-white gap-2"
                >
                  <AppIcon name="chat" />
                  <span>Message</span>
                </Button>
                <Button
                  variant="outline"
                  onClick={() => router.push(`/dashboard/org/users/${selectedUser.id}`)}
                  className="flex-1 gap-2"
                >
                  <AppIcon name="userCheck" />
                  <span>View Profile</span>
                </Button>
              </div>
            </div>
          )}
        </SheetContent>
      </Sheet>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { format, isSameMonth, isSameDay, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, eachDayOfInterval } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { STALE_TIME_CONFIG, queryKeys } from "@/lib/query-keys";
import { Card, CardContent, CardHeader, CardTitle, Skeleton, Button, Popover, PopoverTrigger, PopoverContent, Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, Input, Label, Checkbox, Textarea, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, ConfirmDialog, Tooltip, TooltipContent, TooltipProvider, TooltipTrigger as TooltipTriggerComponent, DatePicker } from "@g4k/ui/components";
import { useCapabilities, hasCapability } from "@/lib/capabilities";
import { toast } from "sonner";
import { z } from "zod";
import { FormError } from "@/components/forms/form-error";

const holidaySchema = z.object({
  name: z.string().min(1, "Name is required"),
  date: z.string().min(1, "Date is required"),
  description: z.string().optional(),
  recurring: z.boolean(),
});

export function HolidayCalendar() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const currentYear = currentDate.getFullYear();
  const queryClient = useQueryClient();
  const { data: caps } = useCapabilities();
  const canManage = hasCapability(caps, "settings.manage");

  const [isAddOpen, setIsAddOpen] = useState(false);
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [confirmState, setConfirmState] = useState<{ isOpen: boolean; id: number | null }>({ isOpen: false, id: null });
  const [editingHoliday, setEditingHoliday] = useState<any>(null);
  
  const [formData, setFormData] = useState({
    name: "",
    date: format(new Date(), "yyyy-MM-dd"),
    description: "",
    recurring: false,
  });
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  const { data: holidays, isLoading } = useQuery({
    queryKey: queryKeys.holidays(currentYear),
    queryFn: () => apiFetch(`/holidays?year=${currentYear}`),
    staleTime: STALE_TIME_CONFIG,
  });

  const addHoliday = useMutation({
    mutationFn: (data: any) => apiFetch("/holidays", { method: "POST", body: JSON.stringify(data) }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.holidays(currentYear) });
      setIsAddOpen(false);
      toast.success("Saved successfully");
    },
    onError: () => toast.error("Failed to save"),
  });

  const editHoliday = useMutation({
    mutationFn: ({ id, data }: { id: number, data: any }) => apiFetch(`/holidays/${id}`, { method: "PUT", body: JSON.stringify(data) }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.holidays(currentYear) });
      setIsEditOpen(false);
      toast.success("Updated successfully");
    },
    onError: () => toast.error("Failed to update"),
  });

  const deleteHoliday = useMutation({
    mutationFn: (id: number) => apiFetch(`/holidays/${id}`, { method: "DELETE" }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.holidays(currentYear) });
      toast.success("Deleted successfully");
    },
    onError: () => toast.error("Failed to delete"),
  });

  const holidayList = Array.isArray(holidays) ? holidays : (holidays?.data || []);

  const handlePrevMonth = () => setCurrentDate(subMonths(currentDate, 1));
  const handleNextMonth = () => setCurrentDate(addMonths(currentDate, 1));

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(currentDate);
  const startDate = startOfWeek(monthStart);
  const endDate = endOfWeek(monthEnd);

  const days = eachDayOfInterval({ start: startDate, end: endDate });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setFieldErrors({});
    const result = holidaySchema.safeParse(formData);
    if (!result.success) {
      const errors: Record<string, string> = {};
      result.error.issues.forEach((err: any) => {
        if (err.path[0]) errors[err.path[0].toString()] = err.message;
      });
      setFieldErrors(errors);
      return;
    }

    if (editingHoliday) {
      editHoliday.mutate({ id: editingHoliday.id, data: formData });
    } else {
      addHoliday.mutate(formData);
    }
  };

  const openEdit = (h: any) => {
    setEditingHoliday(h);
    setFormData({
      name: h.name,
      date: h.date,
      description: h.description || "",
      recurring: h.recurring || false,
    });
    setFieldErrors({});
    setIsEditOpen(true);
  };

  const openAdd = () => {
    setEditingHoliday(null);
    setFormData({
      name: "",
      date: format(currentDate, "yyyy-MM-dd"),
      description: "",
      recurring: false,
    });
    setFieldErrors({});
    setIsAddOpen(true);
  };

  const HolidayFormFields = () => (
    <>
      <div className="space-y-2 flex flex-col">
        <Label>Date</Label>
        <DatePicker 
          value={formData.date ? new Date(formData.date) : undefined} 
          onChange={(date) => setFormData({ ...formData, date: date ? format(date, "yyyy-MM-dd") : "" })} 
          className="w-full"
        />
        <FormError errors={fieldErrors.date} />
      </div>
      <div className="space-y-2">
        <Label>Name</Label>
        <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} />
        <FormError errors={fieldErrors.name} />
      </div>
      <div className="space-y-2">
        <Label>Description</Label>
        <Textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} />
      </div>
      <div className="flex items-center gap-2">
        <Checkbox id="recurring-check" checked={formData.recurring} onCheckedChange={(c) => setFormData({ ...formData, recurring: !!c })} />
        <Label htmlFor="recurring-check">Recurring annually</Label>
      </div>
    </>
  );

  return (
    <Card className="h-full flex flex-col bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader className="border-b border-neutral-100 dark:border-neutral-800 pb-3 flex flex-row items-center justify-between">
        <CardTitle className="text-sm font-bold flex items-center gap-2">
          <AppIcon name="calendar" className=" text-primary-600" />
          {format(currentDate, "MMMM yyyy")}
        </CardTitle>
        <div className="flex items-center gap-1">
          {canManage && (
            <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
              <DialogTrigger asChild>
                <Button variant="outline" size="sm" onClick={openAdd} className="mr-2 h-7 px-2 text-xs">
                  <AppIcon name="plus" size="xs" className=" mr-1" /> Add Holiday/Event
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>Add Holiday or Event</DialogTitle>
                </DialogHeader>
                <form onSubmit={handleSave} className="space-y-4">
                  <HolidayFormFields />
                  <Button type="submit" disabled={addHoliday.isPending} className="w-full">Save</Button>
                </form>
              </DialogContent>
            </Dialog>
          )}
          <Button variant="ghost" size="icon" onClick={handlePrevMonth} className="h-7 w-7" aria-label="Previous month">
            <AppIcon name="chevronLeft" />
          </Button>
          <Button variant="ghost" size="icon" onClick={handleNextMonth} className="h-7 w-7" aria-label="Next month">
            <AppIcon name="chevronRight" />
          </Button>
        </div>
      </CardHeader>
      <CardContent className="flex-1 p-4">
        {isLoading ? (
          <div className="space-y-4">
            <Skeleton className="h-8 w-full" />
            <Skeleton className="h-32 w-full" />
          </div>
        ) : (
          <div className="h-full flex flex-col">
            <div className="grid grid-cols-7 mb-2">
              {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(day => (
                <div key={day} className="text-center text-[10px] font-semibold text-neutral-500">
                  {day}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-7 gap-1 flex-1">
              {days.map((day, idx) => {
                const isCurrentMonth = isSameMonth(day, monthStart);
                const holiday = holidayList.find((h: any) => isSameDay(new Date(h.date), day));
                
                const CellContent = (
                  <div
                    className={`relative flex flex-col items-center justify-center p-1 rounded-[var(--radius)] text-xs transition-all min-h-[50px] sm:min-h-[70px]
                      ${isCurrentMonth ? "text-neutral-900 dark:text-neutral-100" : "text-neutral-400 dark:text-neutral-600 opacity-50"}
                      ${holiday ? 
                        "bg-primary-50 dark:bg-primary-900/20 font-semibold border border-primary-100 dark:border-primary-800/50 cursor-pointer hover:bg-primary-100 dark:hover:bg-primary-900/40" 
                        : ""}`}
                  >
                    <span>{format(day, "d")}</span>
                    {holiday && (
                      <span className={`w-1 h-1 rounded-full mt-1 bg-primary-500`} />
                    )}
                  </div>
                );

                if (holiday) {
                  return (
                    <Popover key={idx}>
                      <PopoverTrigger asChild>
                        {CellContent}
                      </PopoverTrigger>
                      <PopoverContent className="w-64 p-3 z-50">
                        <div className="space-y-2">
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] uppercase font-bold tracking-wider text-neutral-500">Holiday</span>
                          </div>
                          <div>
                            <div className="font-bold text-sm text-neutral-900 dark:text-white leading-tight">
                              {holiday.name}
                            </div>
                            <div className="text-xs text-neutral-500 mt-1">
                              {format(new Date(holiday.date), "MMMM d, yyyy")} {holiday.recurring && "(Recurring)"}
                            </div>
                          </div>
                          {holiday.description && (
                            <p className="text-xs text-neutral-500">{holiday.description}</p>
                          )}
                          <div className="flex gap-2 mt-2 items-center justify-between">
                            {holiday.recurring ? (
                              <span className="inline-flex items-center rounded-full border px-2 py-0.5 text-[10px] font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80">
                                Recurring
                              </span>
                            ) : <span></span>}
                            {canManage && (
                              <div className="flex items-center gap-1">
                                <TooltipProvider delayDuration={150}>
                                  <Tooltip>
                                    <TooltipTriggerComponent asChild>
                                      <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => openEdit(holiday)} aria-label="Edit item">
                                        <AppIcon name="edit" size="xs" className=" text-neutral-500" />
                                      </Button>
                                    </TooltipTriggerComponent>
                                    <TooltipContent className="text-xs">Edit item</TooltipContent>
                                  </Tooltip>
                                </TooltipProvider>
                                <TooltipProvider delayDuration={150}>
                                  <Tooltip>
                                    <TooltipTriggerComponent asChild>
                                      <Button variant="ghost" size="icon" className="h-6 w-6 text-red-500" aria-label="Delete item" onClick={() => {
                                        setConfirmState({ isOpen: true, id: holiday.id });
                                      }}>
                                        <AppIcon name="trash" size="xs" />
                                      </Button>
                                    </TooltipTriggerComponent>
                                    <TooltipContent className="text-xs">Delete item</TooltipContent>
                                  </Tooltip>
                                </TooltipProvider>
                              </div>
                            )}
                          </div>
                        </div>
                      </PopoverContent>
                    </Popover>
                  );
                }

                return <div key={idx}>{CellContent}</div>;
              })}
            </div>
          </div>
        )}
      </CardContent>

      <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit {(formData as any).type === 'event' ? 'Event' : 'Holiday'}</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSave} className="space-y-4">
            <HolidayFormFields />
            <div className="space-y-2">
              <Label>Description</Label>
              <Textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} />
            </div>
            <div className="flex items-center gap-2">
              <Checkbox id="recurring-edit" checked={formData.recurring} onCheckedChange={(c) => setFormData({ ...formData, recurring: !!c })} />
              <Label htmlFor="recurring-edit">Recurring annually</Label>
            </div>
            <Button type="submit" disabled={editHoliday.isPending} className="w-full">Save Changes</Button>
          </form>
        </DialogContent>
      </Dialog>
      
      <ConfirmDialog
        open={confirmState.isOpen}
        onOpenChange={(open) => { if (!open) setConfirmState({ isOpen: false, id: null }) }}
        onConfirm={() => {
          if (confirmState.id) {
            deleteHoliday.mutate(confirmState.id);
            setConfirmState({ isOpen: false, id: null });
          }
        }}
        title="Delete Item"
        description="Are you sure you want to delete this? This action cannot be undone."
        isLoading={deleteHoliday.isPending}
      />
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { Button } from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";
import { ConfirmDialog } from "@g4k/ui/components";
import { queryKeys } from "@/lib/query-keys";

import { useAuthStore } from "@/lib/auth-store";

export function LeaveApprovalActionsCell({ record }: { record: any }) {
  const queryClient = useQueryClient();
  const user = useAuthStore((s) => s.user);
  const [isRejectOpen, setIsRejectOpen] = useState(false);
  const [rejectReason, setRejectReason] = useState("");

  const approvalId = record.approval?.id;
  const status = record.approval?.status;
  const isSelf = user?.id === record.user_id;

  const decisionMutation = useMutation({
    mutationFn: async ({ decision, reason }: { decision: string; reason?: string }) => {
      return apiFetch(`/approvals/${approvalId}/decision`, {
        method: "POST",
        body: JSON.stringify({ decision, reason }),
      });
    },
    onMutate: async ({ decision }) => {
      // Optimistic Update
      await queryClient.cancelQueries({ queryKey: queryKeys.orgLeaveRequests });
      const previousLeaves = queryClient.getQueriesData({ queryKey: queryKeys.orgLeaveRequests });
      
      queryClient.setQueriesData({ queryKey: queryKeys.orgLeaveRequests }, (old: any) => {
        // Handle unwrapped paginator arrays or standard paginators
        if (!old) return old;
        
        let targetArray = Array.isArray(old) ? old : (old.data ?? []);
        const newData = targetArray.map((item: any) => {
          if (item.approval?.id === approvalId) {
            return {
              ...item,
              approval: { ...item.approval, status: decision },
            };
          }
          return item;
        });

        if (Array.isArray(old)) return newData;
        return { ...old, data: newData };
      });
      return { previousLeaves };
    },
    onSuccess: (data, variables) => {
      toast.success(`Leave request ${variables.decision}.`);
      setIsRejectOpen(false);
      setRejectReason("");
    },
    onError: (err: any, newTodo, context) => {
      context?.previousLeaves?.forEach(([key, data]: [any, any]) => {
        queryClient.setQueryData(key, data);
      });
      toast.error(err.message || "Failed to process decision.");
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.orgLeaveRequests });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
  });

  const handleApprove = () => {
    decisionMutation.mutate({ decision: "approved" });
  };

  const handleReject = () => {
    if (!rejectReason) {
      toast.error("Reason is required for rejection.");
      return;
    }
    decisionMutation.mutate({ decision: "rejected", reason: rejectReason });
  };

  if (status !== "pending") {
    return <span className="text-xs text-neutral-400 italic">Decision made</span>;
  }
  
  if (isSelf) {
    return <span className="text-xs text-neutral-400 italic">Cannot self-approve</span>;
  }

  return (
    <>
      <div className="flex items-center justify-end gap-2">
        <Button
          size="sm"
          variant="outline"
          className="h-8 gap-1 text-emerald-600 hover:text-emerald-700 border-emerald-200 hover:bg-emerald-50 dark:border-emerald-900 dark:hover:bg-emerald-950/30"
          onClick={handleApprove}
          disabled={decisionMutation.isPending}
        >
          {decisionMutation.isPending && decisionMutation.variables?.decision === "approved" ? (
            <AppIcon name="loading" size="sm" className=" animate-spin" />
          ) : (
            <AppIcon name="check" size="sm" />
          )}
          Approve
        </Button>
        <Button
          size="sm"
          variant="outline"
          className="h-8 gap-1 text-rose-600 hover:text-rose-700 border-rose-200 hover:bg-rose-50 dark:border-rose-900 dark:hover:bg-rose-950/30"
          onClick={() => setIsRejectOpen(true)}
          disabled={decisionMutation.isPending}
        >
          <AppIcon name="close" size="sm" />
          Reject
        </Button>
      </div>

      <ConfirmDialog
        open={isRejectOpen}
        onOpenChange={(open) => {
          if (!open) {
            setIsRejectOpen(false);
            setRejectReason("");
          }
        }}
        onConfirm={handleReject}
        title="Reject Leave Request"
        description="Please provide a reason for rejecting this leave request. This will be visible to the employee."
        confirmText="Confirm Rejection"
        isLoading={decisionMutation.isPending}
      >
        <div className="py-2">
          <Input
            placeholder="Reason for rejection..."
            value={rejectReason}
            onChange={(e) => setRejectReason(e.target.value)}
            className="text-xs"
          />
        </div>
      </ConfirmDialog>
    </>
  );
}

"use client";

import { useMemo, useState } from "react";
import { format } from "date-fns";
import { ColumnDef } from "@tanstack/react-table";
import { AppIcon, IconName } from "@g4k/ui/components";
import { DataTable, EmptyState } from "@g4k/ui/components";
import { FilterBar } from "@g4k/ui/components";

interface LeaveHistoryTableProps {
  records: any[];
  isLoading: boolean;
  typeFilter?: string;
  setTypeFilter?: (val: string) => void;
  statusFilter?: string;
  setStatusFilter?: (val: string) => void;
  search?: string;
  setSearch?: (val: string) => void;
  showEmployee?: boolean;
  hideFilters?: boolean;
  page?: number;
  perPage?: number;
  totalPages?: number;
  onPageChange?: (page: number) => void;
  onPerPageChange?: (perPage: number) => void;
}

export function LeaveHistoryTable({ 
  records, 
  isLoading,
  typeFilter = "all",
  setTypeFilter = () => {},
  statusFilter = "all",
  setStatusFilter = () => {},
  search,
  setSearch,
  showEmployee = false,
  hideFilters = false,
  page,
  perPage,
  totalPages,
  onPageChange,
  onPerPageChange
}: LeaveHistoryTableProps) {
  const columns = useMemo<ColumnDef<any>[]>(() => {
    const cols: ColumnDef<any>[] = [];
    
    if (showEmployee) {
      cols.push({
        accessorKey: "employee",
        header: "Employee",
        cell: ({ row }) => (
          <div>
            <div className="font-semibold text-neutral-900 dark:text-white">
              {row.original.user?.name || "Unknown"}
            </div>
          </div>
        ),
      });
    }

    cols.push(
      {
        accessorKey: "start_date",
        header: "Dates",
        cell: ({ row }) => {
          const startDate = new Date(row.original.start_date);
          const endDate = new Date(row.original.end_date);
          return (
            <div className="font-medium text-neutral-900 dark:text-neutral-100">
              {format(startDate, "MMM d")} - {format(endDate, "MMM d, yyyy")}
            </div>
          );
        },
      }
    );
    
    return [
      ...cols,
      {
        accessorKey: "type",
        header: "Type",
        cell: ({ row }) => <span className="capitalize">{row.original.type}</span>,
      },
      {
        accessorKey: "reason",
        header: "Reason",
        cell: ({ row }) => (
          <span className="text-neutral-500 truncate max-w-[200px] block">
            {row.original.reason}
          </span>
        ),
      },
      {
        accessorKey: "status",
        header: "Status",
        cell: ({ row }) => {
          const status = row.original.approval?.status || "pending";
          return (
            <span
              className={`inline-flex items-center px-2 py-1 rounded-full text-[10px] font-medium uppercase ${
                status === "approved"
                  ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"
                  : status === "rejected"
                  ? "bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400"
                  : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400"
              }`}
            >
              {status}
            </span>
          );
        },
      },
      {
        id: "approver",
        header: "Approver / Decision",
        cell: ({ row }) => {
          const approval = row.original.approval;
          if (!approval || approval.status === "pending") {
            return <span className="text-neutral-400 italic">Pending...</span>;
          }
          return (
            <div className="flex items-center gap-2">
              {approval.status === "approved" ? (
                <AppIcon name="check" className=" text-emerald-500" />
              ) : (
                <AppIcon name="close" className=" text-rose-600" />
              )}
              {approval.decision_reason && (
                <span className="text-neutral-500 text-xs truncate max-w-[150px] block" title={approval.decision_reason}>
                  {approval.decision_reason}
                </span>
              )}
            </div>
          );
        },
      },
    ];
  }, [showEmployee]);

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1 min-h-[300px]">
        {!isLoading && (!records || records.length === 0) ? (
          <div className="p-8">
            <EmptyState
              icon={<AppIcon name="plane" size="hero" className=" text-neutral-300" />}
              title="No leave requests yet."
              description="You haven't requested any time off, or no requests match your current filters."
            />
          </div>
        ) : (
          <DataTable
            columns={columns}
            data={records || []}
            isLoading={isLoading}
            page={page}
            perPage={perPage}
            totalPages={totalPages}
            onPageChange={onPageChange}
            onPerPageChange={onPerPageChange}
          />
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { Card, CardHeader, CardTitle, CardContent } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";
import { RadioGroup, RadioGroupItem } from "@g4k/ui/components";
import { Textarea } from "@g4k/ui/components";
import { Label } from "@g4k/ui/components";
import { Popover, PopoverContent, PopoverTrigger } from "@g4k/ui/components";
import { Calendar } from "@g4k/ui/components";
import { format, startOfTomorrow } from "date-fns";
import { FormError } from "@/components/forms/form-error";

import { useRouter } from "next/navigation";
import { queryKeys } from "@/lib/query-keys";
import { triggerInvalidation } from "@/lib/invalidation-map";
import { LEAVE_TYPES } from "@/lib/constants";
import { useFormDraft } from "@/hooks/use-form-draft";
import { Alert, AlertDescription, AlertTitle } from "@g4k/ui/components";

export function LeaveRequestForm() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const [startDate, setStartDate] = useState<Date | undefined>(undefined);
  const [endDate, setEndDate] = useState<Date | undefined>(undefined);
  const [type, setType] = useState("casual");
  const [reason, setReason] = useState("");
  const [fieldErrors, setFieldErrors] = useState<Record<string, string[]>>({});

  const { formData: draftData, setFormData: setDraftData, hasDraft, restoreDraft, clearDraft } = useFormDraft<{
    start_date?: Date;
    end_date?: Date;
    type: string;
    reason: string;
  }>("leave_request", {
    type: "casual",
    reason: "",
  });

  const activeStartDate = startDate ?? draftData.start_date;
  const activeEndDate = endDate ?? draftData.end_date;
  const activeType = type !== "casual" ? type : (draftData.type || "casual");
  const activeReason = reason || draftData.reason || "";

  // Update draft whenever fields change
  const handleFieldChange = (updates: Partial<typeof draftData>) => {
    setDraftData({
      start_date: startDate ?? draftData.start_date,
      end_date: endDate ?? draftData.end_date,
      type: type !== "casual" ? type : draftData.type,
      reason: reason || draftData.reason,
      ...updates
    });
  };

  const submitMutation = useMutation({
    mutationFn: async (payload: any) => {
      return apiFetch("/leave-requests", {
        method: "POST",
        body: JSON.stringify(payload),
      });
    },
    onSuccess: () => {
      toast.success("Leave request submitted successfully.");
      setStartDate(undefined);
      setEndDate(undefined);
      setReason("");
      setType("casual");
      clearDraft();
      triggerInvalidation(queryClient, "leave.request");
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to submit leave request.");
      if (err.errors) {
        setFieldErrors(err.errors);
      }
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFieldErrors({});
    if (!activeStartDate || !activeEndDate) return;

    if (activeEndDate < activeStartDate) {
      toast.error("End date must be on or after start date.");
      return;
    }

    const today = new Date();
    today.setHours(0,0,0,0);
    if (activeStartDate <= today) {
      toast.error("Start date must be a future date.");
      return;
    }

    // Optimistic checking of overlapping dates based on cached data
    const queries = queryClient.getQueriesData<any>({ queryKey: [queryKeys.myLeaveHistory()[0]], exact: false });
    const existingLeaves = queries.flatMap(([_, data]) => {
      if (!data) return [];
      if ('data' in data && Array.isArray(data.data)) return data.data;
      if (data.data && 'data' in data.data && Array.isArray(data.data.data)) return data.data.data;
      if (Array.isArray(data)) return data;
      return [];
    });
    const hasOverlap = existingLeaves.some((leave: any) => {
      if (leave.approval?.status !== "pending" && leave.approval?.status !== "approved") return false;
      const existStart = new Date(leave.start_date);
      const existEnd = new Date(leave.end_date);
      return activeStartDate <= existEnd && activeEndDate >= existStart;
    });

    if (hasOverlap) {
      toast.error("You already have a pending or approved leave request that overlaps with these dates.");
      return;
    }

    submitMutation.mutate({ 
      start_date: format(activeStartDate, "yyyy-MM-dd"), 
      end_date: format(activeEndDate, "yyyy-MM-dd"), 
      type: activeType, 
      reason: activeReason 
    });
  };

  const tomorrow = startOfTomorrow();

  return (
    <Card className="h-full border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl flex flex-col">
      <CardHeader>
        <CardTitle className="text-base font-bold">Request Time Off</CardTitle>
      </CardHeader>
      <CardContent>
        {hasDraft && (
          <Alert className="mb-4 bg-amber-50/50 border-amber-200">
            <AppIcon name="warning" className="h-4 w-4 text-amber-600" />
            <AlertTitle className="text-amber-800">Unsaved draft</AlertTitle>
            <AlertDescription className="text-amber-700/80 flex items-center gap-4">
              You have an unsaved leave request.
              <div className="flex items-center gap-2">
                <Button variant="outline" size="sm" onClick={() => {
                  restoreDraft();
                  setStartDate(draftData.start_date);
                  setEndDate(draftData.end_date);
                  setType(draftData.type || "casual");
                  setReason(draftData.reason || "");
                }} className="h-7 px-3 text-xs bg-white">Restore</Button>
                <Button variant="ghost" size="sm" onClick={clearDraft} className="h-7 px-3 text-xs hover:bg-amber-100/50">Discard</Button>
              </div>
            </AlertDescription>
          </Alert>
        )}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-semibold text-neutral-500">Start Date *</label>
              <Popover>
                <PopoverTrigger asChild>
                  <button type="button"
                    className="flex h-9 w-full items-center justify-between rounded-[var(--radius)] border border-border bg-background px-3 text-xs">
                    {activeStartDate ? format(activeStartDate, "dd-MM-yyyy") : <span className="text-muted tracking-wide uppercase">DD-MM-YYYY</span>}
                    <AppIcon name="calendar" className=" text-muted" />
                  </button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar mode="single" selected={activeStartDate} onSelect={(date) => { setStartDate(date); handleFieldChange({ start_date: date }); }}
                    disabled={{ before: tomorrow }}
                    initialFocus />
                </PopoverContent>
              </Popover>
              <FormError errors={fieldErrors.start_date} />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-semibold text-neutral-500">End Date *</label>
              <Popover>
                <PopoverTrigger asChild>
                  <button type="button"
                    className="flex h-9 w-full items-center justify-between rounded-[var(--radius)] border border-border bg-background px-3 text-xs">
                    {activeEndDate ? format(activeEndDate, "dd-MM-yyyy") : <span className="text-muted tracking-wide uppercase">DD-MM-YYYY</span>}
                    <AppIcon name="calendar" className=" text-muted" />
                  </button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar mode="single" selected={activeEndDate} onSelect={(date) => { setEndDate(date); handleFieldChange({ end_date: date }); }}
                    disabled={{ before: activeStartDate ?? tomorrow }}
                    initialFocus />
                </PopoverContent>
              </Popover>
              <FormError errors={fieldErrors.end_date} />
            </div>
          </div>
          
          <div className="space-y-2">
            <label className="text-xs font-semibold text-neutral-500">Leave Type *</label>
            <RadioGroup value={activeType} onValueChange={(val) => { setType(val); handleFieldChange({ type: val }); }} className="grid grid-cols-2 gap-2 mt-1">
              {LEAVE_TYPES.map((item) => (
                <div key={item.value}>
                  <RadioGroupItem
                    value={item.value}
                    id={`type-${item.value}`}
                    className="peer sr-only"
                  />
                  <Label
                    htmlFor={`type-${item.value}`}
                    className="flex flex-col items-center justify-between rounded-[var(--radius)] border-2 border-border bg-popover p-4 hover:bg-accent hover:text-accent-foreground peer-data-[state=checked]:border-primary-600 peer-data-[state=checked]:bg-primary-50 dark:peer-data-[state=checked]:bg-primary-900/20 [&:has([data-state=checked])]:border-primary text-xs cursor-pointer text-center"
                  >
                    {item.label}
                  </Label>
                </div>
              ))}
            </RadioGroup>
            <FormError errors={fieldErrors.type} />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-neutral-500">Reason *</label>
            <Textarea
              required
              rows={3}
              value={activeReason}
              onChange={(e) => { setReason(e.target.value); handleFieldChange({ reason: e.target.value }); }}
              className={`text-xs resize-none focus-visible:ring-primary-500 ${fieldErrors.reason ? "border-red-500" : ""}`}
              placeholder="Provide a brief reason for your leave request..."
            />
            <FormError errors={fieldErrors.reason} />
          </div>

          <Button
            type="submit"
            disabled={submitMutation.isPending || !activeStartDate || !activeEndDate || !activeReason}
            className="w-full bg-primary-600 hover:bg-primary-700 text-white font-semibold h-10"
          >
            {submitMutation.isPending ? <AppIcon name="loading" className=" animate-spin" /> : "Submit Request"}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

