"use client";

import { useEffect, useState } from "react";
import { AppIcon, IconName } from "@g4k/ui/components";
import { cn } from "@/lib/utils";

export function OfflineIndicator() {
  const [isOffline, setIsOffline] = useState(false);

  useEffect(() => {
    // Initial check
    if (typeof window !== "undefined") {
      setIsOffline(!navigator.onLine);
    }

    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    // Register service worker safely on client
    if (typeof window !== "undefined" && "serviceWorker" in navigator) {
      window.addEventListener("load", () => {
        navigator.serviceWorker.register("/sw.js").catch(() => {});
      });
    }

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  if (!isOffline) return null;

  return (
    <div 
      className={cn(
        "fixed bottom-0 left-0 right-0 z-50 p-2",
        "bg-amber-500 text-amber-950 font-medium text-sm text-center shadow-e3",
        "flex items-center justify-center gap-2 animate-in slide-in-from-bottom"
      )}
      aria-live="polite"
    >
      <AppIcon name="wifiOff" />
      <span>You're offline. Changes will be saved locally and synced when you reconnect.</span>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@g4k/ui/components";
import { Button, Input, Select, SelectTrigger, SelectValue, SelectContent, SelectItem, Calendar, FileUploadPopup } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { format } from "date-fns";
import { FormError } from "@/components/forms/form-error";
import { useFormDraft } from "@/hooks/use-form-draft";
import { Alert, AlertDescription, AlertTitle, AppIcon } from "@g4k/ui/components";

export function CreateProjectDialog({
  open,
  onOpenChange
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const queryClient = useQueryClient();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [priority, setPriority] = useState("medium");
  const [departmentId, setDepartmentId] = useState("none");
  const [qaFormId, setQaFormId] = useState("none");
  const [deadline, setDeadline] = useState("");
  const [memberIds, setMemberIds] = useState<string[]>([]);
  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [allowEmployeeTasks, setAllowEmployeeTasks] = useState(false);
  const [showUploadPopup, setShowUploadPopup] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string[]>>({});

  const { formData: draftData, setFormData: setDraftData, hasDraft, restoreDraft, clearDraft } = useFormDraft("create_project", {
    name: "",
    description: "",
    priority: "medium",
    departmentId: "none",
    qaFormId: "none",
    deadline: "",
    memberIds: [] as string[],
    allowEmployeeTasks: false
  });

  const activeName = name || draftData.name || "";
  const activeDescription = description || draftData.description || "";
  const activePriority = priority !== "medium" ? priority : (draftData.priority || "medium");
  const activeDepartmentId = departmentId !== "none" ? departmentId : (draftData.departmentId || "none");
  const activeQaFormId = qaFormId !== "none" ? qaFormId : (draftData.qaFormId || "none");
  const activeDeadline = deadline || draftData.deadline || "";
  const activeMemberIds = memberIds.length > 0 ? memberIds : (draftData.memberIds || []);
  const activeAllowEmployeeTasks = allowEmployeeTasks || draftData.allowEmployeeTasks || false;

  const handleFieldChange = (updates: Partial<typeof draftData>) => {
    setDraftData({
      name: activeName,
      description: activeDescription,
      priority: activePriority,
      departmentId: activeDepartmentId,
      qaFormId: activeQaFormId,
      deadline: activeDeadline,
      memberIds: activeMemberIds,
      allowEmployeeTasks: activeAllowEmployeeTasks,
      ...updates
    });
  };

  const { data: deptsData } = useQuery({ queryKey: ["departments"], queryFn: () => apiFetch("/departments") });
  const { data: qaFormsData } = useQuery({ queryKey: queryKeys.qaForms, queryFn: () => apiFetch("/qa-forms") });
  const { data: usersData } = useQuery({ queryKey: queryKeys.usersList, queryFn: () => apiFetch("/users") });

  const createMutation = useMutation({
    mutationFn: async () => {
      return apiFetch("/projects", {
        method: "POST",
        body: JSON.stringify({
          name: activeName,
          description: activeDescription,
          priority: activePriority,
          department_id: activeDepartmentId === "none" ? null : activeDepartmentId,
          qa_form_id: activeQaFormId === "none" ? null : activeQaFormId,
          deadline: activeDeadline || null,
          member_ids: activeMemberIds,
          cover_image: coverImage,
          allow_employee_tasks: activeAllowEmployeeTasks,
        }),
      });
    },
    onSuccess: () => {
      toast.success("Project created successfully.");
      queryClient.invalidateQueries({ queryKey: ["projects"] });
      onOpenChange(false);
      setName("");
      setDescription("");
      setPriority("medium");
      setDepartmentId("none");
      setQaFormId("none");
      setDeadline("");
      setMemberIds([]);
      setCoverImage(null);
      setAllowEmployeeTasks(false);
      clearDraft();
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to create project.");
      if (err.errors) {
        setFieldErrors(err.errors);
      }
    },
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md max-h-[85dvh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Create Project</DialogTitle>
          <DialogDescription>Add a new project to the workspace.</DialogDescription>
        </DialogHeader>
        
        {hasDraft && (
          <Alert className="mb-4 bg-amber-50/50 border-amber-200 mt-4">
            <AppIcon name="warning" className="h-4 w-4 text-amber-600" />
            <AlertTitle className="text-amber-800">Unsaved draft</AlertTitle>
            <AlertDescription className="text-amber-700/80 flex items-center gap-4">
              You have an unsaved project draft.
              <div className="flex items-center gap-2">
                <Button variant="outline" size="sm" onClick={() => {
                  restoreDraft();
                  setName(draftData.name);
                  setDescription(draftData.description);
                  setPriority(draftData.priority);
                  setDepartmentId(draftData.departmentId);
                  setQaFormId(draftData.qaFormId);
                  setDeadline(draftData.deadline);
                  setMemberIds(draftData.memberIds);
                  setAllowEmployeeTasks(draftData.allowEmployeeTasks);
                }} className="h-7 px-3 text-xs bg-white">Restore</Button>
                <Button variant="ghost" size="sm" onClick={clearDraft} className="h-7 px-3 text-xs hover:bg-amber-100/50">Discard</Button>
              </div>
            </AlertDescription>
          </Alert>
        )}

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <label htmlFor="project-name" className="text-sm font-medium">Name</label>
            <Input id="project-name" value={activeName} onChange={(e) => { setName(e.target.value); handleFieldChange({ name: e.target.value }); }} placeholder="Project Name" className={fieldErrors.name ? "border-red-500" : ""} />
            <FormError errors={fieldErrors.name} />
          </div>
          
          <div className="space-y-2">
            <label htmlFor="project-description" className="text-sm font-medium">Description</label>
            <textarea
              id="project-description"
              value={activeDescription}
              onChange={(e) => { setDescription(e.target.value); handleFieldChange({ description: e.target.value }); }}
              className={`flex w-full rounded-[var(--radius)] border bg-white px-3 py-2 text-sm shadow-e1 ${fieldErrors.description ? "border-red-500" : "border-neutral-200"}`}
              rows={3}
              placeholder="Project Description"
            />
            <FormError errors={fieldErrors.description} />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label htmlFor="project-priority" className="text-sm font-medium">Priority</label>
              <Select value={activePriority} onValueChange={(val) => { setPriority(val); handleFieldChange({ priority: val }); }}>
                <SelectTrigger id="project-priority">
                  <SelectValue placeholder="Select Priority" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="urgent">Urgent</SelectItem>
                </SelectContent>
              </Select>
            </div>
            
            <div className="space-y-2">
              <label htmlFor="project-department" className="text-sm font-medium">Department</label>
              <Select value={activeDepartmentId} onValueChange={(val) => { setDepartmentId(val); handleFieldChange({ departmentId: val }); }}>
                <SelectTrigger id="project-department">
                  <SelectValue placeholder="Select Department" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Company-Wide</SelectItem>
                  {Array.isArray(deptsData?.data) ? deptsData.data.map((d: any) => (
                    <SelectItem key={d.id} value={String(d.id)}>{d.name}</SelectItem>
                  )) : deptsData?.data?.data?.map((d: any) => (
                    <SelectItem key={d.id} value={String(d.id)}>{d.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label htmlFor="project-qa" className="text-sm font-medium">QA Form</label>
              <Select value={activeQaFormId} onValueChange={(val) => { setQaFormId(val); handleFieldChange({ qaFormId: val }); }}>
                <SelectTrigger id="project-qa">
                  <SelectValue placeholder="None" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">None</SelectItem>
                  {(Array.isArray(qaFormsData?.data) ? qaFormsData.data : Array.isArray(qaFormsData) ? qaFormsData : []).map((q: any) => (
                    <SelectItem key={q.id} value={String(q.id)}>{q.title}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label htmlFor="project-deadline" className="text-sm font-medium">Deadline</label>
              <Input id="project-deadline" type="date" value={activeDeadline} onChange={(e) => { setDeadline(e.target.value); handleFieldChange({ deadline: e.target.value }); }} className={fieldErrors.deadline ? "border-red-500" : ""} />
              <FormError errors={fieldErrors.deadline} />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Project Cover (Optional)</label>
            <div className="flex items-center gap-3">
              {coverImage && (
                <img src={coverImage} alt="Cover Preview" className="h-10 w-10 object-cover rounded-[var(--radius)] border" />
              )}
              <Button type="button" variant="outline" size="sm" onClick={() => setShowUploadPopup(true)}>
                {coverImage ? "Change Image" : "Upload Image"}
              </Button>
              <FileUploadPopup
                open={showUploadPopup}
                onOpenChange={setShowUploadPopup}
                title="Upload Project Cover"
                maxSizeMB={5}
                onUpload={async (file) => {
                  const formData = new FormData();
                  formData.append("cover_image", file);
                  const res = await apiFetch("/projects/cover", {
                    method: "POST",
                    body: formData,
                  });
                  setCoverImage(res.url);
                }}
              />
              {coverImage && (
                <Button type="button" variant="ghost" size="sm" onClick={() => setCoverImage(null)} className="text-rose-500 hover:text-rose-600 hover:bg-rose-50">
                  Remove
                </Button>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Team Members</label>
            <div className="max-h-32 overflow-y-auto border border-neutral-200 rounded-[var(--radius)] p-2 space-y-1">
              {usersData?.data?.map((u: any) => (
                <label key={u.id} className="flex items-center gap-2 text-sm cursor-pointer hover:bg-neutral-50 p-1 rounded">
                  <input 
                    type="checkbox" 
                    checked={activeMemberIds.includes(String(u.id))}
                    onChange={(e) => {
                      let nextIds;
                      if (e.target.checked) nextIds = [...activeMemberIds, String(u.id)];
                      else nextIds = activeMemberIds.filter(id => id !== String(u.id));
                      setMemberIds(nextIds);
                      handleFieldChange({ memberIds: nextIds });
                    }}
                  />
                  {u.name}
                </label>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-2 pt-2">
            <input 
              type="checkbox" 
              id="allow-employee-tasks" 
              checked={activeAllowEmployeeTasks}
              onChange={(e) => { setAllowEmployeeTasks(e.target.checked); handleFieldChange({ allowEmployeeTasks: e.target.checked }); }}
              className="rounded border-neutral-300 text-primary-600 focus:ring-primary-600"
            />
            <label htmlFor="allow-employee-tasks" className="text-sm cursor-pointer select-none">
              Allow employees to create tasks
            </label>
          </div>
        </div>

        <div className="flex justify-end gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button 
            className="bg-primary-600 hover:bg-primary-700 text-white" 
            onClick={() => {
              setFieldErrors({});
              createMutation.mutate();
            }}
            disabled={!activeName.trim() || createMutation.isPending}
          >
            {createMutation.isPending ? "Creating..." : "Create Project"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { Card, CardContent, CardHeader, CardTitle, Avatar, AvatarFallback } from "@g4k/ui/components";
import { Badge } from "@g4k/ui/components";
import { usePins } from "@/hooks/use-pins";
import { Button } from "@g4k/ui/components";

export function ProjectCard({ project, onClick }: { project: any; onClick?: () => void }) {
  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "urgent":
        return "bg-rose-100 text-rose-700 dark:bg-rose-950 dark:text-rose-300";
      case "high":
        return "bg-amber-100 text-amber-700 dark:bg-amber-950 dark:text-amber-300";
      case "medium":
        return "bg-blue-100 text-blue-700 dark:bg-blue-950 dark:text-blue-300";
      default:
        return "bg-neutral-100 text-neutral-600 dark:bg-neutral-800 dark:text-neutral-400";
    }
  };

  const { pins, pin, unpin, isPinning, isUnpinning } = usePins();
  const pinnedItem = pins?.find(p => p.type === 'project' && p.target_id === String(project.id));
  const isPinned = !!pinnedItem;

  const handlePinClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isPinned && pinnedItem) {
      unpin(pinnedItem.id);
    } else {
      pin({
        type: 'project',
        target_id: String(project.id),
        label: project.name,
        href: `/dashboard/projects/${project.id}`,
        icon: 'projects'
      });
    }
  };

  return (
    <Card
      onClick={onClick}
      className="hover:shadow-e2 transition-all cursor-pointer bg-card dark:bg-neutral-900 group border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full"
    >
      <CardHeader className="pb-2 relative z-10">
        {project.cover_image && (
          <div className="absolute inset-0 h-24 w-full">
            <div className="absolute inset-0 bg-gradient-to-t from-card/90 to-transparent dark:from-neutral-900/90 z-10" />
            <img src={project.cover_image} alt="Project Cover" className="w-full h-full object-cover opacity-60" />
          </div>
        )}
        <div className={`flex items-start justify-between ${project.cover_image ? 'pt-8' : ''} relative z-20`}>
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-[var(--radius)] bg-primary-50 text-primary-600 dark:bg-primary-950 dark:text-primary-400">
              <AppIcon name="projects" />
            </div>
            <div>
              <CardTitle className="text-sm font-bold group-hover:text-primary-600 transition-colors">
                {project.name}
              </CardTitle>
              <p className="text-[11px] text-neutral-400 line-clamp-1 mt-0.5">
                {project.description || "No description provided."}
              </p>
            </div>
          </div>
          <div className="flex flex-col items-end gap-1">
            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${getPriorityColor(project.priority)}`}>
              {project.priority}
            </span>
            <Button
              variant="ghost"
              size="icon"
              className={`h-6 w-6 mt-1 rounded-full hover:bg-neutral-100 dark:hover:bg-neutral-800 ${isPinned ? "text-amber-500" : "text-neutral-300 dark:text-neutral-600"}`}
              onClick={handlePinClick}
              disabled={isPinning || isUnpinning}
            >
              <AppIcon name="star" className="h-4 w-4 shrink-0" />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="pt-2 space-y-3">
        {/* Progress bar */}
        <div>
          <div className="flex justify-between text-[10px] text-neutral-500 font-semibold mb-1">
            <span>Progress</span>
            <span>{project.progress}%</span>
          </div>
          <div className="w-full h-1.5 bg-neutral-100 dark:bg-neutral-800 rounded-full overflow-hidden">
            <div
              className="h-full bg-primary-600 rounded-full transition-all duration-500"
              style={{ width: `${project.progress}%` }}
            />
          </div>
        </div>

        {/* Footer meta */}
        <div className="flex items-center justify-between pt-2 border-t border-neutral-100 dark:border-neutral-800 text-[11px] text-neutral-400">
          <div className="flex items-center gap-1">
            <AppIcon name="calendar" size="xs" />
            <span>{project.deadline ? format(new Date(project.deadline), "MMM d") : "No due date"}</span>
          </div>
          <div className="flex -space-x-1.5 overflow-hidden">
            {project.members && project.members.length > 0 ? (
              project.members.slice(0, 3).map((m: any) => (
                  <Avatar 
                    key={m.id} 
                    className="inline-block h-5 w-5 rounded-full ring-1 ring-white dark:ring-neutral-900"
                    title={m.name}
                  >
                    <AvatarFallback name={m.name} className="text-[9px]" />
                  </Avatar>
              ))
            ) : (
              <span className="text-[10px]">No members</span>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { queryKeys, STALE_TIME_PROJECTS } from "@/lib/query-keys";
import { useDebounce } from "@/hooks/use-debounce";
import { useUrlState } from "@/hooks/use-url-state";
import { ProjectCard } from "@/components/projects/project-card";
import { CreateProjectDialog } from "@/components/projects/create-project-dialog";
import { Button, FilterBar } from "@g4k/ui/components";
import { ContentSkeleton, IsolatedError, MeaningfulEmpty } from "@g4k/ui/components/state-helpers";
import { useCapabilities, hasCapability } from "@/lib/capabilities";

export function ProjectsTab() {
  const router = useRouter();
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("created_at");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");
  const [status, setStatus] = useState("all");
  const [page, setPage] = useUrlState("p_page", "1");
  const [createOpen, setCreateOpen] = useState(false);
  const debouncedSearch = useDebounce(search, 250);
  const { data: caps = [] } = useCapabilities();
  const canManageProjects = hasCapability(caps, "projects.manage");

  const { data, isPending, isError, error, refetch } = useQuery({
    queryKey: [...queryKeys.projects(debouncedSearch, sort, page), sortDirection, status],
    queryFn: () => apiFetch(`/projects?search=${debouncedSearch || ""}&sort=${sort || "created_at"}&direction=${sortDirection}&status=${status === "all" ? "" : status}&page=${page || 1}`),
    placeholderData: keepPreviousData,
    staleTime: STALE_TIME_PROJECTS,
  });

  const projects = data?.data || [];

  return (
    <div className="space-y-6 mt-4">
      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
        <FilterBar
          searchQuery={search}
          onSearchChange={setSearch}
          searchPlaceholder="Search projects..."
          sortBy={sort}
          sortDirection={sortDirection}
          onSortChange={(val, dir) => {
            setSort(val);
            setSortDirection(dir);
          }}
          sortOptions={[
            { label: "Created Date", value: "created_at" },
            { label: "Deadline", value: "deadline" },
            { label: "Priority", value: "priority" }
          ]}
          filters={[
            {
              key: "status",
              label: "Status",
              type: "select",
              value: status,
              onChange: setStatus,
              options: [
                { label: "Active", value: "active" },
                { label: "Completed", value: "completed" },
                { label: "On Hold", value: "on_hold" },
              ]
            }
          ]}
          onClearAll={() => {
            setSearch("");
            setSort("created_at");
            setSortDirection("desc");
            setStatus("all");
          }}
        />
        {canManageProjects && (
          <Button onClick={() => setCreateOpen(true)} className="w-full sm:w-auto h-11">
            <AppIcon name="plus" className="w-4 h-4 mr-2" />
            Create Project
          </Button>
        )}
      </div>

      <CreateProjectDialog open={createOpen} onOpenChange={setCreateOpen} />

      {isPending ? (
        <ContentSkeleton type="card-grid" rows={6} />
      ) : isError ? (
        <IsolatedError error={error} onRetry={() => refetch()} />
      ) : projects.length === 0 ? (
        <MeaningfulEmpty 
          entityName="projects" 
          icon="folder"
          actionLabel={canManageProjects ? "Create Project" : undefined}
          onAction={canManageProjects ? () => setCreateOpen(true) : undefined}
        />
      ) : (
        <div className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {projects.map((project: any) => (
              <ProjectCard 
                key={project.id} 
                project={project} 
                onClick={() => router.push(`/dashboard/projects/${project.id}`)}
              />
            ))}
          </div>
          
          {(data?.last_page || data?.meta?.last_page) > 1 && (
            <div className="flex justify-center items-center gap-2 pt-4">
              <Button
                variant="outline"
                size="sm"
                disabled={page === "1"}
                onClick={() => setPage((Number(page) - 1).toString())}
              >
                Previous
              </Button>
              <span className="text-xs text-neutral-500">Page {page} of {data?.last_page || data?.meta?.last_page || 1}</span>
              <Button
                variant="outline"
                size="sm"
                disabled={page === (data?.last_page || data?.meta?.last_page || 1).toString()}
                onClick={() => setPage((Number(page) + 1).toString())}
              >
                Next
              </Button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { Input } from "@g4k/ui/components";
import { Textarea } from "@g4k/ui/components";
import { Checkbox } from "@g4k/ui/components";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@g4k/ui/components";

export function QAFieldRenderer({ field, value, onChange }: { field: any, value: any, onChange: (val: any) => void }) {
  if (field.type === "textarea") {
    return (
      <Textarea
        className="w-full text-xs resize-y"
        value={value || ""}
        onChange={(e) => onChange(e.target.value)}
        rows={3}
      />
    );
  }

  if (field.type === "checkbox") {
    return (
      <div className="flex items-center gap-2 mt-1">
        <Checkbox
          id={`qa-${field.id}`}
          checked={value === "true" || value === true}
          onCheckedChange={(c) => onChange(c ? "true" : "false")}
        />
        <label htmlFor={`qa-${field.id}`} className="text-xs text-neutral-600 dark:text-neutral-300">
          {field.label}
        </label>
      </div>
    );
  }

  if (field.type === "select") {
    const options = field.options || [];
    return (
      <Select value={value || ""} onValueChange={onChange}>
        <SelectTrigger className="h-8 text-xs">
          <SelectValue placeholder="Select..." />
        </SelectTrigger>
        <SelectContent>
          {options.map((opt: string) => (
            <SelectItem key={opt} value={opt} className="text-xs">
              {opt}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  if (field.type === "slider") {
    return (
      <div className="flex items-center gap-3">
        <input
          type="range"
          min={field.min || 0}
          max={field.max || 100}
          value={value || field.min || 0}
          onChange={(e) => onChange(e.target.value)}
          className="flex-1 accent-primary-600"
        />
        <span className="text-xs font-mono w-8 text-right">{value || field.min || 0}</span>
      </div>
    );
  }

  // Fallback to text input
  return (
    <Input
      className="h-8 text-xs"
      type={field.type === "number" ? "number" : "text"}
      value={value || ""}
      onChange={(e) => onChange(e.target.value)}
    />
  );
}

"use client";

import { useState, useMemo, useCallback } from "react";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { format } from "date-fns";
import { useAuthStore } from "@/lib/auth-store";
import { apiFetch } from "@/lib/api-client";
import { queryKeys, STALE_TIME_TASKS } from "@/lib/query-keys";
import { TaskDetailSheet } from "@/components/tasks/task-detail-sheet";
import { usePathname, useSearchParams } from "next/navigation";
import { useUrlState } from "@/hooks/use-url-state";
import { useCapabilities, hasCapability } from "@/lib/capabilities";
import dynamic from "next/dynamic";
const TaskKanbanBoard = dynamic(() => import("@/components/tasks/task-kanban-board").then(mod => mod.TaskKanbanBoard), { ssr: false, loading: () => <div className="p-4 text-center text-xs text-neutral-400 font-medium animate-pulse">Loading board...</div> });
const TaskGantt = dynamic(() => import("@/components/tasks/task-gantt").then(mod => mod.TaskGantt), { ssr: false, loading: () => <div className="p-4 text-center text-xs text-neutral-400 font-medium animate-pulse">Loading timeline...</div> });
const QAFormBuilder = dynamic(() => import("@/components/tasks/qa-form-builder").then(mod => mod.QAFormBuilder), { ssr: false, loading: () => <div className="p-4 text-center text-xs text-neutral-400 font-medium animate-pulse">Loading builder...</div> });
import { Button, Input, Skeleton, Checkbox, Avatar, AvatarFallback, Badge, StatusBadge, Tooltip, TooltipTrigger, TooltipContent, TooltipProvider, DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, ConfirmDialog, Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription, DataTable, FilterBar, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, DatePicker } from "@g4k/ui/components";
import { FormError } from "@/components/forms/form-error";
import { toast } from "sonner";
import { ColumnDef } from "@tanstack/react-table";
export function TasksTab({ defaultProjectId }: { defaultProjectId?: string }) {
  const queryClient = useQueryClient();
  const [viewMode, setViewMode] = useState<"kanban" | "gantt" | "qa" | "list">("kanban");
  const [selectedTask, setSelectedTask] = useState<any>(null);
  const [sheetOpen, setSheetOpen] = useState(false);
  
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [priority, setPriority] = useState("medium");
  const [dueDate, setDueDate] = useState("");
  const [fieldErrors, setFieldErrors] = useState<Record<string, string[]>>({});

  const [assigneeIds, setAssigneeIds] = useState<number[]>([]);
  const [projectId, setProjectId] = useState(defaultProjectId || "");
  const [scope, setScope] = useState("global");
  const [qaFormId, setQaFormId] = useState("");
  const [blockedBy, setBlockedBy] = useState("");
  const [isRecurring, setIsRecurring] = useState(false);
  const [recurrencePattern, setRecurrencePattern] = useState("daily");
  const [recurrenceDays, setRecurrenceDays] = useState<number[]>([]);
  const [dayOfMonth, setDayOfMonth] = useState<number>(1);
  
  const { data: usersData } = useQuery({ queryKey: queryKeys.usersList, queryFn: () => apiFetch<any>("/users") });
  const { data: projectsData } = useQuery({ queryKey: queryKeys.projects(), queryFn: () => apiFetch<any>("/projects") });
  const { data: qaFormsData } = useQuery({ queryKey: queryKeys.qaForms, queryFn: () => apiFetch("/qa-forms") });
  
  const searchParams = useSearchParams();
  const isMe = searchParams.get("me") === "1";
  const isReview = searchParams.get("review") === "1";
  const [assigneeFilter, setAssigneeFilter] = useState(isMe ? "me" : "all");
  const user = useAuthStore(s => s.user);

  const { data: caps = [] } = useCapabilities();
  const canManageTasks = hasCapability(caps, "tasks.manage");
  const availableUsers = canManageTasks ? usersData?.data : usersData?.data?.filter((u: any) => u.id === user?.id);
  const availableProjects = canManageTasks ? projectsData?.data : projectsData?.data?.filter((p: any) => p.allow_employee_tasks);

  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState(isReview ? "review" : "all");
  const [scopeFilter, setScopeFilter] = useUrlState("scope", "all");
  const [sortBy, setSortBy] = useState("id");
  const [sortOrder, setSortOrder] = useState("desc");
  const [rowSelection, setRowSelection] = useState({});
  const [isBulkDeleteOpen, setIsBulkDeleteOpen] = useState(false);

  const [page, setPage] = useUrlState("page", "1");
  const [perPage, setPerPage] = useState(20);

  const { data, isLoading, isError, error, refetch } = useQuery({
    queryKey: [...queryKeys.tasks, statusFilter, scopeFilter, searchQuery, assigneeFilter, viewMode === "list" ? page : "1", viewMode === "list" ? perPage : 100, sortBy, sortOrder],
    queryFn: () => {
      const p = new URLSearchParams();
      p.append("per_page", viewMode === "list" ? perPage.toString() : "100");
      p.append("page", viewMode === "list" ? page : "1");
      if (statusFilter !== "all") p.append("status", statusFilter);
      if (scopeFilter !== "all") p.append("scope", scopeFilter);
      if (searchQuery) p.append("search", searchQuery);
      if (assigneeFilter === "me") {
        if (user?.id) p.append("assignee_id", user.id.toString());
      } else if (assigneeFilter !== "all") {
        p.append("assignee_id", assigneeFilter);
      }
      if (defaultProjectId) p.append("project_id", defaultProjectId);
      p.append("sort_by", sortBy);
      p.append("sort_order", sortOrder);
      return apiFetch(`/tasks?${p.toString()}`);
    },
    placeholderData: keepPreviousData,
    staleTime: STALE_TIME_TASKS,
  });

  const moveTaskMutation = useMutation({
    mutationFn: async ({ taskId, status }: { taskId: number; status: string }) => {
      return apiFetch(`/tasks/${taskId}`, {
        method: "PUT",
        body: JSON.stringify({ status }),
      });
    },
    onMutate: async ({ taskId, status }) => {
      await queryClient.cancelQueries({ queryKey: queryKeys.tasks });
      
      const previousTasks = queryClient.getQueriesData({ queryKey: queryKeys.tasks });

      queryClient.setQueriesData({ queryKey: queryKeys.tasks }, (old: any) => {
        if (!old) return old;
        
        // Deep clone to avoid mutating cache directly
        const clone = JSON.parse(JSON.stringify(old));
        let arr = Array.isArray(clone.data) ? clone.data : (Array.isArray(clone.data?.data) ? clone.data.data : []);
        
        const idx = arr.findIndex((t: any) => t.id === taskId);
        if (idx !== -1) {
          arr[idx].status = status;
        }
        
        return clone;
      });

      return { previousTasks };
    },
    onError: (err: any, variables, context: any) => {
      toast.error(err.message || "Failed to move task.");
      if (context?.previousTasks) {
        context.previousTasks.forEach(([key, data]: any) => {
          queryClient.setQueryData(key, data);
        });
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
    },
  });

  const reorderTaskMutation = useMutation({
    mutationFn: async (reorderedTasks: any[]) => {
      return apiFetch(`/tasks/reorder`, {
        method: "POST",
        body: JSON.stringify({
          tasks: reorderedTasks.map(t => ({ id: t.id, order: t.order || 0, status: t.status }))
        }),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to reorder tasks.");
    },
  });

  const deleteTaskMutation = useMutation({
    mutationFn: async (taskId: number) => {
      return apiFetch(`/tasks/${taskId}`, { method: "DELETE" });
    },
    onSuccess: () => {
      toast.success("Task deleted successfully.");
      // T-46.2: invalidate without exact so parameterized keys are included
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
    }
  });

  const bulkDeleteMutation = useMutation({
    mutationFn: async (taskIds: number[]) => {
      let completed = 0;
      for (const id of taskIds) {
        await apiFetch(`/tasks/${id}`, { method: "DELETE" });
        completed++;
      }
    },
    onSuccess: () => {
      toast.success("Tasks deleted successfully.");
      setRowSelection({});
      // T-46.2: invalidate without exact
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
    }
  });

  const bulkStatusMutation = useMutation({
    mutationFn: async ({ taskIds, status }: { taskIds: number[], status: string }) => {
      let completed = 0;
      for (const id of taskIds) {
        await apiFetch(`/tasks/${id}`, { method: "PUT", body: JSON.stringify({ status }) });
        completed++;
      }
    },
    onSuccess: () => {
      toast.success("Tasks status updated.");
      setRowSelection({});
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
    }
  });

  const handleTaskMove = useCallback((taskId: number, status: string) => {
    moveTaskMutation.mutate({ taskId, status });
  }, [moveTaskMutation]);

  const handleTaskSelect = useCallback((task: any) => {
    setSelectedTask(task);
    setSheetOpen(true);
  }, []);

  const handleDeleteTask = useCallback((taskId: number) => {
    deleteTaskMutation.mutate(taskId);
  }, [deleteTaskMutation]);

  const createMutation = useMutation({
    mutationFn: async () => {
      // Map "none" sentinel values to null so backend validators don't reject
      const resolvedAssigneeIds = assigneeIds.length > 0 ? assigneeIds : null;
      const resolvedProjectId = projectId && projectId !== "none" ? projectId : null;
      const resolvedQaFormId = qaFormId && qaFormId !== "none" ? qaFormId : null;
      const resolvedBlockedBy = blockedBy && blockedBy !== "none" ? blockedBy : null;
      // Recurrence contract: backend expects { type, days?, day_of_month? } not { pattern, interval }
      let recurrence = null;
      if (isRecurring) {
        recurrence = { 
          type: recurrencePattern,
          ...(recurrencePattern === "weekly" ? { days: recurrenceDays } : {}),
          ...(recurrencePattern === "monthly" ? { day_of_month: dayOfMonth } : {})
        };
      }
      return apiFetch("/tasks", {
        method: "POST",
        body: JSON.stringify({ 
          title, 
          description, 
          priority, 
          due_date: dueDate || null,
          assignees: resolvedAssigneeIds,
          project_id: resolvedProjectId ? parseInt(resolvedProjectId) : null,
          scope,
          qa_form_id: resolvedQaFormId ? parseInt(resolvedQaFormId) : null,
          blocked_by: resolvedBlockedBy ? parseInt(resolvedBlockedBy) : null,
          recurrence,
        }),
      });
    },
    onSuccess: () => {
      setIsCreateOpen(false);
      setTitle("");
      setDescription("");
      setDueDate("");
      toast.success("Task created successfully.");
      // Drop exact:true so the parameterized list key is also invalidated (T-46.2)
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to create task.");
      if (err.errors) {
        setFieldErrors(err.errors);
      }
    },
  });

  // T-46.1: /tasks returns a standard Laravel paginator — unwrap correctly
  const tasks = Array.isArray(data?.data) ? data.data : (Array.isArray(data?.data?.data) ? data.data.data : []);
  const filteredTasks = tasks; // Using server-side filtering now

  const columns: ColumnDef<any>[] = [
    {
      accessorKey: "title",
      header: "Title",
      cell: ({ row }) => (
        <div 
          className="font-medium cursor-pointer hover:underline text-primary-600"
          onClick={() => {
            setSelectedTask(row.original);
            setSheetOpen(true);
          }}
        >
          {row.getValue("title")}
        </div>
      )
    },
    {
      accessorKey: "status",
      header: "Status",
      cell: ({ row }) => {
        const s = row.getValue("status") as string;
        const task = row.original;
        return (
          <div className="flex items-center gap-1.5 flex-wrap">
            <StatusBadge 
              status={s === 'completed' ? 'success' : s === 'review' ? 'warning' : s === 'redo' || s === 'overdue' ? 'danger' : s === 'in_progress' ? 'info' : 'neutral'} 
              className="capitalize"
            >
              {s.replace("_", " ")}
            </StatusBadge>
            {task.scope && (
              <Badge variant="outline" className="capitalize text-[10px] text-neutral-500 border-neutral-200">
                {task.scope}
              </Badge>
            )}
            {task.blocked_by && (
              <Badge variant="secondary" className="bg-rose-100 text-rose-800 dark:bg-rose-900/50 dark:text-rose-300 border-rose-200 dark:border-rose-800">
                <AppIcon name="error" size="xs" className="mr-1" /> Blocked
              </Badge>
            )}
          </div>
        );
      }
    },
    {
      accessorKey: "priority",
      header: "Priority",
      cell: ({ row }) => <span className="capitalize text-xs">{row.getValue("priority")}</span>
    },
    {
      accessorKey: "due_date",
      header: "Due Date",
      cell: ({ row }) => {
        const val = row.getValue("due_date") as string;
        return <span className="text-xs text-neutral-500">{val ? format(new Date(val), "MMM d, yyyy") : "-"}</span>
      }
    }
  ];

  const selectedTaskIds = Object.keys(rowSelection).filter(k => (rowSelection as any)[k]).map(k => filteredTasks[Number(k)]?.id).filter(Boolean);

  return (
    <div className="space-y-6 mt-4">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex bg-neutral-100/80 dark:bg-neutral-900/50 p-1 rounded-[var(--radius)] w-full sm:w-auto overflow-x-auto thin-scrollbar">
          <Button variant={viewMode === "kanban" ? "primary" : "ghost"} size="sm" onClick={() => setViewMode("kanban")} className="h-8 text-xs px-3 rounded-[var(--radius)] shrink-0">
            <AppIcon name="kanban" size="sm" className=" mr-1.5" />
            Board
          </Button>
          <Button variant={viewMode === "list" ? "primary" : "ghost"} size="sm" onClick={() => setViewMode("list")} className="h-8 text-xs px-3 rounded-[var(--radius)] shrink-0">
            <AppIcon name="list" size="sm" className=" mr-1.5" />
            List
          </Button>
          <Button variant={viewMode === "gantt" ? "primary" : "ghost"} size="sm" onClick={() => setViewMode("gantt")} className="h-8 text-xs px-3 rounded-[var(--radius)] shrink-0">
            <AppIcon name="calendar" size="sm" className=" mr-1.5" />
            Timeline
          </Button>
          <Button variant={viewMode === "qa" ? "primary" : "ghost"} size="sm" onClick={() => setViewMode("qa")} className="h-8 text-xs px-3 rounded-[var(--radius)] shrink-0">
            <AppIcon name="tasks" size="sm" className=" mr-1.5" />
            QA Forms
          </Button>
        </div>
        
        <div className="flex items-center gap-2 w-full sm:w-auto">
          {canManageTasks && (
            <Button 
              variant={statusFilter === "review" ? "secondary" : "outline"} 
              size="sm" 
              onClick={() => setStatusFilter(statusFilter === "review" ? "all" : "review")} 
              className={`h-9 text-xs px-3 ${statusFilter === "review" ? "bg-amber-100 text-amber-800 hover:bg-amber-200 border-amber-200" : ""}`}
            >
              <AppIcon name="clipboard" size="sm" className="mr-1.5" />
              Needs Review
            </Button>
          )}
          {canManageTasks && (
            <Select value={assigneeFilter} onValueChange={setAssigneeFilter}>
              <SelectTrigger className="w-[120px] h-9 text-xs">
                <SelectValue placeholder="Tasks" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="me">My Tasks</SelectItem>
                <SelectItem value="all">All Tasks</SelectItem>
              </SelectContent>
            </Select>
          )}
          <Select value={scopeFilter} onValueChange={setScopeFilter}>
            <SelectTrigger className="w-[130px] h-9 text-xs">
              <SelectValue placeholder="All Scopes" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Scopes</SelectItem>
              <SelectItem value="global">Global</SelectItem>
              <SelectItem value="department">Department</SelectItem>
              <SelectItem value="role">Role</SelectItem>
            </SelectContent>
          </Select>
          <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
            <DialogTrigger asChild>
              <Button className="w-full sm:w-auto bg-primary-600 hover:bg-primary-700 text-white font-semibold gap-2 shadow-e1 hover:shadow-e2 transition-shadow duration-150 h-9">
                <AppIcon name="plus" /> New Task
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Create New Task</DialogTitle>
                <DialogDescription className="sr-only">Create a new task in this project.</DialogDescription>
              </DialogHeader>
              <div className="space-y-4 py-4 max-h-[70dvh] overflow-y-auto px-1">
                <div className="space-y-1">
                  <label className="text-xs font-semibold text-neutral-500">Title *</label>
                  <Input
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    placeholder="Task title..."
                    className={`text-xs ${fieldErrors.title ? "border-red-500" : ""}`}
                  />
                  <FormError errors={fieldErrors.title} />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-semibold text-neutral-500">Description</label>
                  <textarea
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder="Provide context..."
                    className={`w-full p-2 text-xs rounded border bg-background resize-none ${fieldErrors.description ? "border-red-500" : "border-input"}`}
                    rows={3}
                  />
                  <FormError errors={fieldErrors.description} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-neutral-500">Priority</label>
                    <Select value={priority} onValueChange={setPriority}>
                      <SelectTrigger className="w-full h-9 text-xs">
                        <SelectValue placeholder="Priority" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="low">Low</SelectItem>
                        <SelectItem value="medium">Medium</SelectItem>
                        <SelectItem value="high">High</SelectItem>
                        <SelectItem value="urgent">Urgent</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1 flex flex-col">
                    <label className="text-xs font-semibold text-neutral-500">Due Date</label>
                    <DatePicker
                      value={dueDate ? new Date(dueDate) : undefined}
                      onChange={(date) => setDueDate(date ? format(date, "yyyy-MM-dd") : "")}
                      className="text-xs h-9 w-full"
                    />
                  </div>
                </div>
                
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-neutral-500">Project</label>
                    <Select value={projectId} onValueChange={setProjectId}>
                      <SelectTrigger className="w-full h-9 text-xs">
                        <SelectValue placeholder="No Project" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="none">No Project</SelectItem>
                        {availableProjects?.map((p: any) => (
                          <SelectItem key={p.id} value={String(p.id)}>{p.name}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  {canManageTasks ? (
                    <div className="space-y-1">
                      <label className="text-xs font-semibold text-neutral-500">Assignees</label>
                      <div className="border border-neutral-200 dark:border-neutral-800 rounded-md max-h-32 overflow-y-auto p-2 space-y-1 bg-white dark:bg-neutral-900">
                        {availableUsers?.map((u: any) => (
                          <label key={u.id} className="flex items-center gap-2 cursor-pointer p-1 hover:bg-neutral-50 dark:hover:bg-neutral-800 rounded">
                            <Checkbox 
                              checked={assigneeIds.includes(u.id)}
                              onCheckedChange={(checked) => {
                                if (checked) {
                                  setAssigneeIds([...assigneeIds, u.id]);
                                } else {
                                  setAssigneeIds(assigneeIds.filter(id => id !== u.id));
                                }
                              }}
                            />
                            <span className="text-xs">{u.name}</span>
                          </label>
                        ))}
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-1 flex flex-col justify-center bg-primary-50 dark:bg-primary-900/20 border border-primary-100 dark:border-primary-800 rounded-md p-3">
                      <span className="text-xs font-medium text-primary-700 dark:text-primary-300">
                        <AppIcon name="info" size="xs" className="mr-1 inline-block -mt-0.5" />
                        You will be assigned to this task automatically.
                      </span>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-4">
                  {canManageTasks && (
                    <div className="space-y-1">
                      <label className="text-xs font-semibold text-neutral-500">Scope</label>
                      <Select value={scope} onValueChange={setScope}>
                        <SelectTrigger className="w-full h-9 text-xs">
                          <SelectValue placeholder="Global" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="global">Global</SelectItem>
                          <SelectItem value="department">Department</SelectItem>
                          <SelectItem value="role">Role</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  )}
                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-neutral-500">QA Form</label>
                    <Select value={qaFormId} onValueChange={setQaFormId}>
                      <SelectTrigger className="w-full h-9 text-xs">
                        <SelectValue placeholder="None" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="none">None</SelectItem>
                        {(Array.isArray(qaFormsData?.data) ? qaFormsData.data : Array.isArray(qaFormsData) ? qaFormsData : []).map((q: any) => (
                          <SelectItem key={q.id} value={String(q.id)}>{q.title}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-neutral-500">Dependency (Blocked By)</label>
                    <Select value={blockedBy} onValueChange={setBlockedBy}>
                      <SelectTrigger className="w-full h-9 text-xs">
                        <SelectValue placeholder="None" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="none">None</SelectItem>
                        {tasks?.map((t: any) => (
                          <SelectItem key={t.id} value={String(t.id)}>{t.title}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                <div className="border-t border-neutral-100 dark:border-neutral-800 pt-4">
                  <div className="flex items-center gap-2">
                    <Checkbox id="recurring-checkbox" checked={isRecurring} onCheckedChange={(checked) => setIsRecurring(checked === true)} />
                    <label htmlFor="recurring-checkbox" className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
                      Recurring Task
                    </label>
                  </div>
                  {isRecurring && (
                    <div className="grid grid-cols-2 gap-4 mt-3">
                      <div className="space-y-1">
                        <label className="text-xs font-semibold text-neutral-500">Pattern</label>
                        <Select value={recurrencePattern} onValueChange={setRecurrencePattern}>
                          <SelectTrigger className="w-full h-9 text-xs">
                            <SelectValue placeholder="Daily" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="daily">Daily</SelectItem>
                            <SelectItem value="weekly">Weekly</SelectItem>
                            <SelectItem value="monthly">Monthly</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                      {recurrencePattern === "weekly" && (
                        <div className="space-y-1 col-span-2">
                          <label className="text-xs font-semibold text-neutral-500">Days of Week</label>
                          <div className="flex flex-wrap gap-2">
                            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day, idx) => (
                              <label key={day} className="flex items-center gap-1 text-xs">
                                <Checkbox 
                                  checked={recurrenceDays.includes(idx)} 
                                  onCheckedChange={(checked) => {
                                    if (checked) {
                                      setRecurrenceDays([...recurrenceDays, idx]);
                                    } else {
                                      setRecurrenceDays(recurrenceDays.filter(d => d !== idx));
                                    }
                                  }}
                                />
                                {day}
                              </label>
                            ))}
                          </div>
                        </div>
                      )}
                      {recurrencePattern === "monthly" && (
                        <div className="space-y-1 col-span-2">
                          <label className="text-xs font-semibold text-neutral-500">Day of Month</label>
                          <Select value={dayOfMonth.toString()} onValueChange={(val) => setDayOfMonth(parseInt(val))}>
                            <SelectTrigger className="w-full h-9 text-xs">
                              <SelectValue placeholder="Day" />
                            </SelectTrigger>
                            <SelectContent>
                              {Array.from({ length: 31 }, (_, i) => i + 1).map(day => (
                                <SelectItem key={day} value={day.toString()}>{day}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                <Button
                  onClick={() => {
                    setFieldErrors({});
                    createMutation.mutate();
                  }}
                  disabled={createMutation.isPending || !title}
                  className="w-full bg-primary-600 hover:bg-primary-700 text-white font-semibold mt-4"
                >
                  {createMutation.isPending ? <AppIcon name="loading" className=" animate-spin" /> : "Create Task"}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </div>
      
      {viewMode === "list" && (
        <div className="space-y-4">
          <FilterBar
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            searchPlaceholder="Search tasks..."
            filters={[
              {
                key: "assignee",
                label: "Assignee",
                type: "select",
                value: assigneeFilter,
                onChange: setAssigneeFilter,
                options: [
                  { label: "My Tasks", value: "me" },
                  ...(canManageTasks ? [{ label: "All Tasks", value: "all" }] : []),
                  ...(canManageTasks ? (usersData?.data?.map((u: any) => ({ label: u.name, value: String(u.id) })) || []) : [])
                ]
              },
              {
                key: "status",
                label: "Status",
                type: "select",
                value: statusFilter,
                onChange: setStatusFilter,
                options: [
                  { label: "To Do", value: "todo" },
                  { label: "In Progress", value: "in_progress" },
                  { label: "In Review", value: "review" },
                  { label: "Done", value: "done" },
                ]
              },
              {
                key: "scope",
                label: "Scope",
                type: "select",
                value: scopeFilter,
                onChange: setScopeFilter,
                options: [
                  { label: "All Scopes", value: "all" },
                  { label: "Global", value: "global" },
                  { label: "Department", value: "department" },
                  { label: "Role", value: "role" },
                ]
              },
              {
                key: "sort_by",
                label: "Sort By",
                type: "select",
                value: sortBy,
                onChange: setSortBy,
                options: [
                  { label: "Created (Newest)", value: "id" },
                  { label: "Due Date", value: "due_date" },
                  { label: "Priority", value: "priority" },
                  { label: "Status", value: "status" },
                ]
              },
              {
                key: "sort_order",
                label: "Order",
                type: "select",
                value: sortOrder,
                onChange: setSortOrder,
                options: [
                  { label: "Descending", value: "desc" },
                  { label: "Ascending", value: "asc" },
                ]
              }
            ]}
          />
          
          {selectedTaskIds.length > 0 && (
            <div className="flex items-center gap-2 p-3 bg-primary-50 dark:bg-primary-900/20 border border-primary-100 dark:border-primary-800 rounded-[var(--radius)]">
              <span className="text-sm font-medium text-primary-700 dark:text-primary-300">
                {selectedTaskIds.length} task{selectedTaskIds.length > 1 ? "s" : ""} selected
              </span>
              <div className="flex-1" />
              <Button size="sm" variant="outline" onClick={() => bulkStatusMutation.mutate({ taskIds: selectedTaskIds, status: "done" })}>
                <AppIcon name="success" className=" mr-2" /> Mark Done
              </Button>
              <Button size="sm" variant="destructive" onClick={() => setIsBulkDeleteOpen(true)}>
                <AppIcon name="trash" className=" mr-2" /> Delete
              </Button>
            </div>
          )}

          <DataTable
            columns={columns}
            data={filteredTasks}
            stickyHeader={true}
            stickyFirstCol={true}
            rowSelection={rowSelection}
            onRowSelectionChange={setRowSelection}
            page={parseInt(page)}
            perPage={perPage}
            totalPages={data?.last_page || data?.meta?.last_page || data?.data?.last_page || 1}
            onPageChange={(p) => setPage(p.toString())}
            onPerPageChange={setPerPage}
            density="compact"
            isLoading={isLoading}
            isError={isError}
            sorting={[{ id: sortBy, desc: sortOrder === "desc" }]}
            onSortingChange={(sorting) => {
              if (sorting.length > 0) {
                setSortBy(sorting[0].id);
                setSortOrder(sorting[0].desc ? "desc" : "asc");
              } else {
                setSortBy("id");
                setSortOrder("desc");
              }
            }}
          />
        </div>
      )}

      {viewMode === "kanban" && (
        <TaskKanbanBoard
          tasks={filteredTasks}
          onTaskMove={handleTaskMove}
          onTaskSelect={handleTaskSelect}
          onDeleteTask={handleDeleteTask}
          onTaskReorder={(tasks) => reorderTaskMutation.mutate(tasks)}
          isLoading={isLoading}
        />
      )}

      {viewMode === "gantt" && <TaskGantt tasks={filteredTasks} onTaskSelect={handleTaskSelect} />}

      {viewMode === "qa" && <QAFormBuilder />}

      <TaskDetailSheet
        task={filteredTasks.find((t: any) => t.id === selectedTask?.id) || selectedTask}
        open={sheetOpen}
        onOpenChange={setSheetOpen}
      />

      <ConfirmDialog
        open={isBulkDeleteOpen}
        onOpenChange={setIsBulkDeleteOpen}
        title={`Delete ${selectedTaskIds.length} Tasks`}
        description="Are you sure you want to delete the selected tasks? This action cannot be undone."
        confirmText="Delete All"
        onConfirm={() => bulkDeleteMutation.mutate(selectedTaskIds)}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { ThemeProvider as NextThemesProvider } from "next-themes";
import { QueryClient, MutationCache, QueryClientProvider } from "@tanstack/react-query";
import { ErrorBoundary, OfflineBanner, Toaster } from "@g4k/ui/components";
import { useAuthStore } from "@/lib/auth-store";

// Architectural Decision:
// We use a standard in-memory QueryClientProvider rather than PersistQueryClientProvider.
// This resolves the hydration race condition that forced skeletons to flash on cold load.
// Offline mutation queueing is handled separately by the OfflineEngine.

import { useUIStore } from "@/lib/ui-store";
import { queryKeys } from "@/lib/query-keys";
import { triggerInvalidation } from "@/lib/invalidation-map";

function StoreHydration() {
  React.useEffect(() => {
    useAuthStore.persist.rehydrate();
    useUIStore.persist.rehydrate();
  }, []);
  return null;
}

function DensityProvider() {
  const density = useAuthStore((state) => state.density);
  React.useEffect(() => {
    document.documentElement.setAttribute("data-density", density);
  }, [density]);
  return null;
}

import { VersionGuard } from "./version-guard";

export function Providers({ children }: { children: React.ReactNode }) {
  React.useEffect(() => {
    if (process.env.NODE_ENV !== 'production' && typeof window !== 'undefined') {
      import('@axe-core/react').then((axe) => {
        axe.default(React, require('react-dom'), 1000);
      }).catch(() => {});
    }
  }, []);

  const [queryClient] = React.useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: 60000, // 60 seconds
            gcTime: 1000 * 60 * 30, // 30 minutes
            refetchOnWindowFocus: false,
            retry: 1,
            retryDelay: (attempt) => Math.min(1000 * 2 ** attempt, 30000), // Exponential backoff
          },
          mutations: {
            retry: 0,
            retryDelay: (attempt) => Math.min(1000 * 2 ** attempt, 30000),
          },
        },
        mutationCache: new MutationCache({
          onError: (error: any, variables: any, context: any, mutation: any) => {
            if (mutation?.meta?.suppressToast) return;
            const status = error?.status;
            if (status >= 500) {
              import("sonner").then(({ toast }) => 
                toast.error("Server error. Please try again later.", {
                  action: {
                    label: "Retry",
                    onClick: () => mutation.execute(variables),
                  },
                })
              );
            }
          },
        }),
      })
  );

  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const handleSyncComplete = () => {
      triggerInvalidation(queryClient, "attendance.punch"); // Simplification: assume most offline sync is punches
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    };
    window.addEventListener("offline-sync-complete", handleSyncComplete);
    return () => window.removeEventListener("offline-sync-complete", handleSyncComplete);
  }, [queryClient]);

  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        const token = useAuthStore.getState().token;
        if (token) {
          document.cookie = `g4k_token=${token}; path=/; max-age=604800; SameSite=Lax`;
        }
      }
    };
    window.addEventListener("visibilitychange", handleVisibilityChange);
    return () => window.removeEventListener("visibilitychange", handleVisibilityChange);
  }, []);

  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const handleApiError = (event: Event) => {
      const customEvent = event as CustomEvent;
      import("sonner").then(({ toast }) => {
        toast.error(customEvent.detail || "Access Denied");
      });
    };
    window.addEventListener("api-error", handleApiError);
    return () => window.removeEventListener("api-error", handleApiError);
  }, []);

  return (
    <NextThemesProvider
      attribute="class"
      defaultTheme="light"
      enableSystem
      disableTransitionOnChange
    >
      <QueryClientProvider client={queryClient}>
        <StoreHydration />
        <DensityProvider />
        <VersionGuard />
        <ErrorBoundary>
          {children}
        </ErrorBoundary>
        <Toaster position="top-right" duration={4000} richColors closeButton expand={true} visibleToasts={3} />
        <OfflineBanner />
      </QueryClientProvider>
    </NextThemesProvider>
  );
}

"use client";

import { useEffect } from "react";

export function PWARegistry() {
  useEffect(() => {
    if (typeof window !== "undefined" && "serviceWorker" in navigator) {
      window.addEventListener("load", function () {
        navigator.serviceWorker.register("/sw.js").then(
          function (registration) {
            // Service Worker registration successful
          },
          function (err) {
            console.error("Service Worker registration failed: ", err);
          }
        );
      });
    }
  }, []);

  return null;
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { format, subDays } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { Button, Input, DataTable, Card, DatePicker, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@g4k/ui/components";
import { SavedReportViews } from "@/components/reports/saved-report-views";
import { toast } from "sonner";
import { STALE_TIME_DEPARTMENTS, queryKeys } from "@/lib/query-keys";

export function AdminReportsView() {
  const [reportType, setReportType] = useState<"attendance-summary" | "leave-summary">("attendance-summary");
  const [filters, setFilters] = useState({
    start: format(subDays(new Date(), 30), "yyyy-MM-dd"),
    end: format(new Date(), "yyyy-MM-dd"),
    dept: "all"
  });

  const { data: departments = [] } = useQuery({
    queryKey: queryKeys.departments,
    queryFn: () => apiFetch("/departments").then(res => res.data || []),
    staleTime: STALE_TIME_DEPARTMENTS,
  });

  const { data, isLoading, isError } = useQuery({
    queryKey: queryKeys.reports(reportType, filters),
    queryFn: () => {
      const params = new URLSearchParams();
      if (filters.start) params.append("start", filters.start);
      if (filters.end) params.append("end", filters.end);
      if (filters.dept && filters.dept !== "all") params.append("dept", filters.dept);
      
      return apiFetch(`/reports/${reportType}?${params.toString()}`);
    }
  });

  const handleExport = async (format: "csv" | "xlsx" | "pdf") => {
    try {
      const payload = {
        key: reportType,
        format,
        filters
      };
      await apiFetch("/reports/export", {
        method: "POST",
        body: JSON.stringify(payload)
      });
      toast.success(`Export queued. You will be notified when your ${format.toUpperCase()} is ready.`);
    } catch (e: any) {
      toast.error(e.message || "Failed to queue export.");
    }
  };

  const attendanceColumns = [
    { accessorKey: "name", header: "Employee" },
    { accessorKey: "department.name", header: "Department", cell: ({ row }: any) => row.original.department?.name || "—" },
    { accessorKey: "present_days", header: "Present" },
    { accessorKey: "late_days", header: "Late" },
    { accessorKey: "absent_days", header: "Absent" },
    { accessorKey: "leave_days", header: "Leave" },
    { 
      accessorKey: "total_hours", 
      header: "Total Hours",
      cell: ({ row }: any) => {
        const secs = row.original.total_hours || 0;
        return `${Math.floor(secs / 3600)}h ${Math.floor((secs % 3600) / 60)}m`;
      }
    }
  ];

  const leaveColumns = [
    { accessorKey: "name", header: "Employee" },
    { accessorKey: "department.name", header: "Department", cell: ({ row }: any) => row.original.department?.name || "—" },
    { accessorKey: "total_requests", header: "Total Requests" },
    { accessorKey: "approved_requests", header: "Approved" },
    { accessorKey: "pending_requests", header: "Pending" },
    { accessorKey: "rejected_requests", header: "Rejected" },
  ];

  return (
    <div className="flex-1 max-w-7xl mx-auto w-full space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-neutral-900 dark:text-white flex items-center gap-2">
            <AppIcon name="fileText" size="xl" className=" text-emerald-500" />
            Report Builder
          </h1>
          <p className="text-sm text-neutral-500">Generate, save, and export company reports.</p>
        </div>
        
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={() => handleExport("csv")}>
            <AppIcon name="download" className=" mr-2" /> CSV
          </Button>
          <Button variant="outline" onClick={() => handleExport("xlsx")}>
            <AppIcon name="download" className=" mr-2" /> Excel
          </Button>
          <Button variant="outline" onClick={() => handleExport("pdf")}>
            <AppIcon name="download" className=" mr-2" /> PDF
          </Button>
        </div>
      </div>

      <Card className="p-4 border-none shadow-e1 flex flex-col md:flex-row gap-4 items-end bg-surface dark:bg-neutral-900">
        <div className="flex-1 grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="space-y-1.5">
            <label htmlFor="report-type" className="text-xs font-bold text-neutral-500 uppercase">Report Type</label>
            <Select
              value={reportType}
              onValueChange={(v: "attendance-summary" | "leave-summary") => setReportType(v)}
            >
              <SelectTrigger id="report-type" className="w-full h-10 bg-surface">
                <SelectValue placeholder="Select report type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="attendance-summary">Attendance Summary</SelectItem>
                <SelectItem value="leave-summary">Leave Summary</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5 flex flex-col">
            <label className="text-xs font-bold text-neutral-500 uppercase flex items-center gap-1"><AppIcon name="calendar" size="xs" /> Start Date</label>
            <DatePicker
              value={filters.start ? new Date(filters.start) : undefined}
              onChange={(date) => setFilters({ ...filters, start: date ? format(date, "yyyy-MM-dd") : "" })}
              className="w-full"
            />
          </div>

          <div className="space-y-1.5 flex flex-col">
            <label className="text-xs font-bold text-neutral-500 uppercase flex items-center gap-1"><AppIcon name="calendar" size="xs" /> End Date</label>
            <DatePicker
              value={filters.end ? new Date(filters.end) : undefined}
              onChange={(date) => setFilters({ ...filters, end: date ? format(date, "yyyy-MM-dd") : "" })}
              className="w-full"
            />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="dept-filter" className="text-xs font-bold text-neutral-500 uppercase flex items-center gap-1"><AppIcon name="building" size="xs" /> Department</label>
            <Select
              value={filters.dept}
              onValueChange={(v) => setFilters({ ...filters, dept: v })}
            >
              <SelectTrigger id="dept-filter" className="w-full h-10 bg-surface">
                <SelectValue placeholder="All Departments" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Departments</SelectItem>
                {departments.map((d: any) => (
                  <SelectItem key={d.id} value={d.id.toString()}>{d.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="shrink-0">
          <SavedReportViews 
            module="reports"
            currentFilters={{ reportType, ...filters }}
            onApplyFilters={(f) => {
              if (f.reportType) setReportType(f.reportType);
              setFilters({ start: f.start || filters.start, end: f.end || filters.end, dept: f.dept || filters.dept });
            }}
          />
        </div>
      </Card>

      <Card className="border-none shadow-e1 overflow-hidden">
          <DataTable 
            columns={reportType === "attendance-summary" ? attendanceColumns : leaveColumns} 
            data={data?.data || []} 
            isLoading={isLoading}
            isError={isError}
            stickyHeader={true}
            stickyFirstCol={true}
          />
      </Card>
    </div>
  );
}

"use client";
import { useEffect } from "react";

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { format } from "date-fns";
import { apiFetch } from "@/lib/api-client";
import { useReverb } from "@/hooks/use-reverb";
import { useAuthStore } from "@/lib/auth-store";
import { Card, CardHeader, CardTitle, CardContent } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { queryKeys } from "@/lib/query-keys";
import { toast } from "sonner";

export function ExportHistory() {
  const queryClient = useQueryClient();
  const user = useAuthStore((s) => s.user);
  const { subscribe, leaveChannel } = useReverb();
  
  useEffect(() => {
    if (!user?.id) return;
    
    const channelName = `user.${user.id}`;
    const channel = subscribe(channelName, true);
    if (channel) {
      channel.listen(".export-completed", () => {
        queryClient.invalidateQueries({ queryKey: queryKeys.exportHistory });
      });
    }

    return () => {
      if (channel) {
        channel.stopListening(".export-completed");
      }
      leaveChannel(channelName);
    };
  }, [subscribe, leaveChannel, queryClient, user?.id]);

  const { data: exports = [], isLoading } = useQuery({
    queryKey: queryKeys.exportHistory,
    queryFn: () => apiFetch("/reports/exports").then(res => (Array.isArray(res?.data) ? res.data : (Array.isArray(res) ? res : []))),
    refetchInterval: (query) => {
      const currentData = query.state.data as any[] | undefined;
      const isProcessing = currentData?.some((e) => e.status === "processing");
      return isProcessing ? 5000 : false;
    }
  });

    const handleDownload = async (item: any) => {
      try {
        const url = `/reports/exports/${item.id}/download`;
        const blob = await apiFetch(url, { method: "GET" }) as Blob;
        
        const objectUrl = window.URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = objectUrl;
        a.download = `export-${item.report_key}-${item.id}.${item.format}`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        window.URL.revokeObjectURL(objectUrl);
      } catch (e) {
      toast.error("Failed to download export file. It may be expired or inaccessible.");
    }
  };

  return (
    <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader className="pb-3">
        <CardTitle className="text-base font-bold flex items-center gap-2">
          <AppIcon name="teamAttendance" className=" text-primary-600" />
          Export Job Queue
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        {isLoading ? (
          <div className="flex items-center justify-center py-6 text-neutral-400">
            <AppIcon name="loading" className=" animate-spin mr-2" /> Loading exports...
          </div>
        ) : exports.length === 0 ? (
          <p className="text-xs text-neutral-400 py-4 text-center">No export history found.</p>
        ) : (
          exports.slice(0, 3).map((item: any) => (
            <div
              key={item.id}
              className="p-3 rounded-xl bg-neutral-50 dark:bg-neutral-800/50 flex items-center justify-between gap-3 border border-neutral-100 dark:border-neutral-800"
            >
              <div>
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold uppercase text-neutral-900 dark:text-white">
                    {item.report_key} ({item.format})
                  </span>
                  {item.status === "completed" && (
                    <span className="flex items-center gap-1 text-[10px] text-emerald-600 font-semibold">
                      <AppIcon name="success" size="xs" /> Ready
                    </span>
                  )}
                  {item.status === "processing" && (
                    <span className="flex items-center gap-1 text-[10px] text-amber-600 font-semibold">
                      <AppIcon name="loading" size="xs" className=" animate-spin" /> Processing
                    </span>
                  )}
                  {item.status === "failed" && (
                    <span className="flex items-center gap-1 text-[10px] text-rose-600 font-semibold" title={item.error || "Job failed"}>
                      <AppIcon name="error" size="xs" /> Failed
                    </span>
                  )}
                </div>
                <div className="text-[10px] text-neutral-400 mt-0.5">
                  Requested {format(new Date(item.created_at), "MMM d, h:mm a")}
                </div>
              </div>

              {item.file_path && (
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleDownload(item)}
                  className="h-7 text-[11px] gap-1"
                >
                  <AppIcon name="download" size="xs" /> Download
                </Button>
              )}
            </div>
          ))
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { Card, CardHeader, CardTitle, CardContent, DataTable, FilterBar } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { queryKeys } from "@/lib/query-keys";

export function ReportBuilder() {
  const queryClient = useQueryClient();
  const [reportKey, setReportKey] = useState("tasks");
  const [search, setSearch] = useState("");

  const { data: reportData, isLoading, isError, refetch } = useQuery({
    queryKey: queryKeys.reportData(reportKey, search),
    queryFn: () => apiFetch(`/reports/data?key=${reportKey}&search=${encodeURIComponent(search)}`),
  });

  const exportMutation = useMutation({
    mutationFn: async (format: "xlsx" | "csv" | "pdf") => {
      return apiFetch("/reports/export", {
        method: "POST",
        body: JSON.stringify({ key: reportKey, format, filters: { search } }),
      });
    },
    onSuccess: (data: any) => {
      toast.success(`Export job started (${data.format.toUpperCase()}). You will be notified when ready.`);
      queryClient.invalidateQueries({ queryKey: queryKeys.exportHistory });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to initiate export.");
    },
  });

  const items = reportData?.data || [];
  const columns = items.length > 0 ? Object.keys(items[0]).map((key) => ({
    accessorKey: key,
    header: key.replace(/_/g, " ").toUpperCase(),
    cell: ({ row }: any) => {
      const val = row.original[key];
      return typeof val === "object" ? (val?.name || JSON.stringify(val)) : String(val ?? "N/A");
    }
  })) : [];

  return (
    <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader className="flex flex-row items-center justify-between pb-4">
        <CardTitle className="text-base font-bold">Custom Report Builder</CardTitle>
        <div className="flex items-center gap-2">
          <FilterBar
            searchQuery={search}
            onSearchChange={setSearch}
            filters={[
              {
                key: "reportKey",
                label: "Report Type",
                type: "select",
                options: [
                  { label: "Tasks & Deliverables", value: "tasks" },
                  { label: "Projects & Milestones", value: "projects" },
                  { label: "Employee Directory", value: "users" },
                  { label: "Productivity", value: "productivity" }
                ],
                value: reportKey,
                onChange: setReportKey
              }
            ]}
          />

          <Button
            size="sm"
            variant="outline"
            onClick={() => refetch()}
            className="h-8 text-xs gap-1.5"
          >
            <AppIcon name="refresh" size="sm" />
            Refresh
          </Button>

          <Button
            size="sm"
            onClick={() => exportMutation.mutate("xlsx")}
            disabled={exportMutation.isPending}
            className="h-8 text-xs bg-emerald-600 hover:bg-emerald-700 text-white gap-1.5"
          >
            {exportMutation.isPending && exportMutation.variables === "xlsx" ? <AppIcon name="loading" size="sm" className=" animate-spin" /> : <AppIcon name="spreadsheet" size="sm" />}
            Excel
          </Button>

          <Button
            size="sm"
            onClick={() => exportMutation.mutate("csv")}
            disabled={exportMutation.isPending}
            className="h-8 text-xs bg-neutral-600 hover:bg-neutral-700 text-white gap-1.5"
          >
            {exportMutation.isPending && exportMutation.variables === "csv" ? <AppIcon name="loading" size="sm" className=" animate-spin" /> : <AppIcon name="spreadsheet" size="sm" />}
            CSV
          </Button>

          <Button
            size="sm"
            onClick={() => exportMutation.mutate("pdf")}
            disabled={exportMutation.isPending}
            className="h-8 text-xs bg-rose-600 hover:bg-rose-700 text-white gap-1.5"
          >
            {exportMutation.isPending && exportMutation.variables === "pdf" ? <AppIcon name="loading" size="sm" className=" animate-spin" /> : <AppIcon name="fileText" size="sm" />}
            PDF
          </Button>
        </div>
      </CardHeader>

      <CardContent>
        {isError ? (
          <div className="flex flex-col items-center justify-center p-8 text-center space-y-2 bg-rose-50/50 dark:bg-rose-950/10 rounded-xl border border-rose-100 dark:border-rose-900/30">
            <AppIcon name="warning" size="xl" className="text-rose-400" />
            <p className="text-xs font-semibold text-rose-600">Failed to load report data</p>
            <Button variant="outline" size="sm" onClick={() => refetch()} className="h-7 text-xs">
              Retry
            </Button>
          </div>
        ) : (
          <div className="overflow-hidden rounded-xl border border-neutral-100 dark:border-neutral-800">
            <DataTable columns={columns} data={items} isLoading={isLoading} />
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { SheetDescription, Button, Input, Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger, Popover, PopoverContent, PopoverTrigger, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@g4k/ui/components";
import { toast } from "sonner";
import { useIsMobile } from "@g4k/ui/hooks";
import { formatDistanceToNow } from "date-fns";
import { queryKeys } from "@/lib/query-keys";

interface SavedReportViewsProps {
  module: string;
  currentFilters: any;
  onApplyFilters: (filters: any) => void;
}

export function SavedReportViews({ module, currentFilters, onApplyFilters }: SavedReportViewsProps) {
  const queryClient = useQueryClient();
  const [isOpen, setIsOpen] = useState(false);
  const [saveName, setSaveName] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const isMobile = useIsMobile();

  const { data: views = [], isLoading } = useQuery({
    queryKey: queryKeys.savedViews(module),
    queryFn: () => apiFetch(`/saved-views?module=${module}`).then(res => Array.isArray(res) ? res : (res.data || [])),
  });

  const saveMutation = useMutation({
    mutationFn: (name: string) => apiFetch(`/saved-views`, {
      method: "POST",
      body: JSON.stringify({ module, name, filters: currentFilters })
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.savedViews(module) });
      toast.success("View saved successfully");
      setSaveName("");
      setIsSaving(false);
    }
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => apiFetch(`/saved-views/${id}`, { method: "DELETE" }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.savedViews(module) });
      toast.success("View deleted");
    }
  });

  const handleSave = () => {
    if (!saveName.trim()) return;
    saveMutation.mutate(saveName.trim());
  };

  return (
    <div className="relative">
      <div className="flex items-center gap-2">
        {/* Simple Select implementation for saved views if DropdownMenu is not fully available */}
        <Select
          value=""
          onValueChange={(val) => {
            if (!val) return;
            const view = views.find((v: any) => v.id.toString() === val);
            if (view && view.filters) {
              onApplyFilters(view.filters);
              toast.info(`Applied view: ${view.name}`);
            }
          }}
        >
          <SelectTrigger className="w-full sm:min-w-[200px] h-10 bg-surface">
            <SelectValue placeholder="Load saved view..." />
          </SelectTrigger>
          <SelectContent>
            {views.map((v: any) => (
              <SelectItem key={v.id} value={v.id.toString()}>{v.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        {isMobile ? (
          <Sheet open={isSaving} onOpenChange={setIsSaving}>
            <SheetTrigger asChild>
              <Button variant="outline" className="h-10 shrink-0 whitespace-nowrap">
                <AppIcon name="save" className=" mr-2" />
                Save Current
              </Button>
            </SheetTrigger>
            <SheetContent side="bottom" className="rounded-t-2xl">
              <SheetHeader className="mb-4">
                <SheetTitle>Save Report View</SheetTitle>
              </SheetHeader>
              <div className="flex gap-2">
                <Input 
                  value={saveName}
                  onChange={(e) => setSaveName(e.target.value)}
                  placeholder="Name this view..."
                  autoFocus
                  className="flex-1"
                />
                <Button onClick={handleSave} disabled={saveMutation.isPending || !saveName.trim()}>
                  {saveMutation.isPending ? <AppIcon name="loading" className=" animate-spin" /> : "Save"}
                </Button>
              </div>
            </SheetContent>
          </Sheet>
        ) : (
          <Popover open={isSaving} onOpenChange={setIsSaving}>
            <PopoverTrigger asChild>
              <Button variant="outline" className="h-10 shrink-0 whitespace-nowrap">
                <AppIcon name="save" className=" mr-2" />
                Save Current
              </Button>
            </PopoverTrigger>
            <PopoverContent align="end" className="w-[300px] p-3">
              <div className="flex gap-2">
                <Input 
                  value={saveName}
                  onChange={(e) => setSaveName(e.target.value)}
                  placeholder="Name this view..."
                  autoFocus
                  className="flex-1"
                />
                <Button onClick={handleSave} disabled={saveMutation.isPending || !saveName.trim()}>
                  {saveMutation.isPending ? <AppIcon name="loading" className=" animate-spin" /> : "Save"}
                </Button>
              </div>
            </PopoverContent>
          </Popover>
        )}
      </div>
    </div>
  );
}

"use client";
import Link from "next/link";

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { toast } from "sonner";
import { Card, CardContent } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { DataTable } from "@g4k/ui/components";
import { FilterBar, DatePicker } from "@g4k/ui/components";
import { getAuthToken } from "@/lib/auth-store";
import { safeFormat } from "@/lib/format";

import { useUrlState } from "@/hooks/use-url-state";
import { queryKeys } from "@/lib/query-keys";

export function AuditLogTable() {
  const queryClient = useQueryClient();
  const [action, setAction] = useUrlState("action", "");
  const [userId, setUserId] = useUrlState("user_id", "");
  const [startDate, setStartDate] = useUrlState("start_date", "");
  const [endDate, setEndDate] = useUrlState("end_date", "");
  const filters = { action, user_id: userId, start_date: startDate, end_date: endDate };
  const [isExporting, setIsExporting] = useState(false);
  
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(20);

  const { data: usersResponse } = useQuery({
    queryKey: queryKeys.usersList,
    queryFn: () => apiFetch("/users?per_page=100"),
  });
  const users = usersResponse?.data || [];
  const userOptions = [{ label: "All Users", value: "" }, { label: "System", value: "system" }].concat(
    users.map((u: any) => ({ label: u.name, value: String(u.id) }))
  );
  
  const { data: logsData, isLoading, isError } = useQuery({
    queryKey: [...queryKeys.auditLogs(filters), page, perPage],
    queryFn: () => {
      const params = new URLSearchParams();
      if (filters.action) params.append("action", filters.action);
      if (filters.user_id) params.append("user_id", filters.user_id);
      if (filters.start_date) params.append("start_date", filters.start_date);
      if (filters.end_date) params.append("end_date", filters.end_date);
      params.append("page", page.toString());
      params.append("per_page", perPage.toString());
      return apiFetch(`/audit-logs?${params.toString()}`);
    }
  });

  const logs = logsData?.data?.data || [];
  const totalPages = logsData?.data?.last_page || 1;

  const handleExport = async () => {
    try {
      setIsExporting(true);
      const params = new URLSearchParams();
      if (filters.action) params.append("action", filters.action);
      if (filters.user_id) params.append("user_id", filters.user_id);
      if (filters.start_date) params.append("start_date", filters.start_date);
      if (filters.end_date) params.append("end_date", filters.end_date);
      
      await apiFetch(`/audit-logs/export?${params.toString()}`, { method: "POST" });
      toast.success("Export queued. You will be notified when it's ready.");
      queryClient.invalidateQueries({ queryKey: queryKeys.exportHistory });
    } catch (err: any) {
      toast.error(err.message || "Failed to start export.");
    } finally {
      setIsExporting(false);
    }
  };

  const columns = [
    {
      accessorKey: "at",
      header: "Timestamp",
      cell: ({ row }: any) => format(new Date(row.original.at), "MMM d, yyyy HH:mm:ss")
    },
    {
      accessorKey: "user.name",
      header: "User",
      cell: ({ row }: any) => row.original.user ? row.original.user.name : "System"
    },
    {
      accessorKey: "action",
      header: "Action",
      cell: ({ row }: any) => (
        <span className="bg-neutral-100 dark:bg-neutral-800 px-2 py-1 rounded text-[10px] font-mono">
          {row.original.action}
        </span>
      )
    },
    {
      accessorKey: "subject_type",
      cell: ({ row }: any) => {
        if (!row.original.subject_type) return "-";
        const t = row.original.subject_type.split('\\').pop();
        const id = row.original.subject_id;
        
        let href = "";
        if (t === "User") href = `/dashboard/users`; // no user detail page yet, just list
        else if (t === "Project") href = `/dashboard/projects/${id}`;
        else if (t === "Department") href = `/dashboard/settings?tab=departments`;
        else if (t === "WorkSchedule") href = `/dashboard/settings?tab=schedules`;
        else if (t === "QaForm") href = `/dashboard/settings?tab=qa`;
        
        const label = `${t} #${id}`;
        if (href) {
          return <Link href={href} className="text-primary-600 hover:underline">{label}</Link>;
        }
        return label;
      }
    },
    {
      accessorKey: "ip",
      header: "IP Address",
      cell: ({ row }: any) => (
        <span className="text-neutral-400 font-mono text-[10px]">
          {row.original.ip || "127.0.0.1"}
        </span>
      )
    }
  ];

  return (
    <Card className=" border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <div className="p-4 border-b border-neutral-100 dark:border-neutral-800 flex justify-between gap-4 bg-neutral-50/50 dark:bg-neutral-800/30">
        <div className="flex-1 max-w-xl">
          <FilterBar
            searchQuery={filters.action}
            onSearchChange={(val) => setAction(val)}
            searchPlaceholder="Filter by action (e.g. login, update)..."
            filters={[
              {
                key: "user_id",
                label: "User",
                type: "select",
                options: userOptions,
                value: filters.user_id,
                onChange: (v) => setUserId(v)
              }
            ]}
          />
        </div>
        <div className="flex items-center gap-2 text-sm text-neutral-500">
          <DatePicker
            value={filters.start_date ? new Date(filters.start_date) : undefined}
            onChange={(date) => setStartDate(date ? format(date, "yyyy-MM-dd") : "")}
            className="h-9 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-card dark:bg-neutral-900"
            placeholder="Start date"
          />
          <span>to</span>
          <DatePicker
            value={filters.end_date ? new Date(filters.end_date) : undefined}
            onChange={(date) => setEndDate(date ? format(date, "yyyy-MM-dd") : "")}
            className="h-9 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-card dark:bg-neutral-900"
            placeholder="End date"
          />
        </div>
        <Button variant="outline" size="sm" onClick={handleExport} disabled={isExporting} className="h-9 whitespace-nowrap">
          <AppIcon name="download" className=" mr-2" />
          {isExporting ? "Queuing..." : "Export CSV"}
        </Button>
      </div>

      <CardContent className="p-0 overflow-x-auto w-full">
          <DataTable
            columns={columns}
            data={logs}
            isLoading={isLoading}
            isError={isError}
            stickyHeader={true}
            stickyFirstCol={true}
            page={page}
            perPage={perPage}
            totalPages={totalPages}
            onPageChange={setPage}
            onPerPageChange={setPerPage}
          />
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { Button } from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";
import { Card, CardHeader, CardTitle, CardContent } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { queryKeys } from "@/lib/query-keys";

export function AutoNumberingConfig() {
  const queryClient = useQueryClient();

  const { data: records = [], isLoading } = useQuery({
    queryKey: queryKeys.autoNumberings,
    queryFn: async () => {
      const res = await apiFetch("/auto-numberings");
      return Array.isArray(res) ? res : res.data || [];
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: number; data: any }) =>
      apiFetch(`/auto-numberings/${id}`, { method: "PUT", body: JSON.stringify(data) }),
    onSuccess: () => {
      toast.success("Settings saved");
      queryClient.invalidateQueries({ queryKey: queryKeys.autoNumberings });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to update format");
    },
  });

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-20 w-full rounded-xl" />
        <Skeleton className="h-20 w-full rounded-xl" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {records.map((record: any) => (
        <NumberingRow key={record.id} record={record} onSave={(data) => updateMutation.mutate({ id: record.id, data })} isPending={updateMutation.isPending} />
      ))}
    </div>
  );
}

function NumberingRow({ record, onSave, isPending }: { record: any; onSave: (data: any) => void; isPending: boolean }) {
  const [formData, setFormData] = useState({
    prefix: record.prefix || "",
    format: record.format || "",
    start_number: record.current_number ? record.current_number + 1 : record.start_number,
  });

  // Calculate preview
  let preview = formData.format;
  preview = preview.replace('{PREFIX}', formData.prefix);
  if (preview.match(/\{(0+)\}/)) {
    const match = preview.match(/\{(0+)\}/);
    if (match) {
      const paddingLength = match[1].length;
      const paddedNumber = String(formData.start_number).padStart(paddingLength, '0');
      preview = preview.replace(match[0], paddedNumber);
    }
  } else {
    preview = preview.replace('{NUMBER}', String(formData.start_number));
  }

  const handleSave = () => {
    onSave({
      prefix: formData.prefix,
      format: formData.format,
      start_number: formData.start_number,
    });
  };

  return (
    <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader className="pb-2">
        <CardTitle className="text-base capitalize">{record.entity_type} ID Format</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
          <div>
            <label className="block text-xs font-medium mb-1">Prefix</label>
            <Input 
              value={formData.prefix} 
              onChange={(e) => setFormData({ ...formData, prefix: e.target.value })} 
              className="h-9" 
            />
          </div>
          <div>
            <label className="block text-xs font-medium mb-1">Format</label>
            <Input 
              value={formData.format} 
              onChange={(e) => setFormData({ ...formData, format: e.target.value })} 
              className="h-9 font-mono text-sm" 
              placeholder="{PREFIX}{000}" 
            />
          </div>
          <div>
            <label className="block text-xs font-medium mb-1">Next Start Number</label>
            <Input 
              type="number"
              value={formData.start_number} 
              onChange={(e) => setFormData({ ...formData, start_number: parseInt(e.target.value) || 1 })} 
              className="h-9" 
              min={record.current_number ? record.current_number + 1 : 1}
            />
          </div>
          <div className="flex items-center gap-3 justify-end h-9">
            <div className="text-xs text-neutral-500">
              Preview: <strong className="text-neutral-900 dark:text-white font-mono">{preview}</strong>
            </div>
            <Button onClick={handleSave} disabled={isPending} size="sm" className="gap-2">
              <AppIcon name="save" /> Save
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "@/lib/api-client";
import { Card, CardHeader, CardTitle, CardContent, Button } from "@g4k/ui/components";
import { toast } from "sonner";
import { useState } from "react";
import { AppIcon } from "@g4k/ui/components";

export function DemoDataConfig() {
  const queryClient = useQueryClient();
  const [confirmText, setConfirmText] = useState("");

  const { data, isLoading } = useQuery({
    queryKey: ["demo-data-status"],
    queryFn: async () => {
      const res = await apiFetch("/demo-data");
      return res.data;
    }
  });

  const purgeMutation = useMutation({
    mutationFn: async () => {
      await apiFetch("/demo-data/purge", { method: "DELETE" });
    },
    onSuccess: () => {
      toast.success("Demo purge job dispatched. Data will be removed shortly.");
      setConfirmText("");
      setTimeout(() => queryClient.invalidateQueries({ queryKey: ["demo-data-status"] }), 3000);
    },
    onError: (e: any) => {
      toast.error(e.message || "Failed to purge demo data");
    }
  });

  const seedMutation = useMutation({
    mutationFn: async () => {
      await apiFetch("/demo-data/seed", { method: "POST" });
    },
    onSuccess: () => {
      toast.success("Demo seed job dispatched. Data will be seeded shortly.");
      setTimeout(() => queryClient.invalidateQueries({ queryKey: ["demo-data-status"] }), 3000);
    },
    onError: (e: any) => {
      toast.error(e.message || "Failed to seed demo data");
    }
  });

  if (isLoading) {
    return <div className="p-4 text-sm text-neutral-500 animate-pulse">Loading demo data status...</div>;
  }

  const counts = data?.counts || {};
  const hasDemoData = Object.values(counts).some((count: any) => count > 0);

  return (
    <div className="space-y-6">
      <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1">
        <CardHeader>
          <CardTitle className="text-base text-red-600 dark:text-red-400 flex items-center gap-2">
            <AppIcon name="warning" className="w-5 h-5" />
            Demo Data Management
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-900/30 p-4 rounded-[var(--radius)]">
            <h3 className="text-sm font-semibold text-red-800 dark:text-red-300">Danger Zone</h3>
            <p className="text-xs text-red-600 dark:text-red-400 mt-1">
              This will permanently remove ALL demo data — users, departments, projects, tasks, attendance records, leave requests, chats, notifications, settings, and uploaded files. The app will be completely clean for fresh production setup.
            </p>
          </div>

          <div>
            <h4 className="text-sm font-medium mb-3">Current Demo Data Status: {data?.version ? `Seeded (${data.version})` : 'Not Seeded'}</h4>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
              {Object.entries(counts).map(([table, count]: [string, any]) => (
                <div key={table} className="border border-neutral-200 dark:border-neutral-800 rounded-[var(--radius)] p-3">
                  <div className="text-xs text-neutral-500 capitalize">{table.replace(/_/g, ' ')}</div>
                  <div className="text-lg font-semibold text-neutral-900 dark:text-white">{count}</div>
                </div>
              ))}
            </div>
          </div>

          <div className="pt-4 border-t border-neutral-200 dark:border-neutral-800 space-y-4">
            {hasDemoData ? (
              <div className="space-y-3 max-w-sm">
                <label className="text-xs font-medium text-neutral-700 dark:text-neutral-300">
                  Type <span className="font-mono bg-neutral-100 dark:bg-neutral-800 px-1 py-0.5 rounded text-red-600">REMOVE DEMO DATA</span> to confirm:
                </label>
                <input
                  type="text"
                  value={confirmText}
                  onChange={(e) => setConfirmText(e.target.value)}
                  className="w-full text-sm rounded-[var(--radius)] border border-neutral-200 dark:border-neutral-700 bg-transparent px-3 py-2"
                  placeholder="REMOVE DEMO DATA"
                />
                <Button 
                  variant="destructive" 
                  disabled={confirmText !== "REMOVE DEMO DATA" || purgeMutation.isPending}
                  onClick={() => purgeMutation.mutate()}
                  className="w-full"
                >
                  {purgeMutation.isPending ? "Purging..." : "Remove Demo Data"}
                </Button>
              </div>
            ) : (
              <div>
                <Button 
                  variant="outline"
                  onClick={() => seedMutation.mutate()}
                  disabled={seedMutation.isPending}
                >
                  {seedMutation.isPending ? "Seeding..." : "Re-seed Demo Data"}
                </Button>
                <p className="text-xs text-neutral-500 mt-2">
                  This will re-run the demo seeder and populate the database with dummy data for training and support purposes.
                </p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@g4k/ui/components";
import { Input, PasswordInput } from "@g4k/ui/components";
import { DisabledWhileSubmitting, ValidationSummary } from "@g4k/ui/components/state-helpers";

const smtpSchema = z.object({
  from_address: z.string().email("Invalid email address").optional().or(z.literal('')),
  from_name: z.string().optional(),
  host: z.string().optional(),
  port: z.coerce.number().min(1).max(65535).optional(),
  encryption: z.enum(["tls", "ssl", "none"]),
  username: z.string().optional(),
  password: z.string().optional(),
  timeout: z.coerce.number().min(1).optional(),
});

type SmtpFormValues = z.infer<typeof smtpSchema>;

export function MailSmtpConfig() {
  const queryClient = useQueryClient();
  const [isTesting, setIsTesting] = useState(false);

  const { data: settingsData, isLoading } = useQuery({
    queryKey: queryKeys.settings,
    queryFn: () => apiFetch("/settings/grouped"),
  });

  const form = useForm<SmtpFormValues>({
    resolver: zodResolver(smtpSchema) as any,
    defaultValues: {
      from_address: "",
      from_name: "",
      host: "",
      port: 587,
      encryption: "tls",
      username: "",
      password: "",
      timeout: 30,
    },
  });

  useEffect(() => {
    if (settingsData && settingsData.mail) {
      const mailSettings = settingsData.mail.reduce((acc: any, curr: any) => {
        acc[curr.key] = curr.value;
        return acc;
      }, {});

      form.reset({
        from_address: mailSettings.from_address || "",
        from_name: mailSettings.from_name || "",
        host: mailSettings.host || "",
        port: mailSettings.port || 587,
        encryption: mailSettings.encryption || "tls",
        username: mailSettings.username || "",
        password: mailSettings.password || "",
        timeout: mailSettings.timeout || 30,
      });
    }
  }, [settingsData, form]);

  const updateMutation = useMutation({
    mutationFn: (data: SmtpFormValues) => {
      const settingsPayload = Object.entries(data).map(([key, value]) => ({
        category: "mail",
        key,
        value: value?.toString() || ""
      }));
      return apiFetch("/settings/bulk", {
        method: "POST",
        body: JSON.stringify({ settings: settingsPayload }),
      });
    },
    onSuccess: () => {
      toast.success("SMTP settings saved.");
      queryClient.invalidateQueries({ queryKey: queryKeys.settings });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to save settings");
    }
  });

  const handleTestEmail = async () => {
    setIsTesting(true);
    try {
      await apiFetch("/settings/mail/test", { method: "POST" });
      toast.success("Test email sent successfully.");
    } catch (err: any) {
      toast.error(err.message || "Failed to send test email.");
    } finally {
      setIsTesting(false);
    }
  };

  if (isLoading) {
    return <Skeleton className="w-full h-96 rounded-xl" />;
  }

  return (
    <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle className="text-base">Mail / SMTP Settings</CardTitle>
          <CardDescription className="text-xs mt-1">Configure email delivery for the system.</CardDescription>
        </div>
        <Button type="button" variant="outline" size="sm" onClick={handleTestEmail} disabled={isTesting}>
          {isTesting ? <AppIcon name="loading" className=" mr-2 animate-spin" /> : <AppIcon name="send" className=" mr-2" />}
          Send Test Email
        </Button>
      </CardHeader>
      <CardContent>
        <form onSubmit={form.handleSubmit((d) => updateMutation.mutate(d))} className="space-y-4 max-w-xl">
          <DisabledWhileSubmitting isSubmitting={updateMutation.isPending}>
          <div className="space-y-4">
          <ValidationSummary errors={form.formState.errors} />
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-xs font-medium mb-1 block">From Name</label>
              <Input type="text" {...form.register("from_name")} className="h-9 text-xs" />
              {form.formState.errors.from_name && <p className="text-[10px] text-red-500 mt-1">{form.formState.errors.from_name.message}</p>}
            </div>
            <div>
              <label className="text-xs font-medium mb-1 block">From Address</label>
              <Input type="email" {...form.register("from_address")} className="h-9 text-xs" />
