"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent, Button, Switch, Skeleton } from "@g4k/ui/components";

export function NotificationsConfig() {
  const queryClient = useQueryClient();
  const [formData, setFormData] = useState<Record<string, string[]>>({});

  const { data: settings = [], isLoading, isError, refetch } = useQuery({
    queryKey: [...queryKeys.settings, "notifications"],
    queryFn: () => apiFetch("/settings/grouped").then((res: any) => res["notifications"] || []),
  });

  useEffect(() => {
    if (settings) {
      const initial: Record<string, string[]> = {};
      settings.forEach((s: any) => {
        try {
          initial[s.key] = JSON.parse(s.value);
        } catch (e) {
          initial[s.key] = [];
        }
      });
      setFormData(initial);
    }
  }, [settings]);

  const updateMutation = useMutation({
    mutationFn: (settings: any[]) => apiFetch("/settings/bulk", {
      method: "POST",
      body: JSON.stringify({ settings }),
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [...queryKeys.settings, "notifications"] });
      toast.success("Notification preferences updated");
    },
    onError: (e: any) => toast.error(e.message || "Update failed"),
  });

  const handleSave = () => {
    const settingsArr = Object.entries(formData).map(([key, value]) => ({
      category: "notifications",
      key,
      value: JSON.stringify(value),
    }));
    updateMutation.mutate(settingsArr);
  };

  const toggleChannel = (key: string, channel: string, checked: boolean) => {
    setFormData(prev => {
      const currentChannels = prev[key] || [];
      let newChannels;
      if (checked) {
        newChannels = [...currentChannels, channel];
      } else {
        newChannels = currentChannels.filter((c: string) => c !== channel);
      }
      return { ...prev, [key]: newChannels };
    });
  };

  if (isLoading) return <Skeleton className="w-full h-80 rounded-xl" />;

  if (isError) {
    return (
      <Card className="p-6 text-center space-y-3 border border-rose-200 bg-rose-50/50">
        <AppIcon name="warning" size="xl" className="mx-auto text-rose-500" />
        <p className="text-xs font-semibold text-rose-700">Failed to load notification preferences.</p>
        <Button variant="outline" size="sm" onClick={() => refetch()} className="h-7 text-xs">
          Retry
        </Button>
      </Card>
    );
  }

  return (
    <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader>
        <CardTitle className="text-base">System Notification Preferences</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-6 max-w-xl">
          <p className="text-sm text-neutral-500">Configure the default delivery channels for system-wide notifications.</p>
          
          <div className="space-y-4">
            <NotificationRow 
              title="Leave Requests" 
              description="Notifications for leave approvals and rejections"
              settingKey="leave_request.channels"
              channels={formData["leave_request.channels"] || []}
              onToggle={toggleChannel}
            />
            <NotificationRow 
              title="Attendance Reminders" 
              description="Notifications to clock in/out"
              settingKey="attendance_reminder.channels"
              channels={formData["attendance_reminder.channels"] || []}
              onToggle={toggleChannel}
            />
            <NotificationRow 
              title="Weekly Summary" 
              description="Weekly reports for attendance and tasks"
              settingKey="weekly_summary.channels"
              channels={formData["weekly_summary.channels"] || []}
              onToggle={toggleChannel}
            />
          </div>

          <Button onClick={handleSave} disabled={updateMutation.isPending}>
            {updateMutation.isPending ? <AppIcon name="loading" className=" mr-2 animate-spin" /> : <AppIcon name="save" className=" mr-2" />}
            {updateMutation.isPending ? "Saving..." : "Save Preferences"}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

function NotificationRow({ title, description, settingKey, channels, onToggle }: any) {
  return (
    <div className="flex items-center justify-between p-4 border rounded-[var(--radius)] border-neutral-200 dark:border-neutral-800">
      <div>
        <h4 className="text-sm font-semibold text-neutral-900 dark:text-white">{title}</h4>
        <p className="text-xs text-neutral-500 mt-1">{description}</p>
      </div>
      <div className="flex items-center gap-6">
        <div className="flex flex-col items-center gap-2">
          <label className="text-xs font-medium">In-App</label>
          <Switch 
            checked={channels.includes('in_app')}
            onCheckedChange={(c) => onToggle(settingKey, 'in_app', c)}
          />
        </div>
        <div className="flex flex-col items-center gap-2">
          <label className="text-xs font-medium">Email</label>
          <Switch 
            checked={channels.includes('email')}
            onCheckedChange={(c) => onToggle(settingKey, 'email', c)}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardHeader, CardTitle, CardContent } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { AppIcon, IconName } from "@g4k/ui/components";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { queryKeys } from "@/lib/query-keys";

const passwordSchema = z.object({
  min_length: z.coerce.number().min(8, "Minimum 8 characters required").max(32, "Maximum 32 characters allowed"),
  require_mixed: z.boolean(),
  require_number: z.boolean(),
  require_symbol: z.boolean(),
  force_password_change: z.boolean(),
});

const sessionSchema = z.object({
  access_token_ttl: z.coerce.number().min(5, "Minimum 5 mins").max(1440, "Maximum 1440 mins"),
  refresh_token_ttl: z.coerce.number().min(1, "Minimum 1 day").max(90, "Maximum 90 days"),
  max_devices: z.coerce.number().min(1, "Minimum 1 device").max(10, "Maximum 10 devices"),
});

type PasswordFormValues = z.infer<typeof passwordSchema>;
type SessionFormValues = z.infer<typeof sessionSchema>;

export function PoliciesConfig() {
  const queryClient = useQueryClient();

  const { data: settingsGrouped, isLoading } = useQuery({
    queryKey: queryKeys.settings,
    queryFn: () => apiFetch("/settings/grouped"),
  });

  const passwordForm = useForm<PasswordFormValues>({
    resolver: zodResolver(passwordSchema) as any,
    defaultValues: {
      min_length: 8,
      require_mixed: true,
      require_number: true,
      require_symbol: true,
      force_password_change: false,
    },
    mode: "onTouched",
    delayError: 400,
  });

  const sessionForm = useForm<SessionFormValues>({
    resolver: zodResolver(sessionSchema) as any,
    defaultValues: {
      access_token_ttl: 15,
      refresh_token_ttl: 7,
      max_devices: 3,
    },
    mode: "onTouched",
    delayError: 400,
  });

  useEffect(() => {
    if (settingsGrouped?.security) {
      const securityMap: any = {};
      settingsGrouped.security.forEach((s: any) => {
        securityMap[s.key] = s.value;
      });
      passwordForm.reset({
        min_length: parseInt(securityMap["password.min_length"]) || 8,
        require_mixed: securityMap["password.require_mixed"] === "true",
        require_number: securityMap["password.require_number"] === "true",
        require_symbol: securityMap["password.require_symbol"] === "true",
        force_password_change: securityMap["force_password_change"] === "true" || securityMap["force_password_change"] === true,
      });
      sessionForm.reset({
        access_token_ttl: parseInt(securityMap["session.access_token_ttl"]) || 15,
        refresh_token_ttl: parseInt(securityMap["session.refresh_token_ttl"]) || 7,
        max_devices: parseInt(securityMap["session.max_devices"]) || 3,
      });
    }
  }, [settingsGrouped, passwordForm, sessionForm]);

  const updateMutation = useMutation({
    mutationFn: (updates: any[]) =>
      apiFetch("/settings/bulk", {
        method: "POST",
        body: JSON.stringify({ settings: updates }),
      }),
    onSuccess: () => {
      toast.success("Policy updated successfully");
      queryClient.invalidateQueries({ queryKey: queryKeys.settings });
    },
  });

  const handlePasswordSubmit = (data: any) => {
    const updates = [
      { category: "security", key: "password.min_length", value: data.min_length.toString() },
      { category: "security", key: "password.require_mixed", value: data.require_mixed.toString() },
      { category: "security", key: "password.require_number", value: data.require_number.toString() },
      { category: "security", key: "password.require_symbol", value: data.require_symbol.toString() },
      { category: "security", key: "force_password_change", value: data.force_password_change.toString() },
    ];
    updateMutation.mutate(updates);
  };

  const handleSessionSubmit = (data: any) => {
    const updates = [
      { category: "security", key: "session.access_token_ttl", value: data.access_token_ttl.toString() },
      { category: "security", key: "session.refresh_token_ttl", value: data.refresh_token_ttl.toString() },
      { category: "security", key: "session.max_devices", value: data.max_devices.toString() },
    ];
    updateMutation.mutate(updates);
  };

  if (isLoading) {
    return <Skeleton className="h-64 w-full rounded-xl" />;
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
        <CardHeader>
          <CardTitle className="text-base">Password Policy</CardTitle>
        </CardHeader>
      <CardContent>
        <form onSubmit={passwordForm.handleSubmit(handlePasswordSubmit)} className="space-y-4 max-w-md">
          <div>
            <label className="text-xs font-medium">Minimum Length <span className="text-red-500">*</span></label>
            <input
              type="number"
              {...passwordForm.register("min_length")}
              className={`w-full text-sm rounded-[var(--radius)] border ${passwordForm.formState.errors.min_length ? 'border-red-500' : 'border-neutral-200 dark:border-neutral-700'} bg-transparent px-3 py-2 mt-1`}
            />
            {passwordForm.formState.errors.min_length && <p className="text-[10px] text-red-500 mt-1">{passwordForm.formState.errors.min_length.message}</p>}
          </div>
          
          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="require_mixed"
              {...passwordForm.register("require_mixed")}
            />
            <label htmlFor="require_mixed" className="text-sm">Require uppercase and lowercase letters</label>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="require_number"
              {...passwordForm.register("require_number")}
            />
            <label htmlFor="require_number" className="text-sm">Require at least one number</label>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="require_symbol"
              {...passwordForm.register("require_symbol")}
            />
            <label htmlFor="require_symbol" className="text-sm">Require at least one symbol</label>
          </div>

          <div className="flex items-center justify-between p-3 rounded-[var(--radius)] border border-neutral-200 dark:border-neutral-800 bg-neutral-50/50 dark:bg-neutral-900/20 mt-4">
            <div>
              <h4 className="text-sm font-medium">Force password change</h4>
              <p className="text-xs text-neutral-500">Require users to change password on first login or after admin reset</p>
            </div>
            <input
              type="checkbox"
              {...passwordForm.register("force_password_change")}
              className="h-4 w-4 rounded border-neutral-300 text-primary-600 focus:ring-primary-500"
            />
          </div>

          <Button type="submit" disabled={updateMutation.isPending || !passwordForm.formState.isValid} className="mt-4">
            {updateMutation.isPending ? <AppIcon name="loading" className=" mr-2 animate-spin" /> : <AppIcon name="save" className=" mr-2" />}
            {updateMutation.isPending ? "Saving..." : "Save Policy"}
          </Button>
        </form>
      </CardContent>
      </Card>

      <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
        <CardHeader>
          <CardTitle className="text-base">Session & Device Rules</CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={sessionForm.handleSubmit(handleSessionSubmit)} className="space-y-4 max-w-md">
            <div>
              <label className="text-xs font-medium">Access Token Expiration (Minutes) <span className="text-red-500">*</span></label>
              <input
                type="number"
                {...sessionForm.register("access_token_ttl")}
                className={`w-full text-sm rounded-[var(--radius)] border ${sessionForm.formState.errors.access_token_ttl ? 'border-red-500' : 'border-neutral-200 dark:border-neutral-700'} bg-transparent px-3 py-2 mt-1`}
              />
              {sessionForm.formState.errors.access_token_ttl && <p className="text-[10px] text-red-500 mt-1">{sessionForm.formState.errors.access_token_ttl.message}</p>}
              {!sessionForm.formState.errors.access_token_ttl && <p className="text-[10px] text-neutral-500 mt-1">Short-lived token for API access.</p>}
            </div>
            
            <div>
              <label className="text-xs font-medium">Refresh Token Expiration (Days) <span className="text-red-500">*</span></label>
              <input
                type="number"
                {...sessionForm.register("refresh_token_ttl")}
                className={`w-full text-sm rounded-[var(--radius)] border ${sessionForm.formState.errors.refresh_token_ttl ? 'border-red-500' : 'border-neutral-200 dark:border-neutral-700'} bg-transparent px-3 py-2 mt-1`}
              />
              {sessionForm.formState.errors.refresh_token_ttl && <p className="text-[10px] text-red-500 mt-1">{sessionForm.formState.errors.refresh_token_ttl.message}</p>}
              {!sessionForm.formState.errors.refresh_token_ttl && <p className="text-[10px] text-neutral-500 mt-1">Long-lived token used to obtain new access tokens.</p>}
            </div>

            <div>
              <label className="text-xs font-medium">Max Allowed Devices <span className="text-red-500">*</span></label>
              <input
                type="number"
                {...sessionForm.register("max_devices")}
                className={`w-full text-sm rounded-[var(--radius)] border ${sessionForm.formState.errors.max_devices ? 'border-red-500' : 'border-neutral-200 dark:border-neutral-700'} bg-transparent px-3 py-2 mt-1`}
              />
              {sessionForm.formState.errors.max_devices && <p className="text-[10px] text-red-500 mt-1">{sessionForm.formState.errors.max_devices.message}</p>}
              {!sessionForm.formState.errors.max_devices && <p className="text-[10px] text-neutral-500 mt-1">Maximum number of active sessions/devices allowed per user. Oldest will be revoked when exceeded.</p>}
            </div>

            <Button type="submit" disabled={updateMutation.isPending || !sessionForm.formState.isValid} className="mt-4">
              {updateMutation.isPending ? <AppIcon name="loading" className=" mr-2 animate-spin" /> : <AppIcon name="save" className=" mr-2" />}
              {updateMutation.isPending ? "Saving..." : "Save Rules"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

