"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardHeader, CardTitle, CardContent } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { AppIcon, IconName } from "@g4k/ui/components";
import { queryKeys } from "@/lib/query-keys";

export function RemindersConfig() {
  const queryClient = useQueryClient();
  const [formData, setFormData] = useState<any>({});

  const { data: settingsGrouped, isLoading } = useQuery({
    queryKey: queryKeys.settings,
    queryFn: () => apiFetch("/settings/grouped"),
  });

  useEffect(() => {
    if (settingsGrouped?.reminders) {
      const remindersMap: any = {};
      settingsGrouped.reminders.forEach((s: any) => {
        remindersMap[s.key] = s.value;
      });
      setFormData(remindersMap);
    }
  }, [settingsGrouped]);

  const updateMutation = useMutation({
    mutationFn: (updates: any[]) =>
      apiFetch("/settings/bulk", {
        method: "POST",
        body: JSON.stringify({ settings: updates }),
      }),
    onSuccess: () => {
      toast.success("Reminder settings updated");
      queryClient.invalidateQueries({ queryKey: queryKeys.settings });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const updates = [
      { category: "reminders", key: "reminders.shift_offset", value: formData["reminders.shift_offset"]?.toString() || "15" },
      { category: "reminders", key: "reminders.missed_clock_in_offset", value: formData["reminders.missed_clock_in_offset"]?.toString() || "30" },
      { category: "reminders", key: "reminders.open_shift_flag_time", value: formData["reminders.open_shift_flag_time"]?.toString() || "20:00" },
    ];
    updateMutation.mutate(updates);
  };

  if (isLoading) {
    return <Skeleton className="h-64 w-full rounded-xl" />;
  }

  return (
    <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader>
        <CardTitle className="text-base">Shift & Attendance Reminders</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4 max-w-md">
          <div>
            <label className="text-xs font-medium">Shift Reminder Offset (Minutes Before)</label>
            <input
              type="number"
              min={0}
              className="w-full text-sm rounded-[var(--radius)] border border-neutral-200 dark:border-neutral-700 bg-transparent px-3 py-2 mt-1"
              value={formData["reminders.shift_offset"] || "15"}
              onChange={(e) => setFormData({ ...formData, "reminders.shift_offset": e.target.value })}
            />
            <p className="text-[10px] text-neutral-500 mt-1">When to remind users before their shift starts.</p>
          </div>
          
          <div>
            <label className="text-xs font-medium">Missed Clock-In Alert Offset (Minutes After)</label>
            <input
              type="number"
              min={0}
              className="w-full text-sm rounded-[var(--radius)] border border-neutral-200 dark:border-neutral-700 bg-transparent px-3 py-2 mt-1"
              value={formData["reminders.missed_clock_in_offset"] || "30"}
              onChange={(e) => setFormData({ ...formData, "reminders.missed_clock_in_offset": e.target.value })}
            />
            <p className="text-[10px] text-neutral-500 mt-1">When to notify managers/HR if a user misses clock-in.</p>
          </div>

          <div>
            <label className="text-xs font-medium">Open Shift Flag Time</label>
            <input
              type="time"
              className="w-full text-sm rounded-[var(--radius)] border border-neutral-200 dark:border-neutral-700 bg-transparent px-3 py-2 mt-1"
              value={formData["reminders.open_shift_flag_time"] || "20:00"}
              onChange={(e) => setFormData({ ...formData, "reminders.open_shift_flag_time": e.target.value })}
            />
            <p className="text-[10px] text-neutral-500 mt-1">Time of day to flag shifts as abandoned if no clock-out.</p>
          </div>

          <Button type="submit" disabled={updateMutation.isPending} className="mt-4">
            <AppIcon name="save" className=" mr-2" />
            {updateMutation.isPending ? "Saving..." : "Save Settings"}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";

import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { DataTable } from "@g4k/ui/components/data-table";
import { StatusBadge, ConfirmDialog } from "@g4k/ui/components";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";

export function SecurityRequestsConfig() {
  const queryClient = useQueryClient();
  const [resetLink, setResetLink] = useState<string | null>(null);
  const [rejectState, setRejectState] = useState<{ isOpen: boolean; id: number | string | null }>({ isOpen: false, id: null });

  const { data = [], isLoading } = useQuery({
    queryKey: queryKeys.passwordResets("pending"),
    queryFn: async () => {
      const res = await apiFetch("/admin/password-resets");
      return Array.isArray(res) ? res : (res.data || []);
    },
  });

  const approveMutation = useMutation({
    mutationFn: async (id: number | string) => {
      return apiFetch(`/admin/password-resets/${id}/approve`, { method: "POST" });
    },
    onSuccess: (data) => {
      toast.success("Password reset request approved.");
      if (data.reset_link) {
        setResetLink(data.reset_link);
      }
      queryClient.invalidateQueries({ queryKey: queryKeys.passwordResets("pending") });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to approve request.");
    },
  });

  const rejectMutation = useMutation({
    mutationFn: async (id: number | string) => {
      return apiFetch(`/admin/password-resets/${id}/reject`, { method: "POST" });
    },
    onSuccess: () => {
      toast.success("Password reset request rejected.");
      queryClient.invalidateQueries({ queryKey: queryKeys.passwordResets("pending") });
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to reject request.");
    },
  });

  const columns = [
    {
      accessorKey: "user.name",
      header: "Employee",
      cell: ({ row }: any) => (
        <div>
          <div className="font-semibold text-neutral-900 dark:text-white">
            {row.original.user?.name || "Unknown"}
          </div>
          <div className="text-xs text-neutral-500">
            {row.original.user?.email || ""}
          </div>
        </div>
      ),
    },
    {
      accessorKey: "user.employee_id",
      header: "Emp ID",
      cell: ({ row }: any) => (
        <span className="text-xs font-mono">{row.original.user?.employee_id || "-"}</span>
      ),
    },
    {
      accessorKey: "created_at",
      header: "Requested At",
      cell: ({ row }: any) => (
        <span className="text-xs text-neutral-500">
          {row.original.created_at ? format(new Date(row.original.created_at), "MMM d, yyyy h:mm a") : "-"}
        </span>
      ),
    },
    {
      accessorKey: "status",
      header: "Status",
      cell: ({ row }: any) => (
        <StatusBadge status="warning">
          {row.original.status || "Pending"}
        </StatusBadge>
      ),
    },
    {
      id: "actions",
      header: () => <div className="text-right">Action</div>,
      cell: ({ row }: any) => {
        const id = row.original.id;
        const isApproving = approveMutation.isPending && approveMutation.variables === id;
        const isRejecting = rejectMutation.isPending && rejectMutation.variables === id;
        
        return (
          <div className="flex justify-end gap-2">
            <Button
              variant="outline"
              size="sm"
              className="h-8 text-red-600 hover:text-red-700 hover:bg-red-50 border-red-200"
              disabled={isApproving || isRejecting}
              onClick={() => setRejectState({ isOpen: true, id })}
            >
              <AppIcon name="close" size="sm" className=" mr-1" /> Reject
            </Button>
            <Button
              variant="primary"
              size="sm"
              className="h-8 bg-brand-violet hover:bg-brand-violet/90 text-white"
              disabled={isApproving || isRejecting}
              onClick={() => approveMutation.mutate(id)}
            >
              <AppIcon name="check" size="sm" className=" mr-1" /> Approve
            </Button>
          </div>
        );
      },
    },
  ];

  const handleCopyLink = () => {
    if (resetLink) {
      navigator.clipboard.writeText(resetLink);
      toast.success("Reset link copied to clipboard!");
    }
  };

  return (
    <div className="space-y-6">
      <Card className="border border-neutral-200 dark:border-neutral-800 rounded-xl shadow-e1 hover:shadow-e2 transition-shadow duration-150">
        <CardHeader>
          <div className="flex items-center gap-2">
            <AppIcon name="audit" size="lg" className=" text-brand-violet" />
            <CardTitle className="text-lg font-display">Password Reset Requests</CardTitle>
          </div>
          <CardDescription className="font-sans">
            Approve or reject password reset requests initiated by employees who lost access to their accounts. 
            Approving a request will generate a secure reset link for you to share with them out-of-band.
          </CardDescription>
        </CardHeader>
        <CardContent className="p-0 border-t border-neutral-100 dark:border-neutral-800">
          {isLoading ? (
            <div className="p-4 space-y-2">
              <Skeleton className="h-8 w-full" />
              <Skeleton className="h-8 w-full" />
              <Skeleton className="h-8 w-full" />
            </div>
          ) : data?.length === 0 ? (
            <div className="p-12 flex flex-col items-center justify-center text-center space-y-3 bg-neutral-50/50 dark:bg-neutral-900/20">
              <AppIcon name="check" className=" text-green-500 mb-2" />
              <p className="text-sm font-medium text-neutral-500">No pending password reset requests.</p>
            </div>
          ) : (
            <DataTable
              columns={columns}
              data={data || []}
            />
          )}
        </CardContent>
      </Card>

      <Dialog open={!!resetLink} onOpenChange={(open) => !open && setResetLink(null)}>
        <DialogContent className="sm:max-w-md font-sans">
          <DialogHeader>
            <DialogTitle className="font-display flex items-center gap-2 text-green-600">
              <AppIcon name="check" size="lg" /> Request Approved
            </DialogTitle>
            <DialogDescription className="text-sm">
              The password reset request has been approved. A unique reset link has been generated. 
              Please copy this link and securely share it with the employee.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <label className="text-xs font-semibold text-neutral-700 mb-1.5 block">Secure Reset Link</label>
            <div className="flex items-center gap-2">
              <Input 
                value={resetLink || ""} 
                readOnly 
                className="font-mono text-xs bg-neutral-50 text-neutral-500" 
              />
              <Button onClick={handleCopyLink} variant="outline" className="shrink-0 gap-1.5 h-9">
                <AppIcon name="copy" size="sm" /> Copy
              </Button>
            </div>
          </div>

          <DialogFooter>
            <Button variant="primary" onClick={() => setResetLink(null)}>
              Done
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      
      <ConfirmDialog
        open={rejectState.isOpen}
        onOpenChange={(open) => { if (!open) setRejectState({ isOpen: false, id: null }) }}
        onConfirm={() => {
          if (rejectState.id) {
            rejectMutation.mutate(rejectState.id);
            setRejectState({ isOpen: false, id: null });
          }
        }}
        title="Reject Request"
        description="Are you sure you want to reject this password reset request?"
        confirmText="Reject"
        isLoading={rejectMutation.isPending}
      />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {  Tabs, TabsContent, TabsList, TabsTrigger, FileUploadPopup , Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@g4k/ui/components";
import { Card, CardHeader, CardTitle, CardContent } from "@g4k/ui/components";
import { Button, Input, Skeleton } from "@g4k/ui/components";
import { MailSmtpConfig } from "./mail-smtp-config";
import { PoliciesConfig } from "./policies-config";
import { HolidayCalendar } from "@/components/leave/holiday-calendar";
import { WorkSchedulesConfig } from "./work-schedules-config";
import { AuditLogTable } from "./audit-log-table";
import { NotificationsConfig } from "./notifications-config";
import { AutoNumberingConfig } from "./auto-numbering-config";
import { RemindersConfig } from "./reminders-config";
import { SecurityRequestsConfig } from "./security-requests-config";
import { DemoDataConfig } from "./demo-data-config";
import { SystemJobsConfig } from "./system-jobs-config";
import { useAuthStore, getAuthToken } from "@/lib/auth-store";
import { useCapabilities, hasCapability } from "@/lib/capabilities";
import { DisabledWhileSubmitting, ValidationSummary } from "@g4k/ui/components/state-helpers";

const profileSchema = z.object({
  name: z.string().min(2, "Company name must be at least 2 characters"),
  timezone: z.string().default("Asia/Kolkata"),
});

type ProfileFormValues = z.infer<typeof profileSchema>;

import { useUrlState } from "@/hooks/use-url-state";

export function SettingsTabs() {
  const queryClient = useQueryClient();
  const { data: caps } = useCapabilities();
  const canManageSettings = hasCapability(caps, 'settings.manage');
  
  const [logoUploadOpen, setLogoUploadOpen] = useState(false);
  const [tab, setTab] = useUrlState("tab", "company");

  const { data: profile, isLoading: isProfileLoading } = useQuery({
    queryKey: queryKeys.companyProfile,
    queryFn: () => apiFetch("/company-profile"),
  });

  const profileForm = useForm<ProfileFormValues>({
    resolver: zodResolver(profileSchema) as any,
    defaultValues: {
      name: "",
      timezone: "Asia/Kolkata"
    },
    mode: "onTouched",
    delayError: 400,
  });

  useEffect(() => {
    if (profile) {
      profileForm.reset({
        name: profile.name || "",
        timezone: profile.timezone || "Asia/Kolkata"
      });
    }
  }, [profile, profileForm]);

  const updateProfileMutation = useMutation({
    mutationFn: (data: any) =>
      apiFetch("/company-profile", { method: "POST", body: JSON.stringify(data) }),
    onSuccess: () => {
      toast.success("Company profile updated");
      queryClient.invalidateQueries({ queryKey: queryKeys.companyProfile });
    },
    onError: (error: any) => {
      if (error?.errors) {
        Object.keys(error.errors).forEach(key => {
          profileForm.setError(key as any, { message: error.errors[key][0] });
        });
      }
    },
  });

  const uploadLogoMutation = useMutation({
    mutationFn: async (file: File) => {
      const formData = new FormData();
      formData.append("logo", file);
      
      return await apiFetch("/company-profile/logo", {
        method: "POST",
        body: formData,
      });
    },
    onSuccess: () => {
      toast.success("Logo uploaded successfully");
      queryClient.invalidateQueries({ queryKey: queryKeys.companyProfile });
      setLogoUploadOpen(false);
    },
    onError: () => {
      toast.error("Failed to upload logo");
    }
  });

  if (isProfileLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-10 w-64 rounded-xl" />
        <Skeleton className="h-64 w-full rounded-xl" />
      </div>
    );
  }

  const handleProfileSubmit = (data: any) => {
    updateProfileMutation.mutate({
      name: data.name,
      timezone: data.timezone,
    });
  };

  return (
    <Tabs value={tab} onValueChange={setTab} className="w-full">
      <TabsList className="mb-4">
        <TabsTrigger value="company">Company Profile</TabsTrigger>
        {canManageSettings && (
          <>
            <TabsTrigger value="schedule">Work Schedules</TabsTrigger>
            <TabsTrigger value="policies">Policies</TabsTrigger>
            <TabsTrigger value="holidays">Holidays</TabsTrigger>
            <TabsTrigger value="mail">Mail / SMTP</TabsTrigger>
            <TabsTrigger value="notifications">Notifications</TabsTrigger>
            <TabsTrigger value="autonumber">Auto-Numbering</TabsTrigger>
            <TabsTrigger value="reminders">Reminders</TabsTrigger>
            <TabsTrigger value="security">Security Requests</TabsTrigger>
            <TabsTrigger value="audit">Audit Log</TabsTrigger>
            <TabsTrigger value="demo">Demo Data</TabsTrigger>
            <TabsTrigger value="jobs">System Jobs</TabsTrigger>
          </>
        )}
      </TabsList>

      <TabsContent value="company">
        <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
          <CardHeader>
            <CardTitle className="text-base">Company Information</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={profileForm.handleSubmit(handleProfileSubmit)} className="space-y-6 max-w-xl">
              <DisabledWhileSubmitting isSubmitting={updateProfileMutation.isPending}>
              <div className="space-y-4">
                <h3 className="text-sm font-semibold text-neutral-900 dark:text-white border-b pb-2">Identity</h3>
                <ValidationSummary errors={profileForm.formState.errors} />
                <div>
                  <label htmlFor="company-name" className="text-xs font-medium">Company Name <span className="text-red-500">*</span></label>
                  <Input
                    id="company-name"
                    type="text"
                    {...profileForm.register("name")}
                    error={profileForm.formState.errors.name?.message}
                    className="mt-1"
                  />
                </div>
                <div>
                  <label className="text-xs font-medium">Company Logo</label>
                  <div className="flex items-center gap-4 mt-2 mb-4">
                    {profile?.logo_url ? (
                      <img src={profile.logo_url} alt="Logo" className="w-16 h-16 object-contain rounded-[var(--radius)] border border-neutral-200 dark:border-neutral-800 bg-surface" />
                    ) : (
                      <div className="w-16 h-16 rounded-[var(--radius)] border border-neutral-200 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900 flex items-center justify-center text-xs text-neutral-400">
                        No Logo
                      </div>
                    )}
                    <Button type="button" variant="outline" size="sm" onClick={() => setLogoUploadOpen(true)}>
                      Upload New Logo
                    </Button>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h3 className="text-sm font-semibold text-neutral-900 dark:text-white border-b pb-2">Preferences</h3>
                <div>
                  <label className="text-xs font-medium">Timezone <span className="text-red-500">*</span></label>
                  <Select
                    value={profileForm.watch("timezone")}
                    onValueChange={(val) => profileForm.setValue("timezone", val, { shouldDirty: true, shouldValidate: true })}
                  >
                    <SelectTrigger className="w-full mt-1">
                      <SelectValue placeholder="Select Timezone" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Asia/Kolkata">Asia/Kolkata</SelectItem>
                      <SelectItem value="UTC">UTC</SelectItem>
                      <SelectItem value="America/New_York">America/New_York</SelectItem>
                      <SelectItem value="Europe/London">Europe/London</SelectItem>
                      <SelectItem value="Asia/Singapore">Asia/Singapore</SelectItem>
                    </SelectContent>
                  </Select>
                  {profileForm.formState.errors.timezone && (
                    <p className="text-red-500 text-xs mt-1">{profileForm.formState.errors.timezone.message}</p>
                  )}
                </div>
              </div>

              <Button type="submit" disabled={updateProfileMutation.isPending || !profileForm.formState.isValid}>
                {updateProfileMutation.isPending ? <AppIcon name="loading" className=" mr-2 animate-spin" /> : <AppIcon name="save" className=" mr-2" />}
                {updateProfileMutation.isPending ? "Saving..." : "Save Profile"}
              </Button>
              </DisabledWhileSubmitting>
            </form>
          </CardContent>
        </Card>
        
        <FileUploadPopup 
          open={logoUploadOpen} 
          onOpenChange={setLogoUploadOpen} 
          title="Upload Company Logo" 
          description="Select an image file to upload. Max size 5MB."
          onUpload={async (file) => { await uploadLogoMutation.mutateAsync(file); }}
          isLoading={uploadLogoMutation.isPending}
        />
      </TabsContent>

      {canManageSettings && (
        <>
          <TabsContent value="schedule">
            <WorkSchedulesConfig />
          </TabsContent>

          <TabsContent value="policies">
            <PoliciesConfig />
          </TabsContent>

          <TabsContent value="holidays">
            <div className="bg-card dark:bg-neutral-900 rounded-xl overflow-hidden shadow-e1 hover:shadow-e2 transition-shadow duration-150 h-[calc(100dvh-200px)]">
              <HolidayCalendar />
            </div>
          </TabsContent>
      <TabsContent value="mail">
        <MailSmtpConfig />
      </TabsContent>

      <TabsContent value="notifications">
        <NotificationsConfig />
      </TabsContent>

      <TabsContent value="autonumber">
        <AutoNumberingConfig />
      </TabsContent>

      <TabsContent value="reminders">
        <RemindersConfig />
      </TabsContent>

      <TabsContent value="security">
        <SecurityRequestsConfig />
      </TabsContent>

      <TabsContent value="audit">
        <AuditLogTable />
      </TabsContent>

      <TabsContent value="demo">
        <DemoDataConfig />
      </TabsContent>

      <TabsContent value="jobs">
        <SystemJobsConfig />
      </TabsContent>
        </>
      )}
    </Tabs>
  );
}

"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardHeader, CardTitle, CardContent, Button, AppIcon } from "@g4k/ui/components";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { format } from "date-fns";

export function SystemJobsConfig() {
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ["admin_jobs"],
    queryFn: () => apiFetch<any>("/admin/jobs"),
    refetchInterval: 10000, // poll every 10s
  });

  const retryMutation = useMutation({
    mutationFn: () => apiFetch("/admin/jobs/retry", { method: "POST" }),
    onSuccess: () => {
      toast.success("Failed jobs queued for retry.");
      queryClient.invalidateQueries({ queryKey: ["admin_jobs"] });
    },
    onError: () => toast.error("Failed to retry jobs."),
  });

  if (isLoading) {
    return <div className="p-4 text-sm text-neutral-500">Loading jobs...</div>;
  }

  const { pending_count = 0, failed_count = 0, failed_jobs = [] } = data || {};

  return (
    <Card className="bg-card dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-e1 hover:shadow-e2 transition-shadow duration-150 rounded-xl overflow-hidden h-full">
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle className="text-base">System Background Jobs</CardTitle>
        <Button 
          variant="outline" 
          size="sm" 
          onClick={() => retryMutation.mutate()} 
          disabled={failed_count === 0 || retryMutation.isPending}
        >
          {retryMutation.isPending ? <AppIcon name="loading" className="animate-spin mr-2" /> : <AppIcon name="refresh" className="mr-2" />}
          Retry All Failed
        </Button>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-neutral-50 dark:bg-neutral-800 p-4 rounded-[var(--radius)] flex flex-col">
            <span className="text-xs text-neutral-500 font-semibold uppercase tracking-wider mb-1">Pending Jobs</span>
            <span className="text-2xl font-bold">{pending_count}</span>
          </div>
          <div className="bg-rose-50 dark:bg-rose-950/30 p-4 rounded-[var(--radius)] flex flex-col">
            <span className="text-xs text-rose-500 font-semibold uppercase tracking-wider mb-1">Failed Jobs</span>
            <span className="text-2xl font-bold text-rose-600">{failed_count}</span>
          </div>
        </div>

        <div>
          <h3 className="text-sm font-semibold mb-3">Recent Failed Jobs</h3>
          {failed_jobs.length === 0 ? (
            <div className="text-sm text-neutral-500 bg-neutral-50 dark:bg-neutral-800 p-4 rounded-[var(--radius)] text-center">
              No failed jobs.
            </div>
          ) : (
            <div className="space-y-2 max-h-[400px] overflow-y-auto thin-scrollbar pr-2">
              {failed_jobs.map((job: any) => (
                <div key={job.id} className="p-3 border border-neutral-200 dark:border-neutral-800 rounded-[var(--radius)] text-xs space-y-2">
                  <div className="flex justify-between items-start">
                    <span className="font-semibold text-rose-600 break-all pr-4">{job.queue}</span>
                    <span className="text-neutral-500 shrink-0">{format(new Date(job.failed_at), "MMM d, yyyy HH:mm:ss")}</span>
                  </div>
                  <div className="text-neutral-600 dark:text-neutral-400 font-mono text-[10px] break-all">
                    {job.payload ? JSON.parse(job.payload).displayName : "Unknown payload"}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

