        ) : (
          announcements.map((item: any) => {
            const reactions = item.reactions || {};
            const isPinned = Boolean(item.pinned_at);

            return (
              <div
                key={item.id}
                className="p-3 rounded-xl bg-neutral-50 dark:bg-neutral-800/50 space-y-2 border border-neutral-100 dark:border-neutral-800"
              >
                <div className="flex items-center justify-between">
                  <h4 className="text-xs font-bold text-neutral-900 dark:text-white flex items-center gap-1.5">
                    {isPinned && <AppIcon name="pin" size="sm" className=" text-amber-500 fill-amber-500" />}
                    {item.title}
                  </h4>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] text-neutral-400">
                      {safeFormat(item.created_at, "MMM d")}
                    </span>
                    {canManage && (
                      <div className="flex items-center gap-1">
                        <TooltipProvider delayDuration={150}>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => {
                                  setEditingId(item.id);
                                  setCreateData({ title: item.title, body: item.body, scope: item.scope || "company", pinned: isPinned });
                                  setShowCreate(true);
                                }}
                                aria-label="Edit Announcement"
                                className="h-5 w-5 text-neutral-400 hover:text-neutral-600 transition-colors"
                              >
                                <AppIcon name="edit" size="xs" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent className="text-xs">Edit Announcement</TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                        <TooltipProvider delayDuration={150}>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => pinMutation.mutate({ id: item.id, pinned: !isPinned })}
                                aria-label={isPinned ? "Unpin Announcement" : "Pin Announcement"}
                                className={`h-5 w-5 transition-colors ${
                                  isPinned ? "text-warning hover:text-warning/80" : "text-neutral-400 hover:text-neutral-600"
                                }`}
                              >
                                <AppIcon name="pin" size="xs" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent className="text-xs">{isPinned ? "Unpin Announcement" : "Pin Announcement"}</TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                        <TooltipProvider delayDuration={150}>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => setConfirmState({ isOpen: true, id: item.id })}
                                aria-label="Delete Announcement"
                                className="h-5 w-5 text-neutral-400 hover:text-destructive hover:bg-destructive/10 transition-colors"
                              >
                                <AppIcon name="trash" size="xs" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent className="text-xs">Delete Announcement</TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                      </div>
                    )}
                  </div>
                </div>

                <p className="text-xs text-neutral-600 dark:text-neutral-300 leading-relaxed">
                  {item.body}
                </p>

                <div className="flex items-center justify-between pt-1 border-t border-neutral-200/50 dark:border-neutral-700/50 text-[10px]">
                  <span className="text-neutral-400 font-medium">
                    By {item.creator?.name || "Management"}
                  </span>

                  <div className="flex items-center gap-1">
                    {emojis.map(({ key, label }) => {
                      const uids: number[] = Array.isArray(reactions[key]) ? reactions[key] : [];
                      const count = uids.length;
                      const hasReacted = user?.id ? uids.includes(user.id) : false;

                      return (
                        <button
                          key={key}
                          onClick={() => reactMutation.mutate({ id: item.id, emoji: key })}
                          className={`px-1.5 py-0.5 rounded-full text-[10px] flex items-center gap-1 border transition-colors ${
                            hasReacted
                              ? "bg-secondary border-border-strong font-bold"
                              : "bg-transparent border-transparent hover:bg-muted"
                          }`}
                        >
                          <span>{label}</span>
                          {count > 0 && <span>{count}</span>}
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>

      <ConfirmDialog
        open={confirmState.isOpen}
        onOpenChange={(open) => { if (!open) setConfirmState({ isOpen: false, id: null }) }}
        onConfirm={() => {
          if (confirmState.id) {
            deleteMutation.mutate(confirmState.id);
            setConfirmState({ isOpen: false, id: null });
          }
        }}
        title="Delete Announcement"
        description="Are you sure you want to delete this announcement?"
        isLoading={deleteMutation.isPending}
      />
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { Card, CardHeader, CardTitle, CardContent } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";

export function FeedbackForm() {
  const [body, setBody] = useState("");

  const submitMutation = useMutation({
    mutationFn: async () => {
      return apiFetch("/feedback", {
        method: "POST",
        body: JSON.stringify({ body }),
      });
    },
    onSuccess: () => {
      toast.success("Feedback submitted to HR/Management.");
      setBody("");
    },
    onError: (err: any) => {
      toast.error(err.message || "Failed to submit feedback.");
    },
  });

  return (
    <Card className=" bg-card dark:bg-neutral-900">
      <CardHeader className="pb-3">
        <CardTitle className="text-base font-bold flex items-center gap-2">
          <AppIcon name="chat" />
          Submit Feedback / Grievance
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        <textarea
          placeholder="Share your concerns or feedback directly with HR & Management..."
          value={body}
          onChange={(e) => setBody(e.target.value)}
          className="w-full p-2.5 text-xs rounded-xl border border-input bg-background resize-none"
          rows={3}
        />
        {submitMutation.isError && (
          <div className="flex items-center gap-2 text-[10px] text-rose-600 bg-rose-50 dark:bg-rose-950/20 p-2 rounded-[var(--radius)]">
            <AppIcon name="warning" size="xs" />
            <span>Failed to submit. Please try again.</span>
          </div>
        )}
        <Button
          onClick={() => submitMutation.mutate()}
          disabled={submitMutation.isPending || !body.trim()}
          className="w-full h-8 text-xs bg-emerald-600 hover:bg-emerald-700 text-white font-semibold gap-1.5"
        >
          {submitMutation.isPending ? <AppIcon name="loading" size="sm" className=" animate-spin" /> : <AppIcon name="send" size="sm" />}
          Submit Privately
        </Button>
      </CardContent>
    </Card>
  );
}

