"use client";

import { useState, useEffect, useRef } from "react";
import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { STALE_TIME_METRICS, queryKeys } from "@/lib/query-keys";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { Card, CardContent, Button } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { EmptyState } from "@g4k/ui/components";
import { WidgetInfo } from "./widget-info";
import { useRouter } from "next/navigation";

interface MetricWidgetProps {
  title: string;
  metricKey: string;
  icon: IconName;
  color?: "violet" | "emerald" | "amber" | "rose" | "blue" | "indigo" | "pink" | "cyan" | "teal";
  endpoint?: string;
  subtitle?: string;
  hasModule?: boolean;
  info?: React.ReactNode;
  breakdown?: boolean;
  href?: string;
}

export function MetricWidget({
  title,
  metricKey,
  icon,
  color = "violet",
  endpoint = "/dashboard/init",
  subtitle,
  hasModule = true,
  info,
  breakdown = false,
  href,
}: MetricWidgetProps) {
  const [displayValue, setDisplayValue] = useState(0);
  const [isVisible, setIsVisible] = useState(true);
  const isFirstRender = useRef(true);
  const prevValueRef = useRef<number | null>(null);
  const router = useRouter();

  const { data, isPending, isFetching, isError, refetch } = useDashboardInit({
    select: (data: any) => data?.metrics || {},
    placeholderData: keepPreviousData,
  });

  const rawValue = data?.[metricKey] ?? 0;

  // breakdown logic
  const activeCount = data?.active_employees ?? 0;
  const inactiveCount = data?.inactive_employees ?? 0;
  const departmentsCount = data?.departments ?? 0;

  let dynamicInfo = info;
  if (breakdown && metricKey === "total_employees") {
    dynamicInfo = `${activeCount} active · ${inactiveCount} inactive across ${departmentsCount} departments`;
  }

  // Update value instantly
  useEffect(() => {
    if (isPending || typeof rawValue !== "number") return;
    setDisplayValue(rawValue);
  }, [rawValue, isPending]);

  const colorStyles = {
    violet: "bg-primary-100 dark:bg-primary-950/60 text-primary-700 dark:text-primary-300",
    emerald: "bg-emerald-100 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300",
    amber: "bg-amber-100 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300",
    rose: "bg-rose-100 dark:bg-rose-950/60 text-rose-700 dark:text-rose-300",
    blue: "bg-blue-100 dark:bg-blue-950/60 text-blue-700 dark:text-blue-300",
    indigo: "bg-indigo-100 dark:bg-indigo-950/60 text-indigo-700 dark:text-indigo-300",
    pink: "bg-pink-100 dark:bg-pink-950/60 text-pink-700 dark:text-pink-300",
    cyan: "bg-cyan-100 dark:bg-cyan-950/60 text-cyan-700 dark:text-cyan-300",
    teal: "bg-teal-100 dark:bg-teal-950/60 text-teal-700 dark:text-teal-300",
  };

  if (!isVisible) return null;

  if (isPending) {
    return (
      <Card className="h-full border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col transition-shadow duration-150">
        <div className="flex items-center gap-2 pb-3">
          <Skeleton className="w-7 h-7 rounded-[var(--radius)]" />
          <Skeleton className="h-4 w-24" />
        </div>
        <Skeleton className="h-8 w-16 mb-2 mt-2" />
        <Skeleton className="h-3 w-32" />
      </Card>
    );
  }

  if (isError) {
    return (
      <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col justify-between transition-shadow duration-150">
        <div className="flex items-center justify-between pb-3">
          <div className="flex items-center gap-2">
            <div className={`w-7 h-7 rounded-[var(--radius)] ${colorStyles[color]} flex items-center justify-center`}>
              <AppIcon name={icon} size="md" />
            </div>
            <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider">
              {title}
            </span>
            {isFetching && <AppIcon name="loading" size="xs" className=" animate-spin text-neutral-400" />}
          </div>
        </div>
        <div className="flex-1 flex flex-col items-center justify-center bg-rose-50/50 dark:bg-rose-950/10 rounded-[var(--radius)] p-2 mt-2">
          <AppIcon name="warning" size="xl" className=" text-rose-400 mb-2" />
          <span className="text-[11px] text-rose-600 font-medium mb-2">Failed to load</span>
          <Button variant="outline" size="sm" onClick={() => refetch()} className="h-6 text-[10px] px-2">
            Retry
          </Button>
        </div>
      </Card>
    );
  }

  return (
    <Card 
      onClick={() => href && router.push(href)}
      className={`h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col justify-between transition-shadow duration-150 group ${href ? 'cursor-pointer' : ''}`}
    >
      <div>
        <div className="flex items-center justify-between pb-3">
          <div className="flex items-center gap-2">
            <div className={`w-7 h-7 rounded-[var(--radius)] ${colorStyles[color]} flex items-center justify-center transition-transform group-hover:scale-110`}>
              <AppIcon name={icon} size="md" />
            </div>
            <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider flex items-center gap-1.5">
              {title}
              {dynamicInfo && <WidgetInfo summary={dynamicInfo} />}
            </span>
            <div className="flex items-center gap-1">
              {isFetching && <AppIcon name="loading" size="xs" className=" animate-spin text-neutral-400" />}
              {!isFetching && (
                <>
                  <Button variant="ghost" size="icon" className="h-5 w-5 opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => { e.stopPropagation(); refetch(); }}>
                    <AppIcon name="refresh" size="xs" className="text-neutral-400" />
                  </Button>
                  <Button variant="ghost" size="icon" className="h-5 w-5 opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => { e.stopPropagation(); setIsVisible(false); }}>
                    <AppIcon name="close" size="sm" className="text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-200" />
                  </Button>
                </>
              )}
            </div>
          </div>
        </div>

        <div className="mt-2">
          <div className="text-3xl font-bold font-mono tracking-tight text-neutral-900 dark:text-white">
            {displayValue.toLocaleString()}
          </div>
          {breakdown && metricKey === "total_employees" ? (
            <p className="text-[11px] text-neutral-400 mt-1 font-medium">
              <span className="text-emerald-600 dark:text-emerald-400">{activeCount} active</span> <span className="mx-1 opacity-50">·</span> <span className="text-neutral-500">{inactiveCount} inactive</span>
            </p>
          ) : subtitle ? (
            <p className="text-[11px] text-neutral-400 mt-1">{subtitle}</p>
          ) : null}
        </div>
      </div>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { AppIcon, IconName } from "@g4k/ui/components";
import { format } from "date-fns";
import { apiFetch } from "@/lib/api-client";
import { Card, CardHeader, CardTitle, CardContent, Button, Skeleton, ConfirmDialog, Input, Tooltip, TooltipContent, TooltipProvider, TooltipTrigger, Truncate } from "@g4k/ui/components";
import { queryKeys } from "@/lib/query-keys";
import { triggerInvalidation } from "@/lib/invalidation-map";
import { toast } from "sonner";
import { useAuthStore } from "@/lib/auth-store";
import { WidgetInfo } from "./widget-info";

export function PendingApprovalsWidget() {
  const queryClient = useQueryClient();
  const user = useAuthStore((s) => s.user);

  const { data: requests = [], isPending, isFetching, isError, refetch } = useDashboardInit({
    select: (data: any) => Array.isArray(data.pending_approvals) ? data.pending_approvals : [],
    placeholderData: keepPreviousData,
  });

  const [rejectState, setRejectState] = useState<{ isOpen: boolean; id: number | null }>({ isOpen: false, id: null });
  const [rejectReason, setRejectReason] = useState("");

  const decisionMutation = useMutation({
    mutationFn: async ({ id, decision, reason }: { id: number; decision: "approved" | "rejected"; reason?: string }) => {
      return apiFetch(`/approvals/${id}/decision`, {
        method: "POST",
        body: JSON.stringify({ decision, reason }),
      });
    },
    onSuccess: () => {
      toast.success("Action recorded successfully!");
      triggerInvalidation(queryClient, "approval.decision");
    },
  });

  return (
    <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col transition-shadow duration-150">
      <div className="flex items-center justify-between pb-3">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-[var(--radius)] bg-amber-100 dark:bg-amber-950 flex items-center justify-center">
            <AppIcon name="clipboard" className=" text-amber-600 dark:text-amber-400" />
          </div>
          <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider flex items-center gap-1.5">
            Pending Approvals
            <WidgetInfo summary="Leaves, Tasks, and Projects awaiting your review" />
          </span>
          {isFetching && <AppIcon name="loading" size="xs" className=" animate-spin text-neutral-400" />}
        </div>
        <span className="text-xs px-2 py-0.5 rounded-full bg-amber-100 dark:bg-amber-950/50 text-amber-700 dark:text-amber-300 font-semibold">
          {requests.length}
        </span>
      </div>

      <div className="flex-1 space-y-2 overflow-y-auto max-h-[260px] thin-scrollbar">
        {isPending ? (
          <div className="space-y-2 min-h-[150px]">
            {[1, 2, 3].map((i) => (
              <div key={i} className="p-2.5 rounded-xl bg-neutral-50 dark:bg-neutral-800/50 flex items-center justify-between">
                <div className="space-y-1">
                  <Skeleton className="h-3.5 w-28" />
                  <Skeleton className="h-3 w-20" />
                </div>
                <div className="flex gap-1">
                  <Skeleton className="h-7 w-7 rounded-[var(--radius)]" />
                  <Skeleton className="h-7 w-7 rounded-[var(--radius)]" />
                </div>
              </div>
            ))}
          </div>
        ) : isError ? (
          <div className="flex flex-col items-center justify-center p-6 text-center space-y-2 bg-rose-50/50 dark:bg-rose-950/10 rounded-xl border border-rose-100 dark:border-rose-900/30 min-h-[150px]">
            <AppIcon name="warning" size="xl" className=" text-rose-400" />
            <p className="text-xs font-medium text-rose-600">Failed to load requests</p>
            <Button variant="outline" size="sm" onClick={() => refetch()} className="h-6 text-[10px] px-2">
              Retry
            </Button>
          </div>
        ) : requests.length === 0 ? (
          <div className="flex flex-col items-center justify-center p-6 text-center border border-dashed border-neutral-200 dark:border-neutral-800 rounded-xl min-h-[150px]">
            <p className="text-xs font-medium text-neutral-400">No pending approvals</p>
          </div>
        ) : (
          requests.map((item: any) => {
            return (
              <div
                key={`${item.type}-${item.id}`}
                className="p-2.5 rounded-xl bg-neutral-50 dark:bg-neutral-800/50 flex items-center justify-between border border-neutral-100 dark:border-neutral-800"
              >
                <div className="space-y-0.5">
                  <div className="flex items-center gap-1.5">
                    <span className="text-[10px] uppercase font-semibold px-1.5 py-0.5 rounded bg-neutral-200 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300">
                      {item.type}
                    </span>
                    <span className="text-xs font-bold text-neutral-900 dark:text-white">
                      {item.user_name || "Unknown"}
                    </span>
                  </div>
                  <div className="flex items-center gap-1 text-[11px] text-neutral-600 dark:text-neutral-400 font-medium">
                    <Truncate text={item.title} className="max-w-[150px]" />
                    <span className="opacity-50">·</span>
                    <span>{item.created_at ? format(new Date(item.created_at), "MMM d") : ""}</span>
                  </div>
                </div>

                <div className="flex items-center gap-1">
                  {item.type === 'leave' && item.route?.includes('tab=approvals') ? (
                      <>
                        <TooltipProvider delayDuration={150}>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <button
                                onClick={() => decisionMutation.mutate({ id: item.id, decision: "approved" })}
                                disabled={decisionMutation.isPending}
                                aria-label="Approve Request"
                                className="p-1.5 rounded-[var(--radius)] bg-emerald-100 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-200 dark:hover:bg-emerald-900 transition-colors"
                              >
                                <AppIcon name="check" size="sm" />
                              </button>
                            </TooltipTrigger>
                            <TooltipContent className="text-xs">Approve Request</TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                        <TooltipProvider delayDuration={150}>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <button
                                onClick={() => setRejectState({ isOpen: true, id: item.id })}
                                disabled={decisionMutation.isPending}
                                aria-label="Reject Request"
                                className="p-1.5 rounded-[var(--radius)] bg-rose-100 dark:bg-rose-950/60 text-rose-700 dark:text-rose-300 hover:bg-rose-200 dark:hover:bg-rose-900 transition-colors"
                              >
                                <AppIcon name="close" size="sm" />
                              </button>
                            </TooltipTrigger>
                            <TooltipContent className="text-xs">Reject Request</TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                      </>
                  ) : (
                    <Button variant="outline" size="sm" asChild className="h-7 text-[10px] px-2 font-medium">
                      <a href={item.route || item.action_url}>{(item.route?.includes('tab=leave') || item.type === 'task') ? 'View' : 'Review'}</a>
                    </Button>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>

      <ConfirmDialog
        open={rejectState.isOpen}
        onOpenChange={(open) => { 
          if (!open) {
            setRejectState({ isOpen: false, id: null });
            setRejectReason("");
          }
        }}
        onConfirm={() => {
          if (rejectState.id) {
            decisionMutation.mutate({ id: rejectState.id, decision: "rejected", reason: rejectReason });
            setRejectState({ isOpen: false, id: null });
            setRejectReason("");
          }
        }}
        title="Reject Request"
        description="Please provide a reason for rejecting this request."
        confirmText="Reject"
        isLoading={decisionMutation.isPending}
      >
        <Input 
          value={rejectReason} 
          onChange={(e) => setRejectReason(e.target.value)} 
          placeholder="Reason for rejection (required)" 
          className="mt-2"
        />
      </ConfirmDialog>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { AppIcon, IconName } from "@g4k/ui/components";
import { apiFetch } from "@/lib/api-client";
import { Card, CardHeader, CardTitle, CardContent, Skeleton, Collapsible, CollapsibleTrigger, CollapsibleContent, ConfirmDialog, Tooltip, TooltipContent, TooltipProvider, TooltipTrigger, Truncate } from "@g4k/ui/components";
import { Input } from "@g4k/ui/components";
import { Button } from "@g4k/ui/components";
import { OneFieldForm } from "@/components/one-field-form";
import { useUIStore } from "@/lib/ui-store";
import { useShallow } from "zustand/react/shallow";
import { queryKeys } from "@/lib/query-keys";

export function QuickNotes() {
  const queryClient = useQueryClient();
  const widgetStates = useUIStore(useShallow((s) => s.widgetStates));
  const toggleWidgetCollapse = useUIStore((s) => s.toggleWidgetCollapse);
  const isCollapsed = widgetStates["quick-notes"]?.collapsed ?? false;
  const [confirmState, setConfirmState] = useState<{ isOpen: boolean; id: number | null }>({ isOpen: false, id: null });
  const [editingNoteId, setEditingNoteId] = useState<number | null>(null);
  const [editBody, setEditBody] = useState("");

  const { data: notes = [], isPending, isFetching, isError, refetch } = useDashboardInit({
    select: (data: any) => (Array.isArray(data.quick_notes?.data) ? data.quick_notes.data : (Array.isArray(data.quick_notes) ? data.quick_notes : [])),
    placeholderData: keepPreviousData,
  });

  const createMutation = useMutation({
    mutationFn: async (body: string) => {
      return apiFetch("/quick-notes", {
        method: "POST",
        body: JSON.stringify({ body }),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      return apiFetch(`/quick-notes/${id}`, { method: "DELETE" });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
  });

  const togglePinMutation = useMutation({
    mutationFn: async ({ id, pinned }: { id: number; pinned: boolean }) => {
      return apiFetch(`/quick-notes/${id}`, {
        method: "PUT",
        body: JSON.stringify({ pinned }),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
  });

  const editMutation = useMutation({
    mutationFn: async ({ id, body }: { id: number; body: string }) => {
      return apiFetch(`/quick-notes/${id}`, {
        method: "PUT",
        body: JSON.stringify({ body }),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
      setEditingNoteId(null);
      setEditBody("");
    },
  });

  return (
    <Collapsible open={!isCollapsed} onOpenChange={() => toggleWidgetCollapse("quick-notes")}>
      <Card className="h-full bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 flex flex-col transition-shadow duration-150">
        <div className="flex items-center justify-between pb-3">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-[var(--radius)] bg-amber-100 dark:bg-amber-950 flex items-center justify-center">
              <AppIcon name="fileText" />
            </div>
            <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider">
              Quick Scratchpad
            </span>
            {isFetching && <AppIcon name="loading" size="xs" className=" animate-spin text-neutral-400" />}
          </div>
          <CollapsibleTrigger className="h-7 w-7 p-0 flex items-center justify-center rounded-[var(--radius)] text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-200 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring">
            {isCollapsed ? <AppIcon name="chevronDown" /> : <AppIcon name="chevronUp" />}
          </CollapsibleTrigger>
        </div>
        <CollapsibleContent>
          <div className="space-y-3 pt-2">
            <div className="flex gap-2">
              <OneFieldForm
                title="Quick Note"
                placeholder="Type a personal note..."
                buttonLabel="Add Note"
                icon="plus"
                onSubmit={(val) => createMutation.mutateAsync(val)}
                isPending={createMutation.isPending}
              />
            </div>

            <div className="space-y-2 max-h-[200px] overflow-y-auto thin-scrollbar pr-1">
              {isPending ? (
                <div className="space-y-2">
                  {[1, 2].map(i => (
                    <Skeleton key={i} className="h-10 w-full rounded-[var(--radius)]" />
                  ))}
                </div>
              ) : isError ? (
                <div className="flex flex-col items-center justify-center p-4 text-center space-y-2 bg-rose-50/50 dark:bg-rose-950/10 rounded-xl border border-rose-100 dark:border-rose-900/30">
                  <AppIcon name="warning" size="lg" className=" text-rose-400" />
                  <p className="text-[10px] font-medium text-rose-600">Failed to load notes</p>
                  <Button variant="outline" size="sm" onClick={() => refetch()} className="h-5 text-[10px] px-2">
                    Retry
                  </Button>
                </div>
              ) : !notes || notes.length === 0 ? (
                <div className="flex flex-col items-center justify-center p-4 text-center border border-dashed border-neutral-200 dark:border-neutral-800 rounded-xl">
                  <p className="text-xs font-medium text-neutral-400">No notes yet</p>
                </div>
              ) : (
                notes.map((n: any) => (
                  <div
                    key={n.id}
                    className={`p-2.5 rounded-[var(--radius)] text-xs flex flex-col justify-between gap-2 border transition-colors group ${
                      n.pinned 
                        ? 'bg-amber-50 dark:bg-amber-950/30 border-amber-200 dark:border-amber-900/50' 
                        : 'bg-secondary border-border'
                    }`}
                  >
                    {editingNoteId === n.id ? (
                      <div className="w-full flex flex-col gap-2">
                        <textarea
                          className="w-full text-xs p-2 rounded border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 resize-none outline-none focus:ring-1 focus:ring-primary-500"
                          value={editBody}
                          onChange={(e) => setEditBody(e.target.value)}
                          rows={2}
                          autoFocus
                        />
                        <div className="flex items-center justify-end gap-1">
                          <Button variant="outline" size="sm" className="h-6 text-[10px] px-2" onClick={() => setEditingNoteId(null)}>Cancel</Button>
                          <Button variant="primary" size="sm" className="h-6 text-[10px] px-2" onClick={() => editMutation.mutate({ id: n.id, body: editBody })} disabled={!editBody.trim() || editMutation.isPending}>Save</Button>
                        </div>
                      </div>
                    ) : (
                      <div className="flex items-start justify-between w-full gap-2">
                        <div className="flex-1 min-w-0 flex items-start gap-2">
                          {n.pinned && <AppIcon name="pin" size="xs" className="mt-1 text-amber-500 shrink-0" />}
                          <Truncate text={n.body} className="text-secondary-foreground" />
                        </div>
                        <TooltipProvider delayDuration={150}>
                          <div className="flex items-center gap-1 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => {
                                    setEditingNoteId(n.id);
                                    setEditBody(n.body);
                                  }}
                                  className="h-5 w-5 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300"
                                  aria-label="Edit note"
                                >
                                  <AppIcon name="edit" size="sm" />
                                </Button>
                              </TooltipTrigger>
                              <TooltipContent className="text-xs">Edit note</TooltipContent>
                            </Tooltip>

                            <Tooltip>
                              <TooltipTrigger asChild>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => togglePinMutation.mutate({ id: n.id, pinned: !n.pinned })}
                                  className={`h-5 w-5 ${n.pinned ? 'text-amber-500 hover:text-amber-600 hover:bg-amber-100 dark:hover:bg-amber-900/50' : 'text-neutral-400 hover:text-amber-500 hover:bg-amber-100 dark:hover:bg-amber-900/50'}`}
                                  aria-label={n.pinned ? "Unpin note" : "Pin note"}
                                >
                                  <AppIcon name="pin" size="sm" />
                                </Button>
                              </TooltipTrigger>
                              <TooltipContent className="text-xs">{n.pinned ? "Unpin" : "Pin to top"}</TooltipContent>
                            </Tooltip>

                            <Tooltip>
                              <TooltipTrigger asChild>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => setConfirmState({ isOpen: true, id: n.id })}
                                  className="h-5 w-5 text-neutral-400 hover:text-destructive hover:bg-destructive/10"
                                  aria-label="Delete note"
                                >
                                  <AppIcon name="trash" size="sm" />
                                </Button>
                              </TooltipTrigger>
                              <TooltipContent className="text-xs">Delete note</TooltipContent>
                            </Tooltip>
                          </div>
                        </TooltipProvider>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>
          </div>
        </CollapsibleContent>
      </Card>
      
      <ConfirmDialog
        open={confirmState.isOpen}
        onOpenChange={(open) => { if (!open) setConfirmState({ isOpen: false, id: null }) }}
        onConfirm={() => {
          if (confirmState.id) {
            deleteMutation.mutate(confirmState.id);
            setConfirmState({ isOpen: false, id: null });
          }
        }}
        title="Delete Note"
        description="Are you sure you want to delete this note?"
        isLoading={deleteMutation.isPending}
      />
    </Collapsible>
  );
}

"use client";

import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { apiFetch } from "@/lib/api-client";
import { formatDistanceToNow } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import { Card, CardHeader, CardTitle, CardContent, Button } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { STALE_TIME_METRICS, queryKeys } from "@/lib/query-keys";
import { WidgetInfo } from "./widget-info";

export function RecentActivityWidget() {
  const { data: activities = [], isPending, isFetching, isError, refetch } = useDashboardInit({
    select: (data: any) => {
      const list = data?.metrics?.recent_activity || data?.recent_activity;
      return Array.isArray(list) ? list : [];
    },
    staleTime: STALE_TIME_METRICS,
    placeholderData: keepPreviousData,
  });

  function safeFormatDistance(dateString: string | undefined | null) {
    if (!dateString) return "—";
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return "—";
    return formatDistanceToNow(date, { addSuffix: true });
  }

  return (
    <Card className="h-full flex flex-col bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl p-5 overflow-hidden transition-shadow duration-150">
      <div className="flex items-center justify-between pb-3">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-[var(--radius)] bg-primary-100 dark:bg-primary-950 flex items-center justify-center">
            <AppIcon name="activity" className=" text-primary-600 dark:text-primary-400" />
          </div>
          <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider flex items-center gap-1.5">
            Recent Activity Feed
            <WidgetInfo summary="Relevant user activity across the system" />
          </span>
          {isFetching && <AppIcon name="loading" size="xs" className=" animate-spin text-neutral-400" />}
        </div>
      </div>
      <div className="flex-1 overflow-y-auto thin-scrollbar">
        {activities.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
            <AppIcon name="activity" size="2xl" className=" text-neutral-300 dark:text-neutral-700 mb-2" />
            <h4 className="text-sm font-semibold text-neutral-900 dark:text-white">No recent activity</h4>
            <p className="text-xs text-neutral-400 mt-1">Activity will appear here once actions are taken.</p>
          </div>
        ) : (
          <div className="divide-y divide-neutral-100 dark:divide-neutral-800 -mx-5 px-5">
            {activities.map((activity: any) => (
              <div key={activity.id} className="py-2.5 hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors">
                <div className="flex justify-between items-start gap-2">
                  <p className="text-[11px] text-neutral-700 dark:text-neutral-300 leading-tight">
                    <span className="font-semibold text-neutral-900 dark:text-white">
                      {activity.user_name || 'System'}
                    </span>{" "}
                    <span className="text-neutral-500">
                      {activity.action} · {activity.subject_type}
                    </span>
                    {activity.after && (
                      <span className="block mt-0.5 text-[10px] text-neutral-400 truncate max-w-[280px]">
                        {typeof activity.after === 'string' ? activity.after : JSON.stringify(activity.after)}
                      </span>
                    )}
                  </p>
                  <span className="text-[10px] text-neutral-400 whitespace-nowrap mt-0.5">
                    {safeFormatDistance(activity.at)}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </Card>
  );
}

