"use client";

import { useEffect, useState, useRef } from "react";
import { cn } from "@/lib/utils";
import { AppIcon, IconName } from "@g4k/ui/components";
import { toast } from "sonner";
import { Button } from "@g4k/ui/components";
import { StatusBadge } from "@g4k/ui/components/badge";
import { apiFetch } from "@/lib/api-client";
import { queryKeys } from "@/lib/query-keys";
import { useQuery, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { offlineEngine } from "@/lib/offline-engine";
import {
  ConfirmDialog,
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@g4k/ui/components";

import { Skeleton } from "@g4k/ui/components";
import { useTimerStore } from "@/stores/timer-store";
import { LiveTimer } from "@/components/attendance/live-timer";

export function TimeClockWidget({ className }: { className?: string }) {

  const [showConfirmOut, setShowConfirmOut] = useState(false);
  const [showConfirmContinue, setShowConfirmContinue] = useState(false);
  const [standardSeconds, setStandardSeconds] = useState(31500); // default 8h45m
  const [isOffline, setIsOffline] = useState(typeof navigator !== 'undefined' ? !navigator.onLine : false);
  const [isPunching, setIsPunching] = useState(false);

  const queryClient = useQueryClient();

  const isActive = useTimerStore((s) => s.isActive);
  const isOnBreak = useTimerStore((s) => s.isOnBreak);
  const baseSeconds = useTimerStore((s) => s.baseSeconds);
  const lastActiveTimestamp = useTimerStore((s) => s.lastActiveTimestamp);
  const syncWithServer = useTimerStore((s) => s.syncWithServer);
  const startTimer = useTimerStore((s) => s.startTimer);
  const stopTimer = useTimerStore((s) => s.stopTimer);
  const startBreak = useTimerStore((s) => s.startBreak);
  const endBreak = useTimerStore((s) => s.endBreak);

  const { data: todayData, isPending, isFetching, isError, refetch } = useDashboardInit({
    select: (data: any) => data?.attendance_today ?? null,
    placeholderData: keepPreviousData,
  });

  useEffect(() => {
    if (todayData) {
      if (todayData.standard_seconds) {
        setStandardSeconds(todayData.standard_seconds);
      }
      syncWithServer(todayData.day, todayData.events || [], todayData.standard_seconds);
    }
  }, [todayData, syncWithServer]);

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  useEffect(() => {
    const handleSyncFail = () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    };
    window.addEventListener("attendance-sync-failed", handleSyncFail);
    return () => window.removeEventListener("attendance-sync-failed", handleSyncFail);
  }, [queryClient]);

  let activeState: "not_started" | "active" | "on_break" | "completed" = "not_started";
  if (isActive && !isOnBreak) activeState = "active";
  if (isOnBreak) activeState = "on_break";
  // `activeSeconds` logically means we have some accumulated time or active shift. 
  const hasWorked = baseSeconds > 0 || isActive;

  if (!isActive && !isOnBreak && hasWorked) activeState = "completed";
  if (!isActive && !isOnBreak && !hasWorked) activeState = "not_started";

  const handlePunch = async (type: string) => {
    // If local state is not_started, but todayData has a clock_in, reconcile instead of punching
    if (type === "clock_in" && activeState === "not_started" && todayData?.day?.clock_in) {
      syncWithServer(todayData.day, todayData.events || [], todayData.standard_seconds);
      return;
    }

    setIsPunching(true);
    // Optimistic UI state
    const timestamp = new Date().toISOString();

    // Check auto-end break on clock out
    if (type === "clock_out" && isOnBreak) {
      await offlineEngine.recordPunch("break_end", timestamp);
      endBreak(timestamp);
    }

    if (type === "clock_in") {
      startTimer(timestamp, 0);
    } else if (type === "end_break") {
      // resume ticking
      endBreak(timestamp);
    } else if (type === "start_break") {
      startBreak(timestamp);
    } else if (type === "clock_out") {
      stopTimer();
    }

    try {
      // Use OfflineEngine for resilience
      await offlineEngine.recordPunch(type === "end_break" ? "break_end" : type === "start_break" ? "break_start" : type, timestamp);

      // Re-fetch to ensure exact server state once online
      if (navigator.onLine) {
        queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
      }
      toast.success(`Recorded: ${type.replace("_", " ").toUpperCase()}`);
    } catch (err: any) {
      // Revert optimistic state on fatal error
      const msg = err.message || "Failed to record punch. Syncing with server...";
      if (msg.toLowerCase().includes("already")) {
        toast.warning(msg);
      } else {
        toast.error(msg);
      }
      if (todayData) {
        syncWithServer(todayData.day, todayData.events || [], todayData.standard_seconds);
      }
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit }); // Re-sync store state
    } finally {
      setIsPunching(false);
    }
  };



  return (
    <div className={cn("relative w-full h-full p-5 bg-card dark:bg-neutral-900 border shadow-e1 hover:shadow-e2 rounded-xl transition-shadow duration-150 flex flex-col justify-between", className)}>
      {isPending && !todayData && (
        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-surface/95 dark:bg-neutral-950/95 backdrop-blur-md rounded-xl p-6 gap-6">
          <div className="flex justify-between w-full">
            <Skeleton className="h-4 w-24" />
            <Skeleton className="h-6 w-20 rounded-full" />
          </div>
          <div className="flex-1 flex flex-col items-center justify-center space-y-4">
            <Skeleton className="h-16 w-48" />
            <Skeleton className="h-4 w-32" />
          </div>
          <div className="w-full flex gap-2">
            <Skeleton className="h-12 flex-1 rounded-xl" />
            <Skeleton className="h-12 flex-1 rounded-xl" />
          </div>
        </div>
      )}

      <div className="flex items-center justify-between pb-3">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-[var(--radius)] bg-primary-100 dark:bg-primary-950 flex items-center justify-center">
            <AppIcon name="teamAttendance" className=" text-primary-600 dark:text-primary-400" />
          </div>
          <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider">
            Time Clock
          </span>
          {isFetching && <AppIcon name="loading" size="xs" className=" animate-spin text-neutral-400" />}
          {isOffline ? (
            <span className="flex items-center gap-1 text-[10px] font-bold text-rose-600 uppercase tracking-wider bg-rose-50 dark:bg-rose-950/40 px-1.5 py-0.5 rounded ml-2">
              <AppIcon name="error" size="xs" /> Offline Mode
            </span>
          ) : isError && !todayData ? (
            <span className="flex items-center gap-1 text-[10px] font-bold text-rose-600 uppercase tracking-wider bg-rose-50 dark:bg-rose-950/40 px-1.5 py-0.5 rounded ml-2">
              <AppIcon name="error" size="xs" /> Connection Error
              <Button variant="link" onClick={() => refetch()} className="h-auto p-0 text-[10px] font-bold text-rose-600 hover:text-rose-700 ml-1">
                Retry
              </Button>
            </span>
          ) : null}
        </div>
        <StatusBadge
          status={
            activeState === "active" ? "success" :
              activeState === "on_break" ? "warning" :
                activeState === "completed" ? "info" : "neutral"
          }
          className="uppercase tracking-wider px-2.5 py-0.5 text-[10px]"
        >
          {activeState.replace("_", " ")}
        </StatusBadge>
      </div>

      <div className="my-4 text-center">
        <LiveTimer
          render={(formattedTime, displaySeconds) => {
            const isOvertime = displaySeconds > standardSeconds;

            // Format time difference nicely
            const formatTimeDiff = (secs: number) => {
              const h = Math.floor(secs / 3600);
              const m = Math.floor((secs % 3600) / 60);
              const s = secs % 60;
              return `${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
            };

            return (
              <>
                <div
                  className={cn(
                    "text-4xl sm:text-5xl font-mono font-bold tracking-tight tabular-nums transition-colors",
                    isOvertime ? "text-amber-500" : "text-neutral-900 dark:text-white"
                  )}
                >
                  {formattedTime}
                </div>
                {isOvertime && (
                  <p className="text-[11px] text-amber-500 font-medium mt-1">
                    Overtime Threshold Exceeded (+{formatTimeDiff(displaySeconds - standardSeconds)})
                  </p>
                )}
              </>
            );
          }}
        />
      </div>

      <div className="flex items-center justify-center gap-3">
        {activeState === "not_started" && (
          <Button
            disabled={isPunching}
            onClick={() => handlePunch("clock_in")}
            className="w-full h-12 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold gap-2 shadow"
          >
            <AppIcon name="play" />
            <span>Start Shift</span>
          </Button>
        )}

        {activeState === "active" && (
          <>
            <TooltipProvider delayDuration={150}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    disabled={isPunching}
                    onClick={() => handlePunch("start_break")}
                    variant="outline"
                    className="flex-1 h-12 border-warning/50 text-warning hover:bg-warning/10 gap-2"
                    aria-label="Pause Work Session"
                  >
                    <AppIcon name="break" />
                    <span>Pause for Break</span>
                  </Button>
                </TooltipTrigger>
                <TooltipContent className="text-xs">Pause Work Session</TooltipContent>
              </Tooltip>
            </TooltipProvider>

            <Button
              disabled={isPunching}
              onClick={() => setShowConfirmOut(true)}
              variant="destructive"
              className="flex-1 h-12 gap-2"
            >
              <AppIcon name="stop" />
              <span>End Shift</span>
            </Button>
          </>
        )}

        {activeState === "on_break" && (
          <TooltipProvider delayDuration={150}>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  disabled={isPunching}
                  onClick={() => handlePunch("end_break")}
                  className="w-full h-12 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold gap-2 shadow"
                  aria-label="Resume Work Session"
                >
                  <AppIcon name="play" />
                  <span>Resume Work</span>
                </Button>
              </TooltipTrigger>
              <TooltipContent className="text-xs">Resume Work Session</TooltipContent>
            </Tooltip>
          </TooltipProvider>
        )}

        {activeState === "completed" && (
          <Button
            disabled={isPunching}
            onClick={() => setShowConfirmContinue(true)}
            variant="outline"
            className="w-full h-12 border-emerald-600/50 text-emerald-700 dark:text-emerald-400 hover:bg-emerald-50 dark:hover:bg-emerald-950/50 font-semibold gap-2 shadow-e1 hover:shadow-e2 transition-shadow duration-150"
          >
            <AppIcon name="play" />
            <span>Continue Shift</span>
          </Button>
        )}
      </div>

      <ConfirmDialog
        open={showConfirmContinue}
        onOpenChange={setShowConfirmContinue}
        onConfirm={() => {
          setShowConfirmContinue(false);
          handlePunch("clock_in");
        }}
        title="Continue Shift?"
        description="You have already clocked out for today. Continuing your shift will resume your work session and add to your total hours."
        confirmText="Yes, Continue Shift"
      />

      {/* Clock Out Confirmation Dialog */}
      {/* Clock Out Confirmation Dialog */}
      <ConfirmDialog
        open={showConfirmOut}
        onOpenChange={setShowConfirmOut}
        onConfirm={() => {
          setShowConfirmOut(false);
          handlePunch("clock_out");
        }}
        title="Confirm End Shift"
        description="Are you sure you want to clock out for today? Total worked time will be submitted to HR."
        confirmText="Confirm Clock Out"
      >
        <div className="flex items-center gap-2 text-rose-600 mb-2">
          <AppIcon name="error" size="lg" />
          <span className="font-semibold text-sm">Action cannot be reversed</span>
        </div>
      </ConfirmDialog>
    </div>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { isAfter, startOfDay } from "date-fns";
import { AppIcon, IconName } from "@g4k/ui/components";
import Link from "next/link";
import { apiFetch } from "@/lib/api-client";
import { STALE_TIME_CONFIG, queryKeys } from "@/lib/query-keys";
import { safeFormat } from "@/lib/format";
import { Card, CardHeader, CardTitle, CardContent, Skeleton, Button } from "@g4k/ui/components";

export function UpcomingHolidaysWidget() {
  const currentYear = new Date().getFullYear();
  
  const { data: holidays, isLoading, isError, refetch } = useQuery({
    queryKey: queryKeys.holidays(currentYear),
    queryFn: () => apiFetch(`/holidays?year=${currentYear}`),
    staleTime: STALE_TIME_CONFIG,
  });

  const today = startOfDay(new Date());

  const upcomingList = Array.isArray(holidays) || Array.isArray(holidays?.data) 
    ? (holidays?.data || holidays)
      .filter((h: any) => {
        if (!h?.date) return false;
        const d = new Date(h.date);
        if (isNaN(d.getTime())) return false;
        return !isAfter(today, d);
      })
      .slice(0, 3)
    : [];

  return (
    <Card className="h-full bg-card dark:bg-neutral-900 border-neutral-200 dark:border-neutral-800 flex flex-col">
      <CardHeader className="border-b border-neutral-100 dark:border-neutral-800 pb-3 flex flex-row items-center justify-between">
        <CardTitle className="text-sm font-bold flex items-center gap-2">
          <AppIcon name="calendar" className=" text-primary" />
          Upcoming Holidays & Events
        </CardTitle>
        <Button variant="ghost" size="sm" asChild className="h-8 text-xs font-semibold text-primary">
          <Link href="/dashboard/org/leave">
            View All <AppIcon name="chevronRight" size="xs" className=" ml-1" />
          </Link>
        </Button>
      </CardHeader>
      <CardContent className="p-0 flex-1 overflow-y-auto">
        {isLoading ? (
          <div className="p-4 space-y-3">
            <Skeleton className="h-12 w-full rounded-[var(--radius)]" />
            <Skeleton className="h-12 w-full rounded-[var(--radius)]" />
            <Skeleton className="h-12 w-full rounded-[var(--radius)]" />
          </div>
        ) : isError ? (
          <div className="flex-1 flex flex-col items-center justify-center bg-rose-50/50 dark:bg-rose-950/10 rounded-[var(--radius)] p-4 m-4">
            <AppIcon name="warning" size="xl" className=" text-rose-400 mb-2" />
            <span className="text-[11px] text-rose-600 font-medium mb-2">Failed to load holidays</span>
            <Button variant="outline" size="sm" onClick={() => refetch()} className="h-6 text-[10px] px-2">
              Retry
            </Button>
          </div>
        ) : upcomingList.length === 0 ? (
          <div className="p-6 text-center text-sm text-neutral-500">
            No upcoming holidays or events
          </div>
        ) : (
          <div className="divide-y divide-neutral-100 dark:divide-neutral-800">
            {upcomingList.map((holiday: any, idx: number) => {
              const isEvent = holiday.type === 'event';
              return (
                <div key={idx} className="p-4 hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors">
                  <div className="flex items-center justify-between mb-1">
                    <h4 className="text-sm font-bold">{holiday.name}</h4>
                    <span className={`text-[10px] uppercase font-bold tracking-wider px-2 py-0.5 rounded-full ${
                      isEvent 
                        ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' 
                        : 'bg-primary-100 text-primary-700 dark:bg-primary-900/30 dark:text-primary-400'
                    }`}>
                      {isEvent ? 'Event' : 'Holiday'}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-xs font-semibold text-neutral-600 dark:text-neutral-400">
                    {safeFormat(holiday.date, "MMM d, yyyy")}
                  </div>
                  {isEvent && (holiday.start_time || holiday.location) && (
                    <div className="flex items-center gap-3 mt-1.5 text-[11px] text-neutral-500">
                      {holiday.start_time && (
                        <div className="flex items-center gap-1"><AppIcon name="teamAttendance" size="xs" /> {holiday.start_time}</div>
                      )}
                      {holiday.location && (
                        <div className="flex items-center gap-1"><AppIcon name="location" size="xs" /> {holiday.location}</div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import dynamic from "next/dynamic";
import { useQuery } from "@tanstack/react-query";
import { useDashboardInit } from "@/hooks/use-dashboard-init";
import { apiFetch } from "@/lib/api-client";
import { reconcileLayout, GRID_COLS } from "@/lib/reconcile-layout";
import { queryKeys } from "@/lib/query-keys";
import { ErrorBoundary, AppIcon } from "@g4k/ui/components";
import { Skeleton } from "@g4k/ui/components";
import { useUIStore } from "@/lib/ui-store";
import { useShallow } from "zustand/react/shallow";

import { Responsive as ResponsiveGridLayout, WidthProvider } from "react-grid-layout/legacy";
import "react-grid-layout/css/styles.css";
import "react-resizable/css/styles.css";

const ResponsiveGridWithWidth = WidthProvider(ResponsiveGridLayout);
const GridLayout = dynamic(() => Promise.resolve({ default: ResponsiveGridWithWidth }), { ssr: false }) as any;

interface WidgetEngineProps {
  availableWidgets: Array<{
    id: string;
    component: React.ReactNode;
    defaultLayout: any;
  }>;
}

export function WidgetEngine({ availableWidgets }: WidgetEngineProps) {
  const [layouts, setLayouts] = useState<any>(() => ({
    lg: availableWidgets.map((w) => ({ ...(w.defaultLayout?.lg || w.defaultLayout), i: w.id })),
    md: availableWidgets.map((w) => ({ ...(w.defaultLayout?.md || w.defaultLayout), i: w.id })),
    sm: availableWidgets.map((w) => ({ ...(w.defaultLayout?.sm || w.defaultLayout), i: w.id })),
    xs: availableWidgets.map((w) => ({ ...(w.defaultLayout?.xs || w.defaultLayout), i: w.id })),
    xxs: availableWidgets.map((w) => ({ ...(w.defaultLayout?.xxs || w.defaultLayout), i: w.id })),
  }));
  const [mounted, setMounted] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const { widgetStates } = useUIStore(useShallow((s) => ({
    widgetStates: s.widgetStates,
  })));
  
  const draggingRef = useRef(false);
  const startPosRef = useRef({ x: 0, y: 0 });
  const layoutTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const dragStopTimerRef = useRef<NodeJS.Timeout | null>(null);
  const isDirtyRef = useRef(false);

  const { data: preferencesData } = useDashboardInit({
    select: (data: any) => data?.preferences ?? null,
    staleTime: 60_000,
  });

  // Dynamically recalculate heights when widgets collapse/expand (UX-11)
  const computedLayouts = useMemo(() => {
    if (!layouts || Object.keys(layouts).length === 0) return layouts;
    const result: any = {};
    Object.keys(layouts).forEach((bp) => {
      const items = layouts[bp] || [];
      result[bp] = items.map((item: any) => {
        const isCollapsed = widgetStates[item.i]?.collapsed ?? false;
        if (isCollapsed) {
          return { ...item, h: 1, minH: 1, maxH: 1 };
        }
        // If uncollapsed, restore original height if currently stuck at h: 1
        const defaultWidget = Array.isArray(availableWidgets) ? availableWidgets.find((w) => w.id === item.i) : undefined;
        const normalHeight = defaultWidget?.defaultLayout?.h || 3;
        const currentH = item.h === 1 ? normalHeight : item.h;
        return { ...item, h: currentH, minH: undefined, maxH: undefined };
      });
    });
    return result;
  }, [layouts, widgetStates, availableWidgets]);

  // Prevent accidental clicks on widget content during/immediately after dragging with distance threshold (UX-9)
  useEffect(() => {
    const handleMouseDown = (e: MouseEvent) => {
      startPosRef.current = { x: e.clientX, y: e.clientY };
    };

    const captureClick = (e: MouseEvent) => {
      const dx = Math.abs(e.clientX - startPosRef.current.x);
      const dy = Math.abs(e.clientY - startPosRef.current.y);
      const moved = dx > 5 || dy > 5;

      if (draggingRef.current || moved) {
        e.stopPropagation();
        e.preventDefault();
      }
    };

    document.addEventListener("mousedown", handleMouseDown, true);
    document.addEventListener("click", captureClick, true);
    return () => {
      document.removeEventListener("mousedown", handleMouseDown, true);
      document.removeEventListener("click", captureClick, true);
    };
  }, []);

  useEffect(() => {
    setMounted(true);
    if (!preferencesData) return;

    // T-33.3: Canonical read path + Schema versioning
    let savedLayoutsRaw = preferencesData.dashboard_layout || preferencesData.preferences?.dashboard_layout;
    
    // Migrator for unversioned layouts
    let savedLayouts = null;
    if (savedLayoutsRaw) {
      if (savedLayoutsRaw.version === 1 && savedLayoutsRaw.layouts) {
        savedLayouts = savedLayoutsRaw.layouts;
      } else if (!savedLayoutsRaw.version) {
        // Legacy unversioned
        savedLayouts = savedLayoutsRaw;
      }
    }

    const mergedBreakpoints = reconcileLayout(savedLayouts, availableWidgets as any, GRID_COLS);

    if (mergedBreakpoints) {
      setLayouts((prev: any) => JSON.stringify(prev) === JSON.stringify(mergedBreakpoints) ? prev : mergedBreakpoints);
    }
  }, [preferencesData, availableWidgets]);

  const handleLayoutChange = (_currentLayout: any, allLayouts: any) => {
    const isDifferent = JSON.stringify(layouts) !== JSON.stringify(allLayouts);
    if (!isDifferent) return; // Prevent unnecessary re-renders (Fix for #2)

    setLayouts((prev: any) => (JSON.stringify(prev) === JSON.stringify(allLayouts) ? prev : allLayouts));
    
    // Suppress persistence until (a) preferences loaded AND (b) user interacted
    if (!preferencesData || !isDirtyRef.current) return;

    if (layoutTimeoutRef.current) {
      clearTimeout(layoutTimeoutRef.current);
    }
    // Debounce layout save API call to prevent spamming on drag (UX-10)
    layoutTimeoutRef.current = setTimeout(async () => {
      try {
        await apiFetch("/auth/preferences", {
          method: "PUT",
          body: JSON.stringify({
            preferences: { 
              dashboard_layout: { version: 1, layouts: allLayouts } 
            },
          }),
        });
      } catch {
        // Ignore layout save errors silently
      }
    }, 500);
  };

  const handleDragStart = () => {
    if (dragStopTimerRef.current) clearTimeout(dragStopTimerRef.current);
    draggingRef.current = true;
    setIsDragging(true);
    isDirtyRef.current = true;
  };

  const handleDragStop = () => {
    dragStopTimerRef.current = setTimeout(() => {
      draggingRef.current = false;
      setIsDragging(false);
    }, 150);
  };

  const handleResizeStart = () => {
    isDirtyRef.current = true;
  };

  return (
    <div className={`w-full min-h-[500px] ${isDragging ? "is-dragging-widget" : ""}`}>
      <style>{`
        .is-dragging-widget a,
        .is-dragging-widget button,
        .is-dragging-widget [role="button"] {
          pointer-events: none !important;
        }
        .react-resizable-handle {
          opacity: 0;
          transition: opacity 0.2s;
        }
        .react-grid-item:hover .react-resizable-handle {
          opacity: 1;
        }
      `}</style>
      <GridLayout
        className="layout"
        layouts={computedLayouts}
        breakpoints={{ lg: 1200, md: 996, sm: 768, xs: 480, xxs: 0 }}
        cols={GRID_COLS}
        rowHeight={120}
        onLayoutChange={handleLayoutChange}
        onDragStart={handleDragStart}
        onDragStop={handleDragStop}
        margin={[16, 16] as [number, number]}
        draggableHandle=".widget-drag-handle"
      >
        {availableWidgets.map((widget) => (
          <div key={widget.id} className="h-full group/widget relative">
            <div className="absolute top-2 right-2 opacity-0 group-hover/widget:opacity-100 transition-opacity z-10 flex items-center gap-1">
              <div className="widget-drag-handle cursor-grab active:cursor-grabbing p-1 bg-black/5 dark:bg-white/10 rounded flex items-center justify-center shadow-sm">
                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-neutral-500">
                  <circle cx="9" cy="12" r="1" />
                  <circle cx="9" cy="5" r="1" />
                  <circle cx="9" cy="19" r="1" />
                  <circle cx="15" cy="12" r="1" />
                  <circle cx="15" cy="5" r="1" />
                  <circle cx="15" cy="19" r="1" />
                </svg>
              </div>
            </div>
            <ErrorBoundary name={`Widget-${widget.id}`}>
              {widget.component}
            </ErrorBoundary>
          </div>
        ))}
      </GridLayout>
    </div>
  );
}

