import { useState, useCallback, useEffect } from "react";
import { toast } from "sonner";
import { apiFetch } from "@/lib/api-client";
import { useReverb } from "./use-reverb";

export function useExport() {
  const [isExporting, setIsExporting] = useState(false);
  const [downloadUrls, setDownloadUrls] = useState<string[]>([]);
  const { subscribe } = useReverb();

  // Cleanup object URLs on unmount
  useEffect(() => {
    return () => {
      downloadUrls.forEach((url) => {
        // eslint-disable-next-line no-restricted-syntax
        URL.revokeObjectURL(url);
      });
    };
  }, [downloadUrls]);

  const triggerExport = useCallback(
    async (endpoint: string, filename: string, options?: any) => {
      setIsExporting(true);
      const toastId = toast.loading(`Generating export for ${filename}...`);
      
      try {
        const fetchOptions = {
          method: "GET",
          ...options
        };
        const response = await apiFetch(endpoint, fetchOptions);

        // If backend does immediate mock return for now (before real Queue is ready):
        if (response instanceof Blob) {
          // eslint-disable-next-line no-restricted-syntax
          const url = URL.createObjectURL(response);
          setDownloadUrls((prev) => [...prev, url]);
          const a = document.createElement("a");
          a.href = url;
          a.download = filename;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          toast.success(`Export ${filename} ready.`, { id: toastId });
          setIsExporting(false);
          return;
        }

        // apiFetch already parses the JSON if it's not a Blob
        const data = response;

        if (data.job_id) {
          toast.success(`Export queued (Job ${data.job_id}).`, { 
            id: toastId,
            description: "Check the Export history later.",
            action: { label: "View Exports", onClick: () => window.location.href = "/dashboard/reports?tab=exports" }
          });
          setIsExporting(false);
        } else if (data.message === "Export queued") {
          toast.success(`Export queued.`, { 
            id: toastId,
            description: "Check the Export history later.",
            action: { label: "View Exports", onClick: () => window.location.href = "/dashboard/reports?tab=exports" }
          });
          setIsExporting(false);
        } else {
          toast.success(`Export completed.`, { id: toastId });
          setIsExporting(false);
        }
      } catch (error: any) {
        toast.error(error.message || "Failed to start export.", { id: toastId });
        setIsExporting(false);
      }
    },
    []
  );

  return { triggerExport, isExporting };
}

"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import { toast } from "sonner";
import { openDB } from "idb";

const initDB = async () => {
  return openDB('g4k-form-drafts', 1, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('drafts')) {
        db.createObjectStore('drafts');
      }
    },
  });
};

export function useFormDraft<T extends Record<string, any>>(key: string, initialValues: T) {
  const [formData, setFormData] = useState<T>(initialValues);
  const [hasDraft, setHasDraft] = useState(false);
  const dataRef = useRef(formData);

  useEffect(() => {
    dataRef.current = formData;
  }, [formData]);

  // Check draft on mount
  useEffect(() => {
    const checkDraft = async () => {
      try {
        const db = await initDB();
        const saved = await db.get('drafts', key);
        if (saved) {
          setHasDraft(true);
        }
      } catch (e) {
        // Ignore parse errors
      }
    };
    checkDraft();
  }, [key]);

  // 30-second autosave timer
  useEffect(() => {
    const timer = setInterval(async () => {
      const currentData = dataRef.current;
      if (currentData && Object.keys(currentData).some((k) => currentData[k] !== initialValues[k])) {
        try {
          const db = await initDB();
          await db.put('drafts', currentData, key);
        } catch (e) {
          console.error("Failed to autosave draft", e);
        }
      }
    }, 30000);

    return () => clearInterval(timer);
  }, [key, initialValues]);

  const saveDraft = useCallback(async () => {
    try {
      const db = await initDB();
      await db.put('drafts', formData, key);
      setHasDraft(true);
      toast.success("Draft saved");
    } catch (e) {
      toast.error("Failed to save draft");
    }
  }, [key, formData]);

  const restoreDraft = useCallback(async () => {
    try {
      const db = await initDB();
      const saved = await db.get('drafts', key);
      if (saved) {
        setFormData(saved);
        toast.info("Form draft restored!");
      }
    } catch {
      toast.error("Failed to restore draft");
    }
  }, [key]);

  const clearDraft = useCallback(async () => {
    try {
      const db = await initDB();
      await db.delete('drafts', key);
      setHasDraft(false);
    } catch (e) {
      console.error("Failed to clear draft", e);
    }
  }, [key]);

  return {
    formData,
    setFormData,
    hasDraft,
    saveDraft,
    restoreDraft,
    clearDraft,
  };
}

import { useState } from "react";

export function useFormErrors() {
  const [fieldErrors, setFieldErrors] = useState<Record<string, string[]>>({});

  const setErrorsFromResponse = (err: any) => {
    if (err?.errors) {
      setFieldErrors(err.errors);
    } else {
      setFieldErrors({});
    }
  };

  const clearErrors = () => setFieldErrors({});

  return {
    fieldErrors,
    setFieldErrors,
    setErrorsFromResponse,
    clearErrors,
  };
}

