  const [confirmState, setConfirmState] = useState<{ isOpen: boolean; type: string; payload?: any }>({ isOpen: false, type: "" });
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<any>(null);

  const updateMutation = useMutation({
    mutationFn: ({ id, payload }: { id: number; payload: any }) => apiFetch(`/users/${id}`, { method: "PUT", body: JSON.stringify(payload) }),
    onSuccess: (_, variables) => {
      toast.success("User updated successfully!");
      setIsEditOpen(false);
      queryClient.invalidateQueries({ queryKey: queryKeys.usersPaginated() });
      queryClient.invalidateQueries({ queryKey: ["user", variables.id] });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
    onError: (err: any) => toast.error(err.message || "Failed to update user."),
  });

  const statusMutation = useMutation({
    mutationFn: ({ id, status }: any) => apiFetch(`/users/${id}/status`, { method: "PATCH", body: JSON.stringify({ status }) }),
    onSuccess: (_, variables) => {
      toast.success("User status updated.");
      setConfirmState({ isOpen: false, type: "" });
      queryClient.invalidateQueries({ queryKey: queryKeys.usersPaginated() });
      queryClient.invalidateQueries({ queryKey: ["user", variables.id] });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
    onError: (err: any) => toast.error(err.message || "Failed to update status."),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => apiFetch(`/users/${id}`, { method: "DELETE" }),
    onSuccess: (_, variables) => {
      toast.success("User deleted.");
      setConfirmState({ isOpen: false, type: "" });
      queryClient.invalidateQueries({ queryKey: queryKeys.usersPaginated() });
      queryClient.invalidateQueries({ queryKey: ["user", variables] });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
    onError: (err: any) => toast.error(err.message || "Failed to delete user."),
  });

  const restoreMutation = useMutation({
    mutationFn: (id: number) => apiFetch(`/users/${id}/restore`, { method: "POST" }),
    onSuccess: (_, variables) => {
      toast.success("User restored successfully.");
      setConfirmState({ isOpen: false, type: "" });
      queryClient.invalidateQueries({ queryKey: queryKeys.usersPaginated() });
      queryClient.invalidateQueries({ queryKey: ["user", variables] });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    },
    onError: (err: any) => toast.error(err.message || "Failed to restore user."),
  });

  const resetPasswordMutation = useMutation({
    mutationFn: (id: number) => apiFetch(`/users/${id}/reset-password`, { method: "POST" }),
    onSuccess: (res: any) => {
      toast.success(res.message || "Password reset to default.");
      setConfirmState({ isOpen: false, type: "" });
    },
    onError: (err: any) => toast.error(err.message || "Failed to reset password."),
  });

  return {
    confirmState,
    setConfirmState,
    isEditOpen,
    setIsEditOpen,
    editingUser,
    setEditingUser,
    updateMutation,
    statusMutation,
    deleteMutation,
    restoreMutation,
    resetPasswordMutation,
  };
}

import { useState, useCallback, useRef, useEffect } from 'react';

type WorkerFunction<T, R> = (input: T) => R;

/**
 * Creates an inline web worker to offload heavy calculations from the main thread.
 * Ensure the passed function doesn't rely on closures or external scope.
 */
export function useWorker<T, R>(workerFn: WorkerFunction<T, R>) {
  const [result, setResult] = useState<R | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const workerRef = useRef<Worker | null>(null);
  const urlRef = useRef<string | null>(null);

  useEffect(() => {
    // Generate inline worker Blob URL
    const code = `
      self.onmessage = function(e) {
        const result = (${workerFn.toString()})(e.data);
        self.postMessage(result);
      }
    `;
    const blob = new Blob([code], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    urlRef.current = workerUrl;

    workerRef.current = new Worker(workerUrl);

    workerRef.current.onmessage = (e: MessageEvent<R>) => {
      setResult(e.data);
      setIsProcessing(false);
    };

    workerRef.current.onerror = (e) => {
      setError(new Error(e.message));
      setIsProcessing(false);
    };

    return () => {
      // Cleanup on unmount
      workerRef.current?.terminate();
      if (urlRef.current) {
        URL.revokeObjectURL(urlRef.current);
      }
    };
  }, [workerFn]);

  const processData = useCallback((data: T) => {
    if (workerRef.current) {
      setIsProcessing(true);
      setError(null);
      workerRef.current.postMessage(data);
    }
  }, []);

  return { processData, result, isProcessing, error };
}

import { useAuthStore, getAuthToken } from "./auth-store";
import { offlineEngine } from "./offline-engine";
import { toast } from "sonner";

let API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "/api";
if (API_BASE_URL.startsWith("http") && !API_BASE_URL.endsWith("/api")) {
  API_BASE_URL = `${API_BASE_URL.replace(/\/$/, "")}/api`;
}

export function getToken(): string | null {
  return getAuthToken();
}

/**
 * Standardize single resource responses.
 * @param res The API response
 * @returns The unwrapped resource
 */
export function unwrapOne<T = any>(res: any): T {
  if (res && typeof res === "object" && "data" in res) {
    if (res.data && typeof res.data === "object" && !Array.isArray(res.data) && "id" in res.data) {
      return res.data as T;
    }
  }
  return res as T;
}

/**
 * Standardize list responses.
 * @param res The API response
 * @returns The unwrapped array
 */
export function unwrapList<T = any>(res: any): T[] {
  if (!res) return [];
  if (Array.isArray(res)) return res;
  if (Array.isArray(res.data)) return res.data;
  if (res.data && Array.isArray(res.data.data)) return res.data.data;
  return [];
}



let refreshPromise: Promise<string> | null = null;

export async function apiFetch<T = any>(
  endpoint: string,
  options: RequestInit = {},
  bypassQueue = false
): Promise<T> {
  const token = getAuthToken();

  const headers = new Headers(options.headers || {});

  if (!headers.has("Content-Type") && !(options.body instanceof FormData)) {
    headers.set("Content-Type", "application/json");
  }

  if (!headers.has("Accept")) {
    headers.set("Accept", "application/json");
  }

  if (token) {
    headers.set("Authorization", `Bearer ${token}`);
  }

  const url = endpoint.startsWith("http")
    ? endpoint
    : `${API_BASE_URL.replace(/\/$/, "")}/${endpoint.replace(/^\//, "")}`;

  const isGet = !options.method || options.method.toUpperCase() === 'GET';

  const isAuthEndpoint =
    endpoint.includes("/auth/login") ||
    endpoint.includes("/auth/forgot-password") ||
    endpoint.includes("/auth/reset-password") ||
    endpoint.includes("/auth/refresh");

  if (!isAuthEndpoint && !isGet && !bypassQueue && typeof navigator !== 'undefined' && !navigator.onLine) {
    toast.warning("You are offline. Action queued.");
    await offlineEngine.queueRequest(endpoint, options);
    return { queued: true } as any;
  }

  try {
      const response = await fetch(url, {
        ...options,
        headers,
        credentials: "include", // Ensure cookies (like g4k_refresh_token) are passed
      });

      if (!response.ok) {
        // Auth endpoints (login/forgot/reset) own their 401 handling — never intercept.
        // A 401 on these means "invalid credentials", not "expired session".
        if (response.status === 401 && !isAuthEndpoint) {
          // Session may have expired — attempt ONE silent refresh via the HttpOnly cookie.
          // Mutex prevents concurrent 401 requests from making redundant refresh calls.
          try {
            if (!refreshPromise) {
              refreshPromise = (async () => {
                const refreshUrl = `${API_BASE_URL.replace(/\/$/, "")}/auth/refresh`;
                const refreshRes = await fetch(refreshUrl, {
                  method: "GET",
                  headers: {
                    "Accept": "application/json",
                    "X-Refresh-Token": useAuthStore.getState().refreshToken || "",
                  },
                  credentials: "include",
                });

                if (!refreshRes.ok) {
                  throw new Error("Refresh failed");
                }

                const data = await refreshRes.json();
                useAuthStore.getState().setAuth(data.token, data.user, data.active_role, data.refresh_token, data.capabilities);
                return data.token as string;
              })().finally(() => {
                refreshPromise = null;
              });
            }

            const newToken = await refreshPromise;

            // Retry the original request with the fresh token.
            headers.set("Authorization", `Bearer ${newToken}`);
            const retryRes = await fetch(url, {
              ...options,
              headers,
              credentials: "include",
            });

            if (retryRes.ok) {
              return await retryRes.json();
            }
          } catch {
            // refresh failed — fall through to clearing auth
          }

          // Refresh failed or retry still 401 → clear (AuthGuard will redirect).
          useAuthStore.getState().clearAuth();
          if (typeof window !== "undefined") {
            window.location.href = "/login?reason=expired";
          }
          throw new Error("Session expired. Please log in again.");
        }

        // No client-side fetch retries (React Query handles GET retries)

        const errorData = await response.json().catch(() => ({}));

        if (response.status === 403) {
          if (errorData.needs_onboarding) {
            const curUser = useAuthStore.getState().user;
            const curToken = getAuthToken();
            if (curUser && curToken) {
              useAuthStore.getState().setAuth(curToken, { ...curUser, onboarded_at: null }, curUser.active_role || 'employee');
            }
          } else if (errorData.must_change_password) {
            const curUser = useAuthStore.getState().user;
            const curToken = getAuthToken();
            if (curUser && curToken) {
              useAuthStore.getState().setAuth(curToken, { ...curUser, must_change_password: true }, curUser.active_role || 'employee');
            }
          }
        }

        let msg = errorData.message || `Request failed with status ${response.status}`;
        if (response.status === 422 && errorData.errors) {
          msg = Object.values(errorData.errors).flat().join(', ') || msg;
        }
        const error = new Error(msg) as any;
        error.status = response.status;
        error.data = errorData;
        if (errorData.errors) {
          error.errors = errorData.errors;
        }
        throw error;
      }

      if (typeof window !== "undefined" && token && !isAuthEndpoint) {
        document.cookie = `g4k_token=${token}; path=/; max-age=604800; SameSite=Lax`;
      }

      const contentType = response.headers.get("content-type");
      if (contentType && (
        contentType.includes("text/csv") ||
        contentType.includes("application/pdf") ||
        contentType.includes("application/vnd.openxmlformats-officedocument") ||
        contentType.includes("application/octet-stream") ||
        contentType.includes("application/vnd.ms-excel")
      )) {
        return (await response.blob()) as unknown as T;
      }

      const data = await response.json();
      
      // Contract completion: If API returns a bare array, wrap it to match standard Laravel paginated/resource structure
      if (Array.isArray(data)) {
        return { data } as unknown as T;
      }
      
      return data;
    } catch (error: any) {
      // Intercept offline / network failures for mutations (NOT 5xx server errors)
      const isNetworkError = error?.message?.includes("Failed to fetch") || (typeof navigator !== "undefined" && !navigator.onLine);
      if (!isAuthEndpoint && !isGet && !bypassQueue && isNetworkError) {
        toast.warning("Network error. Action queued for sync.");
        await offlineEngine.queueRequest(endpoint, options);
        return { queued: true } as any;
      }

      throw error;
    }
}

import { create } from "zustand";
import { persist } from "zustand/middleware";

export interface UserProfile {
  id: number;
  name: string;
  email: string;
  username?: string;
  employee_id?: string;
  must_change_password?: boolean;
  onboarded_at?: string | null;
  active_status: string;
  preferences?: {
    theme_mode?: string;
    density?: string;
    directory_visibility?: string;
    [key: string]: any;
  };
  active_role?: string;
  roles?: string[];
  role_assignments?: any[];
  department?: any;
  designation?: any;
  company?: any;
}

interface AuthState {
  token: string | null;
  refreshToken: string | null;
  user: UserProfile | null;
  activeRole: string | null;
  density: "comfortable" | "compact";
  setAuth: (token: string, user: UserProfile, activeRole?: string, refreshToken?: string, capabilities?: string[], broadcast?: boolean) => void;
  setDensity: (density: "comfortable" | "compact") => void;
  clearAuth: (broadcast?: boolean) => void;
}

let authChannel: BroadcastChannel | null = null;
if (typeof window !== "undefined") {
  authChannel = new BroadcastChannel("g4k_auth_sync");
}


export const useAuthStore = create<AuthState>()(
  persist(
    (set) => ({
      token: null,
      refreshToken: null,
      user: null,
      activeRole: null,
      density: "compact",
      setAuth: (token, user, activeRole, refreshToken, capabilities, broadcast = true) => {
        if (typeof window !== "undefined") {
          document.cookie = `g4k_token=${token}; path=/; max-age=604800; SameSite=Lax`;
          if (capabilities && Array.isArray(capabilities)) {
            try {
              const encoded = encodeURIComponent(JSON.stringify(capabilities));
              document.cookie = `g4k_capabilities=${encoded}; path=/; max-age=604800; SameSite=Lax`;
            } catch {}
          }
          if (broadcast && authChannel) {
            authChannel.postMessage({ type: "LOGIN" });
          }
        }
        return set((state) => ({
          token,
          refreshToken: refreshToken ?? state.refreshToken,
          user,
          activeRole: activeRole || user.active_role || user.roles?.[0] || "employee",
        }));
      },
      setDensity: (density) => set({ density }),
      clearAuth: (broadcast = true) => {
        if (typeof window !== "undefined") {
          document.cookie = `g4k_token=; path=/; max-age=0; SameSite=Lax`;
          document.cookie = `g4k_capabilities=; path=/; max-age=0; SameSite=Lax`;
          if (broadcast && authChannel) {
            authChannel.postMessage({ type: "LOGOUT" });
          }
        }
        return set({ token: null, refreshToken: null, user: null, activeRole: null });
      },
    }),
    {
      name: "g4k-auth",
      skipHydration: true,
    }
  )
);

if (typeof window !== "undefined" && authChannel) {
  authChannel.onmessage = (event) => {
    if (event.data?.type === "LOGOUT") {
      useAuthStore.getState().clearAuth(false);
      window.location.href = "/login?reason=logged_out";
    } else if (event.data?.type === "LOGIN") {
      window.location.reload();
    }
  };
}

export const getAuthToken = () => useAuthStore.getState().token;

import { useQuery } from "@tanstack/react-query";
import { apiFetch } from "./api-client";
import { useAuthStore } from "./auth-store";
import { queryKeys } from "./query-keys";

export function useCapabilities() {
  const token = useAuthStore((state) => state.token);

  return useQuery({
    queryKey: queryKeys.capabilities(),
    queryFn: async () => {
      if (!token) return [];
      try {
        const res = await apiFetch("/me/capabilities");
        if (!res.capabilities) {
          return [];
        }
        if (typeof window !== "undefined") {
          document.cookie = `g4k_capabilities=${encodeURIComponent(JSON.stringify(res.capabilities))}; path=/; max-age=604800; SameSite=Lax`;
        }
        return res.capabilities;
      } catch (err) {
        throw err;
      }
    },
    enabled: !!token,
    staleTime: 1000 * 60 * 30, // 30 minutes
  });
}

const SELF_SERVICE_EXCLUDED = ["attendance.clock-self"] as const;

export function hasCapability(capabilities: string[] = [], requiredCapability: string): boolean {
  if (SELF_SERVICE_EXCLUDED.includes(requiredCapability as any)) {
    return capabilities.includes(requiredCapability);
  }
  if (capabilities.includes("*")) {
    return true;
  }
  return capabilities.includes(requiredCapability);
}

import { queryKeys } from "./query-keys";
import { QueryClient } from "@tanstack/react-query";

/**
 * Maps logical entity mutations to the query keys that need to be invalidated.
 * Used to ensure all dependent views refresh automatically without manual reloads.
 */
export const invalidationMap: Record<string, (queryClient: QueryClient, payload?: any) => void> = {
  // --- Users & Auth ---
  "user.crud": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.usersList });
    qc.invalidateQueries({ queryKey: queryKeys.usersSelectList });
    qc.invalidateQueries({ queryKey: ["users"] });
    qc.invalidateQueries({ queryKey: queryKeys.directory() });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
  },

  // --- Attendance ---
  "attendance.punch": (qc, payload) => {
    qc.invalidateQueries({ queryKey: queryKeys.attendanceToday });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardMetrics });
    qc.invalidateQueries({ queryKey: queryKeys.myAttendanceHistory() });
    if (payload?.userId && payload?.date) {
      qc.invalidateQueries({ queryKey: queryKeys.memberAttendanceDay(payload.userId, payload.date) });
      qc.invalidateQueries({ queryKey: queryKeys.attendanceDayDetail(payload.date, payload.userId) });
    }
  },

  // --- Leave & Approvals ---
  "approval.decision": (qc) => {
    qc.invalidateQueries({ queryKey: ["my-leave-history"] });
    qc.invalidateQueries({ queryKey: ["team-leave-approvals"] });
    qc.invalidateQueries({ queryKey: ["org-leave-requests"] });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    qc.invalidateQueries({ queryKey: queryKeys.tasks });
    qc.invalidateQueries({ queryKey: ["projects"] });
  },
  "leave.decision": (qc) => {
    qc.invalidateQueries({ queryKey: ["my-leave-history"] });
    qc.invalidateQueries({ queryKey: ["team-leave-approvals"] });
    qc.invalidateQueries({ queryKey: ["org-leave-requests"] });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    // Balance invalidation would go here when implemented
  },
  "leave.request": (qc) => {
    qc.invalidateQueries({ queryKey: ["my-leave-history"] });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
  },

  // --- Projects & Tasks ---
  "project.crud": (qc, payload) => {
    qc.invalidateQueries({ queryKey: ["projects"] });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
    if (payload?.id) {
      qc.invalidateQueries({ queryKey: queryKeys.project(payload.id) });
    }
  },
  "task.crud": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.tasks });
    qc.invalidateQueries({ queryKey: ["projects"] });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
  },

  // --- Communications ---
  "announcement.crud": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.announcements });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
  },
  "notification.read": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.unreadCount });
    qc.invalidateQueries({ queryKey: ["notifications"] });
  },
  "notification.new": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.unreadCount });
    qc.invalidateQueries({ queryKey: ["notifications"] });
  },

  // --- Configuration ---
  "settings.update": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.settings });
    qc.invalidateQueries({ queryKey: queryKeys.companyProfile });
  },
  "department.crud": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.departments });
    qc.invalidateQueries({ queryKey: ["departments-paginated"] });
    qc.invalidateQueries({ queryKey: queryKeys.dashboardInit });
  },
  "designation.crud": (qc) => {
    qc.invalidateQueries({ queryKey: queryKeys.designations });
    qc.invalidateQueries({ queryKey: ["designations"] });
  }
};

/**
 * Helper to trigger invalidation for a specific event
 */
export function triggerInvalidation(queryClient: QueryClient, eventName: keyof typeof invalidationMap, payload?: any) {
  const handler = invalidationMap[eventName];
  if (handler) {
    handler(queryClient, payload);
  } else {
    console.warn(`[InvalidationMap] No handler found for event: ${eventName}`);
  }
}

import { openDB, DBSchema, IDBPDatabase } from 'idb';
import { apiFetch } from './api-client';
import { toast } from 'sonner';
import { create } from 'zustand';

// Store for observing queue length
export const useOfflineStore = create<{ queueCount: number; setQueueCount: (n: number) => void }>((set) => ({
  queueCount: 0,
  setQueueCount: (n) => set({ queueCount: n }),
}));

export interface GenericRequest {
  id: string;
  endpoint: string;
  options: {
    method: string;
    headers?: Record<string, string>;
    body?: string;
  };
  syncStatus: 'pending' | 'synced' | 'failed' | 'conflict';
  addedAt: number;
  retryCount: number;
  lastRetry?: number;
}

interface AttendanceDB extends DBSchema {
  punches: {
    value: {
      client_id: string;
      type: string;
      timestamp: string;
      syncStatus: 'pending' | 'synced' | 'failed';
    };
    key: string;
    indexes: { 'by-status': string };
  };
  requests: {
    value: GenericRequest;
    key: string;
    indexes: { 'by-status': string };
  }
}

class OfflineEngine {
  private dbPromise: Promise<IDBPDatabase<AttendanceDB>> | null = null;
  private syncing = false;
  // Retry ladder: 1s, 5s, 30s, 2m
  private retryLadder = [1000, 5000, 30000, 120000];

  constructor() {
    if (typeof window !== 'undefined') {
      this.dbPromise = openDB<AttendanceDB>('g4k-offline-attendance', 2, {
        upgrade(db, oldVersion, newVersion, transaction) {
          if (oldVersion < 1) {
            const store = db.createObjectStore('punches', { keyPath: 'client_id' });
            store.createIndex('by-status', 'syncStatus');
          }
          if (oldVersion < 2) {
            const reqStore = db.createObjectStore('requests', { keyPath: 'id' });
            reqStore.createIndex('by-status', 'syncStatus');
          }
        },
      });

      window.addEventListener('online', () => {
        this.updateQueueCount();
        this.syncAll();
      });
      window.addEventListener('offline', () => {
        this.updateQueueCount();
      });
      
      // Update queue count initially and run smart sync poll only if queue has pending items
      this.dbPromise.then(() => {
        this.updateQueueCount();
        if (typeof document !== 'undefined') {
          document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible' && navigator.onLine && useOfflineStore.getState().queueCount > 0) {
              this.syncAll();
            }
          });
        }
      });
    }
  }

  private async updateQueueCount() {
    if (!this.dbPromise) return;
    const db = await this.dbPromise;
    const punches = await db.getAllFromIndex('punches', 'by-status', 'pending');
    const requests = await db.getAllFromIndex('requests', 'by-status', 'pending');
    useOfflineStore.getState().setQueueCount(punches.length + requests.length);
  }

  async recordPunch(type: string, timestamp: string): Promise<string> {
    if (!this.dbPromise) return "no-db";
    const db = await this.dbPromise;

    // dedupe: if a pending punch of the same type exists for today, reuse its client_id
    const pending = await db.getAllFromIndex('punches', 'by-status', 'pending');
    const today = timestamp.split('T')[0];
    const existing = pending.find(p => p.type === type && p.timestamp.startsWith(today));
    
    if (existing) {
      if (navigator.onLine) this.syncAll();
      return existing.client_id;
    }

    const client_id = `evt_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

    await db.put('punches', {
      client_id,
      type,
      timestamp,
      syncStatus: 'pending',
    });

    this.updateQueueCount();

    if (navigator.onLine) {
      this.syncAll();
    }

    return client_id;
  }

  async queueRequest(endpoint: string, options: RequestInit): Promise<string> {
    if (!this.dbPromise) throw new Error("No DB");
    
    // Extract serializable options
    const serializableOptions: GenericRequest['options'] = {
      method: options.method || 'GET',
    };

    if (options.headers) {
      const h: Record<string, string> = {};
      new Headers(options.headers).forEach((value, key) => { h[key] = value; });
      serializableOptions.headers = h;
    }

    if (options.body && typeof options.body === 'string') {
      serializableOptions.body = options.body;
    }

    const db = await this.dbPromise;
    const id = `req_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
    
    await db.put('requests', {
      id,
      endpoint,
      options: serializableOptions,
      syncStatus: 'pending',
      addedAt: Date.now(),
      retryCount: 0,
    });

    this.updateQueueCount();
    
    if (navigator.onLine) {
      this.syncAll();
    }

    return id;
  }

  async syncAll() {
    if (this.syncing || !this.dbPromise) return;
    this.syncing = true;
    let syncedCount = 0;
    try {
      syncedCount += await this.syncPendingPunches();
      syncedCount += await this.syncPendingRequests();
      if (syncedCount > 0 && typeof window !== 'undefined') {
        window.dispatchEvent(new Event('offline-sync-complete'));
      }
    } finally {
      this.syncing = false;
      this.updateQueueCount();
    }
  }

  private async syncPendingPunches(): Promise<number> {
    if (!this.dbPromise) return 0;
    const db = await this.dbPromise;
    const pending = await db.getAllFromIndex('punches', 'by-status', 'pending');
    let count = 0;

    for (const punch of pending) {
      try {
        const endpoint = `/attendance/${punch.type.replace('_', '-')}`;
        await apiFetch(endpoint, {
          method: 'POST',
          body: JSON.stringify({
            client_id: punch.client_id,
            timestamp: punch.timestamp,
          }),
        }, true); // pass true to bypass offline queue loop

        punch.syncStatus = 'synced';
        await db.put('punches', punch);
        count++;
      } catch (err: any) {
        if (err.status && err.status >= 400 && err.status < 500) {
          punch.syncStatus = 'failed';
          await db.put('punches', punch);
          // Toast UI explicitly for failed syncs
          toast.error("Offline sync failed. Rolling back...", {
            id: `sync-fail-${punch.client_id}` // prevent duplicates
          });
          // Dispatch event so UI can invalidate and rollback
          if (typeof window !== "undefined") {
            window.dispatchEvent(new Event("attendance-sync-failed"));
          }
        }
      }
    }
    return count;
  }

  private async syncPendingRequests(): Promise<number> {
    if (!this.dbPromise) return 0;
    const db = await this.dbPromise;
    const pending = await db.getAllFromIndex('requests', 'by-status', 'pending');
    let count = 0;

    for (const req of pending) {
      // Check retry ladder
      const delay = this.retryLadder[Math.min(req.retryCount, this.retryLadder.length - 1)];
      if (req.lastRetry && Date.now() - req.lastRetry < delay) {
        continue; // Wait for backoff
      }

      req.lastRetry = Date.now();
      await db.put('requests', req);

      try {
        await apiFetch(req.endpoint, req.options, true);
        req.syncStatus = 'synced';
        await db.put('requests', req);
        count++;
      } catch (err: any) {
        req.retryCount++;
        
        if (err.status === 409 || err.status === 422) {
          req.syncStatus = 'conflict';
          toast.error(`Conflict syncing request to ${req.endpoint}. Please review changes.`);
        } else if (err.status && err.status >= 400 && err.status < 500) {
          req.syncStatus = 'failed';
        }
        await db.put('requests', req);
      }
    }
    return count;
  }
}

export const offlineEngine = new OfflineEngine();

import { useMemo } from 'react';

export interface Paginator<T> {
  data: T[];
  current_page?: number;
  last_page?: number;
  per_page?: number;
  total?: number;
  next_cursor?: string;
  meta?: any;
}

export interface LaravelResponse<T> {
  data?: Paginator<T> | T[];
  meta?: any;
  [key: string]: any;
}

/**
 * Safely extracts paginated data from a Laravel JSON response.
 * Laravel often wraps `paginate()` in `{ data: { data: [...], current_page: ... } }`.
 */
export function unwrapPaginator<T>(response: LaravelResponse<T> | Paginator<T> | null | undefined): Paginator<T> {
  if (!response) {
    return { data: [], last_page: 1, current_page: 1, total: 0 };
  }
  
  // If response has a nested data.data, it's a typical Laravel Response::json($query->paginate()) wrapper
  if ('data' in response && response.data && typeof response.data === 'object' && 'data' in response.data) {
    return response.data as Paginator<T>;
  }
  
  // If it's already unwrapped or a direct paginator
  if ('data' in response && Array.isArray(response.data)) {
    return response as Paginator<T>;
  }

  // Fallback if it's just an array returned as response
  if (Array.isArray(response)) {
    return { data: response, last_page: 1, current_page: 1, total: response.length };
  }

  return { data: [], last_page: 1, current_page: 1, total: 0 };
}

/**
 * Hook to memoize and safely access paginated lists
 */
export function usePaginatedList<T>(queryData: any) {
  return useMemo(() => {
    return unwrapPaginator<T>(queryData);
  }, [queryData]);
}

// @ts-nocheck
import { reconcileLayout } from "./reconcile-layout";

describe("reconcileLayout", () => {
  const colsMap = { lg: 12, md: 10, sm: 6, xs: 4, xxs: 2 };
  const availableWidgets = [
    { id: "w1", defaultLayout: { lg: { w: 3, h: 3, x: 0, y: 0 } } },
    { id: "w2", defaultLayout: { lg: { w: 4, h: 2, x: 3, y: 0 } } },
  ];

  it("should merge saved layout with missing default widgets", () => {
    const savedLayout = {
      lg: [{ i: "w1", w: 3, h: 3, x: 0, y: 0 }]
    };
    const result = reconcileLayout(savedLayout, availableWidgets, colsMap);
    expect(result?.lg).toHaveLength(2);
    expect(result?.lg.find((i: any) => i.i === "w2")).toBeTruthy();
  });

  it("should filter out unknown widgets from saved layout", () => {
    const savedLayout = {
      lg: [
        { i: "w1", w: 3, h: 3, x: 0, y: 0 },
        { i: "unknown_w", w: 3, h: 3, x: 5, y: 0 }
      ]
    };
    const result = reconcileLayout(savedLayout, availableWidgets, colsMap);
    expect(result?.lg).toHaveLength(2); // w1 and w2 (added from available)
    expect(result?.lg.find((i: any) => i.i === "unknown_w")).toBeFalsy();
  });

  it("should clamp coordinates and size to valid geometry", () => {
    const savedLayout = {
      lg: [{ i: "w1", w: 20, h: 0, x: -5, y: -2 }]
    };
    const result = reconcileLayout(savedLayout, availableWidgets, colsMap);
    const w1 = result?.lg.find((i: any) => i.i === "w1");
    expect(w1.w).toBe(12); // clamped to maxCols
    expect(w1.x).toBe(0); // clamped to >=0
    expect(w1.y).toBe(0); // clamped to >=0
    expect(w1.h).toBe(3); // repaired from 0
  });
});

export const GRID_COLS = { lg: 12, md: 10, sm: 6, xs: 4, xxs: 2 };

export function reconcileLayout(savedLayouts: any, availableWidgets: Array<any>, colsMap: { [key: string]: number }) {
  if (!savedLayouts || Object.keys(savedLayouts).length === 0) return null;
  
  const mergedBreakpoints: any = {};
  const breakpoints = ['lg', 'md', 'sm', 'xs', 'xxs'];
  
  breakpoints.forEach(bp => {
    const savedBp = Array.isArray(savedLayouts[bp]) ? savedLayouts[bp] : [];
    let mergedBp = [...savedBp];
    
    if (Array.isArray(availableWidgets)) {
      availableWidgets.forEach(w => {
        const exists = mergedBp.find((item: any) => item.i === w.id);
        if (!exists) {
          mergedBp.push({ ...(w.defaultLayout?.[bp] || w.defaultLayout), i: w.id });
        }
      });
    }
    
    // Filter out old/removed widgets and clamp/repair geometry
    const maxCols = colsMap[bp as keyof typeof colsMap] || 12;
    mergedBreakpoints[bp] = mergedBp
      .filter((item: any) => Array.isArray(availableWidgets) ? availableWidgets.find(w => w.id === item.i) : false)
      .map((item: any) => {
         const defaultWidget = availableWidgets.find(w => w.id === item.i);
         const defL = defaultWidget?.defaultLayout?.[bp] || defaultWidget?.defaultLayout;
         
         let { x, y, w, h } = item;
         
         // Repair missing or invalid
         if (typeof x !== 'number' || isNaN(x)) x = defL?.x || 0;
         if (typeof y !== 'number' || isNaN(y)) y = defL?.y || 0;
         if (typeof w !== 'number' || isNaN(w) || w <= 0) w = defL?.w || 3;
         if (typeof h !== 'number' || isNaN(h) || h <= 0) h = defL?.h || 3;
         
         // Clamp width and x position
         w = Math.min(w, maxCols);
         x = Math.min(x, maxCols - w);
         x = Math.max(0, x);
         y = Math.max(0, y);
         
         return { ...item, x, y, w, h };
      });
  });
  
  return mergedBreakpoints;
}

export function reconcileLayout(saved: any, availableWidgets: any[], colsMap: Record<string, number>) {
  if (!saved || typeof saved !== "object") return null;

  let layoutData = saved;
  if (saved.preferences?.dashboard_layout) {
    layoutData = saved.preferences.dashboard_layout;
  }

  if (!layoutData.layouts) return null;

  const result = {
    version: layoutData.version || 1,
    layouts: {} as Record<string, any[]>,
    dismissed: (Array.isArray(layoutData.dismissed?.data) ? layoutData.dismissed.data : (Array.isArray(layoutData.dismissed) ? layoutData.dismissed : [])),
  };

  const widgetMap = new Map();
  availableWidgets.forEach(w => widgetMap.set(w.id, w));

  Object.keys(colsMap).forEach(bp => {
    const maxCols = colsMap[bp];
    const bpLayouts = Array.isArray(layoutData.layouts[bp]) ? layoutData.layouts[bp] : [];
    
    // Filter and sanitize existing
    const sanitized = bpLayouts
      .filter((item: any) => item && typeof item.i === "string" && widgetMap.has(item.i))
      .map((item: any) => {
        let { i, x, y, w, h } = item;
        
        x = typeof x === 'number' && !isNaN(x) ? Math.max(0, x) : 0;
        y = typeof y === 'number' && !isNaN(y) ? y : 0; 
        w = typeof w === 'number' && !isNaN(w) && w > 0 ? w : 1;
        h = typeof h === 'number' && !isNaN(h) && h > 0 ? h : 1;

        if (w > maxCols) w = maxCols;
        if (x + w > maxCols) x = Math.max(0, maxCols - w);

        return { ...item, i, x, y, w, h };
      });

    const presentIds = new Set(sanitized.map((item: any) => item.i));
    const dismissedIds = new Set(result.dismissed);

    // Add missing from defaults
    availableWidgets.forEach(w => {
      if (!presentIds.has(w.id) && !dismissedIds.has(w.id)) {
        const bpDefault = w.defaultLayout?.[bp] || w.defaultLayout;
        if (bpDefault) {
          let { x = 0, y = 0, w: defW = 1, h: defH = 1 } = bpDefault;
          if (defW > maxCols) defW = maxCols;
          if (x + defW > maxCols) x = Math.max(0, maxCols - defW);
          
          sanitized.push({ ...bpDefault, i: w.id, x, y, w: defW, h: defH });
        }
      }
    });

    result.layouts[bp] = sanitized;
  });

  return result;
}

import { create } from "zustand";
import { persist } from "zustand/middleware";
import React from "react";

export interface RecentItem {
  id: string;
  type: "employee" | "leave" | "attendance" | "project" | "task";
  title: string;
  subtitle?: string;
  url: string;
  icon?: string;
  timestamp: number;
}

interface RecentStore {
  recentItems: RecentItem[];
  addItem: (item: Omit<RecentItem, "timestamp">) => void;
  clearItems: () => void;
}

const MAX_RECENT_ITEMS = 10;

export const useRecentStore = create<RecentStore>()(
  persist(
    (set) => ({
      recentItems: [],
      addItem: (item) =>
        set((state) => {
          // Remove existing item if it exists
          const filtered = state.recentItems.filter(
            (existing) => !(existing.id === item.id && existing.type === item.type)
          );
          
          const newItem: RecentItem = {
            ...item,
            timestamp: Date.now(),
          };

          // Add to beginning and slice to max length
          const newItems = [newItem, ...filtered].slice(0, MAX_RECENT_ITEMS);
          return { recentItems: newItems };
        }),
      clearItems: () => set({ recentItems: [] }),
    }),
    {
      name: "g4k-recent-store",
    }
  )
);

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface TimerState {
  isActive: boolean;
  isOnBreak: boolean;
  clockInTimestamp: string | null;
  currentBreakStart: string | null;
  baseSeconds: number; // Accumulated seconds BEFORE the current active period
  lastActiveTimestamp: string | null; // The exact timestamp when we last resumed/clocked in
  standardSeconds: number; // Standard working hours in seconds for the day
  
  // Actions
  setStandardSeconds: (seconds: number) => void;
  startTimer: (clockInTime: string, initialTotalSeconds: number) => void;
  stopTimer: () => void;
  startBreak: (breakStartTime: string) => void;
  endBreak: (endBreakTime: string) => void;
  syncWithServer: (day: any, events: any[], standardSeconds?: number) => void;
  // Project/Task Timer
  activeProjectId: string | null;
  activeTaskId: string | null;
  activeTaskTitle: string | null;
  projectTimerStartedAt: number | null;
  projectTimerAccumulatedSeconds: number;
  isProjectTimerRunning: boolean;

  startProjectTimer: (projectId: string, taskId: string, title: string) => void;
  pauseProjectTimer: () => void;
  resumeProjectTimer: () => void;
  stopProjectTimer: () => { elapsedSeconds: number; taskId: string | null; projectId: string | null };
}

export const useTimerStore = create<TimerState>()(
  persist(
    (set, get) => ({
  isActive: false,
  isOnBreak: false,
  clockInTimestamp: null,
  currentBreakStart: null,
  baseSeconds: 0,
  lastActiveTimestamp: null,
  standardSeconds: 28800, // Default to 8 hours

  setStandardSeconds: (seconds: number) => set({ standardSeconds: seconds }),

  startTimer: (clockInTime: string, initialTotalSeconds: number) => {
    set({
      isActive: true,
      isOnBreak: false,
      clockInTimestamp: clockInTime,
      baseSeconds: initialTotalSeconds,
      lastActiveTimestamp: clockInTime,
    });
  },

  stopTimer: () => {
    set({
      isActive: false,
      isOnBreak: false,
      lastActiveTimestamp: null,
    });
  },

  startBreak: (breakStartTime: string) => {
    // Before going on break, we must accumulate the seconds from the current active period
    const { lastActiveTimestamp, baseSeconds } = get();
    let updatedBaseSeconds = baseSeconds;
    
    if (lastActiveTimestamp) {
      const elapsedSinceLastEvent = Math.floor((new Date(breakStartTime).getTime() - new Date(lastActiveTimestamp).getTime()) / 1000);
      updatedBaseSeconds += Math.max(0, elapsedSinceLastEvent);
    }

    set({
      isOnBreak: true,
      currentBreakStart: breakStartTime,
      baseSeconds: updatedBaseSeconds,
      lastActiveTimestamp: null, // Timer should stop visually
    });
  },

  endBreak: (endBreakTime: string) => {
    set({
      isOnBreak: false,
      currentBreakStart: null,
      lastActiveTimestamp: endBreakTime,
    });
  },

  syncWithServer: (day: any, events: any[], providedStandardSeconds?: number) => {
    if (!day || events.length === 0) {
      get().stopTimer();
      set({ baseSeconds: 0, lastActiveTimestamp: null });
      return;
    }

    const initialTotalSeconds = day.total_seconds || 0;
    const standardSeconds = providedStandardSeconds || day.standard_seconds || 28800;
    
    // Determine active state based on events
    let isActive = false;
    let isOnBreak = false;
    let clockInTimestamp: string | null = null;
    let currentBreakStart: string | null = null;
    let lastActiveEventTimestamp: string | null = null;

    events.forEach(event => {
      if (event.type === 'clock_in') {
        isActive = true;
        clockInTimestamp = event.timestamp;
        lastActiveEventTimestamp = event.timestamp;
      } else if (event.type === 'clock_out') {
        isActive = false;
        clockInTimestamp = null;
        lastActiveEventTimestamp = null;
      } else if (event.type === 'break_start') {
        isOnBreak = true;
        currentBreakStart = event.timestamp;
        lastActiveEventTimestamp = null; // Timer pauses on break
      } else if (event.type === 'break_end') {
        isOnBreak = false;
        currentBreakStart = null;
        lastActiveEventTimestamp = event.timestamp;
      }
    });

    if (isActive) {
      set({
        isActive: true,
        isOnBreak: isOnBreak,
        clockInTimestamp: clockInTimestamp,
        currentBreakStart: currentBreakStart,
        baseSeconds: initialTotalSeconds,
        lastActiveTimestamp: lastActiveEventTimestamp,
        standardSeconds: standardSeconds,
      });
    } else {
      get().stopTimer();
      set({ baseSeconds: initialTotalSeconds, standardSeconds: standardSeconds });
    }
  },

  // Project Timer Implementation
  activeProjectId: null,
  activeTaskId: null,
  activeTaskTitle: null,
  projectTimerStartedAt: null,
  projectTimerAccumulatedSeconds: 0,
  isProjectTimerRunning: false,

  startProjectTimer: (projectId: string, taskId: string, title: string) => {
    set({
      activeProjectId: projectId,
      activeTaskId: taskId,
      activeTaskTitle: title,
      projectTimerStartedAt: Date.now(),
      projectTimerAccumulatedSeconds: 0,
      isProjectTimerRunning: true,
    });
  },

  pauseProjectTimer: () => {
    const { isProjectTimerRunning, projectTimerStartedAt, projectTimerAccumulatedSeconds } = get();
    if (!isProjectTimerRunning || !projectTimerStartedAt) return;
    const elapsed = Math.floor((Date.now() - projectTimerStartedAt) / 1000);
    set({
      isProjectTimerRunning: false,
      projectTimerStartedAt: null,
      projectTimerAccumulatedSeconds: projectTimerAccumulatedSeconds + elapsed,
    });
  },

  resumeProjectTimer: () => {
    const { activeTaskId, isProjectTimerRunning } = get();
    if (!activeTaskId || isProjectTimerRunning) return;
    set({
      isProjectTimerRunning: true,
      projectTimerStartedAt: Date.now(),
    });
  },

  stopProjectTimer: () => {
    const {
      isProjectTimerRunning,
      projectTimerStartedAt,
      projectTimerAccumulatedSeconds,
      activeTaskId,
      activeProjectId,
    } = get();
    
    let totalSeconds = projectTimerAccumulatedSeconds;
    if (isProjectTimerRunning && projectTimerStartedAt) {
      totalSeconds += Math.floor((Date.now() - projectTimerStartedAt) / 1000);
    }
    
    const tId = activeTaskId;
    const pId = activeProjectId;
    
    set({
      activeProjectId: null,
